schemas.schema-01-systematic.prisma:
/// Shopping mall channel definition for platform multi-channel, omni-channel configuration. Implements requirement for channel-level separation and enables web, mobile, external integrations. Maintains 3NF: all channel attributes are atomic, reusable, and no calculations or redundancy. Used for administration, business rule selection, and UI partitioning. Key relationships: One-to-many with sections. Special behaviors: Code uniqueness and business logic mapping.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies a channel (web, app, partner marketplace).
  id String @id @db.Uuid

  /// Technical channel code (e.g., 'web', 'mobile_app', 'marketplace'). Uniquely identifies channel for platform business rules and selection. Ensures atomicity (1NF/3NF) by separating label from reference. Used in integration logic and admin UI.
  code String

  /// Display name for channel in admin/UX context. Implements name/label separation from code for normalization and UI flexibility. Used for admin/global reporting.
  name String

  /// Channel activation toggle (true = channel available, false = hidden/inactive). Implements activation/deactivation requirement without removing definition. Maintains atomic 3NF compliance—does not duplicate business status elsewhere.
  active Boolean

  /// Arbitrary channel-specific configuration as JSON (string). Used for variable settings (e.g., branding, endpoints). Enables open-ended config without denormalizing standard columns—maintains normalization. Used by devops and expanded integrations.
  config String

  /// When channel definition was created (audit/logging). Implements platform-level audit and traceability. Ensures 3NF: one fact per field.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for channel (for audit, troubleshooting). Supports system-wide consistency and change history retention. Used by operations and admin UI.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_sections shopping_mall_ai_sections[]
  shopping_mall_ai_customers shopping_mall_ai_customers[]
  shopping_mall_ai_sellers shopping_mall_ai_sellers[]
  shopping_mall_ai_ai_recommendations shopping_mall_ai_ai_recommendations[]
  shopping_mall_ai_carts shopping_mall_ai_carts[]
  shopping_mall_ai_orders shopping_mall_ai_orders[]
  shopping_mall_ai_payments shopping_mall_ai_payments[]
  shopping_mall_ai_coupons shopping_mall_ai_coupons[]
  shopping_mall_ai_bbs_posts shopping_mall_ai_bbs_posts[]

  @@unique([code])
  @@index([active])
}

/// Logical application section of the shopping mall platform (e.g., 'catalog', 'checkout'). Implements requirement for modular, channel-specific configuration and flexibility. Maintains strict 3NF—each attribute atomic; section-channel relationship enforces hierarchy on normalized key. Examples: Each channel may support distinct set of sections (multi-tenant/cross-app). Key relationships: Belongs to channel (shopping_mall_ai_channels). Special behaviors: (code,channel) composite unique constraint for business logic mapping.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies a logical application section (e.g., catalog, checkout).
  id String @id @db.Uuid

  /// Associated channel's primary key reference ({@link shopping_mall_ai_channels.id}). Maintains referential integrity for cross-section/channel hierarchy.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Section code for business logic and navigation mapping (e.g., 'home', 'products'). Implements atomicity and enables unique business lookup per channel. 3NF: no code redundancy within channel.
  code String

  /// Admin-facing section name for labeling and reporting. Separated from code for normalization/usability.
  name String

  /// Section enabled/disabled toggle for runtime configuration and navigation control. Enables UX flexibility without data deletion. 3NF: atomic, non-redundant.
  active Boolean

  /// Section-specific extensibility point for arbitrary configuration (JSON as string). Implements open-ended setup without denormalizing core entity.
  config String

  /// Creation timestamp for section, supporting audit trail of platform structure. Implements audit consistency across entities.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (for admin/ops audit and troubleshooting). 3NF compliance: strictly atomic fact.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_carts shopping_mall_ai_carts[]
  shopping_mall_ai_bbs_posts shopping_mall_ai_bbs_posts[]

  @@unique([code, shopping_mall_ai_channel_id])
  @@index([shopping_mall_ai_channel_id])
}

/// Global configuration registry/settings for the shopping mall platform. Implements requirement for centrally managed, system-wide tunables such as site name, URLs, or flags. Maintains 3NF: each setting is represented atomically; no derived or calculated data. Used in global application startup, platform migration, or runtime toggling. Key relationships: None (standalone, not externally referenced). Special behaviors: Unique key required; audit fields always populated.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies a configuration entry.
  id String @id @db.Uuid

  /// Configuration key (e.g., 'site_title', 'api_gateway_url'). Implements atomic config separation for code/access. 3NF: no redundant info.
  key String

  /// String/JSON value for the configuration (arbitrary business data as string). May be interpreted by business logic code as needed. Maintains normalization.
  value String

  /// Config enabled/disabled switch (active/inactive). 3NF: pure flag, never derived. Allows staged rollouts or toggling without removing records.
  active Boolean

  /// Timestamp for config creation (audit and troubleshooting). Maintains auditability for ops and compliance.
  created_at DateTime @db.Timestamptz

  /// Last config update timestamp; supports system troubleshooting and rollback history. 3NF: atomic, auditable, never derived.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([active])
}

schemas.schema-02-actors.prisma:
/// Customer account entity for authentication and shopping activity. Implements user onboarding, role separation, and RBAC requirements. Maintains strict 3NF by keeping password, registration data, and identity attributes atomic and referencing sessions/roles externally. Example: customer logs in via email, manages account, and owns shopping sessions. Key relationships: sessions table (1:N), channel FK. Special behaviors: nickname unique in channel, soft disable via is_active.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique customer identifier.
  id String @id @db.Uuid

  /// Belonged sales channel's {@link shopping_mall_ai_channels.id}.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Email for authentication. Unique per customer. Used for login and communications.
  email String

  /// Hashed password for secure login. Never stored as plain text. Critical for user authentication.
  password String

  /// Display nickname unique per channel. Used for display and personalized settings.
  nickname String

  /// Datetime the customer registered. Used for audit trail, onboarding time analysis.
  registered_at DateTime @db.Timestamptz

  /// Whether the account is active. Used for compliance suspensions, user-initiated deactivation.
  is_active Boolean

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_sessions shopping_mall_ai_sessions[]
  shopping_mall_ai_carts shopping_mall_ai_carts[]
  shopping_mall_ai_orders shopping_mall_ai_orders[]
  shopping_mall_ai_coupon_events shopping_mall_ai_coupon_events[]
  shopping_mall_ai_deposits shopping_mall_ai_deposits[]
  shopping_mall_ai_mileage_points shopping_mall_ai_mileage_points[]
  shopping_mall_ai_loyalty_events shopping_mall_ai_loyalty_events[]
  shopping_mall_ai_bbs_posts shopping_mall_ai_bbs_posts[]
  shopping_mall_ai_bbs_comments shopping_mall_ai_bbs_comments[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]
  shopping_mall_ai_reviews shopping_mall_ai_reviews[]

  @@unique([email])
  @@index([shopping_mall_ai_channel_id, email], map: "shopping_mall_ai_customers_shopping_mall_ai_channel_id_2a15756c")
}

/// Seller account model — distinct from customer — for merchant product management. Implements seller registration, KYC/audit, and seller-side session/auth. Strict 3NF, all key business fields atomic. Key relationships: onboarding workflow (1:N), sessions (1:N), channel FK. Example: seller registers, progresses through onboarding, and gains product listing rights after admin approval. Special behaviors: business verification (verified), email uniqueness enforced.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique seller ID.
  id String @id @db.Uuid

  /// Operating channel's {@link shopping_mall_ai_channels.id}.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Email for seller authentication, unique. Supports login, recovery, and notifications.
  email String

  /// Seller password hash for secure login. No plain text storage, RBAC enforcement.
  password String

  /// Display/business name for the seller. Used across mall assets and shop settings.
  name String

  /// Business verification status. True if KYC/admin approval completed. Supports onboarding/audit workflow.
  verified Boolean

  /// Datetime seller registered. Used for onboarding analytics/compliance.
  registered_at DateTime @db.Timestamptz

  /// Active status. Used for compliance/account suspensions/soft block.
  is_active Boolean

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_seller_onboardings shopping_mall_ai_seller_onboardings[]
  shopping_mall_ai_sessions shopping_mall_ai_sessions[]
  shopping_mall_ai_products shopping_mall_ai_products[]
  shopping_mall_ai_carts shopping_mall_ai_carts[]
  shopping_mall_ai_coupons shopping_mall_ai_coupons[]
  shopping_mall_ai_coupon_events shopping_mall_ai_coupon_events[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]

  @@unique([email])
  @@index([shopping_mall_ai_channel_id, email])
}

/// Admin account: platform superuser with staff-level authority. Tracks audit, onboarding approvals, and manages permissions. All key fields atomic, no denormalization. Key relationships: sessions (1:N), onboarding approvals (1:N). Example: admin creates, audits sellers, and owns system configuration. Special: staff_id must be unique. Follows strict 3NF.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique admin identifier.
  id String @id @db.Uuid

  /// Admin's unique email for login and notifications. RBAC entry point.
  email String

  /// Password hash for admin login. Never stored as plain text. Used for security enforcement.
  password String

  /// Staff/admin display name. Used for admin area displays and audit logs.
  name String

  /// Unique staff identifier. Used for audit, traceability, compliance reporting.
  staff_id String

  /// Datetime staff/admin was registered. Audit and compliance reporting.
  registered_at DateTime @db.Timestamptz

  /// Whether admin account is active. Can be toggled for security/reorgs.
  is_active Boolean

  //----
  // RELATIONS
  //----
  shopping_mall_ai_seller_onboardings shopping_mall_ai_seller_onboardings[]
  shopping_mall_ai_sessions shopping_mall_ai_sessions[]
  shopping_mall_ai_loyalty_events shopping_mall_ai_loyalty_events[]
  shopping_mall_ai_content_moderations shopping_mall_ai_content_moderations[]

  @@unique([email])
  @@unique([staff_id])
}

/// Seller onboarding/audit workflow. Captures KYC/approval step, admin assignment, and doc upload. Key relationships: seller (required), admin (optional, after approval). Maintains atomic onboarding status markers and timestamps. Used for regulatory compliance and admin enforcement. Strict 3NF.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_seller_onboardings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique onboarding workflow instance.
  id String @id @db.Uuid

  /// Seller undergoing onboarding. FK to {@link shopping_mall_ai_sellers.id}.
  shopping_mall_ai_seller_id String @db.Uuid

  /// Admin assigned to/approved this onboarding; nullable FK to {@link shopping_mall_ai_admins.id}.
  shopping_mall_ai_admin_id String? @db.Uuid

  /// Current onboarding status for workflow and business rules. Ex: 'pending', 'approved', 'rejected'.
  status String

  /// Datetime onboarding was started. Used for in-progress analytics and workflow tracing.
  started_at DateTime @db.Timestamptz

  /// Nullable: Completion datetime for onboarding. Only set if completed/approved.
  completed_at DateTime? @db.Timestamptz

  /// URI to uploaded business docs for KYC. Used for regulatory compliance/audit.
  business_document_url String

  //----
  // RELATIONS
  //----
  seller shopping_mall_ai_sellers @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_s_10d5f8a6")
  admin shopping_mall_ai_admins? @relation(fields: [shopping_mall_ai_admin_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_a_ae5f4826")

  @@index([shopping_mall_ai_seller_id], map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_s_73d5dca1")
  @@index([shopping_mall_ai_admin_id], map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_a_4139faf3")
}

/// RBAC row-level grant/deny for mall actors. All fields atomic per strict normalization. Ensures only allowed actions are permitted by actor, role, and permission string. Example: grant seller 'issue_coupon', deny customer 'approve_seller'. Strict 3NF; no denormalization/caching.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_role_permissions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique mapping row.
  id String @id @db.Uuid

  /// Actor domain: 'customer', 'seller', or 'admin'. Used for RBAC and audit.
  actor_type String

  /// Role group. Ex: 'pending_seller', 'seller', 'customer', 'admin'. Policy enforcement granularity.
  role_name String

  /// Permission/action string. Ex: 'manage_products', 'list_orders', 'issue_coupons'.
  permission_key String

  /// If true, permission is allowed for this row. Otherwise denied/blocked.
  granted Boolean

  //----
  // RELATIONS
  //----
  @@unique([actor_type, role_name, permission_key], map: "shopping_mall_ai_role_permissions_actor_type_role_name_22ac8502")
}

/// Session tracking for all actor logins. Nullable FKs reflect actor role. Tracks multi-device, multi-actor, and compliance obligations. Timestamps are atomic. Strict 3NF, no token reuse. Example: customer and seller each have their own sessions, with traceable origin and timings.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique session instance.
  id String @id @db.Uuid

  /// FK to customer session. Nullable; only filled when session is for customer.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// FK to seller session. Nullable; only filled when session is for seller.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// FK to admin session. Nullable; only filled when session is for admin.
  shopping_mall_ai_admin_id String? @db.Uuid

  /// Opaque, securely generated session token for authentication. Unique per session.
  session_token String

  /// Type marker: 'web', 'mobile', 'api', etc. Enables multi-channel support.
  session_type String

  /// IP address of session origin. Recorded for audit, compliance, and fraud analysis.
  ip_address String

  /// Auth time (UTC, required). Used for compliance and last login tracking.
  authenticated_at DateTime @db.Timestamptz

  /// Session expiration time/date. Enforces security, supports audit retention policies.
  expires_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)
  seller shopping_mall_ai_sellers? @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)
  admin shopping_mall_ai_admins? @relation(fields: [shopping_mall_ai_admin_id], references: [id], onDelete: Cascade)

  @@index([shopping_mall_ai_customer_id])
  @@index([shopping_mall_ai_seller_id])
  @@index([shopping_mall_ai_admin_id])

  @@unique([session_token])
}

schemas.schema-03-product-catalog.prisma:
/// Product master table - Implements requirements from the Product Management module, enabling sellers to register, manage, update, and track products through their lifecycle. Maintains 3NF by reference-linking to sellers, categories, and separating options, inventory, tags, and snapshots to discrete tables. Used for registering new items, searching products, assembling bundles, and supporting audit traceability. Key relationships: seller (actor), category, inventory, options, tags, bundles, AI recommendations. Special behaviors: unique SKU constraint per seller, supports full audit traceability via snapshots and timestamps.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller responsible for this product. References existing shopping_mall_ai_sellers table.
  shopping_mall_ai_seller_id String @db.Uuid

  /// Main category reference. References {@link shopping_mall_ai_product_categories.id}.
  shopping_mall_ai_product_category_id String @db.Uuid

  /// Product title (multi-language handled outside this table). Represents main display label.
  title String

  /// Product description for display. Maintains normalization by storing only base string here, not translations or formatted content.
  description String

  /// Base price of the product. Implements pricing requirement from catalog management - atomic field (no aggregation).
  price Float @db.DoublePrecision

  /// Status lifecycle state (active, inactive, archived, etc). Implements requirement for workflow, returns, search. 3NF: not derived from other fields.
  status String

  /// Product Stock Keeping Unit. Enforces business uniqueness within each seller (composite key constraint).
  sku String

  /// Row creation timestamp for audit trail. Not nullable, part of audit compliance.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update for audit trail. Not nullable, required for audit compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_mall_ai_sellers @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)
  category shopping_mall_ai_product_categories @relation(fields: [shopping_mall_ai_product_category_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_products_shopping_mall_ai_product_cat_2245f191")

  shopping_mall_ai_inventories shopping_mall_ai_inventories[]
  shopping_mall_ai_product_snapshots shopping_mall_ai_product_snapshots[]
  shopping_mall_ai_product_options shopping_mall_ai_product_options[]
  shopping_mall_ai_product_tags shopping_mall_ai_product_tags[]
  shopping_mall_ai_ai_recommendations shopping_mall_ai_ai_recommendations[]
  shopping_mall_ai_cart_items shopping_mall_ai_cart_items[]
  shopping_mall_ai_order_items shopping_mall_ai_order_items[]
  shopping_mall_ai_coupons shopping_mall_ai_coupons[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]
  shopping_mall_ai_reviews shopping_mall_ai_reviews[]

  @@unique([shopping_mall_ai_seller_id, sku])
  @@index([status, price])
  @@index([shopping_mall_ai_product_category_id], map: "shopping_mall_ai_products_shopping_mall_ai_product_cat_bdfadada")
}

/// Product category list (hierarchical) - Implements product categorization and navigation requirements. Maintains normalization by referencing parent self-row for hierarchy and separating product assignment. Used for category browsing, assigning products, and analytics. Key relationships: self-parent, products. Unique constraint prevents duplicate category names under same parent. Special behaviors: parent_id can be null (root category); unique name within parent. Fully auditable via timestamps.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key (UUID).
  id String @id @db.Uuid

  /// Optional parent category for hierarchy. Null means root category. References {@link shopping_mall_ai_product_categories.id}.
  parent_id String? @db.Uuid

  /// Category name used for filtering, display, analytics. Not null, enforces clear navigation structure.
  name String

  /// Sort order among siblings. Implements UI/UX display requirement. Atomic, not calculated.
  display_order Int @db.Integer

  /// Is this category active and visible to users? Not null, supports search/filtering.
  active Boolean

  /// Category creation time for audit. Not null.
  created_at DateTime @db.Timestamptz

  /// Category last update time for audit. Not null.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shopping_mall_ai_product_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_products shopping_mall_ai_products[]
  recursive shopping_mall_ai_product_categories[] @relation("recursive")

  @@unique([name, parent_id])
  @@index([parent_id, display_order])
}

/// Product bundle master - Implements requirement for composite/bundle product types (multi-SKU). Maintains normalization by separating bundle/product mapping (via multi-relation). No calculated fields; price is explicit. Used for registering, querying, activating bundles. Key relationships: M:N with products. Audit support via timestamps. Behavioral notes: Only active bundles shown to customers; price is not auto-summed from products, always explicit.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_bundles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Name of this bundle, used for search, navigation, analytic reporting. Atomic.
  title String

  /// Bundle overview text. Implements requirement for informative description. Atomic.
  description String

  /// Bundle price (explicit, not calculated). Implements business requirement for flexibility and control.
  price Float @db.DoublePrecision

  /// Is this bundle available/visible now? Used for customer-facing filtering and search.
  active Boolean

  /// Bundle creation time for audit row. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Bundle last update time for audit trail. Not nullable.
  updated_at DateTime @db.Timestamptz
}

/// Inventory tracking table - Implements strict real-time inventory control and auditability (per product and option-variant granularity). Follows 3NF by separating inventory and reservation state from products/options and excluding calculated values. Used for up-to-date stock validation and operational reporting. Relationships: FK to product, FK to option (nullable for base inventory). Auditable by timestamps. Unique inventory row per product/option. Key usage: reservation and availability queries, restock planning, shortage control. Special: Reserved cannot exceed quantity (enforced at application level).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_inventories {
  //----
  // COLUMNS
  //----
  /// Primary Key for inventory row.
  id String @id @db.Uuid

  /// Tracked product FK. References {@link shopping_mall_ai_products.id}.
  shopping_mall_ai_product_id String @db.Uuid

  /// Optional FK for option-variant specificity. References {@link shopping_mall_ai_product_options.id}.
  shopping_mall_ai_product_option_id String? @db.Uuid

  /// Quantity available in this inventory record. Implements atomic tracking of stock (not derived/calculated).
  quantity Int @db.Integer

  /// Quantity reserved for fulfillment, not available for immediate sale. Separated for normalization and process control.
  reserved_quantity Int @db.Integer

  /// When new stock is expected (null if not planned). Supports supply chain visibility and planning. Optional.
  restock_at DateTime? @db.Timestamptz

  /// Inventory row create audit. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Inventory row last update audit. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade)
  option shopping_mall_ai_product_options? @relation(fields: [shopping_mall_ai_product_option_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_inventories_shopping_mall_ai_product__f5d2bc1a")

  @@index([shopping_mall_ai_product_option_id], map: "shopping_mall_ai_inventories_shopping_mall_ai_product__7204c1df")

  @@unique([shopping_mall_ai_product_id, shopping_mall_ai_product_option_id], map: "shopping_mall_ai_inventories_shopping_mall_ai_product__ac71c199")
  @@index([quantity])
}

/// Product snapshot and versioning - Implements audit requirement for historical record of every change (register, update, delete) for compliance and analysis. Normalized by storing all persistent product data as serialized JSON (no denormalized fields here). Used for rollback, admin audit, and analytics. Relationships: FK to product. Behavioral notes: Only created_at timestamp kept (no modified field). 
