schemas.schema-03-product-catalog.prisma:
/// Product master table - Implements requirements from the Product Management module, enabling sellers to register, manage, update, and track products through their lifecycle. Maintains 3NF by reference-linking to sellers, categories, and separating options, inventory, tags, and snapshots to discrete tables. Used for registering new items, searching products, assembling bundles, and supporting audit traceability. Key relationships: seller (actor), category, inventory, options, tags, bundles, AI recommendations. Special behaviors: unique SKU constraint per seller, supports full audit traceability via snapshots and timestamps.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller responsible for this product. References existing shopping_mall_ai_sellers table.
  shopping_mall_ai_seller_id String @db.Uuid

  /// Main category reference. References {@link shopping_mall_ai_product_categories.id}.
  shopping_mall_ai_product_category_id String @db.Uuid

  /// Product title (multi-language handled outside this table). Represents main display label.
  title String

  /// Product description for display. Maintains normalization by storing only base string here, not translations or formatted content.
  description String

  /// Base price of the product. Implements pricing requirement from catalog management - atomic field (no aggregation).
  price Float @db.DoublePrecision

  /// Status lifecycle state (active, inactive, archived, etc). Implements requirement for workflow, returns, search. 3NF: not derived from other fields.
  status String

  /// Product Stock Keeping Unit. Enforces business uniqueness within each seller (composite key constraint).
  sku String

  /// Row creation timestamp for audit trail. Not nullable, part of audit compliance.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update for audit trail. Not nullable, required for audit compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller   shopping_mall_ai_sellers            @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)
  category shopping_mall_ai_product_categories @relation(fields: [shopping_mall_ai_product_category_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_products_shopping_mall_ai_product_cat_2245f191")

  shopping_mall_ai_inventories        shopping_mall_ai_inventories[]
  shopping_mall_ai_product_snapshots  shopping_mall_ai_product_snapshots[]
  shopping_mall_ai_product_options    shopping_mall_ai_product_options[]
  shopping_mall_ai_product_tags       shopping_mall_ai_product_tags[]
  shopping_mall_ai_ai_recommendations shopping_mall_ai_ai_recommendations[]
  shopping_mall_ai_cart_items         shopping_mall_ai_cart_items[]
  shopping_mall_ai_order_items        shopping_mall_ai_order_items[]
  shopping_mall_ai_coupons            shopping_mall_ai_coupons[]
  shopping_mall_ai_inquiries          shopping_mall_ai_inquiries[]
  shopping_mall_ai_reviews            shopping_mall_ai_reviews[]

  @@unique([shopping_mall_ai_seller_id, sku])
  @@index([status, price])
  @@index([shopping_mall_ai_product_category_id], map: "shopping_mall_ai_products_shopping_mall_ai_product_cat_bdfadada")
}

/// Product category list (hierarchical) - Implements product categorization and navigation requirements. Maintains normalization by referencing parent self-row for hierarchy and separating product assignment. Used for category browsing, assigning products, and analytics. Key relationships: self-parent, products. Unique constraint prevents duplicate category names under same parent. Special behaviors: parent_id can be null (root category); unique name within parent. Fully auditable via timestamps.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key (UUID).
  id String @id @db.Uuid

  /// Optional parent category for hierarchy. Null means root category. References {@link shopping_mall_ai_product_categories.id}.
  parent_id String? @db.Uuid

  /// Category name used for filtering, display, analytics. Not null, enforces clear navigation structure.
  name String

  /// Sort order among siblings. Implements UI/UX display requirement. Atomic, not calculated.
  display_order Int @db.Integer

  /// Is this category active and visible to users? Not null, supports search/filtering.
  active Boolean

  /// Category creation time for audit. Not null.
  created_at DateTime @db.Timestamptz

  /// Category last update time for audit. Not null.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shopping_mall_ai_product_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_products shopping_mall_ai_products[]
  recursive                 shopping_mall_ai_product_categories[] @relation("recursive")

  @@unique([name, parent_id])
  @@index([parent_id, display_order])
}

/// Product bundle master - Implements requirement for composite/bundle product types (multi-SKU). Maintains normalization by separating bundle/product mapping (via multi-relation). No calculated fields; price is explicit. Used for registering, querying, activating bundles. Key relationships: M:N with products. Audit support via timestamps. Behavioral notes: Only active bundles shown to customers; price is not auto-summed from products, always explicit.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_bundles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Name of this bundle, used for search, navigation, analytic reporting. Atomic.
  title String

  /// Bundle overview text. Implements requirement for informative description. Atomic.
  description String

  /// Bundle price (explicit, not calculated). Implements business requirement for flexibility and control.
  price Float @db.DoublePrecision

  /// Is this bundle available/visible now? Used for customer-facing filtering and search.
  active Boolean

  /// Bundle creation time for audit row. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Bundle last update time for audit trail. Not nullable.
  updated_at DateTime @db.Timestamptz
}

/// Inventory tracking table - Implements strict real-time inventory control and auditability (per product and option-variant granularity). Follows 3NF by separating inventory and reservation state from products/options and excluding calculated values. Used for up-to-date stock validation and operational reporting. Relationships: FK to product, FK to option (nullable for base inventory). Auditable by timestamps. Unique inventory row per product/option. Key usage: reservation and availability queries, restock planning, shortage control. Special: Reserved cannot exceed quantity (enforced at application level).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_inventories {
  //----
  // COLUMNS
  //----
  /// Primary Key for inventory row.
  id String @id @db.Uuid

  /// Tracked product FK. References {@link shopping_mall_ai_products.id}.
  shopping_mall_ai_product_id String @db.Uuid

  /// Optional FK for option-variant specificity. References {@link shopping_mall_ai_product_options.id}.
  shopping_mall_ai_product_option_id String? @db.Uuid

  /// Quantity available in this inventory record. Implements atomic tracking of stock (not derived/calculated).
  quantity Int @db.Integer

  /// Quantity reserved for fulfillment, not available for immediate sale. Separated for normalization and process control.
  reserved_quantity Int @db.Integer

  /// When new stock is expected (null if not planned). Supports supply chain visibility and planning. Optional.
  restock_at DateTime? @db.Timestamptz

  /// Inventory row create audit. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Inventory row last update audit. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product shopping_mall_ai_products         @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade)
  option  shopping_mall_ai_product_options? @relation(fields: [shopping_mall_ai_product_option_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_inventories_shopping_mall_ai_product__f5d2bc1a")

  @@unique([shopping_mall_ai_product_id, shopping_mall_ai_product_option_id], map: "shopping_mall_ai_inventories_shopping_mall_ai_product__ac71c199")
  @@index([shopping_mall_ai_product_option_id], map: "shopping_mall_ai_inventories_shopping_mall_ai_product__7204c1df")
  @@index([quantity])
}

/// Product snapshot and versioning - Implements audit requirement for historical record of every change (register, update, delete) for compliance and analysis. Normalized by storing all persistent product data as serialized JSON (no denormalized fields here). Used for rollback, admin audit, and analytics. Relationships: FK to product. Behavioral notes: Only created_at timestamp kept (no modified field). 
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to tracked product ({@link shopping_mall_ai_products.id}).
  shopping_mall_ai_product_id String @db.Uuid

  /// Action that caused this snapshot (created/updated/deleted etc). Implements requirement for change log granularity.
  action String

  /// Serialized JSON state of product at snapshot. 3NF-compliant; not calculated, atomic data blob.
  snapshot_json String

  /// Time the change was snapshotted (never null).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_product_snapshots_shopping_mall_ai_pr_363cd0d7")

  @@index([shopping_mall_ai_product_id], map: "shopping_mall_ai_product_snapshots_shopping_mall_ai_pr_4ff1b04c")
}

/// Product options (variants) - Implements multi-attribute SKU structures (size/color/etc.) separate from product records per normalization. Used for registration of product attributes, pricing structures, inventory granularity. Relationships: FK to product, unique SKU per product/option. Behavioral: Option_sku is always unique within product. Atomic, not calculated. 
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_options {
  //----
  // COLUMNS
  //----
