  /// FK to parent product ({@link shopping_mall_ai_products.id}).
  shopping_mall_ai_product_id String @db.Uuid

  /// Option category name such as Size/Color. Required for variant registration.
  name String

  /// Option value, e.g., "Large" or "Red". Implements flexible attribute design.
  value String

  /// Single SKU for this option/variant within the parent product requirement. Uniqueness enforced.
  option_sku String

  /// Created at (audit row). Not nullable.
  created_at DateTime @db.Timestamptz

  /// Updated at (audit row). Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_product_options_shopping_mall_ai_prod_cae213bb")

  shopping_mall_ai_inventories shopping_mall_ai_inventories[]
  shopping_mall_ai_cart_items  shopping_mall_ai_cart_items[]
  shopping_mall_ai_order_items shopping_mall_ai_order_items[]

  @@unique([shopping_mall_ai_product_id, option_sku], map: "shopping_mall_ai_product_options_shopping_mall_ai_prod_d32c7a42")
}

/// Product-tag M:N mapping - Implements flexible tagging for user search, analytics, AI recommendations (per requirements). Strict 3NF: each row is atomic, reference to one product and one tag. Used for assigning labels (seasonal, thematic, marketing), tagging analytics. Uniqueness constraint prevents duplicate tag for same product. Fully auditable.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to associated product ({@link shopping_mall_ai_products.id}).
