  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_ai_recommendations_shopping_mall_ai_p_76893b18")
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_ai_recommendations_shopping_mall_ai_c_2c44a17c")

  @@unique([shopping_mall_ai_product_id, shopping_mall_ai_channel_id], map: "shopping_mall_ai_ai_recommendations_shopping_mall_ai_p_1b4f1e42")
  @@index([shopping_mall_ai_channel_id], map: "shopping_mall_ai_ai_recommendations_shopping_mall_ai_c_90ef022f")
