schemas.schema-04-carts.prisma:
/// Shopping cart representing short-lived user intent before checkout. Implements the requirement for separating intent/mutable cart state from transactional orders (see Cart & Order System doc). Maintains strict 3NF by isolating customer, channel, and section as FKs. For example, guest carts have null customer ID; multi-seller split is enabled by seller_id. Key relationships: links to customers/products/sessions/items. Special behaviors: cart can expire or be deleted if unused.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer who owns this cart. Nullable for guest carts (intent tracking without persistent identity).
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Seller (if cart is seller-specific). Used for multi-seller/split-cart scenarios.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// Channel the cart was created from (web/app/partner). Required for tracking context and analytics.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Mall section/category that the cart applies to (for analytics, marketing, campaign scope).
  shopping_mall_ai_section_id String @db.Uuid

  /// Last update timestamp for cart record. Used in cart expiry and abandoned cart logic.
  updated_at DateTime @db.Timestamptz

  /// Time the cart was first created. Used for audit trail and analytics.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)
  seller   shopping_mall_ai_sellers?   @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)
  channel  shopping_mall_ai_channels   @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade)
  section  shopping_mall_ai_sections   @relation(fields: [shopping_mall_ai_section_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_cart_items    shopping_mall_ai_cart_items[]
  shopping_mall_ai_cart_sessions shopping_mall_ai_cart_sessions[]

  @@index([shopping_mall_ai_seller_id])
  @@index([shopping_mall_ai_channel_id])
  @@index([shopping_mall_ai_section_id])
  @@index([shopping_mall_ai_customer_id, shopping_mall_ai_channel_id], map: "shopping_mall_ai_carts_shopping_mall_ai_customer_id_sh_1a1d7753")
  @@index([updated_at])
}

/// Cart item records - each row represents an atomic product/option/quantity selected in a cart. Implements requirement for normalized item representation in the Cart & Order System; avoids denormalized arrays. Usage example: Customer adds 2 products to cart, two rows are created. Key relationships: references carts and products; optional product_option for variants. Special behaviors: supports audit via timestamps, quantity changes, updates.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_cart_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent cart for this item (1:N relationship; must reference shopping_mall_ai_carts.id).
  shopping_mall_ai_cart_id String @db.Uuid

  /// Product being considered for purchase (must reference shopping_mall_ai_products.id).
  shopping_mall_ai_product_id String @db.Uuid

  /// Specific product option (e.g., color/size variant chosen; nullable if product has no variants).
  shopping_mall_ai_product_option_id String? @db.Uuid

  /// Quantity chosen in this cart item row. Atomic to maintain normalization and enable accurate order creation.
  quantity Int @db.Integer

  /// Time this item was added to cart. Used for analytics and audit trail.
  added_at DateTime @db.Timestamptz

  /// Time item was last modified. Used for detecting stale/reserved items.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart           shopping_mall_ai_carts            @relation(fields: [shopping_mall_ai_cart_id], references: [id], onDelete: Cascade)
  product        shopping_mall_ai_products         @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade)
  product_option shopping_mall_ai_product_options? @relation(fields: [shopping_mall_ai_product_option_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_cart_items_shopping_mall_ai_product_o_0a639292")

  @@index([shopping_mall_ai_product_id])
  @@index([shopping_mall_ai_product_option_id], map: "shopping_mall_ai_cart_items_shopping_mall_ai_product_o_c54eaf47")
  @@index([shopping_mall_ai_cart_id, shopping_mall_ai_product_id], map: "shopping_mall_ai_cart_items_shopping_mall_ai_cart_id_s_7aba6c8c")
}

/// Tracks guest/member session linkage to carts, enabling resume/sharing/expiration by session or device. Implements requirement for decoupling ephemeral session/cart lifecycles. Maintains normalization with session_token and cart FK (unique per token). For example, returning guest resumes session by session_token lookup. Key relationships: each session links to one cart. Special behaviors: auto-expiry, support guest/member migration.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_cart_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The cart this session is linked to. 1:N mapping for session to cart. Required for all records.
  shopping_mall_ai_cart_id String @db.Uuid

  /// Opaque token binding session to cart (guest modes, device restoration, etc.). Must be unique.
  session_token String

  /// Session creation timestamp. Used for audit and recall.
  created_at DateTime @db.Timestamptz

  /// Most recent activity timestamp for session expiry/cleanup.
  last_active_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart shopping_mall_ai_carts @relation(fields: [shopping_mall_ai_cart_id], references: [id], onDelete: Cascade)

  @@unique([session_token])
  @@index([shopping_mall_ai_cart_id])
}

schemas.schema-05-orders.prisma:
/// Order record for each completed checkout event - This implements the need for atomic, auditable transaction records as per cart/order system and compliance requirements. Business purpose: provides a persistent, auditable record of sales including references to customer, channel, and all transactional relationships. Technical context: references customers, channels (both from other components), and aggregates items/payments/shipments. Maintains strict 3NF normalization; order-level calculated/summary fields are NOT stored here. Used for all order reporting, fulfillment, and analytics workflows. Key relationships: customer (buyer), channel (origin), order_items (breakdown), payments, shipments. Special behaviors: Immutable after completion for legal compliance. Timestamps support audit and temporal analytics.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for each order, enforcing entity integrity and traceability.
  id String @id @db.Uuid

  /// References the customer who placed the order. Links to {@link shopping_mall_ai_customers.id} from Actors domain for audit and reporting. Ensures 3NF normalization by externalizing identity.
  shopping_mall_ai_customer_id String @db.Uuid

  /// Channel through which the order was placed. References {@link shopping_mall_ai_channels.id} for analytics and multi-channel support. Fully normalized design.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Current workflow status (pending, paid, shipped, cancelled, completed). Implements requirement for full order lifecycle management. 3NF by isolating state as atomic value.
  status String

  /// Timestamp of order creation - Implements audit and analytics requirements. Ensures non-redundant atomic values (3NF). Used for event ordering and tracing.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last modification - For audit and compliance reporting. Maintains temporal integrity and normalization.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)
  channel  shopping_mall_ai_channels  @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_order_items   shopping_mall_ai_order_items[]
  shopping_mall_ai_payments      shopping_mall_ai_payments[]
  shopping_mall_ai_shipments     shopping_mall_ai_shipments[]
  shopping_mall_ai_coupon_events shopping_mall_ai_coupon_events[]
  shopping_mall_ai_reviews       shopping_mall_ai_reviews[]

  @@index([shopping_mall_ai_customer_id, created_at], map: "shopping_mall_ai_orders_shopping_mall_ai_customer_id_c_31422ac8")
  @@index([shopping_mall_ai_channel_id, created_at], map: "shopping_mall_ai_orders_shopping_mall_ai_channel_id_cr_0e483ae2")
}

/// Atomic breakdown for each product or SKU included in an order - Implements the requirement for line-item auditability and support for returns/analytics. Each row represents one discrete unit, normalized by separating all product/item info. Business purpose: supports quantity, price, and option-specific fulfillment, enabling precise return/cancel handling. Technical context: references order, product, and option from respective domains. Maintains strict 3NF. Used for inventory deduction, refund calculations, and SKU-level reporting. Key relationships: parent order, product/option, possibly option for variants. Special behaviors: status tracking for line-level returns/exchanges.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for each order item, enforcing atomicity and referential integrity.
  id String @id @db.Uuid

  /// Link to parent order's {@link shopping_mall_ai_orders.id} for 1:N relationship. Maintains strict normalization.
  shopping_mall_ai_order_id String @db.Uuid

  /// Reference to the purchased product. Ties to {@link shopping_mall_ai_products.id} from ProductCatalog. Allows accurate analytics and inventory management.
