  moderator shopping_mall_ai_admins @relation(fields: [shopping_mall_ai_admin_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_content_moderations_shopping_mall_ai__fb2e260a")

  @@index([shopping_mall_ai_admin_id], map: "shopping_mall_ai_content_moderations_shopping_mall_ai__90f4f709")
  @@index([content_type, content_id], map: "shopping_mall_ai_content_moderations_content_type_cont_972be893")
