model shopping_mall_ai_ai_content_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Content type: one of modeled values, e.g., 'bbs_post', 'review', etc. Used for AI scan traceability. Normalized—never denormalized.
