  /// Target ID of content object being audited. Maintains normalized reference for per-entity audit.
  content_id String @db.Uuid

  /// Detected violation type (e.g., 'spam', 'profanity', 'personal_info'). Normalized atomic string.
  violation_type String

  /// Confidence level as probability between 0.0 and 1.0. Atomic double value; not cached/precalculated from other tables.
  confidence Float @db.DoublePrecision

  /// Suggested action (e.g., 'review', 'block', 'accept'). Output from AI scan; normalized field—never derived.
