schemas.schema-09-compliance.prisma:
/// Audit log records for all cross-domain actions, operations, or compliance events—implements regulatory and legal audit trail requirements per Compliance documents. Enables tracing of operations for every business entity and actor. Maintains strict 3NF (each log atomic, referencing actor and entity only). Usage example: reviewing all changes to a specific order. Key relationships: entity_type/entity_id can reference any business domain; actor_id links to customer/seller/admin. Special behaviors: soft delete for retention, dense indexing for high-volume compliance queries.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Type of business object affected—implements requirement for domain/entity-level audit visibility. Fully normalized; entity_type/ID pattern allows reference to any object. For example: 'order', 'product'.
  entity_type String

  /// ID of the affected business object—supports traceability across domains. Remains atomic and normalized. Example: review all actions on a given order or file.
  entity_id String

  /// Performs identity linkage for audit—can be customer, seller, admin, or null (system/automated action). Enables complete operation tracing as per compliance. Nullable for system/process events.
  actor_id String?

  /// Role of actor performing operation (customer, seller, admin, system)—has business meaning for compliance reviews. Remains strictly normalized; no embedding of user/role details.
  actor_role String

  /// Type of operation performed (e.g., 'update', 'delete')—traces required compliance event type. Business purpose: supports granular auditability. 3NF via atomic string.
  operation String

  /// Detail record of the change—implements requirement for before/after or diff storage for historical trace. Example: serialized change diff. Remains atomic; no calculated data.
  detail String

  /// Timestamp for event—required for legal/compliance retention/timelines. Business process: used in audit investigation. 3NF compliance.
  occurred_at DateTime @db.Timestamptz

  /// IP/session/context—enriches compliance record for origin investigation. Nullable. 1NF/3NF; only atomic context info. Example: trace suspicious activity origin.
  context String?

  /// Soft deletion marker for audit/log retention cycle. Implements legal/business purge/retention. Remains atomic per 1NF. Nullable, not calculated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([entity_type, entity_id])
  @@index([actor_id, occurred_at])
}

/// Policy document change/version audit records—implements legal requirement to track all changes to business-critical compliance documents (per 09_shopping-mall-ai_business-rules-compliance.md). 3NF normalized: each record is a single policy change/version, no embedded or derived fields. Example: Viewing policy modification history. Key relationships: policy_code/policy_version—external reference to published docs. Special: unique constraint on (policy_code, policy_version).
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_policy_changes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Policy/document code—requirement aspect: enables document-level traceability and unique change history. Fully normalized, atomic.
  policy_code String

  /// Changed-to version number of the policy—fulfilling traceability and version audit requirements. Atomic, normalized. Example: 'v1.2'.
  policy_version String

  /// Summary of business/content change—directly implements audit/documentation requirement. 3NF: not precomputed; no denormalization. Example: 'Added GDPR compliance section.'
  change_summary String

  /// Admin/actor approving change—direct requirement tracing for signoff. Follows 3NF: only ID. Example: admin UUID.
  approved_by String

  /// Timestamp of change approval—EARS-derived retention requirement. Strictly atomic; key to compliance trails.
  approved_at DateTime @db.Timestamptz

  /// If policy was updated, this links to the prior version. Nullable for initial issue. Normalization rationale: only the prior version, not full version tree.
  previous_version String?

  /// Soft deletion (retention lifecycle/cycle). Regulatory requirement for delayed/purge states. Not calculated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([policy_code, policy_version])
  @@index([approved_by, approved_at])
}

/// Legal consent/acceptance records for any user/actor (customer, seller, admin)—fulfills the legal/regulatory requirement to capture timestamped, versioned consents as per 09_shopping-mall-ai_business-rules-compliance.md and audit trail needs. 3NF compliance: each consent is atomic for a single version/policy per user. Example usage: proving opt-in for privacy policy required by regulators. Key constraints: unique (user, policy, version)—each consent distinct. Special: supports withdrawal, consent IP trace.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_legal_consents {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User/actor ID—requirement mapping for cross-actor (customer/seller/admin) consents. Fully normalized; not embedded. Usage: join with any actor table for full consent trace.
  user_id String

  /// Code of the compliance document agreed to. Implements document-specific consent requirement. Atomic/normalized.
  policy_code String

  /// Version of policy consented—tracks which version user agreed to. Fully normalized, atomic. Example: 'v2.0'.
  policy_version String

  /// Consent timestamp—fulfills regulatory/certification audit needs. Strict 3NF, atomic per event.
  consented_at DateTime @db.Timestamptz

  /// Path/method of consent (user, admin, migrated import)—direct EARS requirement mapping. Normalization: maintains method axis atomically.
  consent_method String

  /// If consent was withdrawn: timestamp. Implements withdrawal tracking or GDPR 'right to be forgotten'. Null if not withdrawn. 1NF/3NF rationale. Example: lawfully revoke consent.
  withdrawn_at DateTime? @db.Timestamptz

  /// IP at time of consent; business/compliance requirement for traceability. Atomic and nullable (may not be present for batch/admin).
  consent_ip String?

  /// Soft deletion marker; supports retention policy cycles. Atomic/nullable per event. Compliance: legal deletion lag.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([user_id, policy_code, policy_version], map: "shopping_mall_ai_legal_consents_user_id_policy_code_po_d3422dde")
  @@index([policy_code, policy_version])
}

/// Analytics/data export operation logs—meet requirements for business intelligence export traceability and legal data release reporting (see Compliance module requirements). Maintains full audit trace for all generated data sets, supporting proof of compliance for audit/eDiscovery. Strict 3NF: each export is atomic; no aggregates. Usage: reviewing export process history. Special: data retention cycles, status field for workflow/audit, detailed index for export process correlation.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_analytics_exports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Type/category of analytics export. Requirement mapping: supports granular legal/biz reporting for each export subtype. Atomic, never calculated. Example: 'user_activity'.
  export_type String

  /// Business justification/context for export—implements requirement for reason trace on audit. Strict 3NF; never pre-populated/cached. Example: 'regulator request Q1'.
  export_reason String

  /// Export location reference (file path, URI)—necessary for legal trace/audit of data location. 3NF: strictly atomic URI, not derived.
  export_uri String

  /// Actor (user/admin/system) requesting export—core to audit trail (requirement). Always atomic, fully normalized for referential trace.
  requested_by String

  /// Timestamp for export completed. Regulatory/audit requirement for data release timeline.
  exported_at DateTime @db.Timestamptz

  /// If retention/expiry required, deletion date marker. Null implies indefinite retention. Audited for compliance cycles. 1NF/3NF compliance rationale.
  delete_after DateTime? @db.Timestamptz

  /// Status of export record—supports audit workflow, exception tracking (pending, completed, failed, archived). Atomic business field for compliance reporting. Example: use to trigger further audit or data retention events.
  status String

  /// Soft deletion for indefinite record lifecycle/regulatory purges. Strict 3NF compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([export_type, export_reason], map: "shopping_mall_ai_analytics_exports_export_type_export__a76d4ad0")
  @@index([requested_by, exported_at])
}

