import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiLegalConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiLegalConsent";

/**
 * Verify customer consent withdrawal on a legal document policy and audit
 * trail.
 *
 * This test ensures that a customer can withdraw their consent for a
 * previously-agreed policy document and that audit fields are updated
 * accordingly. The business significance is to comply with privacy requirements
 * (e.g., GDPR) and ensure that legal consent records have correct withdrawn
 * status and timestamps for auditability.
 *
 * Steps:
 *
 * 1. Create a legal consent record for a user (simulate a fresh agreement for a
 *    policy version).
 * 2. Immediately perform an update using the PUT endpoint to withdraw the consent
 *    (set withdrawn_at timestamp and, optionally, method/IP updates).
 * 3. Assert that the returned record reflects withdrawal: withdrawn_at is not null
 *    (recent timestamp) and matches the input, and the rest of the audit fields
 *    retain correct values (policy_code, policy_version, consented_at).
 * 4. Confirm that withdrawn_at is greater than or equal to original consented_at.
 * 5. Confirm soft deletion is not set (deleted_at remains null) on withdrawal
 *    update, as this is not compliance erasure.
 */
export async function test_api_shopping_mall_ai_customer_legalConsents_test_update_legal_consent_withdraw_by_customer(
  connection: api.IConnection,
) {
  // 1. Register a legal consent as a customer
  const consentCreateInput: IShoppingMallAiLegalConsent.ICreate = {
    user_id: typia.random<string>(),
    policy_code: RandomGenerator.alphaNumeric(8),
    policy_version: RandomGenerator.alphaNumeric(4),
    consented_at: new Date().toISOString(),
    consent_method: "user",
    consent_ip: "127.0.0.1",
  };

  const created: IShoppingMallAiLegalConsent =
    await api.functional.shopping_mall_ai.customer.legalConsents.create(
      connection,
      { body: consentCreateInput },
    );
  typia.assert(created);
  TestValidator.equals("initial consent user_id matches")(created.user_id)(
    consentCreateInput.user_id,
  );
  TestValidator.equals("initial consent policy_code matches")(
    created.policy_code,
  )(consentCreateInput.policy_code);
  TestValidator.equals("initial consent policy_version matches")(
    created.policy_version,
  )(consentCreateInput.policy_version);
  TestValidator.equals("initial consent consented_at matches")(
    created.consented_at,
  )(consentCreateInput.consented_at);
  TestValidator.equals("initial consent consent_method matches")(
    created.consent_method,
  )(consentCreateInput.consent_method);
  if (consentCreateInput.consent_ip)
    TestValidator.equals("initial consent consent_ip matches")(
      created.consent_ip,
    )(consentCreateInput.consent_ip);

  // 2. Withdraw the consent via PUT
  const withdrawalTimestamp = new Date(Date.now() + 1000).toISOString(); // Ensure it's after consented_at
  const updateInput: IShoppingMallAiLegalConsent.IUpdate = {
    withdrawn_at: withdrawalTimestamp,
    consent_method: "user-withdrawal",
  };

  const updated: IShoppingMallAiLegalConsent =
    await api.functional.shopping_mall_ai.customer.legalConsents.update(
      connection,
      { legalConsentId: created.id, body: updateInput },
    );
  typia.assert(updated);

  // 3. Confirm update: withdrawn_at is set and matches, audit fields remain unchanged
  TestValidator.equals("withdrawn_at is set")(updated.withdrawn_at)(
    withdrawalTimestamp,
  );
  TestValidator.equals("audit id retained")(updated.id)(created.id);
  TestValidator.equals("policy_code retained")(updated.policy_code)(
    created.policy_code,
  );
  TestValidator.equals("policy_version retained")(updated.policy_version)(
    created.policy_version,
  );
  TestValidator.equals("consented_at retained")(updated.consented_at)(
    created.consented_at,
  );
  TestValidator.equals("user_id retained")(updated.user_id)(created.user_id);

  // 4. Confirm withdrawn_at is after or equal to consented_at
  TestValidator.predicate("withdrawn_at >= consented_at")(
    new Date(updated.withdrawn_at!).getTime() >=
      new Date(created.consented_at).getTime(),
  );

  // 5. deleted_at remains null (not erased by withdrawal)
  TestValidator.equals("deleted_at should remain null after withdrawal")(
    updated.deleted_at ?? null,
  )(null);
}

