import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiLegalConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiLegalConsent";

/**
 * Validate that customers cannot update legal consent records that do not
 * belong to them.
 *
