 *   pagination and data integrity.
 * - Validate that export logs are not accessible by non-admins (access control
 *   enforced).
 *
 * Business context:
 *
 * - Admin/compliance teams rely on this API to audit historical analytics export
 *   events.
 * - Prevents unauthorized viewing of sensitive export logs by non-admin users.
 *
 * Steps:
 *
 * 1. Register several analytics export records as an admin.
 * 2. Retrieve analytics export logs as an admin, verifying record presence and
 *    field correctness.
 * 3. Confirm all created logs are listed and all fields match.
 * 4. Attempt to list exports as a non-admin (simulate by connection header
 *    permission removal), and expect denial.
 */
export async function test_api_shopping_mall_ai_admin_analyticsExports_index_test_list_analytics_exports_pagination_and_admin_scope(
  connection: api.IConnection,
) {
  // 1. Register multiple analytics export records as an admin
  const createdExports: IShoppingMallAiAnalyticsExport[] = [];
  for (let i = 0; i < 3; ++i) {
    const record: IShoppingMallAiAnalyticsExport =
      await api.functional.shopping_mall_ai.admin.analyticsExports.create(
        connection,
        {
          body: {
            export_type: `user_activity_${i}`,
            export_reason: `compliance_test_${i}`,
            export_uri: `/exports/data/log_${i}.csv`,
            requested_by: `admin_${i}@company.com`,
            exported_at: new Date(Date.now() - i * 3600000).toISOString(),
            delete_after: null,
            status: "completed",
          } satisfies IShoppingMallAiAnalyticsExport.ICreate,
        },
      );
    typia.assert(record);
    createdExports.push(record);
  }

  // 2. Retrieve analytics export logs list as admin
  const result: IPageIShoppingMallAiAnalyticsExport =
    await api.functional.shopping_mall_ai.admin.analyticsExports.index(
      connection,
    );
  typia.assert(result);
  TestValidator.predicate("returns at least as many as inserted exports")(
    result.data.length >= createdExports.length,
  );

  // 3. Verify each created record appears, and all fields match
  for (const created of createdExports) {
    const found = result.data.find((r) => r.id === created.id);
    TestValidator.predicate("created export is listed")(!!found);
    TestValidator.equals("export_type matches")(found?.export_type)(
      created.export_type,
    );
    TestValidator.equals("export_reason matches")(found?.export_reason)(
      created.export_reason,
    );
    TestValidator.equals("export_uri matches")(found?.export_uri)(
      created.export_uri,
    );
    TestValidator.equals("requested_by matches")(found?.requested_by)(
      created.requested_by,
    );
    TestValidator.equals("status matches")(found?.status)(created.status);
  }

  // 4. Attempt to list exports as a non-admin
  const nonAdminConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  if (nonAdminConnection.headers && nonAdminConnection.headers.Authorization)
    delete nonAdminConnection.headers.Authorization;
  await TestValidator.error("access denied for non-admin")(async () => {
    await api.functional.shopping_mall_ai.admin.analyticsExports.index(
      nonAdminConnection as api.IConnection,
    );
  });
}

