import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validate listing all cart items for a customer's own cart (by owner).
 *
 * This test ensures that when a customer creates a cart and adds items to it,
 * querying the cart's items returns exactly what was added, accurately and
 * completely. It covers the full workflow from cart creation, cart item
 * addition, to cart item retrieval and validation.
 *
 * Test steps:
 *
 * 1. Create a new cart for the customer.
 * 2. Add multiple distinct items to the cart.
 * 3. Retrieve the list of cart items using the cartId.
 * 4. Validate that all items are present, with correct product references,
 *    quantities, and belonging to the correct cart.
 */
export async function test_api_shopping_mall_ai_customer_carts_cartItems_test_list_cart_items_for_valid_cart_by_owner(
  connection: api.IConnection,
) {
  // 1. Create a new cart for the customer (as guest or customer, per available API context)
  const cartBody: IShoppingMallAiCart.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    { body: cartBody },
  );
  typia.assert(cart);

  // 2. Add multiple distinct items to the cart
  const itemCount = 3;
  const addedItems = await ArrayUtil.asyncRepeat(itemCount)(async () => {
    const productId = typia.random<string & tags.Format<"uuid">>();
    const quantity = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1>
    >();
    const body: IShoppingMallAiCartItem.ICreate = {
      shopping_mall_ai_cart_id: cart.id,
      shopping_mall_ai_product_id: productId,
      quantity,
    };
    const item =
      await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
        connection,
        {
          cartId: cart.id,
          body,
        },
      );
    typia.assert(item);
    return item;
  });

  // 3. Retrieve the list of cart items
  const page =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.index(
      connection,
      { cartId: cart.id },
    );
  typia.assert(page);

  // 4. Validate all cart items are present and match what was added
  TestValidator.equals("Number of cart items")(page.data.length)(itemCount);

  for (const addedItem of addedItems) {
    const found = page.data.find((x) => x.id === addedItem.id);
    TestValidator.predicate(`Cart item exists: ${addedItem.id}`)(!!found);
    if (found) {
      TestValidator.equals("cart id matches")(found.shopping_mall_ai_cart_id)(
        cart.id,
      );
      TestValidator.equals("product id matches")(
        found.shopping_mall_ai_product_id,
      )(addedItem.shopping_mall_ai_product_id);
      TestValidator.equals("quantity matches")(found.quantity)(
        addedItem.quantity,
      );
    }
  }
}

