import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";
import type { IPageIShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching/filtering items in a customer's shopping cart by product ID
 * and quantity criteria.
 *
 * This test performs an end-to-end user flow to validate the cart item search
 * with filtering options for product ID and quantity window. It ensures that
 * when the customer populates a cart with multiple items (with different
 * product IDs and quantities), then filters by a specific product ID and
 * quantity window, only the matching cart items are returned.
 *
 * Steps:
 *
 * 1. Create a customer shopping cart via the customer cart creation endpoint.
 * 2. Add several items to this cart, making sure:
 *
 *    - At least one product ID is used for multiple items with different quantities.
 *    - Other items use distinct product IDs and quantities.
 * 3. Select a product ID that occurs in at least two cart items with different
 *    quantities.
 * 4. Search cart items with the filter for that product ID and check for matching
 *    quantities in test logic.
 * 5. Verify only the correct cart item(s) are returned by the search.
 * 6. Search for an unrelated product ID to validate negative case.
 */
export async function test_api_shopping_mall_ai_customer_carts_cartItems_search_by_product_id_and_quantity_range(
  connection: api.IConnection,
) {
  // 1. Create a customer cart
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cart);

  // 2. Add multiple cart items
  const productIdForFilter = typia.random<string & tags.Format<"uuid">>();
  const otherProductId = typia.random<string & tags.Format<"uuid">>();
  const quantityA = 2;
  const quantityB = 3;
  // Add two items with same product ID but different quantities
  const itemA =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productIdForFilter,
          quantity: quantityA,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(itemA);
  const itemB =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productIdForFilter,
          quantity: quantityB,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(itemB);
  // Add an item with different product ID
  const itemOther =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: otherProductId,
          quantity: 5,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(itemOther);

  // 3. Search for items with selected product ID
  const response =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_product_id: productIdForFilter,
        } satisfies IShoppingMallAiCartItem.IRequest,
      },
    );
  typia.assert(response);
  // Ensure each result in the data array has the target product ID
  TestValidator.predicate("all results have the correct product ID")(
    response.data.every(
      (item) => item.shopping_mall_ai_product_id === productIdForFilter,
    ),
  );
  // Filter by quantityA
  const filteredA = response.data.filter((item) => item.quantity === quantityA);
  TestValidator.equals("should return only one item with quantityA")(
    filteredA.length,
  )(1);
  TestValidator.equals("correct itemA is returned")(filteredA[0].id)(itemA.id);
  // Filter by quantityB
  const filteredB = response.data.filter((item) => item.quantity === quantityB);
  TestValidator.equals("should return only one item with quantityB")(
    filteredB.length,
  )(1);
  TestValidator.equals("correct itemB is returned")(filteredB[0].id)(itemB.id);

  // 4. Search for unrelated product ID; expect zero results
  const responseUnrelated =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IShoppingMallAiCartItem.IRequest,
      },
    );
  typia.assert(responseUnrelated);
