/**
 * Test the successful deletion of a file attachment by an admin.
 *
 * Validates that an admin user can permanently (hard) delete a file attachment
 * record, ensuring the record is removed and cannot be operated on a second
 * time. This test also confirms that referential integrity is maintained: the
 * file remains in the system after its attachment is deleted. Direct retrieval
 * of deleted attachment is not possible as no GET/list endpoint exists, so
 * verification is done by asserting a second delete fails.
 *
 * **Test Workflow:**
 *
 * 1. Register a new file in the system (file metadata).
 * 2. Create a file attachment linking the saved file to a test business object.
 * 3. Perform the hard delete operation (admin file attachment erase).
 * 4. Attempt to delete again and assert error occurs (ensures proper deletion).
 * 5. Comment: File persists after attachment deletion (referential integrity). If
 *    a file GET endpoint existed, would verify directly.
 */
export async function test_api_shopping_mall_ai_admin_fileAttachments_erase_success(
  connection: api.IConnection,
) {
  // 1. Register a new file with required metadata
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      {
        body: {
          original_name: RandomGenerator.alphaNumeric(12) + ".jpg",
          uri: `https://cdn.example.com/file/${typia.random<string & tags.Format<"uuid">>()}`,
          extension: "jpg",
          mime_type: "image/jpeg",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1000> &
              tags.Maximum<5000000>
          >(),
          hash: RandomGenerator.alphaNumeric(32),
          actor_type: "admin",
          actor_id: typia.random<string & tags.Format<"uuid">>(),
        } satisfies IShoppingMallAiFile.ICreate,
      },
    );
  typia.assert(file);

  // 2. Create a file attachment linking the file to a dummy business entity
  const targetId = typia.random<string & tags.Format<"uuid">>();
  const fileAttachment =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          shopping_mall_ai_media_asset_id: null,
          target_type: "test_object",
          target_id: targetId,
          attached_at: new Date().toISOString(),
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(fileAttachment);

  // 3. Perform the delete operation as admin on the attachment record
  await api.functional.shopping_mall_ai.admin.fileAttachments.erase(
    connection,
    {
      fileAttachmentId: fileAttachment.id,
    },
  );

  // 4. Verify that the record cannot be deleted again (should trigger error)
  await TestValidator.error(
    "File attachment should not be found after deletion",
  )(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.erase(connection, {
      fileAttachmentId: fileAttachment.id,
    }),
  );

  // 5. Referential integrity check (file remains; direct check not possible due to lack of file retrieval endpoint)
  //    If file read API existed, we would assert file still exists here.
}

