import type { IPageIShoppingMallAiFileAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFileAccessLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiFileAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAccessLog";

/**
 * Validates that an admin user can successfully retrieve the paginated list of
 * file access logs including content and metadata verification.
 *
 * This test ensures that file access audit events are being properly recorded
 * and retrievable for compliance/audit dashboard scenarios. The test will:
 *
 * 1. Create multiple unique file metadata records as an admin—this triggers file
 *    registration into the system.
 * 2. For each file, create 2+ associated file access logs (events), simulating
 *    e.g., 'view', 'download' actions, with varied actor_type, access_type, and
 *    event metadata.
 * 3. Call the GET fileAccessLogs API as admin to list all logs (paginated).
 * 4. Assert that the returned logs include all newly created log entries with the
 *    correct actor type, access type, file linkage, and pagination.
 * 5. Optionally, check at least one log has the expected admin actor context and
 *    event type, and at least one log for each event type we produced.
 */
export async function test_api_shopping_mall_ai_admin_fileAccessLogs_test_list_file_access_logs_as_admin_success(
  connection: api.IConnection,
) {
  // 1. Create 2 file metadata records
  const files = await ArrayUtil.asyncRepeat(2)(async () => {
    const file =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
        connection,
        {
          body: {
            original_name: RandomGenerator.alphaNumeric(10),
            uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(12)}`,
            extension: "pdf",
            mime_type: "application/pdf",
            size: typia.random<number & tags.Type<"int32">>(),
            hash: RandomGenerator.alphaNumeric(32),
            actor_type: "admin",
            actor_id: null,
          } satisfies IShoppingMallAiFile.ICreate,
        },
      );
    typia.assert(file);
    return file;
  });

  // 2. For each file, create 2 access logs with varied event metadata
  const eventTypes = [
    { access_type: "view", channel: "web" },
    { access_type: "download", channel: "api" },
  ];

  const createdLogs: IShoppingMallAiFileAccessLog[] = [];
  for (const file of files) {
    for (const evt of eventTypes) {
      const log =
        await api.functional.shopping_mall_ai.admin.fileAccessLogs.create(
          connection,
          {
            body: {
              shopping_mall_ai_file_id: file.id,
              actor_type: "admin",
              actor_id: null,
              access_type: evt.access_type,
              channel: evt.channel,
              outcome: "success",
              ip_address: "127.0.0.1",
              accessed_at: new Date().toISOString(),
            } satisfies IShoppingMallAiFileAccessLog.ICreate,
          },
        );
      typia.assert(log);
      createdLogs.push(log);
    }
  }

  // 3. Retrieve the file access logs as admin
  const logsPage =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.index(
      connection,
    );
  typia.assert(logsPage);

  // 4. Assert: All created logs are included in the results
  const resultIds = logsPage.data.map((l) => l.id);
  for (const log of createdLogs) {
    TestValidator.predicate(`should include created log with id ${log.id}`)(
      resultIds.includes(log.id),
    );
    // Additional content validation
    const resultLog = logsPage.data.find((l) => l.id === log.id);
    if (resultLog) {
      TestValidator.equals("actor_type matches")(resultLog.actor_type)(
        log.actor_type,
      );
      TestValidator.equals("access_type matches")(resultLog.access_type)(
        log.access_type,
      );
      TestValidator.equals("shopping_mall_ai_file_id matches")(
        resultLog.shopping_mall_ai_file_id,
      )(log.shopping_mall_ai_file_id);
    }
  }

  // 5. Pagination: at least expected number of logs and fields correct
  TestValidator.predicate(
    "pagination.records includes at least as many logs as created",
  )(logsPage.pagination.records >= createdLogs.length);
  TestValidator.predicate("pagination.data is non-empty")(
    logsPage.data.length > 0,
  );
}

