      actor_id: actors[1].id,
      access_type: "download",
      channel: "web",
      outcome: "success",
      ip_address: "10.0.0.5",
      accessed_at: times[4].toISOString(),
    },
    {
      actor_type: actors[0].type,
      actor_id: actors[0].id,
      access_type: "download",
      channel: "api",
      outcome: "success",
      ip_address: "8.8.8.8",
      accessed_at: times[5].toISOString(),
    },
  ];

  // 2. Create each log via admin fileAccessLogs.create
  const createdLogs = [];
  for (const sample of logSamples) {
    const log =
      await api.functional.shopping_mall_ai.admin.fileAccessLogs.create(
        connection,
        {
          body: {
            shopping_mall_ai_file_id: file.id,
            actor_type: sample.actor_type,
            actor_id: sample.actor_id,
            access_type: sample.access_type,
            channel: sample.channel,
            outcome: sample.outcome,
            ip_address: sample.ip_address,
            accessed_at: sample.accessed_at,
          } satisfies IShoppingMallAiFileAccessLog.ICreate,
        },
      );
    typia.assert(log);
    createdLogs.push(log);
  }

  // 3. Search by actor_type (e.g., 'admin')
  const actorType = "admin";
  const res1 =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.search(
      connection,
      {
        body: {
          actor_type: actorType,
          limit: 100,
          page: 1,
        } satisfies IShoppingMallAiFileAccessLog.IRequest,
      },
    );
  typia.assert(res1);
  for (const entry of res1.data) {
    TestValidator.equals("actor_type filter")(entry.actor_type)(actorType);
  }

  // 4. Search by a date range (covering only times[2] ~ times[4])
  const dateFrom = times[2].toISOString();
  const dateTo = times[4].toISOString();
  const res2 =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.search(
      connection,
      {
        body: {
          date_from: dateFrom,
          date_to: dateTo,
          limit: 100,
          page: 1,
        } satisfies IShoppingMallAiFileAccessLog.IRequest,
      },
    );
  typia.assert(res2);
  for (const entry of res2.data) {
    const entryTime = new Date(entry.accessed_at).getTime();
    TestValidator.predicate("date range filter")(
      entryTime >= new Date(dateFrom).getTime() &&
        entryTime <= new Date(dateTo).getTime(),
    );
  }

  // 5. Search by channel ('api') and outcome ('denied')
  const res3 =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.search(
      connection,
      {
        body: {
          channel: "api",
          outcome: "denied",
          limit: 100,
          page: 1,
        } satisfies IShoppingMallAiFileAccessLog.IRequest,
      },
    );
  typia.assert(res3);
  for (const entry of res3.data) {
    TestValidator.equals("channel filter")(entry.channel)("api");
    TestValidator.equals("outcome filter")(entry.outcome)("denied");
  }

  // 6. Precise file_id & ip_address search (should match only specific log)
  const specificLog = createdLogs.find((log) => log.ip_address === "8.8.8.8");
  if (specificLog) {
    const res4 =
      await api.functional.shopping_mall_ai.admin.fileAccessLogs.search(
        connection,
        {
          body: {
            file_id: file.id,
            ip_address: "8.8.8.8",
            limit: 100,
            page: 1,
          } satisfies IShoppingMallAiFileAccessLog.IRequest,
        },
      );
    typia.assert(res4);
    TestValidator.equals("file_id match")(res4.data.length)(1);
    TestValidator.equals("ip_address match")(res4.data[0].ip_address)(
      "8.8.8.8",
    );
    TestValidator.equals("id match")(res4.data[0].id)(specificLog.id);
  }

  // 7. Confirm pagination fields and structure in each response
  [res1, res2, res3].forEach((res, idx) => {
    TestValidator.predicate(`pagination - page ${idx + 1}`)(
      typeof res.pagination.current === "number" && res.pagination.current > 0,
    );
    TestValidator.predicate(`pagination - limit ${idx + 1}`)(
      typeof res.pagination.limit === "number" && res.pagination.limit > 0,
    );
    TestValidator.predicate(`pagination - total pages ${idx + 1}`)(
      typeof res.pagination.pages === "number" && res.pagination.pages >= 1,
    );
    TestValidator.predicate(`pagination - total records ${idx + 1}`)(
      typeof res.pagination.records === "number" && res.pagination.records >= 1,
    );
  });
}

