import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";

/**
 * Validate that attempting to update immutable fields of a product option via
 * admin results in an appropriate error.
 *
 * This test ensures the backend enforces the restriction that product options
 * cannot be reassigned (their parent product reference cannot be changed).
 *
 * Steps:
 *
 * 1. Create two products to set up the scenario—one original and one forbidden
 *    target
 * 2. Create a product option for the original product
 * 3. Attempt to update the product option, trying to change allowed fields and
 *    (conceptually) forbidden immutable field (the product reference)
 * 4. Verify that you cannot include immutable fields in the update request, as
 *    they are not part of the update DTO
 * 5. Confirm that only permitted fields can be updated, and attempts to mutate
 *    immutable references result in TypeScript or backend errors
 * 6. (No after-state verification, as endpoint for reload is not available)
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiProductOptions_test_update_product_option_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a new product category and seller UUIDs for association (simulated foreign keys)
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const seller_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create product A
  const productA =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: category_id,
          title: "Product A",
          description: "First product for option association",
          price: 1000,
          status: "active",
          sku: `SKU-A-${typia.random<string>()}`,
        },
      },
    );
  typia.assert(productA);

  // 3. Create product B (for forbidden reference attempt)
  const productB =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: category_id,
          title: "Product B",
          description: "Second product (for invalid reassignment)",
          price: 1200,
          status: "active",
          sku: `SKU-B-${typia.random<string>()}`,
        },
      },
    );
  typia.assert(productB);

  // 4. Register a product option against productA
  const option =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productA.id,
          name: "Color",
          value: "Red",
          option_sku: `OPT-RED-${typia.random<string>()}`,
        },
      },
    );
  typia.assert(option);

  // 5. Attempt to update the product option, including an allowed field, and conceptually (not in code) an immutable field
  // Because the IUpdate DTO does not include shopping_mall_ai_product_id, TypeScript will not allow it to be present
  // Backend should also reject extra properties or silently ignore (either is safe)
  // So we can only check that an update with only allowed fields succeeds, and the compiler blocks forbidden ones
  await TestValidator.error("immutable field cannot be updated")(() =>
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.update(
      connection,
      {
        shoppingMallAiProductOptionId: option.id,
        // Only allowed fields are present according to IUpdate
        body: {
          // updating an allowed field
          name: "Size",
          // attempting to add shopping_mall_ai_product_id here would be a TS error—not allowed
        },
      },
    ),
  );
  // 6. No reload endpoint for further validation; test complete at error assertion step.
}

