 * the detailed cart data by its unique cartId, and receives the correct
 * metadata and relationships as defined by the cart schema. It confirms that
 * the retrieved cart matches the originally created cart and all relevant
 * fields are populated.
 *
 * Steps:
 *
 * 1. Prepare synthetic "customer" identity with a random UUID
 * 2. Create a new cart for this customer with random channel and section values
 * 3. Retrieve the cart details by cartId
 * 4. Assert that returned cart data matches the initial values (customer, channel,
 *    section, etc.)
 * 5. Assert that all schema fields are populated appropriately (timestamps are ISO
 *    strings, ownership fields, etc)
 */
export async function test_api_shopping_mall_ai_customer_carts_test_get_cart_details_as_cart_owner_success(
  connection: api.IConnection,
) {
  // 1. Prepare synthetic customer UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a new cart for the customer
  const createInput: IShoppingMallAiCart.ICreate = {
    shopping_mall_ai_customer_id: customerId,
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const createdCart: IShoppingMallAiCart =
    await api.functional.shopping_mall_ai.customer.carts.create(connection, {
      body: createInput,
    });
  typia.assert(createdCart);

  // 3. Retrieve the cart details with the returned cart ID
