import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Advanced search for file attachments by target_type, pagination, and
 * validation
 *
 * This test validates the advanced search capabilities of the shopping mall
 * file attachment admin API.
 *
 * Steps:
 *
 * 1. Prepare two file attachment records: one for target_type 'product', one for
 *    'review', with different attached_at values.
 * 2. Search by target_type 'product' and verify only the 'product' attachment is
 *    returned.
 * 3. Search by target_type 'review' and verify only the 'review' attachment is
 *    returned.
 * 4. Use pagination (limit=1) and confirm only one record is returned, and test
 *    that page=2 returns the next one or empty set as appropriate.
 * 5. Use a non-existent target_type (e.g., 'non_existent_type') and verify
 *    response is empty.
 */
export async function test_api_shopping_mall_ai_admin_fileAttachments_test_search_file_attachments_by_target_type_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create attachment for 'product'
  const targetProductId = typia.random<string & tags.Format<"uuid">>();
  const attachProduct =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          shopping_mall_ai_media_asset_id: null,
          target_type: "product",
          target_id: targetProductId,
          attached_at: new Date(Date.now() - 10000).toISOString(),
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(attachProduct);

  // 2. Create attachment for 'review' with later attached_at
  const targetReviewId = typia.random<string & tags.Format<"uuid">>();
  const attachReview =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          shopping_mall_ai_media_asset_id: null,
          target_type: "review",
          target_id: targetReviewId,
          attached_at: new Date(Date.now()).toISOString(),
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(attachReview);

  // 3. Search for 'product' attachments
  const productSearch =
    await api.functional.shopping_mall_ai.admin.fileAttachments.search(
      connection,
      {
        body: {
          target_type: "product",
          target_id: targetProductId,
        } satisfies IShoppingMallAiFileAttachment.IRequest,
      },
    );
  typia.assert(productSearch);
  TestValidator.predicate("product search only returns product record")(
    productSearch.data.length === 1 &&
      productSearch.data[0].id === attachProduct.id &&
      productSearch.data[0].target_type === "product",
  );

  // 4. Search for 'review' attachments
  const reviewSearch =
    await api.functional.shopping_mall_ai.admin.fileAttachments.search(
      connection,
      {
        body: {
          target_type: "review",
          target_id: targetReviewId,
        } satisfies IShoppingMallAiFileAttachment.IRequest,
      },
    );
  typia.assert(reviewSearch);
  TestValidator.predicate("review search only returns review record")(
    reviewSearch.data.length === 1 &&
      reviewSearch.data[0].id === attachReview.id &&
      reviewSearch.data[0].target_type === "review",
  );

  // 5. Test pagination (limit=1)
  const allSearch =
    await api.functional.shopping_mall_ai.admin.fileAttachments.search(
      connection,
      {
        body: {
          limit: 1,
        } satisfies IShoppingMallAiFileAttachment.IRequest,
      },
    );
  typia.assert(allSearch);
  TestValidator.equals("pagination limit 1")(allSearch.pagination.limit)(1);
  TestValidator.equals("pagination page 1")(allSearch.pagination.current)(1);
  TestValidator.equals("page 1 record count")(allSearch.data.length)(1);

  // 6. Test next page (page=2)
  const nextPage =
    await api.functional.shopping_mall_ai.admin.fileAttachments.search(
      connection,
      {
        body: {
          limit: 1,
          page: 2,
        } satisfies IShoppingMallAiFileAttachment.IRequest,
      },
    );
  typia.assert(nextPage);
  TestValidator.equals("pagination page 2")(nextPage.pagination.current)(2);
  // Expect the second record or empty
  TestValidator.equals("page 2 record count")(nextPage.data.length)(1);

  // 7. Test non-existent target_type
  const noneSearch =
    await api.functional.shopping_mall_ai.admin.fileAttachments.search(
      connection,
      {
        body: {
          target_type: "non_existent_type",
        } satisfies IShoppingMallAiFileAttachment.IRequest,
      },
    );
  typia.assert(noneSearch);
  TestValidator.equals("no records for unknown target_type")(
    noneSearch.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAttachment";

/**
 * Validate retrieval of file attachment details via admin API.
 *
 * This test verifies that:
 *
 * 1. An admin can create a file attachment with various combinations of file/media
 *    asset references and target types (e.g., only file, only media asset, both
 *    null/one null, different target_type values).
 * 2. The file attachment details can be retrieved using its unique
 *    fileAttachmentId, matching all fields (ID, file/media asset IDs,
 *    target_type, target_id, attached_at) from the creation payload.
 * 3. Error handling is performed when a non-existent/invalid UUID is given (should
 *    return not-found or validation error).
 *
 * Test Steps:
 *
 * 1. Create a valid file attachment (file, media asset, target_type) via admin.
 * 2. Retrieve the attachment by its fileAttachmentId and verify all fields.
 * 3. Repeat with at least one attachment referencing a media asset instead of a
 *    file (and vice versa, if both are nullable).
 * 4. Attempt retrieval with a random UUID not present (should fail with not-found
 *    error).
 * 5. Attempt retrieval with an invalid UUID string (should fail with validation
 *    error).
 */
export async function test_api_shopping_mall_ai_admin_fileAttachments_test_get_file_attachment_detail_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create attachment referencing only a file
  const fileOnlyPayload: IShoppingMallAiFileAttachment.ICreate = {
    shopping_mall_ai_file_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_media_asset_id: null,
    target_type: "product",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    attached_at: new Date().toISOString(),
  };
  const fileAttachmentFile =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      { body: fileOnlyPayload },
    );
  typia.assert(fileAttachmentFile);

  // 2. Retrieve and validate
  const outputFile =
    await api.functional.shopping_mall_ai.admin.fileAttachments.at(connection, {
      fileAttachmentId: fileAttachmentFile.id,
    });
  typia.assert(outputFile);
  TestValidator.equals("file id")(outputFile.shopping_mall_ai_file_id)(
    fileOnlyPayload.shopping_mall_ai_file_id,
  );
  TestValidator.equals("media asset id")(
    outputFile.shopping_mall_ai_media_asset_id,
  )(fileOnlyPayload.shopping_mall_ai_media_asset_id);
  TestValidator.equals("target type")(outputFile.target_type)(
    fileOnlyPayload.target_type,
  );
  TestValidator.equals("target id")(outputFile.target_id)(
    fileOnlyPayload.target_id,
  );

  // 3. Create attachment referencing only a media asset
  const mediaAssetPayload: IShoppingMallAiFileAttachment.ICreate = {
    shopping_mall_ai_file_id: null,
    shopping_mall_ai_media_asset_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    target_type: "review",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    attached_at: new Date().toISOString(),
  };
  const fileAttachmentAsset =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      { body: mediaAssetPayload },
    );
  typia.assert(fileAttachmentAsset);

  // 4. Retrieve and validate
  const outputAsset =
    await api.functional.shopping_mall_ai.admin.fileAttachments.at(connection, {
      fileAttachmentId: fileAttachmentAsset.id,
    });
  typia.assert(outputAsset);
  TestValidator.equals("media asset id")(
    outputAsset.shopping_mall_ai_media_asset_id,
  )(mediaAssetPayload.shopping_mall_ai_media_asset_id);
  TestValidator.equals("file id")(outputAsset.shopping_mall_ai_file_id)(
    mediaAssetPayload.shopping_mall_ai_file_id,
  );
  TestValidator.equals("target type")(outputAsset.target_type)(
    mediaAssetPayload.target_type,
  );
  TestValidator.equals("target id")(outputAsset.target_id)(
    mediaAssetPayload.target_id,
  );

  // 5. Error: non-existent UUID (should fail with 404 or similar)
  await TestValidator.error("not found - non-existent fileAttachmentId")(
    async () => {
      await api.functional.shopping_mall_ai.admin.fileAttachments.at(
        connection,
        { fileAttachmentId: typia.random<string & tags.Format<"uuid">>() },
      );
    },
  );

  // 6. Error: invalid UUID string (should fail validation)
  await TestValidator.error("invalid UUID")(async () => {
    await api.functional.shopping_mall_ai.admin.fileAttachments.at(connection, {
      fileAttachmentId: "not-a-uuid" as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAttachment";

/**
 * Test successful creation of a file attachment by an admin, including all
 * referential integrity, required/optional field behavior, and error handling.
 *
 * This E2E test validates:
 *
 * 1. Admins can register files, then create attachments that link files to
 *    business objects.
 * 2. The attachment response returns all expected fields, correct file/business
 *    refs, and valid audit data.
 * 3. The system rejects attachments with (a) non-existent file/media asset IDs,
 *    (b) both file and media asset set, (c) both missing, and (d)
 *    missing/invalid business object references.
 *
 * Steps:
 *
 * 1. Register a file asset.
 * 2. Generate a mock business object reference (target_type + uuid).
 * 3. Attach the file to the object by creating an attachment.
 * 4. Validate all returned fields and referential integrity.
 * 5. Attempt to create invalid/missing/malformed attachments to check error
 *    handling (referential and business constraint enforcement).
 */
export async function test_api_shopping_mall_ai_admin_fileAttachments_test_create_file_attachment_with_valid_references(
  connection: api.IConnection,
) {
  // 1. Register a new file asset.
  const fileInput: IShoppingMallAiFile.ICreate = {
    original_name: "test_document.pdf",
    uri: `https://cdn.example.com/blob/${typia.random<string & tags.Format<"uuid">>()}`,
    extension: "pdf",
    mime_type: "application/pdf",
    size: 1024,
    hash: typia.random<string>(),
    actor_type: "admin",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const file = await api.functional.shopping_mall_ai.admin.files.create(
    connection,
    { body: fileInput },
  );
  typia.assert(file);

  // 2. Prepare a target business object (simulate a random UUID and a known valid type string).
  const target_type = "product";
  const target_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a file attachment linking the file to the business object.
  const attachmentInput: IShoppingMallAiFileAttachment.ICreate = {
    shopping_mall_ai_file_id: file.id,
    shopping_mall_ai_media_asset_id: null,
    target_type,
    target_id,
    attached_at: new Date().toISOString(),
  };
  const attachment =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      { body: attachmentInput },
    );
  typia.assert(attachment);
  TestValidator.equals("file ref")(attachment.shopping_mall_ai_file_id)(
    file.id,
  );
  TestValidator.equals("media asset unset")(
    attachment.shopping_mall_ai_media_asset_id,
  )(null);
  TestValidator.equals("target_type")(attachment.target_type)(target_type);
  TestValidator.equals("target_id")(attachment.target_id)(target_id);
  TestValidator.predicate("id is uuid")(
    !!attachment.id.match(
      /[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/i,
    ),
  );
  TestValidator.predicate("attached_at RFC3339")(
    typia.is<string & tags.Format<"date-time">>(attachment.attached_at),
  );

  // 4. Attempt: non-existent file reference (should error).
  const nonExistentFileId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent file reference")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.create(connection, {
      body: {
        shopping_mall_ai_file_id: nonExistentFileId,
        shopping_mall_ai_media_asset_id: null,
        target_type,
        target_id,
        attached_at: new Date().toISOString(),
      },
    }),
  );

  // 5. Attempt: missing file and media asset reference (should error).
  await TestValidator.error("missing file and media asset reference")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.create(connection, {
      body: {
        shopping_mall_ai_file_id: null,
        shopping_mall_ai_media_asset_id: null,
        target_type,
        target_id,
        attached_at: new Date().toISOString(),
      },
    }),
  );

  // 6. Attempt: both file and media asset references set (should error).
  await TestValidator.error("set both file and media asset reference")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.create(connection, {
      body: {
        shopping_mall_ai_file_id: file.id,
        shopping_mall_ai_media_asset_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        target_type,
        target_id,
        attached_at: new Date().toISOString(),
      },
    }),
  );

  // 7. Attempt: invalid business object reference (target_type empty, target_id random uuid).
  await TestValidator.error("empty target_type should error")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.create(connection, {
      body: {
        shopping_mall_ai_file_id: file.id,
        shopping_mall_ai_media_asset_id: null,
        target_type: "",
        target_id,
        attached_at: new Date().toISOString(),
      },
    }),
  );
  // 8. Attempt: invalid business object reference (target_id malformed: not uuid but non-empty string)
  await TestValidator.error("malformed target_id should error")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.create(connection, {
      body: {
        shopping_mall_ai_file_id: file.id,
        shopping_mall_ai_media_asset_id: null,
        target_type,
        target_id: "non-uuid-string",
        attached_at: new Date().toISOString(),
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAttachment";

/**
 * Test admin updating the target object (target_type and target_id) of a file
 * attachment.
 *
 * This test verifies that an admin can reassign a file attachment to a
 * different business object, and that changes are persisted and reflected in
 * subsequent retrievals. It also checks negative/validation flows: updating
 * with an invalid target_id or invalid target_type must fail. Steps:
 *
 * 1. Create a file attachment record (required setup).
 * 2. Update its target_type and target_id to new valid values and check the
 *    persistence of that change.
 * 3. Try to update with a non-existent target_id and expect a validation error.
 * 4. Try to update with an illegal target_type and expect a validation error.
 * 5. Confirm that audit fields (such as attached_at) are refreshed/updated on a
 *    successful mutation.
 */
export async function test_api_shopping_mall_ai_test_update_file_attachment_to_change_target_object(
  connection: api.IConnection,
) {
  // 1. Create initial file attachment to serve as the update target
  const initialAttachment =
    await api.functional.shopping_mall_ai.admin.fileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          shopping_mall_ai_media_asset_id: null,
          target_type: "product",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          attached_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(initialAttachment);

  // 2. Update the file attachment with new target_type and target_id
  const newTargetType = "review";
  const newTargetId = typia.random<string & tags.Format<"uuid">>();
  const updatedAttachment =
    await api.functional.shopping_mall_ai.admin.fileAttachments.update(
      connection,
      {
        fileAttachmentId: initialAttachment.id,
        body: {
          target_type: newTargetType,
          target_id: newTargetId,
          attached_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAttachment.IUpdate,
      },
    );
  typia.assert(updatedAttachment);
  TestValidator.equals("target_type updated")(updatedAttachment.target_type)(
    newTargetType,
  );
  TestValidator.equals("target_id updated")(updatedAttachment.target_id)(
    newTargetId,
  );
  TestValidator.predicate("attached_at updated")(
    updatedAttachment.attached_at !== initialAttachment.attached_at,
  );

  // 3. Try to update with a non-existent target_id (should fail)
  await TestValidator.error("update with invalid target_id should fail")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.update(connection, {
      fileAttachmentId: initialAttachment.id,
      body: {
        target_type: newTargetType,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        attached_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } satisfies IShoppingMallAiFileAttachment.IUpdate,
    }),
  );

  // 4. Try to update with an illegal target_type (should fail)
  await TestValidator.error("update with invalid target_type should fail")(() =>
    api.functional.shopping_mall_ai.admin.fileAttachments.update(connection, {
      fileAttachmentId: initialAttachment.id,
      body: {
        target_type: "illegal_type",
        attached_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } satisfies IShoppingMallAiFileAttachment.IUpdate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
