/**
 * Test retrieving a paginated list of all AI shopping mall product tags as an
 * admin.
 *
 * Validates that:
 *
 * - An admin can access the endpoint and retrieve a paginated response containing
 *   full product tag entity information.
 * - The response includes correct pagination info and complete tag data for each
 *   entity.
 * - Unauthorized or non-admin roles are denied access (permission error is
 *   thrown).
 * - All system tags are visible, and visibility/business rules regarding product
 *   associations are respected (where applicable).
 *
 * Test steps:
 *
 * 1. (Success) Authenticate or assume an admin connection and call the endpoint.
 *    Verify the response contains expected pagination and tag data.
 * 2. (Failure) Simulate non-admin or unauthorized user and verify access is
 *    denied.
 * 3. (Edge/Business rule) If possible, check that tags associated with
 *    deleted/unavailable products behave as described by business visibility
 *    rules (if API/data allows).
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiProductTags_index(
  connection: api.IConnection,
) {
  // 1. (Success) Call endpoint as admin and verify result shape
  const page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.index(
      connection,
    );
  typia.assert(page);

  // Response includes correct pagination object
  TestValidator.predicate("pagination.current is int >=1")(
    typeof page.pagination.current === "number" && page.pagination.current >= 1,
  );
  TestValidator.predicate("pagination.limit >= 1")(
    typeof page.pagination.limit === "number" && page.pagination.limit >= 1,
  );
  TestValidator.predicate("pagination.records >= 0")(
    typeof page.pagination.records === "number" && page.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages >= 1")(
    typeof page.pagination.pages === "number" && page.pagination.pages >= 1,
  );

  // Response includes list of IShoppingMallAiProductTag objects
  for (const tag of page.data) {
    typia.assert(tag);
    TestValidator.predicate("tag.id is uuid")(
      typeof tag.id === "string" && tag.id.length > 0,
    );
    TestValidator.predicate("tag.shopping_mall_ai_product_id is uuid")(
      typeof tag.shopping_mall_ai_product_id === "string" &&
        tag.shopping_mall_ai_product_id.length > 0,
    );
    TestValidator.predicate("tag.tag is non-empty string")(
      typeof tag.tag === "string" && tag.tag.length > 0,
    );
    TestValidator.predicate("tag.created_at is date-time string")(
      typeof tag.created_at === "string" && tag.created_at.length > 0,
    );
  }

  // 2. (Failure) Simulate a non-admin user and verify access denied
  // To simulate unauthorized scenario, correctly deep-clone and remove Authorization from headers (type-safe)
  const unauthorizedConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  if (
    unauthorizedConnection.headers &&
    "Authorization" in unauthorizedConnection.headers
  ) {
    delete unauthorizedConnection.headers["Authorization"];
  }
  await TestValidator.error(
    "Non-admin or unauthorized cannot access admin tag endpoint",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.index(
      unauthorizedConnection,
    );
  });

  // 3. Optional: If there is data/testcase for tags on deleted/unavailable products, verify business visibility logic
  // (Not implemented as specific logic/rules/details are unknown from provided entities)
}

