 * /shopping-mall-ai/admin/shoppingMallAiProductTags endpoint to query product
 * tags with advanced filters. It verifies correct API behavior for multiple
 * filter combinations, pagination, and error handling. The steps are:
 *
 * 1. Search by tag label substring and check all tags match the filter, pagination
 *    meta is correct.
 * 2. Filter by date range; verify tags fall within date interval.
 * 3. Combine label and date range filters, validate the result set.
 * 4. Search with a label that should yield no match, confirming empty results and
 *    zero pagination counts.
 * 5. Test error scenarios: negative pagination or nonsensical date strings should
 *    yield error responses.
 * 6. Confirm that no moderation/activity status fields are present in the DTO, so
 *    those filters are omitted.
 */
export async function test_api_shopping_mall_ai_product_tag_test_advanced_search_product_tags_by_label_and_usage(
  connection: api.IConnection,
) {
  // 1. Search by tag label substring (case-insensitive match expected)
  const label = "ai";
  const out1 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          tag: label,
          page: 1,
          limit: 10,
          shopping_mall_ai_product_id: null,
          created_at_from: null,
          created_at_to: null,
        },
      },
    );
  typia.assert(out1);
  for (const tag of out1.data) {
    TestValidator.predicate("tag label substring match")(
      tag.tag.toLowerCase().includes(label.toLowerCase()),
    );
    TestValidator.predicate("tag has id")(
      typeof tag.id === "string" && tag.id.length > 0,
    );
    TestValidator.predicate("tag has product id")(
      typeof tag.shopping_mall_ai_product_id === "string" &&
        tag.shopping_mall_ai_product_id.length > 0,
    );
    TestValidator.predicate("tag has created_at")(
      typeof tag.created_at === "string" && tag.created_at.length > 0,
    );
  }
  TestValidator.equals("pagination current page")(out1.pagination.current)(1);
  TestValidator.equals("pagination limit")(out1.pagination.limit)(10);
  TestValidator.predicate("pagination total pages > 0")(
    out1.pagination.pages > 0,
  );
  TestValidator.predicate("pagination total records >= data length")(
    out1.pagination.records >= out1.data.length,
  );

  // 2. Filter by date range (created_at_from/to)
  const from = new Date(Date.now() - 1000 * 60 * 60 * 24 * 3).toISOString();
  const to = new Date().toISOString();
  const out2 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          created_at_from: from,
          created_at_to: to,
          page: 1,
          limit: 10,
          shopping_mall_ai_product_id: null,
          tag: null,
        },
      },
    );
  typia.assert(out2);
  for (const tag of out2.data) {
    TestValidator.predicate("tag.created_at >= from")(tag.created_at >= from);
    TestValidator.predicate("tag.created_at <= to")(tag.created_at <= to);
  }
  TestValidator.equals("pagination current page")(out2.pagination.current)(1);
  TestValidator.equals("pagination limit")(out2.pagination.limit)(10);

  // 3. Combined label and date range filter
  const out3 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          tag: label,
          created_at_from: from,
          created_at_to: to,
          page: 1,
          limit: 10,
          shopping_mall_ai_product_id: null,
        },
      },
    );
  typia.assert(out3);
  for (const tag of out3.data) {
    TestValidator.predicate("tag label substring match (comb.)")(
      tag.tag.toLowerCase().includes(label.toLowerCase()),
    );
    TestValidator.predicate("tag.created_at >= from (comb.)")(
      tag.created_at >= from,
    );
    TestValidator.predicate("tag.created_at <= to (comb.)")(
      tag.created_at <= to,
    );
  }
  TestValidator.equals("pagination current page")(out3.pagination.current)(1);
  TestValidator.equals("pagination limit")(out3.pagination.limit)(10);

  // 4. Query with gibberish label should have no results
  const gibberishLabel = "nonexistent_random_label_12345";
  const out4 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          tag: gibberishLabel,
          page: 1,
          limit: 5,
          shopping_mall_ai_product_id: null,
          created_at_from: null,
          created_at_to: null,
        },
      },
    );
  typia.assert(out4);
  TestValidator.equals("empty data if no matches")(out4.data.length)(0);
  TestValidator.equals("zero records if no matches")(out4.pagination.records)(
    0,
  );
  TestValidator.equals("zero pages if no matches")(out4.pagination.pages)(0);

  // 5. Error: negative pagination and illegal date format
  await TestValidator.error("error on negative page/limit")(() =>
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          page: -1,
          limit: -10,
          tag: label,
          shopping_mall_ai_product_id: null,
          created_at_from: null,
          created_at_to: null,
        },
      },
    ),
  );
  await TestValidator.error("error on invalid dates")(() =>
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductTags.search(
      connection,
      {
        body: {
          created_at_from: "not_a_date",
          created_at_to: "bad_format",
          tag: label,
          page: 1,
          limit: 10,
          shopping_mall_ai_product_id: null,
        },
      },
    ),
  );

  // 6. No activity or moderation status fields to test in schema
}

