/**
 * Validate admin creation of file attachment records to business objects.
 *
 * This test ensures that an admin can create a new file attachment by:
 *
 * 1. Creating a new file metadata entry (prerequisite for referential integrity)
 * 2. Creating a valid file attachment that refers to the above file, with correct
 *    target type and target ID
 * 3. Validating the file attachment record response for all expected fields
 *    (including foreign key mapping)
 * 4. Ensuring uniqueness and referential integrity are enforced (e.g., error on
 *    double insert with same keys)
 * 5. Verifying schema validation error for missing required fields
 *
 * Steps:
 *
 * 1. Prepare a file record via admin file creation API.
 * 2. Generate a random UUID and target type for business object (e.g. 'product').
 * 3. Create a file attachment referencing created file and random target.
 * 4. Receive and validate the full attachment record (fields, FK relationships).
 * 5. Attempt to re-attach the same file to the same target (should fail due to
 *    uniqueness constraint).
 * 6. Omit required field (e.g. target_id) to confirm schema validation error.
 */
export async function test_api_shopping_mall_ai_file_attachment_test_create_file_attachment_with_valid_file_and_target(
  connection: api.IConnection,
) {
  // 1. Create a file metadata record as prerequisite
  const fileInput: IShoppingMallAiFile.ICreate = {
    original_name: RandomGenerator.alphaNumeric(10) + ".jpg",
    uri: `https://cdn.shopping.example.com/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    extension: "jpg",
    mime_type: "image/jpeg",
    size: typia.random<number & tags.Type<"int32">>(),
    hash: RandomGenerator.alphaNumeric(64),
    actor_type: "admin",
    actor_id: null,
  };
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      { body: fileInput },
    );
  typia.assert(file);

  // 2. Generate random target info
  const targetType = "product"; // example business object
  const targetId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a file attachment referencing the just-created file
  const now = new Date().toISOString();
  const attachmentInput: IShoppingMallAiFileAttachment.ICreate = {
    shopping_mall_ai_file_id: file.id,
    shopping_mall_ai_media_asset_id: null,
    target_type: targetType,
    target_id: targetId,
    attached_at: now,
  };
  const attachment =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
      connection,
      { body: attachmentInput },
    );
  typia.assert(attachment);
  TestValidator.equals("file FK matches")(attachment.shopping_mall_ai_file_id)(
    file.id,
  );
  TestValidator.equals("target type matches")(attachment.target_type)(
    targetType,
  );
  TestValidator.equals("target ID matches")(attachment.target_id)(targetId);
  TestValidator.equals("attached_at matches")(attachment.attached_at)(now);

  // 4. Attempt to re-attach the same file to the same target (should fail if uniqueness enforced)
  await TestValidator.error("duplicate file attachment should fail")(
    async () => {
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
        connection,
        { body: attachmentInput },
      );
    },
  );

  // 5. Missing required field (should return schema validation error)
  const badAttachmentInput = {
    ...attachmentInput,
  };
  // Remove required 'target_id' field
  delete (badAttachmentInput as Partial<IShoppingMallAiFileAttachment.ICreate>)
    .target_id;
  await TestValidator.error("missing required field should fail")(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
      connection,
      { body: badAttachmentInput as IShoppingMallAiFileAttachment.ICreate },
    );
  });
}

