/**
 * Validate admin hard deletion of a file attachment record and compliance with
 * audit and permission requirements.
 *
 * This test ensures that an admin user can successfully perform a hard delete
 * of a file attachment record. The flow validates the following:
 *
 * - Only an authorized admin can perform the deletion action.
 * - Once deleted, the file attachment cannot be retrieved by subsequent API
 *   calls, demonstrating the record is actually removed from persistence (no
 *   soft-delete).
 * - Deletion is properly compliant with audit and permission requirements (as
 *   enforced by API behavior).
 * - Deletion of a non-existent or already-deleted record must result in a not
 *   found error (404).
 *
 * The overall steps are:
 *
 * 1. Create a new file attachment as deletion target (using the permitted admin
 *    API).
 * 2. Hard delete the file attachment record with its returned ID.
 * 3. Attempt to delete the same record again, expecting a not found error.
 *
 * Note: There is no GET/read API for attachment by ID provided in the current
 * SDK, so absence of record can only be validated by trying to delete again
 * (expecting failure), and by ensuring the original deletion call completes
 * without error.
 */
export async function test_api_shopping_mall_ai_file_attachment_test_delete_file_attachment_success(
  connection: api.IConnection,
) {
  // 1. Create a file attachment as deletion target
  const createBody: IShoppingMallAiFileAttachment.ICreate = {
    shopping_mall_ai_file_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_media_asset_id: null,
    target_type: "bbs_post", // Example valid type string from allowed business domains
