  // 2. Hard delete the file attachment by id (as admin)
  await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.erase(
    connection,
    {
      shoppingMallAiFileAttachmentId: fileAttachment.id,
    },
  );

  // 3. Attempt to delete it again: should throw not found error,
  // confirming the record is truly gone (used as a proxy for GET-absence check)
  await TestValidator.error(
    "Deleting already-deleted file attachment should fail",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.erase(
      connection,
      {
        shoppingMallAiFileAttachmentId: fileAttachment.id,
      },
    );
  });
}

