import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Test unauthenticated customer cannot create BBS post (401 Unauthorized).
 *
 * This test validates that a customer who is not authenticated cannot create a
 * BBS post in the shopping mall AI system. Attempting to post without a login
 * or customer session must result in a 401 Unauthorized error, preserving both
 * resource integrity and proper authentication flow for end users.
 *
 * Steps:
 *
 * 1. Build a valid IShoppingMallAiBbsPost.ICreate DTO (with valid channel,
 *    section, title, and body fields)
 * 2. Attempt to create a BBS post using
 *    api.functional.shopping_mall_ai.customer.bbsPosts.create with a connection
 *    that has NO customer authentication
 * 3. Assert that a 401 Unauthorized error is thrown using TestValidator.error
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_create_bbs_post_as_unauthenticated_customer(
  connection: api.IConnection,
) {
  // 1. Build a valid BBS post creation input
  const input: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Test title (unauthorized attempt)",
    body: "Test post body (should not be created)",
  };

  // 2 & 3. Attempt post creation, expect 401 Unauthorized error (must not allow anonymous)
  await TestValidator.error(
    "unauthenticated customer should get 401 Unauthorized",
  )(async () => {
    await api.functional.shopping_mall_ai.customer.bbsPosts.create(connection, {
      body: input,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Test that an authenticated seller can create a BBS post with all required
 * fields.
 *
 * This test verifies the successful creation of a forum post (BBS post) by a
 * seller, ensuring:
 *
 * - All required fields (title, body, channel, section) are provided on input.
 * - The response contains correct author/audit fields and is assigned to the
 *   seller.
 * - The created post is not hidden or deleted (active for moderation/review).
 * - The author assignment is automatic (may be implicit via authentication).
 *
 * Steps:
 *
 * 1. Assume an authenticated seller (connection context is valid).
 * 2. Generate valid BBS post input (random UUIDs for channel/section, plausible
 *    title/body).
 * 3. Call the API to create the BBS post.
 * 4. Assert the output matches input and business rules:
 *
 *    - Fields match what was sent.
 *    - Author/customer and audit fields are present (not empty).
 *    - Deleted_at is null or not set (not soft deleted).
 */
export async function test_api_shopping_mall_ai_test_create_bbs_post_with_valid_seller_account(
  connection: api.IConnection,
) {
  // 1. Prepare random but valid BBS post input
  const bbsPostInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(2),
  };

  // 2. Call API to create the BBS post
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: bbsPostInput,
    },
  );
  typia.assert(post);

  // 3. Validate output matches input
  TestValidator.equals("channel matches")(post.shopping_mall_ai_channel_id)(
    bbsPostInput.shopping_mall_ai_channel_id,
  );
  TestValidator.equals("section matches")(post.shopping_mall_ai_section_id)(
    bbsPostInput.shopping_mall_ai_section_id,
  );
  TestValidator.equals("title matches")(post.title)(bbsPostInput.title);
  TestValidator.equals("body matches")(post.body)(bbsPostInput.body);

  // Author/customer ID must be present (UUID string)
  TestValidator.predicate("customer_id is UUID")(
    typeof post.shopping_mall_ai_customer_id === "string" &&
      /^[0-9a-fA-F-]{36}$/.test(post.shopping_mall_ai_customer_id),
  );
  // IP must be non-empty string
  TestValidator.predicate("ip present")(
    typeof post.ip === "string" && post.ip.length > 0,
  );
  // created_at and updated_at are non-empty ISO8601 strings
  TestValidator.predicate("created_at present")(
    typeof post.created_at === "string" && post.created_at.length > 0,
  );
  TestValidator.predicate("updated_at present")(
    typeof post.updated_at === "string" && post.updated_at.length > 0,
  );
  // deleted_at should be undefined or null
  TestValidator.equals("not deleted")(post.deleted_at)(null);
}

