 * 입력값(채널/섹션/제목/본문)이 정상 반영되는지, 작성자/등록일(IP 등)이 서버에서 올바로 기록되는지, soft-delete 없이 바로
 * 노출되는지 등을 체크한다.
 *
 * [진행 프로세스]
 *
 * 1. 필요한 입력값(채널 UUID, 섹션 UUID, 제목, 본문) 준비
 * 2. 전제: connection은 admin(관리자) 권한임을 가정함
 * 3. 관리자 권한으로 bbsPosts.create() 호출 → 게시글 생성
 * 4. 응답: 주요 속성 실제 DB 반영/자동 기록 여부, 포맷 등 검증
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_test_create_bbs_post_as_admin_announcement(
  connection: api.IConnection,
) {
  // 1. 입력 데이터(채널/섹션 UUID 등) 준비
  const input: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(5),
    body: RandomGenerator.content()(2)(5),
  };

  // 2. 전제: connection이 이미 admin 세션임 (따라서 별도 인증 API 없음)

  // 3. API 호출(관리자 권한)
  const post = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
    connection,
    { body: input },
  );
  typia.assert(post);

  // 4. 반환된 게시글의 각 속성 검증
  TestValidator.equals("채널 UUID 일치")(post.shopping_mall_ai_channel_id)(
    input.shopping_mall_ai_channel_id,
  );
  TestValidator.equals("섹션 UUID 일치")(post.shopping_mall_ai_section_id)(
    input.shopping_mall_ai_section_id,
  );
  TestValidator.equals("제목 일치")(post.title)(input.title);
  TestValidator.equals("본문 일치")(post.body)(input.body);
  TestValidator.equals("soft-delete가 null")(post.deleted_at)(null);
  // 작성/수정 시각은 최초 생성이므로 동일해야 함
  TestValidator.equals("동일 작성/수정일시")(post.created_at)(post.updated_at);
  // IP, 작성자 UUID 포맷 간단 검증
  TestValidator.predicate("IP 기록 존재")(
    typeof post.ip === "string" && !!post.ip,
  );
  TestValidator.predicate("작성자는 UUID 형식")(
    typeof post.shopping_mall_ai_customer_id === "string" &&
      !!post.shopping_mall_ai_customer_id.match(/[0-9a-fA-F-]{36}/),
  );
}

