import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Test that a customer can successfully update their own BBS post.
 *
 * This test validates the workflow where a customer creates a new BBS post and
 * then immediately edits it (e.g., changes the title and body). The test
 * checks:
 *
 * - Update permissions: only the author (customer) can update their own post
 * - Updated fields reflect correctly (title/body)
 * - Audit fields (updated_at) are modified while others remain unchanged
 * - Post is still visible (not soft-deleted)
 *
 * Steps:
 *
 * 1. Create a BBS post with known title/body as a customer (using random linkage
 *    IDs)
 * 2. Update the post as the same customer with new title/body
 * 3. Assert updated fields, audit fields, and that post remains active and
 *    correctly linked
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_customer_edit_own_bbs_post_success(
  connection: api.IConnection,
) {
  // 1. Create BBS post as customer
  const createInput = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Original Title for Update Test",
    body: "Original body for update scenario.",
  } satisfies IShoppingMallAiBbsPost.ICreate;

  const originalPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.create(connection, {
      body: createInput,
    });
  typia.assert(originalPost);

  // 2. Update the post as the same customer
  const updateInput = {
    title: "[UPDATED] New Title Set",
    body: "Updated body content for success update test.",
  } satisfies IShoppingMallAiBbsPost.IUpdate;

  // Small delay so updated_at differs from created_at
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const updatedPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.update(connection, {
      bbsPostId: originalPost.id,
      body: updateInput,
    });
  typia.assert(updatedPost);

  // 3. Validate the changes and audit info
  TestValidator.equals("title updated")(updatedPost.title)(updateInput.title);
  TestValidator.equals("body updated")(updatedPost.body)(updateInput.body);

  // updated_at should now be newer than created_at
  TestValidator.predicate("updated_at newer than created_at")(
    new Date(updatedPost.updated_at).getTime() >
      new Date(updatedPost.created_at).getTime(),
  );

  // not soft-deleted
  TestValidator.equals("not soft deleted")(updatedPost.deleted_at)(null);

  // Immutable fields
  TestValidator.equals("id unchanged")(updatedPost.id)(originalPost.id);
  TestValidator.equals("author linkage unchanged")(
    updatedPost.shopping_mall_ai_customer_id,
  )(originalPost.shopping_mall_ai_customer_id);
  TestValidator.equals("channel linkage unchanged")(
    updatedPost.shopping_mall_ai_channel_id,
  )(originalPost.shopping_mall_ai_channel_id);
  TestValidator.equals("section linkage unchanged")(
    updatedPost.shopping_mall_ai_section_id,
  )(originalPost.shopping_mall_ai_section_id);
  TestValidator.equals("ip unchanged")(updatedPost.ip)(originalPost.ip);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Test that a customer cannot update a post that has already been soft-deleted
 * (deleted_at set).
 *
 * This test ensures that after creating a BBS post and soft-deleting it using
 * the erase endpoint, any update attempts to that post are rejected. The update
 * call must result in an error, confirming that the system enforces soft-delete
 * protection for forum posts and preserves post integrity.
 *
 * Steps:
 *
 * 1. Create a new customer BBS post with valid data.
 * 2. Soft-delete the post via the erase endpoint.
 * 3. Attempt to update the soft-deleted post and validate that an error occurs.
 *
 * Note: At present, no API for reading a post back after modification is
 * available, so this test focuses only on error detection, not post-content
 * verification after failure.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_customer_attempt_update_deleted_bbs_post(
  connection: api.IConnection,
) {
  // 1. Create a customer BBS post
  const createInput = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Soft delete test: update forbidden after erase",
    body: "This body will be used for a soft-delete update-forbidden check.",
  } satisfies IShoppingMallAiBbsPost.ICreate;
  const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    { body: createInput },
  );
  typia.assert(post);

  // 2. Soft-delete the post
  await api.functional.shopping_mall_ai.customer.bbsPosts.erase(connection, {
    bbsPostId: post.id,
  });

  // 3. Attempt to update the soft-deleted post and validate error response
  const updateInput = {
    title: "EDIT FAIL: new title after soft delete",
    body: "EDIT FAIL: this body update should be blocked due to soft delete.",
  } satisfies IShoppingMallAiBbsPost.IUpdate;

  await TestValidator.error("Updating a soft-deleted post must fail")(() =>
    api.functional.shopping_mall_ai.customer.bbsPosts.update(connection, {
      bbsPostId: post.id,
      body: updateInput,
    }),
  );
}

