  )(originalPost.shopping_mall_ai_channel_id);
  TestValidator.equals("section unchanged")(
    updatedPost.shopping_mall_ai_section_id,
  )(originalPost.shopping_mall_ai_section_id);
  TestValidator.predicate("timestamp updated")(
    updatedPost.updated_at !== updatedPost.created_at,
  );
  if ("deleted_at" in updatedPost)
    TestValidator.equals("not deleted")(updatedPost.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
