import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IPageIShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search and filtering for BBS posts as a seller with
 * complex filters and pagination.
 *
 * Covers end-to-end business flow:
 *
 * - Data preparation: create BBS posts with variants of channel, section,
 *   customer, title, and creation dates.
 * - Multiple search cases: keyword (title), specific section/channel,
 *   customer-based author filter, pagination, non-deleted results, date range.
 * - Negative/edge cases: No-match filter, out-of-range page, malformed filter
 *   parameter.
 *
 * Steps:
 *
 * 1. Create 3 BBS posts as seller with varying channels, sections, titles,
 *    creation dates, and simulated authors/customers.
 * 2. Test filter by keyword in title. Should return only posts with that keyword
 *    substring.
 * 3. Test filter by specific channel and section. Only posts matching IDs should
 *    be returned.
 * 4. Test filter by customer/author. Only posts from that author returned.
 * 5. Test combined filters (channel + title) for AND logic. Only posts matching
 *    all filters appear.
 * 6. Test pagination: set limit low, retrieve first and second page, verify
 *    correct post slicing and pagination fields, including total counts/pages.
 * 7. Negative test: filter by fake/unused channel/customer id; should return zero
 *    results.
 * 8. Negative test: request an out-of-range page (e.g., page 999); should return
 *    empty data.
 * 9. Negative test: supply malformed (invalid type/format) for a filter property
 *    and ensure error is thrown.
 * 10. Due to summary schema, do not assert against inferred properties like
 *     deleted_at.
 */
export async function test_api_shopping_mall_ai_seller_bbsPosts_test_search_bbs_posts_with_multiple_filters_and_pagination_seller(
  connection: api.IConnection,
) {
  // --- 1. Data Preparation: Create 3 posts with distinct attributes ---
  // Simulate different channels, sections, and pseudo-authors (customer_id)
  const channelA = typia.random<string & tags.Format<"uuid">>();
  const channelB = typia.random<string & tags.Format<"uuid">>();
  const sectionA = typia.random<string & tags.Format<"uuid">>();
  const sectionB = typia.random<string & tags.Format<"uuid">>();

  // Create post 1: ChannelA/SectionA/Title: "Alpha Foo"
  const titleA = "Alpha Foo";
  const postA = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelA,
        shopping_mall_ai_section_id: sectionA,
        title: titleA,
        body: "First post for Alpha Foo.",
      },
    },
  );
  typia.assert(postA);

  // Create post 2: ChannelB/SectionB/Title: "Beta Bar"
  const titleB = "Beta Bar";
  const postB = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelB,
        shopping_mall_ai_section_id: sectionB,
        title: titleB,
        body: "Second post for Beta Bar.",
      },
    },
  );
  typia.assert(postB);

  // Create post 3: ChannelA/SectionB/Title: "Gamma Foo"
  const titleC = "Gamma Foo";
  const postC = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelA,
        shopping_mall_ai_section_id: sectionB,
        title: titleC,
        body: "Third post for Gamma Foo.",
      },
    },
  );
  typia.assert(postC);

  // --- 2. Search/filter by keyword in title ("Foo") ---
  const searchByFoo =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        title: "Foo",
        active_only: true,
      },
    });
  typia.assert(searchByFoo);
  TestValidator.predicate("search by title contains both Foo-titled posts")(
    searchByFoo.data.some((x) => x.title === titleA) &&
      searchByFoo.data.some((x) => x.title === titleC) &&
      !searchByFoo.data.some((x) => x.title === titleB),
  );

  // --- 3. Filter by channel/section ---
  const searchChannelA_SectionB =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_channel_id: channelA,
        shopping_mall_ai_section_id: sectionB,
        active_only: true,
      },
    });
  typia.assert(searchChannelA_SectionB);
  TestValidator.equals("only Gamma Foo returned channelA/sectionB")(
    searchChannelA_SectionB.data.length,
  )(1);
  TestValidator.equals("post matches Gamma Foo")(
    searchChannelA_SectionB.data[0].title,
  )(titleC);

  // --- 4. Filter by author (must use customer_id from create response) ---
  const searchByCustomerA =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_customer_id: postA.shopping_mall_ai_customer_id,
        active_only: true,
      },
    });
  typia.assert(searchByCustomerA);
  TestValidator.predicate("only Alpha Foo for customerA")(
    searchByCustomerA.data.some((x) => x.title === titleA),
  );

  // --- 5. Combined filters AND: channel and title (should match only postA) ---
  const searchCombo =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_channel_id: channelA,
        title: "Alpha",
        active_only: true,
      },
    });
  typia.assert(searchCombo);
  TestValidator.equals("combo returns one Alpha Foo")(searchCombo.data.length)(
    1,
  );
  TestValidator.equals("combo data is Alpha Foo")(searchCombo.data[0].title)(
    titleA,
  );

  // --- 6. Pagination: set low limit and get first/second pages, validate slicing and metadata ---
  const limit = 2;
  const paginated1 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        limit,
        page: 1,
        active_only: true,
      },
    });
  typia.assert(paginated1);
  TestValidator.equals("limit == page size")(paginated1.data.length)(
    Math.min(limit, paginated1.pagination.records),
  );
  TestValidator.equals("pagination current page")(
    paginated1.pagination.current,
  )(1);

  const paginated2 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        limit,
        page: 2,
        active_only: true,
      },
    });
  typia.assert(paginated2);
  TestValidator.equals("pagination current page 2")(
    paginated2.pagination.current,
  )(2);
  // If there are 3 posts, page 2 will have up to 1 post
  TestValidator.equals("remaining records on page 2")(paginated2.data.length)(
    Math.max(0, paginated2.pagination.records - limit),
  );

  // --- 7. Negative: filter for unused channel/customer should return zero results ---
  const unusedChannel = typia.random<string & tags.Format<"uuid">>();
  const unusedCustomer = typia.random<string & tags.Format<"uuid">>();

  const searchUnusedChannel =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_channel_id: unusedChannel,
        active_only: true,
      },
    });
  typia.assert(searchUnusedChannel);
  TestValidator.equals("no results for unused channel")(
    searchUnusedChannel.data.length,
  )(0);

  const searchUnusedCustomer =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_customer_id: unusedCustomer,
        active_only: true,
      },
    });
  typia.assert(searchUnusedCustomer);
  TestValidator.equals("no results for unused customer")(
    searchUnusedCustomer.data.length,
  )(0);

  // --- 8. Negative: out-of-range page returns empty data array ---
  const outOfRangePage =
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        page: 999,
        limit: 2,
        active_only: true,
      },
    });
  typia.assert(outOfRangePage);
  TestValidator.equals("empty result on out-of-range page")(
    outOfRangePage.data.length,
  )(0);

  // --- 9. Malformed input: supply invalid type for a filter property (should throw) ---
  await TestValidator.error("invalid type for page parameter")(async () => {
    // Passing a string instead of int32 for 'page' (which expects a number & tags.Type<'int32'>)
    await api.functional.shopping_mall_ai.seller.bbsPosts.search(connection, {
      body: {
        page: "wrong-type" as unknown as number,
        active_only: true,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
