import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the admin’s advanced BBS post search functionality with rich
 * filtering, pagination, and moderation auditing.
 *
 * This test ensures:
 *
 * - Admin can filter BBS posts by author, channel, and creation date
 * - Admin can retrieve both deleted and non-deleted posts for moderation/audit
 * - Pagination and empty result sets function properly
 * - Title fuzzy search works for flagged/keyworded content
 * - Malformed/invalid input is handled with error response
 *
 * Step-by-step:
 *
 * 1. Create several BBS posts as admin in multiple channels/sections with
 *    distinguishable authors and titles
 * 2. (SKIP - deletion simulation not possible via provided API) – only test what
 *    is exposed
 * 3. Query all posts with no filters (should include all, regardless of deleted
 *    state)
 * 4. Query only non-deleted posts (active_only: true, should exclude soft-deleted
 *    posts if supported)
 * 5. Filter by author: retrieve only posts by one specific author nickname
 * 6. Filter by channel: retrieve only posts for a single channel
 * 7. Filter by creation date range: posts created after a certain time
 * 8. Filter by keyword in title
 * 9. Request a page/limit that results in empty results
 * 10. Submit a malformed request (e.g., negative page number) and ensure error
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_test_admin_advanced_search_bbs_posts_with_moderation_filters(
  connection: api.IConnection,
) {
  // 1. Create posts in multiple combinations (simulate variation by distinct UUIDs/titles)
  const channelA = typia.random<string & tags.Format<"uuid">>();
  const channelB = typia.random<string & tags.Format<"uuid">>();
  const sectionA = typia.random<string & tags.Format<"uuid">>();
  const sectionB = typia.random<string & tags.Format<"uuid">>();
  // Simulate authors by unique titles (we cannot actually set author_id)
  const authorNames = [RandomGenerator.name(), RandomGenerator.name()];
  const keywordTitle = "special moderation keyword";

  const posts = [] as IShoppingMallAiBbsPost[];
  for (let i = 0; i < 4; ++i) {
    const body: IShoppingMallAiBbsPost.ICreate = {
      shopping_mall_ai_channel_id: i % 2 === 0 ? channelA : channelB,
      shopping_mall_ai_section_id: i % 2 === 0 ? sectionA : sectionB,
      title: i === 1 ? keywordTitle : RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    };
    const post = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
      connection,
      { body },
    );
    typia.assert(post);
    posts.push(post);
  }

  // 3. Unfiltered admin query — should see >= all just-created posts
  const allResp = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
    connection,
    {
      body: {},
    },
  );
  typia.assert(allResp);
  TestValidator.predicate("admin sees all posts")(
    allResp.data.length >= posts.length,
  );

  // 4. Only active posts (no deleted_at, if supported)
  const actResp = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
    connection,
    {
      body: { active_only: true },
    },
  );
  typia.assert(actResp);
  // Can't guarantee some posts are deleted without a deletion API, just check type

  // 5. Filter by author nickname (from at least one post)
  const authorToFind =
    allResp.data.length > 0 ? allResp.data[0].author_nickname : undefined;
  if (authorToFind !== undefined) {
    const byAuthor =
      await api.functional.shopping_mall_ai.admin.bbsPosts.search(connection, {
        body: { shopping_mall_ai_customer_id: null }, // No way to search by nickname, only by customer_id
      });
    typia.assert(byAuthor);
    // Without knowing customer_id, skip actual result check for author_nickname
  }

  // 6. Filter by channel (use channelA)
  const byChanA = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
    connection,
    {
      body: { shopping_mall_ai_channel_id: channelA },
    },
  );
  typia.assert(byChanA);
  TestValidator.predicate("only posts for channel A")(
    byChanA.data.every((post) => post.shopping_mall_ai_channel_id === channelA),
  );

  // 7. Filter by creation date (after first post)
  const dateBound = posts[0]?.created_at;
  if (dateBound) {
    const byDate = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
      connection,
      {
        body: { created_from: dateBound },
      },
    );
    typia.assert(byDate);
    TestValidator.predicate("posts from dateBound or later")(
      byDate.data.every((post) => post.created_at >= dateBound),
    );
  }

  // 8. Filter by keyword in title
  const byKeyword = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
    connection,
    {
      body: { title: "moderation keyword" },
    },
  );
  typia.assert(byKeyword);
  TestValidator.predicate("title search matches at least one post")(
    byKeyword.data.some((post) => post.title.includes("moderation keyword")),
  );

  // 9. Pagination to get empty set (high page number)
  const emptyResp = await api.functional.shopping_mall_ai.admin.bbsPosts.search(
    connection,
    {
      body: { page: 1000 },
    },
  );
  typia.assert(emptyResp);
  TestValidator.equals("pagination empty")(emptyResp.data.length)(0);

  // 10. Malformed request – negative page number triggers error
  await TestValidator.error("negative page triggers error")(() =>
    api.functional.shopping_mall_ai.admin.bbsPosts.search(connection, {
      body: { page: -1 },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
