/**
 * Validate retrieving a BBS post by ID for a customer, including normal and
 * deleted cases.
 *
 * This test ensures:
 *
 * - A newly created BBS post is retrievable by its unique ID and all expected
 *   fields match
 * - After being soft-deleted, the post cannot be retrieved (API returns error)
 *
 * Business steps:
 *
 * 1. Create a BBS post as a customer
 * 2. Retrieve the post by its ID; expect all fields to match
 * 3. Soft-delete the created post
 * 4. Attempt to retrieve the now-deleted post; expect error (not found or
 *    forbidden)
 *
 * (Section/channel-based access control checking is not implemented here, as
 * channel/section ACLs cannot be simulated directly with available APIs.)
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_customer_get_bbs_post_by_id_success_and_deleted(
  connection: api.IConnection,
) {
  // 1. Create BBS post as customer
  const bbsPostCreateInput = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  } satisfies IShoppingMallAiBbsPost.ICreate;
  const created: IShoppingMallAiBbsPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.create(connection, {
      body: bbsPostCreateInput,
    });
  typia.assert(created);

  // 2. Retrieve by ID (should succeed and match)
  const found: IShoppingMallAiBbsPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.at(connection, {
      bbsPostId: created.id,
    });
  typia.assert(found);
  TestValidator.equals("id matches")(found.id)(created.id);
  TestValidator.equals("channel matches")(found.shopping_mall_ai_channel_id)(
    bbsPostCreateInput.shopping_mall_ai_channel_id,
  );
  TestValidator.equals("section matches")(found.shopping_mall_ai_section_id)(
    bbsPostCreateInput.shopping_mall_ai_section_id,
  );
  TestValidator.equals("title matches")(found.title)(bbsPostCreateInput.title);
  TestValidator.equals("body matches")(found.body)(bbsPostCreateInput.body);

  // 3. Soft-delete the post
  await api.functional.shopping_mall_ai.customer.bbsPosts.erase(connection, {
    bbsPostId: created.id,
  });

  // 4. Attempt to retrieve deleted post (should fail)
  await TestValidator.error("retrieving deleted post should fail")(async () => {
    await api.functional.shopping_mall_ai.customer.bbsPosts.at(connection, {
      bbsPostId: created.id,
    });
  });
}

