import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";

/**
 * Validate admin creation of a new order item linked to an order
 *
 * This test checks that an admin can successfully add a new order item to an
 * existing order. The workflow covers:
 *
 * 1. Creating a new order via the admin API (POST /shopping-mall-ai/admin/orders)
 * 2. Creating an order item in that order specifying all required fields
 * 3. Verifying the returned order item is properly linked and all core attributes
 *    are as expected
 *
 * Steps:
 *
 * 1. Execute admin order creation (POST /shopping-mall-ai/admin/orders) with valid
 *    data to get a new orderId
 * 2. Prepare IShoppingOrderItem.ICreate data with all required fields, referencing
 *    the newly created order
 * 3. Call POST /shopping-mall-ai/admin/orders/{orderId}/orderItems to create new
 *    order item, both with and without product option id
 * 4. Assert the returned IShoppingOrderItem record has correct field values
 *    (linkage, price, quantity, product ref, status, and option id as
 *    provided)
 */
export async function test_api_shopping_mall_ai_admin_orders_orderItems_test_create_order_item_admin_successful_creation(
  connection: api.IConnection,
) {
  // 1. Create a new order via admin (dependency and context)
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Prepare test cases with and without the optional product option field
  const testCases: IShoppingOrderItem.ICreate[] = [
    // Case without product option id
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
      price: 32900,
      quantity: 1,
      status: "active",
    },
    // Case explicitly with product option id = null
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
      price: 54800.75,
      quantity: 3,
      status: "pending",
      shopping_mall_ai_product_option_id: null,
    },
    // Case with a concrete product option id
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
      price: 11000,
      quantity: 5,
      status: "active",
      shopping_mall_ai_product_option_id: typia.random<
        string & tags.Format<"uuid">
      >(),
    },
  ];

  for (const input of testCases) {
    const orderItem =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: input,
        },
      );
    typia.assert(orderItem);

    // 4. Validate linkage and attributes
    TestValidator.equals("order linkage")(orderItem.shopping_mall_ai_order_id)(
      order.id,
    );
    TestValidator.equals("product id")(orderItem.shopping_mall_ai_product_id)(
      input.shopping_mall_ai_product_id,
    );
    TestValidator.equals("quantity")(orderItem.quantity)(input.quantity);
    TestValidator.equals("unit price")(orderItem.price)(input.price);
    TestValidator.equals("status")(orderItem.status)(input.status);
    if ("shopping_mall_ai_product_option_id" in input) {
      TestValidator.equals("product option id")(
        orderItem.shopping_mall_ai_product_option_id,
      )(input.shopping_mall_ai_product_option_id);
    } else {
      TestValidator.equals("product option id should be undefined")(
        orderItem.shopping_mall_ai_product_option_id,
      )(undefined);
    }
  }
}

