 * 2. Seller adds a new valid item to this order via the seller endpoint,
 *    specifying correct product id and order id. The item is added and all
 *    returned fields are asserted for correctness.
 * 3. Attempt to add a new order item to another (random or unauthorized) order id
 *    to validate rejection/security enforcement.
 */
export async function test_api_shopping_mall_ai_test_create_order_item_seller_successful_creation(
  connection: api.IConnection,
) {
