import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";

/**
 * Test successful update of an order item by an admin user.
 *
 * This test validates that an admin can update permitted (mutable) fields like
 * quantity and status of an order item, while immutable fields such as the
 * associated product and parent order linkage remain unchanged.
 *
 * Steps:
 *
 * 1. Create an admin order.
 * 2. Create an order item for that order.
 * 3. Update the order item's quantity and status.
 * 4. Verify that the updated fields reflect the new values, while the product and
 *    order references remain unchanged.
 */
export async function test_api_shopping_mall_ai_admin_orders_orderItems_update_successful(
  connection: api.IConnection,
) {
  // 1. Create an admin order
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Create an order item linked to this order
  const productId = typia.random<string & tags.Format<"uuid">>();
  const item =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: productId,
          price: 1000.0,
          quantity: 2,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(item);

  // 3. Update the order item's quantity and status
  const updateRequest = {
    quantity: item.quantity + 3,
    status: "returned",
  } satisfies IShoppingOrderItem.IUpdate;
  const updated =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.update(
      connection,
      {
        orderId: order.id,
        orderItemId: item.id,
        body: updateRequest,
      },
    );
  typia.assert(updated);

  // 4. Assert mutable fields are updated
  TestValidator.equals("quantity updated")(updated.quantity)(
    updateRequest.quantity,
  );
  TestValidator.equals("status updated")(updated.status)(updateRequest.status);
  // Assert immutable fields do not change
  TestValidator.equals("order linkage unchanged")(
    updated.shopping_mall_ai_order_id,
  )(item.shopping_mall_ai_order_id);
  TestValidator.equals("product linkage unchanged")(
    updated.shopping_mall_ai_product_id,
  )(item.shopping_mall_ai_product_id);
}

