 * they own.
 *
 * This e2e test checks the core workflow from order and order item creation to
 * updating a field (quantity) on that item, ensuring the update applies and
 * does not affect other fields.
 *
 * Steps:
 *
 * 1. Admin creates a new order (assigned to random customer/channel).
 * 2. Seller creates an order item within this order, for a product + optional
 *    option.
 * 3. Seller updates the order item, changing quantity.
 * 4. Verify that only the specified field (quantity) is updated and others remain
 *    unchanged.
 *
 * Authorization enforcement (ensuring other users can't update) is omitted due
 * to no customer/seller auth API in test scope. Negative tests are not
 * included.
 *
 * This test verifies:
 *
 * - Seller can update fields allowed by IShoppingOrderItem.IUpdate.
 * - Update only affects permitted fields.
 * - The returned IShoppingOrderItem reflects the applied modifications.
 */
export async function test_api_shopping_mall_ai_test_update_order_item_seller_successful_update(
  connection: api.IConnection,
) {
  // 1. Admin creates a new order (simulate admin context)
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Seller creates an order item associated with this order
  const itemCreateInput: IShoppingOrderItem.ICreate = {
    shopping_mall_ai_order_id: order.id,
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_product_option_id:
      Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
    price: 10000,
    quantity: 2,
    status: "active",
  };
  const orderItem =
    await api.functional.shopping_mall_ai.seller.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: itemCreateInput,
      },
    );
  typia.assert(orderItem);

  // 3. Seller updates the order item. Change quantity only.
  const newQuantity = itemCreateInput.quantity + 1;
  const updateResult =
    await api.functional.shopping_mall_ai.seller.orders.orderItems.update(
      connection,
      {
        orderId: order.id,
        orderItemId: orderItem.id,
        body: {
          quantity: newQuantity,
        } satisfies IShoppingOrderItem.IUpdate,
      },
    );
  typia.assert(updateResult);

  // 4. Assert update: quantity should be changed, others preserved
  TestValidator.equals("order item id matches")(updateResult.id)(orderItem.id);
  TestValidator.equals("order linkage")(updateResult.shopping_mall_ai_order_id)(
    order.id,
  );
  TestValidator.equals("product")(updateResult.shopping_mall_ai_product_id)(
    itemCreateInput.shopping_mall_ai_product_id,
  );
  TestValidator.equals("quantity updated")(updateResult.quantity)(newQuantity);
  // Optionally check product option id: both can be uuid or null
  TestValidator.equals("product option id unchanged")(
    updateResult.shopping_mall_ai_product_option_id ?? null,
  )(itemCreateInput.shopping_mall_ai_product_option_id ?? null);
  TestValidator.equals("status unchanged")(updateResult.status)(
    itemCreateInput.status,
  );
  TestValidator.equals("price unchanged")(updateResult.price)(
    itemCreateInput.price,
  );
}

