import type { IPageIShoppingMallAiAiRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAiRecommendation";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the advanced search and filtering of AI recommendations (admin
 * API).
 *
 * This test verifies correct operation of the advanced search endpoint for AI
 * product recommendations. It creates multiple diverse recommendation records
 * with distinct products, channels, and metadata, then exercises search filters
 * for product, channel, combined product+channel, and metadata substring.
 * Finally, it validates pagination and that filtered queries return the correct
 * subset of records.
 *
 * Workflow:
 *
 * 1. Create several (combinatorial) recommendation records covering distinctive
 *    products/channels/metadata
 * 2. Search with no filters—should return all records just created (paginated)
 * 3. For each product, search by product
 * 4. For each channel, search by channel
 * 5. For a specific product+channel, search by both (should uniquely match)
 * 6. For a metadata substring, search by that metadata (should only match intended
 *    record)
 * 7. Check pagination with page/limit
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiAiRecommendations_test_advanced_search_ai_recommendations_by_channel_and_product(
  connection: api.IConnection,
) {
  // 1. Create diverse recommendations (combinatorics for completeness)
  const records: IShoppingMallAiAiRecommendation[] = [];
  const productIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const channelIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const metadataSamples = [
    JSON.stringify({ score: 98, note: "metal" }),
    JSON.stringify({ score: 88, note: "pop" }),
    JSON.stringify({ score: 77, note: "jazz" }),
  ];
  for (let i = 0; i < productIds.length; ++i) {
    for (let j = 0; j < channelIds.length; ++j) {
      const meta = metadataSamples[(i + j) % metadataSamples.length];
      const rec =
        await api.functional.shopping_mall_ai.admin.shoppingMallAiAiRecommendations.create(
          connection,
          {
            body: {
              shopping_mall_ai_product_id: productIds[i],
              shopping_mall_ai_channel_id: channelIds[j],
              metadata_json: meta,
            } satisfies IShoppingMallAiAiRecommendation.ICreate,
          },
        );
      typia.assert(rec);
      records.push(rec);
    }
  }
  // Insert one that can be found via memorable metadata substring
  const magicMeta = JSON.stringify({ score: 42, note: "magic-match" });
