 * metadata records with the same content hash. Deduplication at the file-hash
 * level is a critical business integrity rule to prevent redundant records and
 * storage waste.
 *
 * Workflow:
 *
 * 1. Create a file metadata record as admin with a unique content hash.
 * 2. Attempt to create a second file metadata record using the same hash (but
 *    otherwise random file data) as admin.
 * 3. Confirm that the second attempt fails with a conflict or validation error,
 *    proving deduplication is strictly enforced.
 */
export async function test_api_shopping_mall_ai_test_create_file_metadata_with_duplicate_hash_fails(
  connection: api.IConnection,
) {
  // 1. Create initial file metadata record with unique hash
  const fileHash: string = typia.random<string>();
  const createInput: IShoppingMallAiFile.ICreate = {
    original_name: "imageA.jpg",
    uri: "https://cdn.example.com/blob/test-imageA" + Math.random(),
