  // 2. Attempt duplicate creation using the same hash
  const duplicateInput: IShoppingMallAiFile.ICreate = {
    original_name: "imageB.jpg",
    uri: "https://cdn.example.com/blob/test-imageB" + Math.random(),
    extension: "jpg",
    mime_type: "image/jpeg",
    size: 51200,
    hash: fileHash, // intentionally identical to previous hash
    actor_type: "admin",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("Duplicate file hash should block creation")(
    async () => {
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
        connection,
        { body: duplicateInput },
      );
    },
  );
}

