 *
 * 비즈니스 컨텍스트:
 *
 * - 쇼핑몰 플랫폼의 업로드 파일 메타데이터 관리는 보안, 트레이스 및 감사(Audit)를 위해 엄격하게 제한됩니다.
 * - Original_name, actor_type, deleted_at 등 일부 필드만 수정 가능하며, uri, hash 등은
 *   불변(immutable)입니다.
 * - 관리자는 파일 소유자 변경, 파일명 교정, 삭제(soft delete) 처리와 같이 제한된 메타데이터 편집 권한이 있습니다.
 *
 * 검증 시나리오:
 *
 * 1. 테스트용 파일을 우선 등록합니다 (선행 데이터 구축).
 * 2. 관리자가 original_name, actor_type, deleted_at(삭제 또는 복원) 등 수정 가능 필드를 변경 요청합니다.
 * 3. 응답된 파일 메타데이터에서 변경이 반영됐고, 불변 필드(uri, hash 등)는 그대로 유지되며, 감사 이력이 일관됨을 검증합니다.
 *
 * (불변 필드 변경 시도, 에러 케이스 등은 본 테스트에 포함하지 않음 - 정상 플로우만 다룸)
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiFiles_test_update_file_metadata_with_valid_fields_by_admin(
  connection: api.IConnection,
) {
  // 1. 선행: 테스트용 파일 메타데이터 등록
  const originalFile =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      {
        body: {
          original_name: RandomGenerator.paragraph()(10),
          uri:
            "https://cdn.example.com/test-upload/" +
            typia.random<string>() +
            ".jpeg",
          extension: "jpeg",
          mime_type: "image/jpeg",
          size: 1024,
          hash: typia.random<string>(),
          actor_type: "admin",
          actor_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(originalFile);

  // 2. 관리자가 수정 가능한 필드(original_name, actor_type, deleted_at)를 업데이트 요청
  const newOriginalName = "수정된 파일명_" + RandomGenerator.alphaNumeric(5);
  const newActorType = "system";
  const newDeletedAt = new Date().toISOString();
  const updatedFile =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.update(
      connection,
      {
        shoppingMallAiFileId: originalFile.id,
        body: {
          original_name: newOriginalName,
          actor_type: newActorType,
          deleted_at: newDeletedAt,
        },
      },
    );
  typia.assert(updatedFile);

  // 3. 결과 검증: 변경 필드는 바뀌고, 불변 필드는 동일함을 확인
  TestValidator.equals("original_name 반영 여부")(updatedFile.original_name)(
    newOriginalName,
  );
  TestValidator.equals("actor_type 반영 여부")(updatedFile.actor_type)(
    newActorType,
  );
  TestValidator.equals("deleted_at 값 반영 여부")(updatedFile.deleted_at)(
    newDeletedAt,
  );
  // 불변 필드 검증
  TestValidator.equals("uri 불변 확인")(updatedFile.uri)(originalFile.uri);
  TestValidator.equals("hash 불변 확인")(updatedFile.hash)(originalFile.hash);
  TestValidator.equals("id 불변 확인")(updatedFile.id)(originalFile.id);
  // 기타 기본 감사 필드 확인
  TestValidator.equals("created_at 유지됨")(updatedFile.created_at)(
    originalFile.created_at,
  );
}

