          shopping_mall_ai_file_id: baseFileId2,
          asset_type: "preview",
          asset_uri: "https://cdn.example.com/media/preview1.jpg",
          width: 400,
          height: 300,
          duration: null,
        } satisfies IShoppingMallAiMediaAsset.ICreate,
      },
    );
  typia.assert(asset2);

  const asset3 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: baseFileId2,
          asset_type: "compressed",
          asset_uri: "https://cdn.example.com/media/compressed1.mp4",
          width: null,
          height: null,
          duration: 100,
        } satisfies IShoppingMallAiMediaAsset.ICreate,
      },
    );
  typia.assert(asset3);

  // Step 2: Filter by asset_type
  const respByType =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.search(
      connection,
      {
        body: {
          asset_type: "thumb",
        } satisfies IShoppingMallAiMediaAsset.IRequest,
      },
    );
  typia.assert(respByType);
  // Only assets with asset_type 'thumb' should be present
  TestValidator.predicate("filter: asset_type=thumb")(
    respByType.data.every((asset) => asset.asset_type === "thumb"),
  );

  // Step 3: Filter by shopping_mall_ai_file_id
  const respByFileId =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.search(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: baseFileId2,
        } satisfies IShoppingMallAiMediaAsset.IRequest,
      },
    );
  typia.assert(respByFileId);
  TestValidator.predicate("filter: base file id match")(
    respByFileId.data.every(
      (asset) => asset.shopping_mall_ai_file_id === baseFileId2,
    ),
  );

  // Step 4: Filter by creation date range
  const createdFromDate = new Date(
    now.getTime() - 1000 * 60 * 40,
  ).toISOString(); // 40 min ago
  const createdToDate = new Date(now.getTime() - 1000 * 60 * 20).toISOString(); // 20 min ago
  const respByCreatedRange =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.search(
      connection,
      {
        body: {
          created_from: createdFromDate,
          created_to: createdToDate,
        } satisfies IShoppingMallAiMediaAsset.IRequest,
      },
    );
  typia.assert(respByCreatedRange);
  TestValidator.predicate("filter: by created range")(
    respByCreatedRange.data.every(
      (asset) =>
        new Date(asset.created_at) >= new Date(createdFromDate) &&
        new Date(asset.created_at) <= new Date(createdToDate),
    ),
  );

  // Step 5: Pagination (limit = 2)
  const respByPagination =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.search(
      connection,
      {
        body: {
          limit: 2,
          page: 1,
        } satisfies IShoppingMallAiMediaAsset.IRequest,
      },
    );
  typia.assert(respByPagination);
  TestValidator.equals("pagination: page size=2")(respByPagination.data.length)(
    Math.min(2, respByPagination.pagination.records),
  );
  TestValidator.equals("pagination: limit")(respByPagination.pagination.limit)(
    2,
  );

  // Step 6: Negative search (no match case)
  const respNegative =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.search(
      connection,
      {
        body: {
          asset_type: "does_not_exist_type",
        } satisfies IShoppingMallAiMediaAsset.IRequest,
      },
    );
  typia.assert(respNegative);
  TestValidator.equals("negative: returns empty array")(
    respNegative.data.length,
  )(0);
}

