/**
 * E2E Test: Update editable metadata for a shopping mall AI media asset variant
 * by ID
 *
 * This test validates that an admin can update mutable fields (like asset_type,
 * asset_uri, dimensions) for a media asset variant, and further confirms that
 * the changes persist and sensitive fields (such as file linkage and creation
 * timestamp) are not altered.
 *
 * Business context:
 *
 * - Admin must first create a file as the base for media asset variants.
 * - Then, a media asset variant is registered referencing the file.
 * - The test updates allowed fields via the admin update endpoint, verifying
 *   updates, and ensuring prohibited fields are unchanged.
 * - This mimics asset transformation or metadata rectification flows and ensures
 *   proper audit-logging on update.
 *
 * Test steps:
 *
 * 1. Register a new file as the base via shoppingMallAiFiles.create
 * 2. Register a media asset variant with reference to this file
 * 3. As admin, call update on this media asset by ID with changes to asset_type,
 *    asset_uri, width, height
 * 4. Confirm the returned object reflects ALL intended changes, while file
 *    reference and creation timestamp are immutable
 * 5. Optionally, validate audit logging (if observable via response or
 *    side-effect)
 * 6. Error tests: Try to mutate immutable fields like file linkage or created_at
 *    (should be ignored or rejected)
 */
export async function test_api_shopping_mall_ai_media_assets_test_update_media_asset_metadata_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Register a new file
  const fileInput = {
    original_name: "example.png",
    uri: "https://cdn.example.com/file1.png",
    extension: "png",
    mime_type: "image/png",
    size: 102400,
    hash: "abc123def456",
    actor_type: "admin",
    actor_id: null,
  };
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      { body: fileInput },
    );
  typia.assert(file);

  // 2. Register a media asset variant referencing this file
  const assetInput = {
    shopping_mall_ai_file_id: file.id,
    asset_type: "thumb",
    asset_uri: "https://cdn.example.com/media/asset/thumb1.png",
    width: 128,
    height: 128,
    duration: null,
  };
  const asset =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.create(
      connection,
      { body: assetInput },
    );
  typia.assert(asset);

  // 3. Update asset_type, asset_uri, dimensions for this media asset
  const updateBody = {
    asset_type: "preview",
    asset_uri: "https://cdn.example.com/media/asset/preview1.png",
    width: 256,
    height: 144,
    duration: null,
  };
  const updated =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.update(
      connection,
      {
        mediaAssetId: asset.id,
        body: updateBody,
      },
    );
  typia.assert(updated);

  // 4. Confirm intended fields changed and sensitive fields did not
  TestValidator.equals("asset_type updated")(updated.asset_type)("preview");
  TestValidator.equals("asset_uri updated")(updated.asset_uri)(
    "https://cdn.example.com/media/asset/preview1.png",
  );
  TestValidator.equals("width updated")(updated.width)(256);
  TestValidator.equals("height updated")(updated.height)(144);
  TestValidator.equals("duration updated")(updated.duration)(null);

  // Sensitive/immutable checks
  TestValidator.equals("file linkage unchanged")(
    updated.shopping_mall_ai_file_id,
  )(asset.shopping_mall_ai_file_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(
    asset.created_at,
  );

  // 5. (Optional) Attempt forbidden update: Try to change file linkage and created_at -- should be ignored or rejected
  await TestValidator.error("cannot update file linkage or created_at fields")(
    async () => {
      await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.update(
        connection,
        {
          mediaAssetId: asset.id,
          body: {
            // @ts-expect-error: deliberately trying forbidden fields for error scenario
            shopping_mall_ai_file_id: file.id,
            created_at: new Date().toISOString(),
          },
        },
      );
    },
  );
}

