 *
 * Steps:
 *
 * 1. Create a file resource using the file creation endpoint (acts as the base
 *    file for the asset).
 * 2. Register a media asset using the file from step 1.
 * 3. Attempt to update the media asset's immutable fields:
 *
 *    - Shopping_mall_ai_file_id (should be immutable)
 *    - Created_at (should be immutable)
 * 4. Validate that the update operation throws a validation error and the
 *    immutable fields are not changed.
 * 5. Optionally, verify that mutable fields (like asset_type) can still be updated
 *    successfully for control.
 */
export async function test_api_shopping_mall_ai_media_assets_test_update_media_asset_with_immutable_fields_should_fail(
  connection: api.IConnection,
) {
