            // No effect, should be rejected by the API, or these props ignored if extra props are sent.
            // Here, we test by passing only valid (documented) update fields to confirm immutability protection is handled server-side, not client-side.
            asset_type: RandomGenerator.alphaNumeric(8),
            asset_uri: RandomGenerator.alphaNumeric(18),
            width: typia.random<number & tags.Type<"int32">>(),
            height: typia.random<number & tags.Type<"int32">>(),
            duration: typia.random<number & tags.Type<"int32">>(),
            // Even if we added shopping_mall_ai_file_id or created_at here, they'd be ignored or rejected since the schema blocks them.
          } satisfies IShoppingMallAiMediaAsset.IUpdate,
        },
      );
    },
  );

  // 4. Optionally, re-query the asset and verify the immutable fields remain unchanged
