/**
 * Validate that the coupon list for a customer only includes currently valid,
 * active coupons.
 *
 * This test registers several coupons as admin with different validity and
 * status scenarios, then as customer ensures the endpoint GET
 * /shopping-mall-ai/customer/coupons only returns coupons that should be
 * visible and usable. Covers cases: active/valid, expired, not-yet-valid, and
 * irrelevant (simulated "suspended" cannot be set via SDK).
 *
 * Steps:
 *
 * 1. Register, as admin,:
 *
 * - A valid active coupon (today-now inside window)
 * - An expired coupon (end date in past)
 * - A future coupon (start date in future)
 *
 * 2. As customer, GET /shopping-mall-ai/customer/coupons
 * 3. Assert only the valid/active coupon appears, all others are filtered out
 * 4. Validate the summary object against expectations for correct fields and
 *    values
 */
export async function test_api_shopping_mall_ai_customer_coupons_index(
  connection: api.IConnection,
) {
  // Setup date windows for coupon validity
  const now = new Date();
  const past = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 10); // 10 days ago
  const yesterday = new Date(now.getTime() - 1000 * 60 * 60 * 24); // 1 day ago
  const tomorrow = new Date(now.getTime() + 1000 * 60 * 60 * 24); // 1 day ahead
  const nextWeek = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7);

  // 1. Create a valid coupon (active now)
  const validCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        type: "percent",
        value: 5,
        max_usage: 100,
        max_usage_per_customer: 3,
        valid_from: now.toISOString(),
        valid_until: nextWeek.toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(validCoupon);

  // 2. Create an expired coupon (now outside window)
  const expiredCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        type: "fixed",
        value: 2000,
        max_usage: 50,
        max_usage_per_customer: 1,
        valid_from: past.toISOString(),
        valid_until: yesterday.toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(expiredCoupon);

  // 3. Create a not-yet-active coupon (valid_from in the future)
  const futureCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        type: "fixed",
        value: 3000,
        max_usage: 10,
        max_usage_per_customer: 1,
        valid_from: tomorrow.toISOString(),
        valid_until: nextWeek.toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(futureCoupon);

  // 4. List coupons as customer
  const summaryList =
    await api.functional.shopping_mall_ai.customer.coupons.index(connection);
  typia.assert(summaryList);
  const codes = summaryList.data.map((c) => c.code);
  // 5. Assert only valid coupon is included
  TestValidator.predicate("valid coupon appears")(
    codes.includes(validCoupon.code),
  );
  TestValidator.predicate("expired coupon hidden")(
    !codes.includes(expiredCoupon.code),
  );
  TestValidator.predicate("future coupon hidden")(
    !codes.includes(futureCoupon.code),
  );
  // 6. Validate details match (for summary fields)
  const summaryObj = summaryList.data.find((c) => c.code === validCoupon.code);
  if (!summaryObj) throw new Error("Valid coupon summary missing");
  TestValidator.equals("coupon id matches")(summaryObj.id)(validCoupon.id);
  TestValidator.equals("coupon type matches")(summaryObj.type)(
    validCoupon.type,
  );
  TestValidator.equals("coupon value matches")(summaryObj.value)(
    validCoupon.value,
  );
  TestValidator.equals("status is active")(summaryObj.status)("active");
  TestValidator.equals("validity begin matches")(summaryObj.valid_from)(
    validCoupon.valid_from,
  );
  TestValidator.equals("validity end matches")(summaryObj.valid_until)(
    validCoupon.valid_until,
  );
  TestValidator.equals("summary has created_at")(
    typeof summaryObj.created_at === "string",
  )(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";

/**
 * Test listing all coupons issued by this seller.
 *
 * This verifies:
 *
 * - Coupons created via POST /shopping-mall-ai/seller/coupons appear in the list
 * - Coupons created via POST /shopping-mall-ai/admin/coupons (global or for other
 *   sellers) do NOT appear
 * - Both active and expired coupons from this seller are listed
 *
 * Steps:
 *
 * 1. Create several coupons as this seller (with unique codes, one active and one
 *    expired)
 * 2. Create a platform/global coupon from the admin context
 * 3. List the seller's coupons via GET /shopping-mall-ai/seller/coupons
 * 4. Assert that only coupons assigned to this seller's ID (including expired)
 *    appear in the results
 * 5. Assert that created admin coupons are NOT present in the seller's list
 */
export async function test_api_shopping_mall_ai_seller_coupons_index(
  connection: api.IConnection,
) {
  // 1. Prep: create seller's test coupons (one active, one expired)
  const now = new Date();
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  const future = new Date(now.getTime() + 7 * 86400 * 1000); // 7 days from now
  const past = new Date(now.getTime() - 7 * 86400 * 1000); // 7 days ago

  const seller_active_coupon =
    await api.functional.shopping_mall_ai.seller.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: seller_id,
        code: `SELLER-ACTIVE-${typia.random<string>().slice(0, 8)}`,
        type: "fixed",
        value: 10000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: now.toISOString(),
        valid_until: future.toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(seller_active_coupon);

  const seller_expired_coupon =
    await api.functional.shopping_mall_ai.seller.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: seller_id,
        code: `SELLER-EXPIRED-${typia.random<string>().slice(0, 8)}`,
        type: "percent",
        value: 20,
        max_usage: 50,
        max_usage_per_customer: 1,
        valid_from: past.toISOString(),
        valid_until: now.toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(seller_expired_coupon);

  // 2. Create a platform/global coupon not belonging to the seller
  const admin_coupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: null,
        code: `ADMIN-GLOBAL-${typia.random<string>().slice(0, 8)}`,
        type: "fixed",
        value: 5000,
        max_usage: 30,
        max_usage_per_customer: 2,
        valid_from: now.toISOString(),
        valid_until: future.toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(admin_coupon);

  // 3. Retrieve list of seller coupons
  const coupon_list =
    await api.functional.shopping_mall_ai.seller.coupons.index(connection);
  typia.assert(coupon_list);

  // 4. Validate seller's coupons are in the returned list
  const found_active = coupon_list.data.find(
    (x) => x.code === seller_active_coupon.code,
  );
  const found_expired = coupon_list.data.find(
    (x) => x.code === seller_expired_coupon.code,
  );
  TestValidator.predicate("seller's active coupon is present")(!!found_active);
  TestValidator.predicate("seller's expired coupon is present")(
    !!found_expired,
  );

  // 5. Validate the admin (global) coupon does not appear
  const found_admin = coupon_list.data.find(
    (x) => x.code === admin_coupon.code,
  );
  TestValidator.equals("admin/global coupon must not appear")(found_admin)(
    undefined,
  );

  // Optionally, ensure that all returned coupons matching our test prefix are tied to seller_id
  for (const c of coupon_list.data) {
    if (c.code.startsWith("SELLER-"))
      TestValidator.predicate("test seller coupon present in seller list")(
        true,
      );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
