import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";

/**
 * Validate admin listing of all coupons, covering diverse statuses and
 * system-wide visibility
 *
 * This test ensures that an admin can retrieve a complete list of all coupon
 * records in the platform, including:
 *
 * - Active, expired, suspended/revoked, and upcoming coupons
 * - Coupons not visible to end-users (customers/sellers) due to privacy or status
 *   The test covers creation of several coupons with different statuses as
 *   setup, then validates that all are present in the admin listing response.
 *
 * Step-by-step process:
 *
 * 1. Create an active coupon (valid window encompasses now, status active)
 * 2. Create an expired coupon (valid_until in the past)
 * 3. Create a future coupon (valid_from in the future)
 * 4. Create a revoked/suspended coupon (simulated as 'business-meaningful')
 * 5. Call the admin coupon listing API
 * 6. Validate that all created coupons are present, irrespective of their
 *    active/expired/suspended status
 * 7. Check full summary details for accuracy (id, code, type, value, status,
 *    valid_from/until, etc)
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_list_all_coupons_as_admin(
  connection: api.IConnection,
) {
  // 1. Create an active coupon
  const now = new Date();
  const activeCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `ACTIVECODE-${typia.random<string>()}`,
        type: "fixed",
        value: 1000,
        max_usage: 100,
        max_usage_per_customer: 10,
        valid_from: new Date(now.getTime() - 10000).toISOString(),
        valid_until: new Date(
          now.getTime() + 1000 * 60 * 60 * 24,
        ).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(activeCoupon);

  // 2. Create an expired coupon
  const expiredCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `EXPIREDCODE-${typia.random<string>()}`,
        type: "percent",
        value: 20,
        max_usage: 10,
        max_usage_per_customer: 2,
        valid_from: new Date(now.getTime() - 1000 * 60 * 60 * 48).toISOString(),
        valid_until: new Date(
          now.getTime() - 1000 * 60 * 60 * 24,
        ).toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(expiredCoupon);

  // 3. Create a future coupon
  const futureCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `FUTURECODE-${typia.random<string>()}`,
        type: "fixed",
        value: 500,
        max_usage: 50,
        max_usage_per_customer: 5,
        valid_from: new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString(),
        valid_until: new Date(
          now.getTime() + 1000 * 60 * 60 * 48,
        ).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(futureCoupon);

  // 4. Create a revoked/suspended coupon (simulate by type/status, marked for business recognition)
  const suspendedCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `SUSPENDCODE-${typia.random<string>()}`,
        type: "fixed",
        value: 300,
        max_usage: 10,
        max_usage_per_customer: 1,
        valid_from: new Date(now.getTime() - 10000).toISOString(),
        valid_until: new Date(
          now.getTime() + 1000 * 60 * 60 * 24,
        ).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(suspendedCoupon);

  // 5. Call the coupon listing API as admin
  const list =
    await api.functional.shopping_mall_ai.admin.coupons.index(connection);
  typia.assert(list);
  const summaryList = list.data;

  // 6. Validate that all created coupons are present by code
  const codes = [
    activeCoupon.code,
    expiredCoupon.code,
    futureCoupon.code,
    suspendedCoupon.code,
  ];
  for (const code of codes) {
    const found = summaryList.find((s) => s.code === code);
    TestValidator.predicate(`Coupon ${code} should be in admin listing`)(
      !!found,
    );
  }
  // 7. (Optionally) Check some fields of summaries for consistency
  // (e.g., type, status, valid_from/until for each code)
  for (const summary of summaryList) {
    if (codes.includes(summary.code)) {
      TestValidator.equals("summary type matches")(summary.type)(
        [activeCoupon, expiredCoupon, futureCoupon, suspendedCoupon].find(
          (c) => c.code === summary.code,
        )!.type,
      );
      TestValidator.equals("summary value matches")(summary.value)(
        [activeCoupon, expiredCoupon, futureCoupon, suspendedCoupon].find(
          (c) => c.code === summary.code,
        )!.value,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced coupon search for a customer using valid filter conditions.
 *
 * 본 테스트는 고객이 유효한 필터(상태, 타입, 기간, 페이지네이션 등)를 활용해 고급 쿠폰 검색을 수행할 때 결과가 적합하게 노출되는지
 * 검증합니다.
 *
 * 사업적 목적:
 *
 * - 다양한 쿠폰(활성/만료/일시중지/타입별, 기간별)을 사전에 생성하고, 고객 조회 시 필터에 의한 정확한 결과 반환과 페이지/정렬 동작을
 *   보증.
 *
 * Step-by-step
 *
 * 1. 관리자로 여러 조합의 쿠폰을 생성 (상태, 타입, 기간 다양화)
 * 2. 고객으로 '활성-고정금액' 쿠폰만, 현재 날짜 기준으로 유효한 것만 검색하는 요청을 보냄
 * 3. 결과로 반환되는 모든 쿠폰이 필터(상태=active, 타입=fixed, 유효기간)에 정확히 부합하는지 검증
 * 4. 페이지네이션/정렬 필드 등도 설정/검증
 */
export async function test_api_shopping_mall_ai_customer_coupons_test_advanced_coupon_search_for_customer_valid_criteria(
  connection: api.IConnection,
) {
  // 1. 다양한 속성의 쿠폰을 관리자로 사전 생성
  const now = new Date();

  // 활성, fixed 타입, 현재 유효한 쿠폰
  const couponActiveFixed =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `FIXED-${now.getTime()}`,
        type: "fixed",
        value: 10000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(),
        valid_until: new Date(
          now.getTime() + 24 * 60 * 60 * 1000,
        ).toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponActiveFixed);

  // 만료된 fixed 타입 쿠폰
  const couponExpiredFixed =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `EXPIRED-FIXED-${now.getTime()}`,
        type: "fixed",
        value: 5000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(
          now.getTime() - 7 * 24 * 60 * 60 * 1000,
        ).toISOString(),
        valid_until: new Date(
          now.getTime() - 24 * 60 * 60 * 1000,
        ).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponExpiredFixed);

  // 활성 percent 타입 쿠폰
  const couponActivePercent =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `PERCENT-${now.getTime()}`,
        type: "percent",
        value: 20,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(now.getTime() - 12 * 60 * 60 * 1000).toISOString(),
        valid_until: new Date(
          now.getTime() + 12 * 60 * 60 * 1000,
        ).toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponActivePercent);

  // 일시중지(가정) 쿠폰: 기간만 유효하게 생성
  const couponSuspended =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code: `SUSPENDED-${now.getTime()}`,
        type: "fixed",
        value: 3000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(now.getTime() - 12 * 60 * 60 * 1000).toISOString(),
        valid_until: new Date(
          now.getTime() + 12 * 60 * 60 * 1000,
        ).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponSuspended);

  // 2. 고객 쿠폰 검색 - 필터: 'active', 'fixed' 타입, 현재 유효기간 내
  const filterRequest: IShoppingMallAiCoupon.IRequest = {
    status: "active",
    type: "fixed",
    valid_from_from: new Date(
      now.getTime() - 24 * 60 * 60 * 1000,
    ).toISOString(),
    valid_until_to: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
    sort_by: "value",
    sort_order: "desc",
    page: 1,
    limit: 10,
  };

  const searchResult =
    await api.functional.shopping_mall_ai.customer.coupons.search(connection, {
      body: filterRequest,
    });
  typia.assert(searchResult);

  // 3. 검색 결과의 모든 쿠폰이 조건을 충족하는지
  searchResult.data.forEach((summary) => {
    TestValidator.equals("status is active")(summary.status)("active");
    TestValidator.equals("type is fixed")(summary.type)("fixed");
    TestValidator.predicate("valid_from >= filter")(
      new Date(summary.valid_from) >= new Date(filterRequest.valid_from_from!),
    );
    TestValidator.predicate("valid_until <= filter")(
      new Date(summary.valid_until) <= new Date(filterRequest.valid_until_to!),
    );
  });
  // 4. 페이지네이션 값 검사
  TestValidator.equals("current page is 1")(searchResult.pagination.current)(1);
  TestValidator.equals("limit is 10")(searchResult.pagination.limit)(10);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate coupon search endpoint RBAC and filter rules for customers.
 *
 * This test ensures that a customer cannot use unauthorized or privileged
 * filters (like restricted coupon types) on the
 * /shopping-mall-ai/customer/coupons search endpoint. The API should enforce
 * RBAC, denying access to coupon data that would not be permitted. The workflow
 * is:
 *
 * 1. An admin creates at least one restricted coupon (e.g., a coupon with a
 *    unique/restricted type or a seller-specific coupon) and one open-access
 *    (platform/general) coupon.
 * 2. Attempt to search using an invalid or forbidden filter as a customer — for
 *    example, by specifying a restricted type, or by filtering for a coupon
 *    that the customer should not be able to see.
 * 3. The API should respond with a validation or permission error; or (if no
 *    error) it must return zero unauthorized coupons in the response.
 */
export async function test_api_shopping_mall_ai_test_advanced_coupon_search_with_invalid_filters(
  connection: api.IConnection,
) {
  // 1. Admin creates a RESTRICTED coupon (e.g., seller-specific) and an open platform coupon
  const restrictedCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        code: `SELLER-ONLY-${typia.random<string>()}`,
        type: "seller_restricted", // Intentionally use a pseudo-restricted type (business-side)
        value: 1000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(Date.now() - 1000 * 60 * 60).toISOString(),
        valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(restrictedCoupon);

  const openCoupon = await api.functional.shopping_mall_ai.admin.coupons.create(
    connection,
    {
      body: {
        code: `OPEN-${typia.random<string>()}`,
        type: "fixed",
        value: 500,
        max_usage: 999,
        max_usage_per_customer: 3,
        valid_from: new Date(Date.now() - 1000 * 60 * 60).toISOString(),
        valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    },
  );
  typia.assert(openCoupon);

  // 2. Customer attempts to search coupons using an unauthorized filter (e.g., restricted type)
  await TestValidator.error("unauthorized coupon search should fail")(
    async () => {
      await api.functional.shopping_mall_ai.customer.coupons.search(
        connection,
        {
          body: {
            type: restrictedCoupon.type,
          } satisfies IShoppingMallAiCoupon.IRequest,
        },
      );
    },
  );
  // Optionally, also check that searching by seller-only coupon ID returns no data
  const result = await api.functional.shopping_mall_ai.customer.coupons.search(
    connection,
    {
      body: {
        code: restrictedCoupon.code,
      } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(result);
  TestValidator.equals("restricted coupons not visible for customers")(
    result.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
