import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and pagination for shopping mall AI media assets.
 *
 * This test ensures the admin media asset search endpoint properly supports
 * various filter combinations and pagination:
 *
 * - Filtering by asset_type (e.g., 'thumbnail', 'preview')
 * - Filtering by associated file id (shopping_mall_ai_file_id)
 * - Filtering by recent upload range (created_from, created_to)
 * - Pagination for large result sets It also covers error conditions including
 *   invalid filter keys, out-of-range page requests, and permission validation
 *   for non-admin users.
 *
 * Steps:
 *
 * 1. Admin performs search with multiple filters (asset_type, file_id, date
 *    range), requesting a specific page and limit.
 * 2. Validate that results and pagination info match filter criteria and
 *    pagination request.
 * 3. Attempt to search with an invalid filter key; expect an error.
 * 4. Attempt to request page number greater than total available; expect empty
 *    results or an error.
 * 5. Attempt the search as a non-admin user; expect an authorization error.
 */
export async function test_api_shopping_mall_ai_admin_mediaAssets_test_advanced_search_media_assets_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare advanced search filters
  const filters: IShoppingMallAiMediaAsset.IRequest = {
    asset_type: RandomGenerator.pick([
      "thumbnail",
      "preview",
      "large",
      "compressed",
    ]),
    shopping_mall_ai_file_id: typia.random<string & tags.Format<"uuid">>(),
    created_from: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7).toISOString(), // one week ago
    created_to: new Date().toISOString(),
    page: 1,
    limit: 5,
  };

  // 2. Search as admin with correct filters
  const output = await api.functional.shopping_mall_ai.admin.mediaAssets.search(
    connection,
    { body: filters },
  );
  typia.assert(output);
  TestValidator.equals("pagination.page matches")(output.pagination.current)(
    filters.page,
  );
  TestValidator.equals("pagination.limit matches")(output.pagination.limit)(
    filters.limit,
  );
  if (output.data.length > 0) {
    for (const asset of output.data) {
      if (filters.asset_type)
        TestValidator.equals("asset_type matches")(asset.asset_type)(
          filters.asset_type,
        );
      if (filters.shopping_mall_ai_file_id)
        TestValidator.equals("file id matches")(asset.shopping_mall_ai_file_id)(
          filters.shopping_mall_ai_file_id,
        );
      if (filters.created_from)
        TestValidator.predicate("created_at after from")(
          asset.created_at >= filters.created_from!,
        );
      if (filters.created_to)
        TestValidator.predicate("created_at before to")(
          asset.created_at <= filters.created_to!,
        );
    }
  }

  // 3. Error: invalid filter key (attempt to inject an undefined property)
  TestValidator.error("invalid filter key rejects")(() =>
    api.functional.shopping_mall_ai.admin.mediaAssets.search(connection, {
      body: {
        ...filters,
        non_existing_filter: "should fail",
      } as unknown as IShoppingMallAiMediaAsset.IRequest,
    }),
  );

  // 4. Out-of-range page (page > total pages)
  const impossiblePage = (output.pagination.pages ?? 1) + 999;
  const outPageOut =
    await api.functional.shopping_mall_ai.admin.mediaAssets.search(connection, {
      body: { ...filters, page: impossiblePage },
    });
  typia.assert(outPageOut);
  TestValidator.equals("empty data for out-of-range page")(
    outPageOut.data.length,
  )(0);

  // 5. Authorization: non-admin (simulate by removing token)
  const nonAdminConn = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConn.headers["Authorization"];
  TestValidator.error("non-admin cannot search")(async () => {
    await api.functional.shopping_mall_ai.admin.mediaAssets.search(
      nonAdminConn,
      { body: filters },
    );
  });
}

