 * Test Steps:
 *
 * 1. Create shopping mall file metadata (admin scope).
 * 2. Register media asset variant referencing that file.
 * 3. Retrieve metadata for the asset using its ID and verify all returned details
 *    match creation inputs.
 * 4. Attempt retrieval with a random but valid UUID that does not correspond to
 *    any asset: expect 404.
 * 5. Attempt retrieval with an invalid UUID string: expect 400.
 * 6. If possible, test unauthorized access by clearing admin credentials and
 *    retrying (should fail).
 */
export async function test_api_shopping_mall_ai_admin_mediaAssets_test_retrieve_media_asset_metadata_by_id_when_asset_exists(
  connection: api.IConnection,
) {
