  // 2. Register media asset, referencing created file
  const assetInput: IShoppingMallAiMediaAsset.ICreate = {
    shopping_mall_ai_file_id: createdFile.id,
    asset_type: "thumb",
    asset_uri: `https://cdn.assets/${RandomGenerator.alphabets(20)}-thumb.png`,
    width: 128,
    height: 128,
    duration: null,
