    assetInput.asset_type,
  );
  TestValidator.equals("asset uri")(assetRetrieved.asset_uri)(
    assetInput.asset_uri,
  );
  TestValidator.equals("width")(assetRetrieved.width)(assetInput.width);
  TestValidator.equals("height")(assetRetrieved.height)(assetInput.height);
  TestValidator.equals("duration")(assetRetrieved.duration)(
    assetInput.duration,
