/**
 * Validate advanced searching of product bundles by admin using multiple
 * filters, pagination, and negative cases.
 *
 * Business context: Admin users need to search/filter the product bundle
 * catalog using many criteria (availability, price, keyword, pagination). This
 * test verifies correct implementation of all documented filters, accurate
 * results, robust pagination, and error/edge handling.
 *
 * Step-by-step testing process:
 *
 * 1. Create multiple product bundles with varied attributes (title, price, active
 *    flags) for robust search validation.
 * 2. Search with 'active' filter to validate boolean filtering.
 * 3. Search bundles within a price range with 'price_min'/'price_max' to check
 *    numeric boundaries.
 * 4. Search by title keyword (partial, case-insensitive) for string filter
 *    correctness.
 * 5. Combine filters to validate compound logic.
 * 6. Test pagination: use 'page' and 'limit', ensure correct current/limit in
 *    pagination info.
 * 7. Edge: Use filters that match no bundles, validate empty result.
 * 8. (Omitted: Unauthorized access as non-admin—no public endpoint present or
 *    filter schema error test: such checks are not possible with current
 *    DTO/type setup.)
 */
export async function test_api_shopping_mall_ai_product_bundles_test_search_product_bundles_with_filters_by_admin(
  connection: api.IConnection,
) {
  // 1. Create several product bundles with diverse attributes
  const bundles = await Promise.all([
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      {
        body: {
          title: "BundleAlpha",
          description: "Alpha desc",
          price: 111.0,
          active: true,
        },
      },
    ),
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      {
        body: {
          title: "BundleBeta",
          description: "Beta desc",
          price: 222.0,
          active: false,
        },
      },
    ),
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      {
        body: {
          title: "Gamma Bundle",
          description: "Gamma desc",
          price: 333.33,
          active: true,
        },
      },
    ),
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      {
        body: {
          title: "DeltaPack",
          description: "Delta desc",
          price: 444.0,
          active: false,
        },
      },
    ),
    api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      {
        body: {
          title: "Omicron",
          description: "Omicron desc",
          price: 555.5,
          active: true,
        },
      },
    ),
  ]);
  bundles.forEach((b) => typia.assert(b));

  // 2. Filter by active=true
  let page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { active: true } },
    );
  typia.assert(page);
  TestValidator.predicate("all bundles active")(
    page.data.every((b) => b.active === true),
  );

  // 3. Filter by price range
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { price_min: 200, price_max: 500 } },
    );
  typia.assert(page);
  TestValidator.predicate("all within price range")(
    page.data.every((b) => b.price >= 200 && b.price <= 500),
  );

  // 4. Filter by partial title match (case-insensitive)
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { title: "bundle" } },
    );
  typia.assert(page);
  TestValidator.predicate("title contains keyword")(
    page.data.every((b) => b.title.toLowerCase().includes("bundle")),
  );

  // 5. Combine filters: active, price, partial title
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { active: true, price_min: 300, price_max: 600, title: "omic" } },
    );
  typia.assert(page);
  TestValidator.predicate("all filters match")(
    page.data.every(
      (b) =>
        b.active === true &&
        b.price >= 300 &&
        b.price <= 600 &&
        b.title.toLowerCase().includes("omic"),
    ),
  );

  // 6. Test pagination: page 2, limit 2
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { page: 2, limit: 2 } },
    );
  typia.assert(page);
  TestValidator.equals("pagination page")(page.pagination.current)(2);
  TestValidator.equals("pagination limit")(page.pagination.limit)(2);

  // 7. Filter edge: price_min larger than any bundle
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.search(
      connection,
      { body: { price_min: 99999 } },
    );
  typia.assert(page);
  TestValidator.equals("empty data")(page.data.length)(0);
}

