 * Process:
 *
 * 1. Create a new policy change record (initial audit entry)
 * 2. Update select fields (change_summary, approved_at) of the created record via
 *    the PUT endpoint
 * 3. Assert the returned record reflects updates, preserves id, and leaves other
 *    properties unchanged
 * 4. Repeat with a single-field partial update and assert correct patching
 * 5. Validate correct type and structure at every stage
 */
export async function test_api_shopping_mall_ai_admin_policyChanges_test_update_policy_change_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new policy change for audit
  const initial: IShoppingMallAiPolicyChange =
    await api.functional.shopping_mall_ai.admin.policyChanges.create(
      connection,
      {
        body: {
          policy_code: RandomGenerator.alphaNumeric(8),
          policy_version: "v1.0",
          change_summary: RandomGenerator.paragraph()(),
          approved_by: typia.random<string & tags.Format<"uuid">>(),
          approved_at: new Date().toISOString(),
          previous_version: null,
        } satisfies IShoppingMallAiPolicyChange.ICreate,
      },
    );
  typia.assert(initial);

  // 2. Update summary and approval date using PUT
  const newSummary = RandomGenerator.paragraph()();
  const newApprovedAt = new Date(Date.now() + 60_000).toISOString();
  const updated: IShoppingMallAiPolicyChange =
    await api.functional.shopping_mall_ai.admin.policyChanges.update(
      connection,
      {
        policyChangeId: initial.id,
        body: {
          change_summary: newSummary,
          approved_at: newApprovedAt,
        } satisfies IShoppingMallAiPolicyChange.IUpdate,
      },
    );
  typia.assert(updated);

  // 3. Assert updated fields change, unchanged remain the same, and id is preserved
  TestValidator.equals("id is not changed")(updated.id)(initial.id);
  TestValidator.equals("change_summary updated")(updated.change_summary)(
    newSummary,
  );
  TestValidator.equals("approved_at updated")(updated.approved_at)(
    newApprovedAt,
  );
  TestValidator.equals("policy_code not changed")(updated.policy_code)(
    initial.policy_code,
  );
  TestValidator.equals("policy_version not changed")(updated.policy_version)(
    initial.policy_version,
  );
  TestValidator.equals("approved_by not changed")(updated.approved_by)(
    initial.approved_by,
  );
  TestValidator.equals("previous_version still null")(updated.previous_version)(
    initial.previous_version,
  );
  TestValidator.equals("deleted_at remains unchanged")(
    updated.deleted_at ?? null,
  )(initial.deleted_at ?? null);

  // 4. Partial update: change only approved_by
  const newAdminId = typia.random<string & tags.Format<"uuid">>();
  const partial: IShoppingMallAiPolicyChange =
    await api.functional.shopping_mall_ai.admin.policyChanges.update(
      connection,
      {
        policyChangeId: initial.id,
        body: {
          approved_by: newAdminId,
        } satisfies IShoppingMallAiPolicyChange.IUpdate,
      },
    );
  typia.assert(partial);
  TestValidator.equals("id stable after partial update")(partial.id)(
    initial.id,
  );
  TestValidator.equals("approved_by changed")(partial.approved_by)(newAdminId);
  TestValidator.equals("change_summary still the same")(partial.change_summary)(
    updated.change_summary,
  );
  TestValidator.equals("approved_at unchanged")(partial.approved_at)(
    updated.approved_at,
  );
  TestValidator.equals("policy_code not changed after partial update")(
    partial.policy_code,
  )(initial.policy_code);
  TestValidator.equals("policy_version not changed after partial update")(
    partial.policy_version,
  )(initial.policy_version);
  TestValidator.equals("previous_version still null after partial")(
    partial.previous_version,
  )(initial.previous_version);
  TestValidator.equals("deleted_at still unchanged")(
    partial.deleted_at ?? null,
  )(initial.deleted_at ?? null);
}

