/**
 * Test retrieving a paginated list of legal consent records as an admin for
 * compliance audits.
 *
 * This test verifies the ability of admin users to fetch a paginated list of
 * legal consent records, ensuring that each returned record includes user ID,
 * policy details, consent timestamp, and audit/compliance fields as per
 * business rules. Also validates the pagination structure for completeness and
 * correctness. This test is crucial for legal compliance and audit workflows.
 *
 * Steps:
 *
 * 1. Fetch the first page of legal consent records using the GET
 *    /shopping-mall-ai/admin/legalConsents endpoint.
 * 2. Validate the overall result conforms to IPageIShoppingMallAiLegalConsent.
 * 3. Examine each returned consent record and check all business-critical fields.
 * 4. Confirm that pagination metadata is present and numerically valid.
 */
export async function test_api_shopping_mall_ai_admin_legalConsents_index(
  connection: api.IConnection,
) {
  // 1. Fetch the first page of legal consent records
  const output =
    await api.functional.shopping_mall_ai.admin.legalConsents.index(connection);
  typia.assert(output);

  // 2. Check pagination metadata fields are present and valid
  TestValidator.predicate("pagination.current is non-negative integer")(
    typeof output.pagination.current === "number" &&
      Number.isInteger(output.pagination.current) &&
      output.pagination.current >= 0,
  );
  TestValidator.predicate("pagination.limit is positive integer")(
    typeof output.pagination.limit === "number" &&
      Number.isInteger(output.pagination.limit) &&
      output.pagination.limit > 0,
  );
  TestValidator.predicate("pagination.records is non-negative integer")(
    typeof output.pagination.records === "number" &&
      Number.isInteger(output.pagination.records) &&
      output.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages is non-negative integer")(
    typeof output.pagination.pages === "number" &&
      Number.isInteger(output.pagination.pages) &&
      output.pagination.pages >= 0,
  );

  // 3. Check that data is an array (possibly empty) of legal consent objects
  TestValidator.predicate("output.data is array")(Array.isArray(output.data));
  for (const consent of output.data) {
    // 4. Check business-required and audit fields for each record
    TestValidator.predicate("consent.id is uuid string")(
      typeof consent.id === "string" && /^[0-9a-fA-F-]{36}$/.test(consent.id),
    );
    TestValidator.predicate("consent.user_id is string")(
      typeof consent.user_id === "string",
    );
    TestValidator.predicate("consent.policy_code is string")(
      typeof consent.policy_code === "string",
    );
    TestValidator.predicate("consent.policy_version is string")(
      typeof consent.policy_version === "string",
    );
    TestValidator.predicate("consent.consented_at is ISO date-time")(
      typeof consent.consented_at === "string" &&
        consent.consented_at.includes("T"),
    );
    TestValidator.predicate("consent.consented_method is string")(
      typeof consent.consent_method === "string",
    );
    // nullable fields are either string, null or undefined
    TestValidator.predicate("consent.withdrawn_at is string/null/undefined")(
      consent.withdrawn_at === undefined ||
        consent.withdrawn_at === null ||
        typeof consent.withdrawn_at === "string",
    );
    TestValidator.predicate("consent.consented_ip is string/null/undefined")(
      consent.consent_ip === undefined ||
        consent.consent_ip === null ||
        typeof consent.consent_ip === "string",
    );
    TestValidator.predicate("consent.deleted_at is string/null/undefined")(
      consent.deleted_at === undefined ||
        consent.deleted_at === null ||
        typeof consent.deleted_at === "string",
    );
  }
}

