import type { IShoppingMallAiLegalConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiLegalConsent";

/**
 * Validate legal consent list retrieval and pagination in the admin interface.
 *
 * This test ensures the system correctly retrieves legal consent records with
 * proper pagination logic. The process is as follows:
 *
 * 1. Create more legal consent records than would fit in a single page (default
 *    page size assumed from DTO is 100 records)
 *
 *    - Use the admin legal consent creation API multiple times to populate enough
 *         test records.
 * 2. Retrieve all legal consent records via the admin API (assuming .index()
 *    returns paged data)
 *
 *    - Fetch the first page
 *    - Fetch the second page (if available)
 *    - (If more pages, fetch additional as needed)
 * 3. Verify:
 *
 *    - The paginated data sets together contain all created records
 *    - There are no duplicates or missing records across pages
 *    - The current/limit/records/pages fields in pagination reflect the correct
 *         state
 *    - Data ordering is stable between requests
 *
 * Note: This test assumes that pagination parameters (page/limit) are not
 * supported by the current admin legalConsents.index API, so only the first
 * page is directly testable. If the API is later extended to support query
 * params for pagination, this function should be extended to traverse all pages
 * and validate strict record continuity.
 */
export async function test_api_shopping_mall_ai_admin_legalConsents_test_get_legal_consents_with_large_dataset(
  connection: api.IConnection,
) {
  // Step 1: Determine the default page size. The DTO IPage.IPagination description says default is 100
  const pageSize = 100;
  const totalToCreate = pageSize * 2 + 10; // Ensure two full pages plus extra

  // Step 2: Create legal consent records in excess of page size
  const createdRecords: IShoppingMallAiLegalConsent[] = [];
  for (let i = 0; i < totalToCreate; ++i) {
    const record =
      await api.functional.shopping_mall_ai.admin.legalConsents.create(
        connection,
        {
          body: {
            user_id: `test-user-${i}`,
            policy_code: `policyCode-${i % 5}`,
            policy_version: `v${1 + (i % 3)}`,
            consented_at: new Date(Date.now() - i * 1000).toISOString(),
            consent_method: i % 2 === 0 ? "admin" : "import",
            consent_ip: `192.168.1.${i % 255}`,
          } satisfies IShoppingMallAiLegalConsent.ICreate,
        },
      );
    typia.assert(record);
    createdRecords.push(record);
  }

  // Step 3: Retrieve the first page of legal consent records
  const page1 =
    await api.functional.shopping_mall_ai.admin.legalConsents.index(connection);
  typia.assert(page1);

  // Step 4: Validate pagination and record integrity for first page
  // Confirm that first page contains correct number of records
  TestValidator.equals("page1 data matches with limit or record count")(
    page1.data.length,
  )(Math.min(page1.pagination.limit, page1.pagination.records));
  // Validate all returned records are unique by id within the page
  const uniqueIds = new Set(page1.data.map((item) => item.id));
  TestValidator.equals("all records are unique in the page")(page1.data.length)(
    uniqueIds.size,
  );
  // Validate pagination metadata is consistent
  TestValidator.equals("pages calculation matches records and limit")(
    page1.pagination.pages,
  )(Math.ceil(page1.pagination.records / page1.pagination.limit));

  // Optionally, check that at least some of the records we created are present in the returned page (not guaranteed depending on sorting)
  const presentCount = createdRecords.filter((r) => uniqueIds.has(r.id)).length;
  TestValidator.predicate(
    "at least one record we created is present in first page",
  )(presentCount > 0);

  // If/when API supports pagination query params, extend this test to traverse all pages and verify every created record.
}

