/**
 * Test updating a content moderation record as an admin.
 *
 * This test validates the workflow where an admin updates a moderation
 * log—correcting a previous moderation action, changing status (e.g. 'hidden'
 * to 'restored'), or amending the rationale/comment. This scenario is critical
 * for dashboard reporting, audit traceability, and legal compliance.
 *
 * Step-by-step process:
 *
 * 1. Create an initial moderation record (e.g., action 'hide', targeting a
 *    'bbs_post')
 * 2. Update that record: change action to 'restore', update message, set
 *    restored_at
 * 3. Assert all update fields are reflected in the response
 * 4. Confirm unchanged fields remain intact
 */
export async function test_api_shopping_mall_ai_admin_contentModerations_test_update_content_moderation_successful_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a moderation event log record
  const moderationCreate =
    await api.functional.shopping_mall_ai.admin.contentModerations.create(
      connection,
      {
        body: {
          shopping_mall_ai_admin_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          content_type: "bbs_post",
          content_id: typia.random<string & tags.Format<"uuid">>(),
          action: "hide",
          message: "Hidden for test purposes.",
          acted_at: new Date().toISOString(),
        } satisfies IShoppingContentModeration.ICreate,
      },
    );
  typia.assert(moderationCreate);

  // 2. Update the moderation record: action='restore', supply new message, set restored_at
  const updateBody = {
    action: "restore",
    message: "Restored after review.",
    restored_at: new Date().toISOString(),
  } satisfies IShoppingContentModeration.IUpdate;
  const moderationUpdate =
    await api.functional.shopping_mall_ai.admin.contentModerations.update(
      connection,
      {
        contentModerationId: moderationCreate.id,
        body: updateBody,
      },
    );
  typia.assert(moderationUpdate);

  // 3. Assert update took effect on modifiable fields
  TestValidator.equals("updated action")(moderationUpdate.action)("restore");
  TestValidator.equals("updated message")(moderationUpdate.message)(
    "Restored after review.",
  );
  TestValidator.equals("updated restored_at")(
    moderationUpdate.restored_at !== null,
  )(true);

  // 4. Assert unchanged fields remain the same
  TestValidator.equals("admin id unchanged")(
    moderationUpdate.shopping_mall_ai_admin_id,
  )(moderationCreate.shopping_mall_ai_admin_id);
  TestValidator.equals("content id unchanged")(moderationUpdate.content_id)(
    moderationCreate.content_id,
  );
  TestValidator.equals("content type unchanged")(moderationUpdate.content_type)(
    moderationCreate.content_type,
  );
  TestValidator.equals("acted_at unchanged")(moderationUpdate.acted_at)(
    moderationCreate.acted_at,
  );
}

