import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAiContentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAiContentAudit";
import type { IPageIShoppingAiContentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAiContentAudit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching AI content audits using complex filters.
 *
 * This function validates the admin-only search functionality for AI content
 * audit logs using a combination of filter criteria: violation type, confidence
 * threshold, and audit time window. It verifies that the search endpoint
 * returns only records matching the search criteria, and that all pagination
 * and filtering logic is correct as per business rules.
 *
 * Steps:
 *
 * 1. Create several distinguishable AI content audit logs (w/ varying
 *    violation_type, confidence, audited_at, and action_suggested) using the
 *    admin-only create endpoint.
 * 2. Perform search queries with various filter combinations: a. Filter by single
 *    violation_type, expecting only records of that type b. Filter by modeled
 *    confidence_min/confidence_max, expecting only records in range c. Filter
 *    by audited_at_from/audited_at_to for date-range filter d. Combine multiple
 *    filters to narrow results
 * 3. For each search, check:
 *
 *    - Only matching records are returned
 *    - Non-matching records are excluded
 *    - Pagination meta is correct
 */
export async function test_api_shopping_mall_ai_admin_aiContentAudits_test_search_ai_content_audits_with_filter(
  connection: api.IConnection,
) {
  // 1. Create multiple AI content audit logs with distinguishable attributes
  const contentTypes = ["bbs_post", "review", "bbs_comment"];
  const violationTypes = ["spam", "profanity", "personal_info"];
  const actions = ["accept", "block", "review"];
  const baseDate = new Date();

  // Ensure date spread for filtering
  const audits = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const content_type = RandomGenerator.pick(contentTypes);
    const violation_type = RandomGenerator.pick(violationTypes);
    const action_suggested = RandomGenerator.pick(actions);
    const confidence = 0.5 + 0.1 * i; // [0.5, 0.9]
    const audited_at = new Date(
      baseDate.getTime() + 60 * 60 * 1000 * i,
    ).toISOString();
    const content_id = typia.random<string & tags.Format<"uuid">>();
    const created =
      await api.functional.shopping_mall_ai.admin.aiContentAudits.create(
        connection,
        {
          body: {
            content_type,
            content_id,
            violation_type,
            confidence,
            action_suggested,
            audited_at,
          } satisfies IShoppingAiContentAudit.ICreate,
        },
      );
    typia.assert(created);
    return created;
  });

  // 2a. Filter by violation_type
  const typeToFilter = audits[0].violation_type;
  const outType =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.search(
      connection,
      {
        body: {
          violation_type: typeToFilter,
        } satisfies IShoppingAiContentAudit.IRequest,
      },
    );
  typia.assert(outType);
  TestValidator.predicate("all violation types match filter")(
    outType.data.every((row) => row.violation_type === typeToFilter),
  );

  // 2b. Filter by confidence_min/confidence_max
  const minConf = 0.6,
    maxConf = 0.8;
  const outConf =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.search(
      connection,
      {
        body: {
          confidence_min: minConf,
          confidence_max: maxConf,
        } satisfies IShoppingAiContentAudit.IRequest,
      },
    );
  typia.assert(outConf);
  TestValidator.predicate("all confidence values in range")(
    outConf.data.every(
      (row) => row.confidence >= minConf && row.confidence <= maxConf,
    ),
  );

  // 2c. Filter by audited_at_from/audited_at_to (date range)
  const from = audits[1].audited_at;
  const to = audits[3].audited_at;
  const outDate =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.search(
      connection,
      {
        body: {
          audited_at_from: from,
          audited_at_to: to,
        } satisfies IShoppingAiContentAudit.IRequest,
      },
    );
  typia.assert(outDate);
  TestValidator.predicate("all audited_at in range")(
    outDate.data.every((row) => row.audited_at >= from && row.audited_at <= to),
  );

  // 2d. Combine multiple filters to narrow result
  const filter = {
    violation_type: audits[2].violation_type,
    confidence_min: audits[2].confidence,
    confidence_max: audits[2].confidence,
    action_suggested: audits[2].action_suggested,
    audited_at_from: audits[2].audited_at,
    audited_at_to: audits[2].audited_at,
  } satisfies IShoppingAiContentAudit.IRequest;
  const outCombo =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.search(
      connection,
      {
        body: filter,
      },
    );
  typia.assert(outCombo);
  TestValidator.predicate("result only includes exact filtered record")(
    outCombo.data.length === 1 && outCombo.data[0].id === audits[2].id,
  );

  // 3. Pagination meta check
  TestValidator.predicate("pagination meta valid")(
    typeof outCombo.pagination === "object" &&
      typeof outCombo.pagination.current === "number" &&
      outCombo.pagination.current >= 1 &&
      typeof outCombo.pagination.pages === "number" &&
      outCombo.pagination.pages >= 1 &&
      typeof outCombo.pagination.limit === "number" &&
      outCombo.pagination.limit >= 1,
  );
}

