import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Validate that soft-deleted posts do not appear in customer BBS listing.
 *
 * Customers may create posts (BBS) and soft-delete them (sets deleted_at, not
 * hard-remove). The endpoint GET /shopping-mall-ai/customer/bbsPosts must never
 * return posts with deleted_at not null.
 *
 * Step-by-step:
 *
 * 1. Create several BBS posts (at least 3, for coverage)
 * 2. Soft-delete at least one post
 * 3. Query the list of BBS posts
 * 4. Assert only non-deleted post IDs are present
 * 5. Confirm soft-deleted post(s) are excluded, and all expected remain
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_index_excludes_deleted(
  connection: api.IConnection,
) {
  // 1. Create 3 BBS posts
  const posts: IShoppingMallAiBbsPost[] = [];
  for (let i = 0; i < 3; ++i) {
    const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
      connection,
      {
        body: {
          shopping_mall_ai_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          shopping_mall_ai_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: `Post number ${i + 1}`,
          body: `Post body for BBS post #${i + 1}.`,
        } satisfies IShoppingMallAiBbsPost.ICreate,
      },
    );
    typia.assert(post);
    posts.push(post);
  }

  // 2. Soft-delete the second post
  await api.functional.shopping_mall_ai.customer.bbsPosts.erase(connection, {
    bbsPostId: posts[1].id,
  });

  // 3. Query the list of BBS posts
  const summary: IPageIShoppingMallAiBbsPost.ISummary =
    await api.functional.shopping_mall_ai.customer.bbsPosts.index(connection);
  typia.assert(summary);

  // 4. Gather returned post IDs
  const returnedIds = summary.data.map((x) => x.id);

  // 5. Checks:
  //   - The deleted post (posts[1]) must NOT be present
  //   - All non-deleted posts (posts[0], posts[2]) must be present
  TestValidator.predicate("deleted post should NOT be listed")(
    !returnedIds.includes(posts[1].id),
  );
  TestValidator.predicate("1st post present")(
    returnedIds.includes(posts[0].id),
  );
  TestValidator.predicate("3rd post present")(
    returnedIds.includes(posts[2].id),
  );

  // 6. Optionally, check that only expected posts present (no extras)
  const expectedIds = [posts[0].id, posts[2].id];
  TestValidator.equals("Only non-deleted posts present")(returnedIds.sort())(
    expectedIds.sort(),
  );
}

