) {
  // 1. Create two BBS posts as a seller in different sections/channels
  const channelId1 = typia.random<string & tags.Format<"uuid">>();
  const sectionId1 = typia.random<string & tags.Format<"uuid">>();
  const title1 = "Seller's Post One - " + RandomGenerator.paragraph()(3);
  const body1 = RandomGenerator.content()(2)(3);

