  const channelId2 = typia.random<string & tags.Format<"uuid">>();
  const sectionId2 = typia.random<string & tags.Format<"uuid">>();
  const title2 = "Seller's Post Two - " + RandomGenerator.paragraph()(3);
  const body2 = RandomGenerator.content()(2)(3);

  const created2 = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
