import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";

/**
 * Validate that BBS post listing for sellers excludes soft-deleted posts.
 *
 * Business context:
 *
 * - Seller forum (BBS) should only display posts that have not been soft-deleted,
 *   i.e., deleted_at is null.
 * - When posts are soft-deleted (deleted_at set, not null), they must not show up
 *   in the seller BBS list (GET endpoint).
 * - Soft-deletion is performed by API: seller/bbsPosts/{bbsPostId} DELETE, which
 *   must set deleted_at timestamp.
 *
 * Steps:
 *
 * 1. Create two posts as the seller (Post A and Post B)
 * 2. Soft-delete Post A using the DELETE API
 * 3. Perform a GET for seller/bbsPosts (index API)
 * 4. Verify that Post A is not in the returned data, and Post B is present
 * 5. (Edge) Soft-delete Post B, then GET again and confirm the list is empty
 */
export async function test_api_shopping_mall_ai_seller_bbsPosts_excludes_deleted_for_seller(
  connection: api.IConnection,
) {
  // Step 1: Create two posts as seller
  const postA = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Post A - visible",
        body: "This is Post A, which will be deleted.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(postA);
  const postB = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Post B - should persist",
        body: "This is Post B, should remain after A deleted.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(postB);

  // Step 2: Soft-delete Post A
  await api.functional.shopping_mall_ai.seller.bbsPosts.erase(connection, {
    bbsPostId: postA.id,
  });

  // Step 3: List all posts as seller
  const list1 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.index(connection);
  typia.assert(list1);
  // Step 4: Check Post A is absent, Post B is present
  TestValidator.predicate("Post A not in list after delete")(
    !list1.data.some((item) => item.id === postA.id),
  );
  TestValidator.predicate("Post B present in list")(
    list1.data.some((item) => item.id === postB.id),
  );

  // Step 5: Soft-delete Post B, confirm list is empty
  await api.functional.shopping_mall_ai.seller.bbsPosts.erase(connection, {
    bbsPostId: postB.id,
  });
  const list2 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.index(connection);
  typia.assert(list2);
  TestValidator.equals("No posts after both deleted")(list2.data.length)(0);
}

