/**
 * Test advanced BBS forum post searching with multiple filters as a customer.
 *
 * This test validates the advanced search/filter endpoint for customer BBS
 * posts, ensuring that:
 *
 * 1. Posts can be filtered by channel, section, author, title substring, and
 *    creation date range.
 * 2. Only posts that are not soft-deleted (deleted_at is null) appear in the
 *    search results.
 * 3. Returned posts strictly match the specified filter criteria.
 * 4. Returned summary fields are appropriate for the customer role.
 *
 * Step-by-step process:
 *
 * 1. Create multiple test posts with varying channels, sections, authors, titles,
 *    and timestamps.
 *
 *    - Some posts intentionally overlap on certain fields to test filter
 *         correctness.
 * 2. For each filter type:
 *
 *    - Filter by channel: verify only posts of that channel are returned.
 *    - Filter by section: verify only posts from the given section are returned.
 *    - Filter by title substring: perform fuzzy search on title and verify correct
 *         matches.
 *    - Filter by creation date range: only posts created within the range are
 *         returned.
 * 3. For combination filters, verify intersection works (AND logic).
 * 4. Note: Filtering by author cannot be directly tested (we can only create posts
 *    with the current session customer).
 * 5. Note: Soft-deleted post test is skipped due to lack of delete API.
 *
 * All tests assert that returned results match the filters and customer-facing
 * summary field expectations.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_search_bbs_posts_with_advanced_filters(
  connection: api.IConnection,
) {
  // Step 1: Test data setup - create posts with different channels, sections, authors, titles, timestamps
  // Create two channels and two sections for coverage
  const channelA = typia.random<string & tags.Format<"uuid">>();
  const channelB = typia.random<string & tags.Format<"uuid">>();
  const sectionA = typia.random<string & tags.Format<"uuid">>();
  const sectionB = typia.random<string & tags.Format<"uuid">>();

  // Author A (current customer session)
  const titleKeyword = "filter-keyword-" + RandomGenerator.alphaNumeric(5);
  const now = new Date();

  // Create posts with controlled fields
  const post1 = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelA,
        shopping_mall_ai_section_id: sectionA,
        title: titleKeyword + " A",
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(post1);

  const post2 = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelA,
        shopping_mall_ai_section_id: sectionB,
        title: "Unrelated",
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(post2);

  const post3 = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelB,
        shopping_mall_ai_section_id: sectionA,
        title: titleKeyword + " B",
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(post3);

  // Step 2: Test filtering by channel
  const searchByChannel =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_channel_id: channelA,
        active_only: true,
      },
    });
  typia.assert(searchByChannel);
  for (const summary of searchByChannel.data) {
    TestValidator.equals("channel filter")(summary.shopping_mall_ai_channel_id)(
      channelA,
    );
  }

  // Step 3: Test filtering by section
  const searchBySection =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_section_id: sectionA,
        active_only: true,
      },
    });
  typia.assert(searchBySection);
  for (const summary of searchBySection.data) {
    TestValidator.equals("section filter")(summary.shopping_mall_ai_section_id)(
      sectionA,
    );
  }

  // Step 4: Test filtering by title substring (free text)
  const searchByTitle =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        title: titleKeyword,
        active_only: true,
      },
    });
  typia.assert(searchByTitle);
  for (const summary of searchByTitle.data) {
    TestValidator.predicate("title substring filter")(
      summary.title.includes(titleKeyword),
    );
  }

  // Step 5: Test filtering by date range
  const from = new Date(now.getTime() - 30000).toISOString();
  const to = new Date(now.getTime() + 30000).toISOString();
  const searchByDate =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        created_from: from,
        created_to: to,
        active_only: true,
      },
    });
  typia.assert(searchByDate);
  for (const summary of searchByDate.data) {
    TestValidator.predicate("date range filter")(
      summary.created_at >= from && summary.created_at <= to,
    );
  }

  // Step 6: Test combined filters - channel + title substring
  const combined =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        shopping_mall_ai_channel_id: channelA,
        title: titleKeyword,
        active_only: true,
      },
    });
  typia.assert(combined);
  for (const summary of combined.data) {
    TestValidator.equals("combined channel")(
      summary.shopping_mall_ai_channel_id,
    )(channelA);
    TestValidator.predicate("combined title")(
      summary.title.includes(titleKeyword),
    );
  }
  // Note: Soft-deleted post test is skipped (no delete API), and author filtering is not tested (cannot create posts by multiple authors with current session).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IPageIShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that advanced forum search (PATCH
 * /shopping-mall-ai/customer/bbsPosts) as a customer excludes soft-deleted
 * posts, even when they match the search filter criteria.
 *
 * Business context: BBS posts in the AI-driven shopping mall support soft
 * deletion. Customer-facing search should not show posts that have been
 * soft-deleted (deleted_at is not null), even if they would match search
 * filters. Compliance with this rule is essential for content visibility and
 * user experience.
 *
 * Steps:
 *
 * 1. Create multiple forum posts (with a common title substring, channel, and
 *    section) as the customer.
 * 2. Soft-delete one or more of these posts using the proper erase endpoint.
 * 3. Use advanced search (PATCH) with filters that would normally match all
 *    created posts — specifically, filter by title substring, channel, and
 *    section.
 * 4. Validate: The search result must exclude all posts where deleted_at is not
 *    null (i.e., soft-deleted), and only show the posts that remain active.
 * 5. As an edge case, verify that the deleted post is _not_ present even when
 *    searching without the active_only flag (as customer context may enforce
 *    this automatically), or test the flag if allowed.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_test_search_bbs_posts_excludes_deleted_entries(
  connection: api.IConnection,
) {
  // 1. Create two posts with the same title prefix, channel, and section
  const sharedTitle = "TestPost-" + RandomGenerator.alphaNumeric(8);
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        title: sharedTitle + "-A",
        body: RandomGenerator.paragraph()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post1);

  const post2 = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        title: sharedTitle + "-B",
        body: RandomGenerator.paragraph()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post2);

  // 2. Soft-delete post2
  await api.functional.shopping_mall_ai.customer.bbsPosts.erase(connection, {
    bbsPostId: post2.id,
  });

  // 3. Advanced search: filter by shared title substring, channel, and section
  //    This should normally return both posts if no delete; now only post1
  const searchResult =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        title: sharedTitle,
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        active_only: true, // ensure non-deleted results only
        page: 1,
        limit: 10,
      } satisfies IShoppingMallAiBbsPost.IRequest,
    });
  typia.assert(searchResult);
  // Should only return post1 in the results
  const resultIds = searchResult.data.map((x) => x.id);
  TestValidator.predicate("deleted post should not appear")(
    !resultIds.includes(post2.id),
  );
  TestValidator.predicate("active post should appear")(
    resultIds.includes(post1.id),
  );

  // 4. Edge case: Search again without active_only flag
  const unfilteredSearch =
    await api.functional.shopping_mall_ai.customer.bbsPosts.search(connection, {
      body: {
        title: sharedTitle,
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        page: 1,
        limit: 10,
        // active_only omitted/null
      } satisfies IShoppingMallAiBbsPost.IRequest,
    });
  typia.assert(unfilteredSearch);
  const resultIds2 = unfilteredSearch.data.map((x) => x.id);
  TestValidator.predicate(
    "even without active_only, deleted should not appear",
  )(!resultIds2.includes(post2.id));
  TestValidator.predicate("unfiltered: active post must appear")(
    resultIds2.includes(post1.id),
  );
}

