 *
 * Steps:
 *
 * 1. Create posts as another user (admin context) to represent both public and
 *    private/restricted content.
 * 2. As a customer, perform a search using normal and section-specific filters.
 * 3. Validate that only visible (non-deleted, accessible section) posts are
 *    present and that restricted/private content is not exposed.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_search_non_owner_customer(
  connection: api.IConnection,
) {
  // 1. Setup test channel/section identifiers
  const shared_channel_id = typia.random<string & tags.Format<"uuid">>();
  const shared_section_id = typia.random<string & tags.Format<"uuid">>();
  const restricted_section_id = typia.random<string & tags.Format<"uuid">>();

  // Create post #1: public/active
  const post1 = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: shared_channel_id,
        shopping_mall_ai_section_id: shared_section_id,
        title: "Public Post 1",
        body: "This is a visible public post.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post1);

  // Create post #2: public/active
  const post2 = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: shared_channel_id,
        shopping_mall_ai_section_id: shared_section_id,
        title: "Public Post 2",
        body: "This is another visible post.",
