import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAnalyticsExport } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAnalyticsExport";
import type { IPageIShoppingMallAiAnalyticsExport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAnalyticsExport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced admin searching for analytics export records with multiple
 * filter and pagination criteria.
 *
 * Verifies admin can filter analytics export logs by all supported filters and
 * controls:
 *
 * - Export_type (string)
 * - Export_reason (string)
 * - Requested_by (string)
 * - Status (string)
 * - Exported_at_from/exported_at_to (date range)
 * - Delete_after_from/delete_after_to (date range/retention)
 * - Deleted_at (date-time | null)
 * - Page/limit (pagination) Checks output schema and that all returned records
 *   match the given filters.
 *
 * Steps:
 *
 * 1. Query with no filters
 * 2. Query with each filter one by one (using representative values)
 * 3. Query with multiple filters
 * 4. Paging: normal and out-of-bounds
 * 5. Edge: no results, bad value in filter
 * 6. Query by soft-deleted (deleted_at)
 * 7. Simulate unauthorized access by removing Authorization from the connection
 *    (should error) For each test, typia.assert() is called and appropriate
 *    TestValidator(s) run on result conformance or error occurrence.
 */
export async function test_api_shopping_mall_ai_admin_analyticsExports_search_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Query with no filters
  const outputAll =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: {} },
    );
  typia.assert(outputAll);

  // Step 2: Query each filter by extracting field(s) from first record
  const record = outputAll.data[0];
  if (record) {
    // export_type
    const byExportType =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { export_type: record.export_type } },
      );
    typia.assert(byExportType);
    byExportType.data.forEach((r) => {
      TestValidator.equals("filter export_type")(r.export_type)(
        record.export_type,
      );
    });

    // export_reason
    const byReason =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { export_reason: record.export_reason } },
      );
    typia.assert(byReason);
    byReason.data.forEach((r) => {
      TestValidator.equals("filter export_reason")(r.export_reason)(
        record.export_reason,
      );
    });

    // requested_by
    const byRequestedBy =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { requested_by: record.requested_by } },
      );
    typia.assert(byRequestedBy);
    byRequestedBy.data.forEach((r) => {
      TestValidator.equals("filter requested_by")(r.requested_by)(
        record.requested_by,
      );
    });

    // status
    const byStatus =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { status: record.status } },
      );
    typia.assert(byStatus);
    byStatus.data.forEach((r) => {
      TestValidator.equals("filter status")(r.status)(record.status);
    });

    // exported_at_from/to
    const exportedAtFrom =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { exported_at_from: record.exported_at } },
      );
    typia.assert(exportedAtFrom);
    exportedAtFrom.data.forEach((r) => {
      TestValidator.predicate("exported_at_from")(
        r.exported_at >= record.exported_at,
      );
    });
    const exportedAtTo =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        { body: { exported_at_to: record.exported_at } },
      );
    typia.assert(exportedAtTo);
    exportedAtTo.data.forEach((r) => {
      TestValidator.predicate("exported_at_to")(
        r.exported_at <= record.exported_at,
      );
    });
    // delete_after_from/to, if present
    if (record.delete_after) {
      const deleteAfterFrom =
        await api.functional.shopping_mall_ai.admin.analyticsExports.search(
          connection,
          { body: { delete_after_from: record.delete_after } },
        );
      typia.assert(deleteAfterFrom);
      deleteAfterFrom.data.forEach((r) => {
        if (r.delete_after)
          TestValidator.predicate("delete_after_from")(
            r.delete_after >= record.delete_after!,
          );
      });
      const deleteAfterTo =
        await api.functional.shopping_mall_ai.admin.analyticsExports.search(
          connection,
          { body: { delete_after_to: record.delete_after } },
        );
      typia.assert(deleteAfterTo);
      deleteAfterTo.data.forEach((r) => {
        if (r.delete_after)
          TestValidator.predicate("delete_after_to")(
            r.delete_after <= record.delete_after!,
          );
      });
    }
    // deleted_at
    if (record.deleted_at) {
      const byDeletedAt =
        await api.functional.shopping_mall_ai.admin.analyticsExports.search(
          connection,
          { body: { deleted_at: record.deleted_at } },
        );
      typia.assert(byDeletedAt);
      byDeletedAt.data.forEach((r) => {
        TestValidator.equals("filter deleted_at")(r.deleted_at)(
          record.deleted_at,
        );
      });
    }
    // Multiple filters
    const mulFilter =
      await api.functional.shopping_mall_ai.admin.analyticsExports.search(
        connection,
        {
          body: {
            export_type: record.export_type,
            requested_by: record.requested_by,
            status: record.status,
          },
        },
      );
    typia.assert(mulFilter);
    mulFilter.data.forEach((r) => {
      TestValidator.equals("multi export_type")(r.export_type)(
        record.export_type,
      );
      TestValidator.equals("multi requested_by")(r.requested_by)(
        record.requested_by,
      );
      TestValidator.equals("multi status")(r.status)(record.status);
    });
  }

  // Step 3: Pagination, page 1/2 + out-of-bounds
  const paged1 =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: { page: 1, limit: 2 } },
    );
  typia.assert(paged1);
  const paged2 =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: { page: 2, limit: 2 } },
    );
  typia.assert(paged2);
  // Out of bounds: page after last
  const outOfBounds =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: { page: paged1.pagination.pages + 1, limit: 2 } },
    );
  typia.assert(outOfBounds);
  TestValidator.equals("paging out of bounds")(outOfBounds.data.length)(0);

  // Step 4: Edge - no result filter
  const none =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: { export_type: "NON_EXISTENT_EXPORT_TYPE_@!#" } },
    );
  typia.assert(none);
  TestValidator.equals("empty query")(none.data.length)(0);

  // Step 5: Edge - bad date (should not fail, just return nothing or 400 handled gracefully)
  const badDate =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      { body: { exported_at_from: "not-a-date" as any } },
    );
  typia.assert(badDate);

  // Step 6: deleted_at query
  const softDeleted =
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      connection,
      {
        body: {
          deleted_at:
            record && record.deleted_at
              ? record.deleted_at
              : new Date().toISOString(),
        },
      },
    );
  typia.assert(softDeleted);
  if (record && record.deleted_at)
    softDeleted.data.forEach((r) =>
      TestValidator.equals("only soft-deleted")(r.deleted_at)(
        record.deleted_at,
      ),
    );

  // Step 7: Unauthorized access simulation. Use a connection copy omitting Authorization, not with Authorization: undefined.
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized access")(async () => {
    await api.functional.shopping_mall_ai.admin.analyticsExports.search(
      unauthConn,
      { body: {} },
    );
  });
}

