/**
 * Validate admin creation of analytics export records with both valid and
 * invalid input.
 *
 * This test ensures that the admin can successfully create a new analytics
 * export log by providing all required fields, and that the created record is
 * schema-compliant and persisted. It also verifies rejection of invalid
 * payloads: missing required fields or malformed data. Error responses for
 * invalid input are asserted. (Uniqueness and permission/role checks are
 * omitted due to scope.)
 *
 * Steps:
 *
 * 1. Construct valid input data for export (type, reason, URI, actor, status,
 *    completion time, optional delete_after)
 * 2. As admin, call the analyticsExports.create API and assert output shape
 * 3. Attempt creation with each required field missing (one at a time) and expect
 *    rejection (runtime error)
 * 4. Attempt creation with invalid/malformed fields and expect rejection (runtime
 *    error)
 */
export async function test_api_shopping_mall_ai_admin_analyticsexports_test_create_analytics_export_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Build valid payload
  const validInput: IShoppingMallAiAnalyticsExport.ICreate = {
    export_type: RandomGenerator.alphabets(8),
    export_reason: RandomGenerator.paragraph()(),
    export_uri: `s3://exports/analytics/${RandomGenerator.alphaNumeric(12)}`,
    requested_by: RandomGenerator.name(),
    exported_at: new Date().toISOString(),
    delete_after: null,
    status: "completed",
  };

  // 2. Call create API and validate response
  const record =
    await api.functional.shopping_mall_ai.admin.analyticsExports.create(
      connection,
      { body: validInput },
    );
  typia.assert(record);
  TestValidator.equals("all fields copied back")(record.export_type)(
    validInput.export_type,
  );
  TestValidator.equals("all fields copied back")(record.export_reason)(
    validInput.export_reason,
  );
  TestValidator.equals("all fields copied back")(record.export_uri)(
    validInput.export_uri,
  );
  TestValidator.equals("all fields copied back")(record.requested_by)(
    validInput.requested_by,
  );
  TestValidator.equals("all fields copied back")(record.exported_at)(
    validInput.exported_at,
  );
  TestValidator.equals("all fields copied back")(record.delete_after)(
    validInput.delete_after,
  );
  TestValidator.equals("all fields copied back")(record.status)(
    validInput.status,
  );

  // 3. For each required field, attempt creation with it missing (omit at runtime)
  const requiredFields = [
    "export_type",
    "export_reason",
    "export_uri",
    "requested_by",
    "exported_at",
    "status",
  ];
  for (const field of requiredFields) {
    const invalid: any = { ...validInput };
    delete invalid[field];
    TestValidator.error(`missing required '[32m${field}[39m' should fail`)(
      async () =>
        api.functional.shopping_mall_ai.admin.analyticsExports.create(
          connection,
          { body: invalid },
        ),
    );
  }

  // 4. Some malformed values: empty string for required text, badly formed export_uri
  const malformedInputs = [
    { ...validInput, export_uri: "not a uri" },
    { ...validInput, requested_by: "" },
    { ...validInput, status: "" },
  ];
  for (const inv of malformedInputs) {
    TestValidator.error("malformed field should fail")(async () =>
      api.functional.shopping_mall_ai.admin.analyticsExports.create(
        connection,
        { body: inv },
      ),
    );
  }
}

