 * modification.
 *
 * 1. Create a new analytics export record (POST) with all required fields.
 * 2. Update mutable fields: status, delete_after, export_uri—change them and
 *    confirm the record updates correctly.
 * 3. Test business/compliance: update with invalid/edge case values (e.g., change
 *    retention date to past, or status to unaccepted values if restricted).
 * 4. Attempt to update immutable fields (if any; all are mutable per DTO; check
 *    attempted update of `id`).
 * 5. Attempt update on a non-existent record and confirm the API returns not
 *    found.
 * 6. Confirm that updates are reflected in response data and subsequent GET/list
 *    (if GET API existed—but skip, as not provided).
 * 7. Confirm type correctness and structure via typia.assert.
 * 8. Confirm API erroring via TestValidator.error where update should fail.
 */
export async function test_api_shopping_mall_ai_admin_analyticsExports_test_update_analytics_export_fields_and_audit_trail(
  connection: api.IConnection,
) {
  // 1. Create a new analytics export log entry for test
  const base: IShoppingMallAiAnalyticsExport =
    await api.functional.shopping_mall_ai.admin.analyticsExports.create(
      connection,
      {
        body: {
          export_type: "user_activity",
          export_reason: "initial test export for update",
          export_uri: "s3://bucket-a/exports/file1.json",
          requested_by: "admin@company.com",
          exported_at: new Date().toISOString(),
          delete_after: null,
          status: "pending",
        } satisfies IShoppingMallAiAnalyticsExport.ICreate,
      },
    );
  typia.assert(base);

  // 2. Update mutable fields (status, delete_after, export_uri)
  const newStatus = "completed";
  const newDeleteAfter = new Date(
    Date.now() + 1000 * 60 * 60 * 24 * 7,
  ).toISOString(); // +7 days
  const newExportUri = "s3://bucket-b/exports/file1-updated.json";
  const updated: IShoppingMallAiAnalyticsExport =
    await api.functional.shopping_mall_ai.admin.analyticsExports.update(
      connection,
      {
        analyticsExportId: base.id,
        body: {
          status: newStatus,
          delete_after: newDeleteAfter,
          export_uri: newExportUri,
        } satisfies IShoppingMallAiAnalyticsExport.IUpdate,
      },
