  TestValidator.equals("status updated")(updated.status)(newStatus);
  TestValidator.equals("delete_after updated")(updated.delete_after)(
    newDeleteAfter,
  );
  TestValidator.equals("export_uri updated")(updated.export_uri)(newExportUri);
  TestValidator.equals("id unchanged")(updated.id)(base.id);
  TestValidator.equals("requested_by unchanged")(updated.requested_by)(
    base.requested_by,
  );

  // 3. Compliance/business rule validation: update delete_after to a past date (may trigger error)
  const pastDeleteAfter = new Date(
    Date.now() - 1000 * 60 * 60 * 24,
  ).toISOString(); // -1 day
  await TestValidator.error("setting past delete_after should fail")(() =>
    api.functional.shopping_mall_ai.admin.analyticsExports.update(connection, {
      analyticsExportId: base.id,
      body: {
        delete_after: pastDeleteAfter,
      },
    }),
  );

  // 4. Edge case: attempt to update with an invalid field (attempt to update immutable 'id'—not allowed by DTO, so skipped)

  // 5. Attempt update on non-existent record id (should fail)
  await TestValidator.error("update on non-existent record should fail")(() =>
    api.functional.shopping_mall_ai.admin.analyticsExports.update(connection, {
      analyticsExportId: typia.random<string & tags.Format<"uuid">>(),
      body: { status: "archived" },
    }),
  );

  // 6. Confirm changes reflected in update response already done above; no GET endpoint to further confirm.
}

