/**
 * Test updating a product snapshot's metadata fields while safeguarding
 * historical state immutability.
 *
 * Business context: Product snapshots are regulatory/audit records where the
 * serialized state (snapshot_json) must remain immutable for compliance and
 * rollbacks, but metadata such as the action/event label can be corrected if
 * mislogged. Admin users should be able to fix a mistaken action without
 * altering the underlying historic state blob.
 *
 * This test verifies:
 *
 * 1. Only allowed metadata fields (action) are updatable via the admin API.
 * 2. The core product snapshot state (snapshot_json) is never changed by such
 *    updates.
 * 3. That attempts to mutate the historical serialized product state are correctly
 *    rejected (error thrown, or state not updated).
 *
 * Steps:
 *
 * 1. Create a new product snapshot (simulate an original 'created' event) and
 *    capture all field values.
 * 2. Update just the action via the admin API. Confirm the action changes, but
 *    snapshot_json remains identical.
 * 3. Attempt to update both action and snapshot_json (should be forbidden);
 *    validate the API throws an error or refuses the change.
 */
export async function test_api_shopping_mall_ai_product_snapshots_test_update_product_snapshot_metadata_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a valid product snapshot for update target
  const originalAction = "created";
  const originalSnapshotJson = JSON.stringify({
    name: RandomGenerator.paragraph()(4),
    price: 5000 + Math.ceil(Math.random() * 10000),
    tags: ["tag1", "tag2"],
    last_updated: new Date().toISOString(),
  });
  const created =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          action: originalAction,
          snapshot_json: originalSnapshotJson,
        } satisfies IShoppingMallAiProductSnapshot.ICreate,
      },
    );
  typia.assert(created);

  // 2. Update only the action field (compliant metadata fix)
  const newAction = "updated";
  const updated =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.update(
      connection,
      {
        shoppingMallAiProductSnapshotId: created.id,
        body: {
          action: newAction,
          snapshot_json: originalSnapshotJson,
        } satisfies IShoppingMallAiProductSnapshot.IUpdate,
      },
    );
  typia.assert(updated);
  TestValidator.equals("action field updated")(updated.action)(newAction);
  TestValidator.equals("historical snapshot_json remains immutable")(
    updated.snapshot_json,
  )(created.snapshot_json);

  // 3. Attempt (forbidden) update of the snapshot_json, should be rejected
  const tamperedSnapshotJson = JSON.stringify({
    ...JSON.parse(originalSnapshotJson),
    hacker_field: "regulatory bypass attempt",
  });
  await TestValidator.error("updating snapshot_json must fail for compliance")(
    () =>
      api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.update(
        connection,
        {
          shoppingMallAiProductSnapshotId: created.id,
          body: {
            action: "deleted",
            snapshot_json: tamperedSnapshotJson,
          } satisfies IShoppingMallAiProductSnapshot.IUpdate,
        },
      ),
  );
}

