import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiMileagePoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiMileagePoint";
import type { IPageIShoppingMallAiMileagePoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiMileagePoint";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for admin advanced search of mileage point events (loyalty points
 * audit).
 *
 * Validates:
 *
 * - Filtering by customer ID, event type ('accrual' or 'redemption'), and a date
 *   range.
 * - Proper pagination in paged results.
 * - Robust handling of malformed filter criteria (bad request errors).
 *
 * Business context:
 *
 * - Loyalty point (mileage) accrual and redemption records are critical for both
 *   auditing and customer wallet features.
 * - Accurate admin dashboard search and analytics require flexible,
 *   correctly-filtered pagination and role restriction.
 *
 * Test structure:
 *
 * 1. Construct valid filters for customer ID, event type, and sensible date range;
 *    limit result count.
 * 2. As admin, search for mileage point event records and validate all returned
 *    results match filter criteria.
 * 3. Confirm pagination settings: limit and current page.
 * 4. Issue query with an invalid filter (negative limit); expect error handling.
 */
export async function test_api_shopping_mall_ai_admin_mileagePoints_search(
  connection: api.IConnection,
) {
  // Step 1: Prepare filter parameters
  const customerId: string = typia.random<string & tags.Format<"uuid">>();
  const pointType: string = RandomGenerator.pick(["accrual", "redemption"]);
  const now = new Date();
  const occurredFrom = new Date(
    now.getTime() - 1000 * 60 * 60 * 24 * 30,
  ).toISOString(); // 30 days ago
  const occurredTo = new Date(
    now.getTime() + 1000 * 60 * 60 * 24 * 30,
  ).toISOString(); // 30 days ahead
  const limit = 3;

  // Step 2: Admin search — valid filters
  const output =
    await api.functional.shopping_mall_ai.admin.mileagePoints.search(
      connection,
      {
        body: {
          shopping_mall_ai_customer_id: customerId,
          point_type: pointType,
          occurred_at_from: occurredFrom,
          occurred_at_to: occurredTo,
          limit,
          page: 1,
        },
      },
    );
  typia.assert(output);

  // Validate filter application: all returned events must match filters
  for (const event of output.data) {
    if (event.shopping_mall_ai_customer_id !== customerId)
      throw new Error(
        `Returned event with mismatched customer_id: got ${event.shopping_mall_ai_customer_id}, expected ${customerId}`,
      );
    if (event.point_type !== pointType)
      throw new Error(
        `Returned event with mismatched point_type: got ${event.point_type}, expected ${pointType}`,
      );
    if (event.occurred_at < occurredFrom || event.occurred_at > occurredTo)
      throw new Error(
        `Event occurred_at (${event.occurred_at}) outside requested range (${occurredFrom} - ${occurredTo})`,
      );
  }
  TestValidator.equals("limit respected")(output.data.length)(
    Math.min(output.pagination.limit, output.pagination.records),
  );
  TestValidator.equals("pagination: current page is 1")(
    output.pagination.current,
  )(1);

  // Step 3: Malformed input — negative limit (should trigger validation error)
  await TestValidator.error("bad request on negative limit filter")(() =>
    api.functional.shopping_mall_ai.admin.mileagePoints.search(connection, {
      body: { limit: -10, page: 1 },
    }),
  );
}

