/**
 * Validate creation of a new mileage point event for a customer through the
 * admin API.
 *
 * This test covers the scenario where an admin creates a mileage (loyalty)
 * event for a customer as an 'accrual'. It checks that:
 *
 * - The event is successfully created when using valid, schema-compliant input
 * - The returned record matches the input fields (customer, amount, event_type,
 *   occurred_at, details) and includes a valid, generated id
 * - Attempting to create an identical event results in a new record (unique id)
 *   or enforced duplication rules
 * - Negative "amount" for accrual is rejected by business logic
 *
 * Steps:
 *
 * 1. Prepare a synthetic, valid accrual input for a customer (with uuid, positive
 *    int32 amount, ISO8601 datetime, event_type 'accrual')
 * 2. Call the admin API to create a mileage event
 * 3. Assert the event is created, output matches input (except id), and id is a
 *    uuid
 * 4. Attempt to create a duplicate (same input), verify either new id or
 *    duplication business rules (no silent overwrite)
 * 5. Attempt to create an 'accrual' event with negative amount, and verify that an
 *    error is raised
 */
export async function test_api_shopping_mall_ai_admin_mileagePoints_create(
  connection: api.IConnection,
) {
  // 1. Prepare a valid input for accrual
  const accrualInput: IShoppingMallAiMileagePoint.ICreate = {
    shopping_mall_ai_customer_id: typia.random<string & tags.Format<"uuid">>(),
    point_type: "accrual",
    amount: 100,
    details: "Welcome points for first purchase",
    occurred_at: new Date().toISOString(),
  };

  // 2. Call the admin API to create the mileage event
  const result =
    await api.functional.shopping_mall_ai.admin.mileagePoints.create(
      connection,
      { body: accrualInput },
    );
  typia.assert(result);

  // 3. Assert returned fields match input (except id)
  TestValidator.equals("customer id matches")(
    result.shopping_mall_ai_customer_id,
  )(accrualInput.shopping_mall_ai_customer_id);
  TestValidator.equals("point_type matches")(result.point_type)(
    accrualInput.point_type,
  );
  TestValidator.equals("amount matches")(result.amount)(accrualInput.amount);
  TestValidator.equals("details matches")(result.details)(accrualInput.details);
  TestValidator.equals("occurred_at matches")(result.occurred_at)(
    accrualInput.occurred_at,
  );
  // id should be a uuid, non-empty
  typia.assert<string & tags.Format<"uuid">>(result.id);

  // 4. Attempt duplicate: same input, confirm either duplicate rule or new record with distinct id
  const duplicateResult =
    await api.functional.shopping_mall_ai.admin.mileagePoints.create(
      connection,
      { body: accrualInput },
    );
  typia.assert(duplicateResult);
  TestValidator.notEquals("duplicate event id must differ")(duplicateResult.id)(
    result.id,
  );

  // 5. Attempt an 'accrual' event with a negative amount. Should fail (business rule).
  const negativeInput: IShoppingMallAiMileagePoint.ICreate = {
    ...accrualInput,
    amount: -50,
  };
  await TestValidator.error("accrual should not allow negative points")(
    async () => {
      await api.functional.shopping_mall_ai.admin.mileagePoints.create(
        connection,
        { body: negativeInput },
      );
    },
  );
}

