import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiMileagePoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiMileagePoint";

/**
 * Validates updating mutable fields of a specific mileage point event via admin
 * API.
 *
 * This test ensures that only updatable properties (amount, point_type,
 * occurred_at, details) of a mileage event can be modified, while immutable
 * fields (id, customer reference) are protected. The test includes both
 * successful update and attempts to mutate immutable fields which must be
 * rejected.
 *
 * Steps:
 *
 * 1. Create a baseline mileage point event as a fixture with the POST API.
 * 2. Update permitted fields (amount, point_type, occurred_at, details) and
 *    confirm all relevant changes.
 * 3. Attempt to update immutable fields (id, shopping_mall_ai_customer_id) via the
 *    update API, expecting errors.
 */
export async function test_api_shopping_mall_ai_admin_mileagePoints_test_update_mileage_point_event_with_permitted_fields(
  connection: api.IConnection,
) {
  // 1. Create a baseline mileage point event
  const base: IShoppingMallAiMileagePoint =
    await api.functional.shopping_mall_ai.admin.mileagePoints.create(
      connection,
      {
        body: {
          shopping_mall_ai_customer_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          point_type: "accrual",
          amount: 100,
          details: "Initial accrual for test",
          occurred_at: new Date().toISOString(),
        } satisfies IShoppingMallAiMileagePoint.ICreate,
      },
    );
  typia.assert(base);

  // 2. Update one or more permitted fields (amount, point_type, occurred_at, details)
  const updateBody: IShoppingMallAiMileagePoint.IUpdate = {
    amount: 250,
    point_type: "adjustment",
    occurred_at: new Date(Date.now() + 86400000).toISOString(),
    details: "Corrected test amount and event type.",
  };
  const updated: IShoppingMallAiMileagePoint =
    await api.functional.shopping_mall_ai.admin.mileagePoints.update(
      connection,
      {
        mileagePointId: base.id,
        body: updateBody,
      },
    );
  typia.assert(updated);
  TestValidator.equals("ID should remain the same")(updated.id)(base.id);
  TestValidator.equals("customer ID should remain the same")(
    updated.shopping_mall_ai_customer_id,
  )(base.shopping_mall_ai_customer_id);
  TestValidator.equals("amount updated")(updated.amount)(updateBody.amount);
  TestValidator.equals("point_type updated")(updated.point_type)(
    updateBody.point_type,
  );
  TestValidator.equals("occurred_at updated")(updated.occurred_at)(
    updateBody.occurred_at,
  );
  TestValidator.equals("details updated")(updated.details)(updateBody.details);

  // 3. Attempt to update immutable fields (should throw error or be ignored)
  await TestValidator.error("id update rejected")(() =>
    api.functional.shopping_mall_ai.admin.mileagePoints.update(connection, {
      mileagePointId: base.id,
      body: { id: typia.random<string & tags.Format<"uuid">>() } as any,
    }),
  );
  await TestValidator.error("customer id update rejected")(() =>
    api.functional.shopping_mall_ai.admin.mileagePoints.update(connection, {
      mileagePointId: base.id,
      body: {
        shopping_mall_ai_customer_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } as any,
    }),
  );
}

