import type { IPageIShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFile";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the advanced search functionality for shopping mall AI files as an
 * admin.
 *
 * This test ensures that an admin can use various filtering and sorting
 * parameters to search file metadata records and accurately receive paginated
 * results.
 *
 * Steps:
 *
 * 1. Prepare a complex set of filters, including original file name, extension,
 *    MIME type, a date range (created_from/to), and pagination options.
 * 2. Call the advanced search endpoint with these filters.
 * 3. Verify the response contains only records that match the provided criteria,
 *    respecting all filters.
 * 4. Validate that the pagination information is present and accurate.
 * 5. Ensure the result data structure matches expectations and all required
 *    metadata (e.g., pagination, file properties) is included.
 * 6. Validate that pagination behaves as intended by testing different limit/page
 *    combinations.
 */
export async function test_api_shopping_mall_ai_file_test_advanced_search_of_files_with_filters_and_sorting(
  connection: api.IConnection,
) {
  // 1. Prepare filters (some realistic example values).
  const filterRequest: IShoppingMallAiFile.IRequest = {
    // Filter by file name substring
    original_name: "invoice",
    // Extension filter
    extension: "pdf",
    // MIME type filter
    mime_type: "application/pdf",
    // Simulate a date range (last month)
    created_from: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30).toISOString(),
    created_to: new Date().toISOString(),
    // No actor filters for this test
    actor_type: null,
    actor_id: null,
    // Only active (not deleted)
    deleted: false,
    // Pagination
    page: 1,
    limit: 10,
  };

  // 2. Call the search endpoint
  const initialPage =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.search(
      connection,
      { body: filterRequest },
    );
  typia.assert(initialPage);
  const files = initialPage.data;

  // 3. Validate filter match
  for (const file of files) {
    if (filterRequest.original_name)
      TestValidator.predicate("original_name match")(
        file.original_name
          .toLowerCase()
          .includes(filterRequest.original_name.toLowerCase()),
      );
    if (filterRequest.extension)
      TestValidator.equals("extension match")(file.extension)(
        filterRequest.extension,
      );
    if (filterRequest.mime_type)
      TestValidator.equals("mime_type match")(file.mime_type)(
        filterRequest.mime_type,
      );
    if (filterRequest.created_from)
      TestValidator.predicate("created_at after created_from")(
        new Date(file.created_at) >= new Date(filterRequest.created_from!),
      );
    if (filterRequest.created_to)
      TestValidator.predicate("created_at before created_to")(
        new Date(file.created_at) <= new Date(filterRequest.created_to!),
      );
    if (filterRequest.deleted === false)
      TestValidator.equals("active file (not deleted)")(file.deleted_at)(null);
  }

  // 4. Validate pagination metadata
  TestValidator.equals("pagination limit")(initialPage.pagination.limit)(
    filterRequest.limit,
  );
  TestValidator.equals("pagination page")(initialPage.pagination.current)(
    filterRequest.page,
  );
  TestValidator.predicate("pagination records nonnegative")(
    initialPage.pagination.records >= 0,
  );
  TestValidator.predicate("pagination pages positive")(
    initialPage.pagination.pages >= 1,
  );
  TestValidator.equals("result data length matches or is below limit")(
    files.length <= filterRequest.limit!,
  )(true);

  // 5. Pagination: Call next page and check for independence
  if (initialPage.pagination.pages > 1) {
    const nextPage =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.search(
        connection,
        { body: { ...filterRequest, page: filterRequest.page! + 1 } },
      );
    typia.assert(nextPage);
    TestValidator.equals("pagination next page")(nextPage.pagination.current)(
      filterRequest.page! + 1,
    );
  }
}

