import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";

/**
 * Test that unauthenticated users cannot register file metadata (forbidden).
 *
 * This test simulates an attempt to register a file metadata record via the
 * customer endpoint without performing customer authentication first. The
 * request should fail with an authorization/permission denied error, confirming
 * that only authenticated users can use this endpoint.
 *
 * Step-by-step process:
 *
 * 1. Construct valid file metadata input (simulating a file upload metadata
 *    object).
 * 2. Attempt to register file metadata using the customer API endpoint WITHOUT
 *    authenticating the user.
 * 3. Assert that an authorization/permission denied error occurs.
 */
export async function test_api_shopping_mall_ai_test_register_file_metadata_forbidden_if_unauthenticated(
  connection: api.IConnection,
) {
  // 1. Create a sample input for file metadata (simulate file upload)
  const input = {
    original_name: "user_document.pdf",
    uri: "https://cdn.example.com/blob/1234567890abcdef.pdf",
    extension: "pdf",
    mime_type: "application/pdf",
    size: 123456,
    hash: "f3bbbd66a63d4bf1747940578ec3d0103530e21d6c7c1b6c826caae1c3a5c953",
  } satisfies IShoppingMallAiFile.ICreate;

  // 2. Attempt registering file metadata without authentication (should fail with authorization error)
  await TestValidator.error(
    "should deny unauthenticated file metadata registration",
  )(async () => {
    await api.functional.shopping_mall_ai.customer.shoppingMallAiFiles.create(
      connection,
      { body: input },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";

/**
 * Validate that a seller can register new file metadata after uploading a file.
 *
 * This test checks the process after a file is uploaded by the seller, ensuring
 * correct registration of the file's metadata. Every field in the body
 * represents information expected at registration, such as the file's original
 * name, URI, extension, MIME type, size, and hash. The test will:
 *
 * 1. Construct a valid IShoppingMallAiFile.ICreate object, providing all metadata
 *    fields as if a seller just uploaded a new file. This includes `actor_type`
 *    and `actor_id` to identify the uploader.
 * 2. Call the /shopping-mall-ai/seller/shoppingMallAiFiles create endpoint to
 *    register the file metadata.
 * 3. Assert that all fields provided in input are exactly reflected in the
 *    response, for full round-trip compliance.
 * 4. Verify that system-generated fields (id, created_at, deleted_at) are present
 *    and properly formatted.
 * 5. Validate types and all documentation contract expectations for both request
 *    and response.
 */
export async function test_api_shopping_mall_ai_seller_shoppingMallAiFiles_create(
  connection: api.IConnection,
) {
  // Step 1: Generate input metadata as if a seller has uploaded a file
  const fileInput: IShoppingMallAiFile.ICreate = {
    original_name: "sample-report.pdf",
    uri: "https://cdn.example.com/uploads/sample-report.pdf",
    extension: "pdf",
    mime_type: "application/pdf",
    size: 543210,
    hash: "4a44dc15364204a80fe80e9039455cc1",
    actor_type: "seller",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };

  // Step 2: Register the file metadata through the API as seller
  const output: IShoppingMallAiFile =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiFiles.create(
      connection,
      { body: fileInput },
    );
  typia.assert(output);

  // Step 3: Confirm that all metadata fields match the input payload
  TestValidator.equals("original_name")(output.original_name)(
    fileInput.original_name,
  );
  TestValidator.equals("uri")(output.uri)(fileInput.uri);
  TestValidator.equals("extension")(output.extension)(fileInput.extension);
  TestValidator.equals("mime_type")(output.mime_type)(fileInput.mime_type);
  TestValidator.equals("size")(output.size)(fileInput.size);
  TestValidator.equals("hash")(output.hash)(fileInput.hash);
  TestValidator.equals("actor_type")(output.actor_type)(fileInput.actor_type);
  TestValidator.equals("actor_id")(output.actor_id)(fileInput.actor_id);

  // Step 4: Validate system fields
  TestValidator.predicate("id is uuid")(
    typeof output.id === "string" && /^[0-9a-f-]{36}$/i.test(output.id),
  );
  TestValidator.predicate("created_at is valid ISO8601")(
    typeof output.created_at === "string" &&
      !isNaN(Date.parse(output.created_at)),
  );
  TestValidator.equals("deleted_at must be null for active files")(
    output.deleted_at,
  )(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";

/**
 * Validate deduplication enforcement when registering file metadata as a
 * seller.
 *
 * This test confirms that when a seller attempts to register metadata for an
 * uploaded file with a hash already present in the system, the backend enforces
 * deduplication and rejects the request with an error (e.g., conflict or
 * validation failure).
 *
 * Steps:
 *
 * 1. Prepare a valid file metadata object with unique random hash.
 * 2. Register the file metadata via the seller API (should succeed; store used
 *    hash).
 * 3. Modify one or more non-unique fields, but keep the hash exactly the same.
 * 4. Attempt to register the modified file metadata (with duplicate hash) via the
 *    seller API.
 * 5. Assert that the operation fails due to deduplication enforcement.
 */
export async function test_api_shopping_mall_ai_test_register_file_metadata_with_duplicate_hash_as_seller(
  connection: api.IConnection,
) {
  // 1. Prepare a valid file metadata object (random values, including a unique hash)
  const fileMetadata = {
    original_name: RandomGenerator.alphaNumeric(10),
    uri: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}`,
    extension: "png",
    mime_type: "image/png",
    size: 512,
    hash: typia.random<string>(),
    actor_type: "seller",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallAiFile.ICreate;

  // 2. Register the file metadata for the first time (should succeed)
  const output =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiFiles.create(
      connection,
      {
        body: fileMetadata,
      },
    );
  typia.assert(output);

  // 3. Modify non-unique fields (but keep the hash the same), e.g. original_name
  const duplicateMetadata = {
    ...fileMetadata,
    original_name: RandomGenerator.alphaNumeric(12),
    uri: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}`,
    size: 1024,
  } satisfies IShoppingMallAiFile.ICreate;

  // 4. Attempt to register metadata with same hash (should error)
  await TestValidator.error("Deduplication violation: duplicate file hash")(
    async () => {
      await api.functional.shopping_mall_ai.seller.shoppingMallAiFiles.create(
        connection,
        {
          body: duplicateMetadata,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";

/**
 * Validate that registering a file metadata as a seller without authentication
 * or with insufficient seller permissions is forbidden.
 *
 * This test ensures the system correctly restricts file metadata registration
 * to only authenticated sellers with proper access. Attempts from
 * unauthenticated requests (no valid token) or those lacking seller authority
 * (e.g., customer or invalid token) must be denied.
 *
 * Steps:
 *
 * 1. Attempt to register file metadata WITHOUT authentication header; expect
 *    permission (authorization) error.
 * 2. (Optionally) Attempt the same request with a connection that is authenticated
 *    as a non-seller (if possible, e.g., as a customer or using an expired
 *    token); expect permission error.
 * 3. Ensure that no metadata record is created in either case.
 *
 * Error handling: Must assert that a proper error is thrown and no file record
 * is created.
 */
export async function test_api_shopping_mall_ai_file_test_register_file_metadata_forbidden_if_unauthenticated_seller(
  connection: api.IConnection,
) {
  // Step 1: Attempt to register file metadata as unauthenticated
  const fileBody: IShoppingMallAiFile.ICreate = {
    original_name: RandomGenerator.alphabets(12),
    uri: RandomGenerator.alphaNumeric(16),
    extension: "png",
    mime_type: "image/png",
    size: typia.random<number & tags.Type<"int32">>(),
    hash: RandomGenerator.alphaNumeric(32),
    actor_type: "seller",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };

  // Remove authentication
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(
        ([key]) => key.toLowerCase() !== "authorization",
      ),
    ),
  };

  await TestValidator.error("unauthenticated requests must be forbidden")(() =>
    api.functional.shopping_mall_ai.seller.shoppingMallAiFiles.create(
      unauthConnection,
      { body: fileBody },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";
import type { IPageIShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced customer review search using composite filters.
 *
 * This test verifies that a customer can perform complex searches over their
 * own product reviews using multiple filters (product ID, order ID, rating
 * range, creation date, keywords), and receives only the expected (non-deleted,
 * authored by self) reviews. Also confirms business privacy:
 * restricted/internal/moderation fields are not included in results.
 *
 * Steps:
 *
 * 1. Authenticate as a customer (assume pre-existing or simulated).
 * 2. Generate filters for the search (as review insertion is not available via
 *    SDK, test proceeds on existing/simulated data).
 * 3. Call /shopping-mall-ai/customer/reviews endpoint with composite filters for
 *    product, order, rating range, date, and body keyword, plus sort, order,
 *    and pagination.
 * 4. Validate all returned reviews match the filters, belong to the customer, are
 *    not soft-deleted, and that paging/sorting/privacy requirements are
 *    upheld.
 * 5. Edge case: Search with a non-existent product to confirm zero results.
 */
export async function test_api_shopping_mall_ai_customer_reviews_test_search_customer_reviews_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Prepare composite filters: product, order, rating range, date, body
  const filterProductId = typia.random<string & tags.Format<"uuid">>();
  const filterOrderId = typia.random<string & tags.Format<"uuid">>();
  const ratingMin = 3;
  const ratingMax = 5;
  const createdAfter = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 1 week ago
  const createdBefore = new Date().toISOString();
  const bodyKeyword = "great";

  // Composite filter (assuming supported server-side operators)
  const compositeFilter = {
    shopping_mall_ai_product_id: filterProductId,
    shopping_mall_ai_order_id: filterOrderId,
    rating: { $gte: ratingMin, $lte: ratingMax },
    created_at: { $gte: createdAfter, $lte: createdBefore },
    body: { $regex: bodyKeyword },
  };

  // Pagination and sorting
  const page = 1;
  const limit = 10;
  const sort = "created_at";
  const order = "desc";

  // 2. Search reviews with all filters
  const result = await api.functional.shopping_mall_ai.customer.reviews.search(
    connection,
    {
      body: { filter: compositeFilter, sort, order, page, limit },
    },
  );
  typia.assert(result);

  // 3. Validate results
  for (const review of result.data) {
    if (review.shopping_mall_ai_product_id !== filterProductId)
      throw new Error("Returned review is for the wrong product");
    if (review.shopping_mall_ai_order_id !== filterOrderId)
      throw new Error("Returned review is for the wrong order");
    if (review.rating < ratingMin || review.rating > ratingMax)
      throw new Error("Returned review is outside the rating range");
    if (review.created_at < createdAfter || review.created_at > createdBefore)
      throw new Error("Returned review is outside the date range");
    if (!review.body.includes(bodyKeyword))
      throw new Error("Review does not contain filter keyword");
    if (review.deleted_at !== null && typeof review.deleted_at !== "undefined")
      throw new Error("Returned review is soft-deleted");
  }

  // 4. Validate pagination
  TestValidator.equals("pagination page matches")(result.pagination.current)(
    page,
  );
  TestValidator.equals("pagination limit matches")(result.pagination.limit)(
    limit,
  );

  // 5. Validate descending order by created_at
  for (let i = 1; i < result.data.length; ++i) {
    if (result.data[i - 1].created_at < result.data[i].created_at)
      throw new Error("Reviews are not sorted descending by created_at");
  }

  // 6. Edge case: non-existent product yields zero reviews
  const noResults =
    await api.functional.shopping_mall_ai.customer.reviews.search(connection, {
      body: {
        filter: {
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        },
        page: 1,
        limit: 5,
      },
    });
  typia.assert(noResults);
  TestValidator.equals("no review for fake product")(noResults.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";
import type { IPageIShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test invalid filter scenarios for customer review search endpoint.
 *
 * Business context: This test ensures that the shopping mall AI customer review
 * search endpoint robustly rejects invalid or unauthorized filter criteria,
 * returning correct REST-compliant error responses and never leaking any
 * sensitive review data.
 *
 * Step-by-step process:
 *
 * 1. Submit a search request with a negative page number (violates schema minimum
 *    constraint).
 * 2. Submit a search request with a syntactically invalid UUID for a filterable
 *    field.
 * 3. Submit a search request with an unauthorized (unrecognized) field in the
 *    filter object.
 * 4. For each, assert that an error occurs (validation or business error is
 *    thrown).
 * 5. Implicitly confirm that no review data is leaked via error responses.
 */
export async function test_api_shopping_mall_ai_test_search_customer_reviews_with_invalid_filters(
  connection: api.IConnection,
) {
  // 1. Negative page number (should fail with 400/422)
  await TestValidator.error("negative page number should fail")(() =>
    api.functional.shopping_mall_ai.customer.reviews.search(connection, {
      body: {
        page: -1, // violates Minimum<1>
      },
    }),
  );

  // 2. Invalid UUID value in filter object (for a UUID field)
  await TestValidator.error("invalid uuid in filter should fail")(() =>
    api.functional.shopping_mall_ai.customer.reviews.search(connection, {
      body: {
        filter: {
          shopping_mall_ai_customer_id: "not-a-uuid",
        },
      },
    }),
  );

  // 3. Unauthorized/unrecognized field in filter (should fail)
  await TestValidator.error("unauthorized filter field should fail")(() =>
    api.functional.shopping_mall_ai.customer.reviews.search(connection, {
      body: {
        filter: {
          forbidden_field: "should-not-be-here",
        },
      },
    }),
  );

  // (Implicit in TestValidator error assertion) In all error conditions, confirm no review data is returned
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";
import type { IPageIShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiReview";
