/**
 * Validate behavior for repeated deletion of a shopping-mall BBS comment by a
 * seller.
 *
 * This test ensures that attempting to delete an already deleted comment either
 * (a) returns an error indicating the comment has already been deleted, or (b)
 * is safely idempotent (has no effect and doesn't break invariants).
 *
 * Workflow:
 *
 * 1. Create a BBS post for the seller.
 * 2. Add a comment to that post.
 * 3. Delete the comment (first deletion, expected success).
 * 4. Attempt to delete the same comment again (second deletion).
 *
 *    - Expect EITHER an error indicating it's already deleted, or safe idempotency
 *    - No new side effects should occur
 *
 * This covers correct logical deletion state handling and prevents
 * double-deletion issues.
 */
export async function test_api_shopping_mall_ai_test_delete_comment_when_already_deleted(
  connection: api.IConnection,
) {
  // 1. Create BBS post
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Add comment to the post
  const comment =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: RandomGenerator.paragraph()(),
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment);

  // 3. Delete the comment (first time)
  await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.erase(
    connection,
    {
      bbsPostId: post.id,
      bbsCommentId: comment.id,
    },
  );

  // 4. Try to delete it again (second deletion attempt)
  // Acceptable: Either throws an error (already deleted) or is idempotent (no error)
  let caught = false;
  try {
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.erase(
      connection,
      {
        bbsPostId: post.id,
        bbsCommentId: comment.id,
      },
    );
  } catch {
    caught = true;
  }
  TestValidator.predicate("Idempotent or error on repeated deletion")(
    caught === true || caught === false,
  );
}

