import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";

/**
 * Test listing product inquiries for the current authenticated customer,
 * ensuring only that customer's inquiries (public and private) are returned.
 *
 * 1. Prepare a random product ID (as real product creation is not available)
 * 2. As a customer, create a public inquiry for the product
 * 3. As the same customer, create a private inquiry for the product
 * 4. List inquiries as the customer via the index API
 * 5. Confirm that both public and private inquiries created by this customer are
 *    present in the returned data, and that all records in the result set match
 *    the customer's own ID
 * 6. Confirm privacy flag (is_private) correctness for the created inquiries
 * 7. (Edge case) Confirm that no inquiries from other customers are present (not
 *    possible to create other-customer records via available APIs, but validate
 *    for safety)
 */
export async function test_api_shopping_mall_ai_customer_inquiries_test_customer_lists_own_and_visible_inquiries(
  connection: api.IConnection,
) {
  // Step 1: Generate a random product ID (simulate existing product)
  const productId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Create a public inquiry
  const publicInquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productId,
          question: "Is this product available now?",
          is_private: false,
        } satisfies IShoppingMallAiInquiry.ICreate,
      },
    );
  typia.assert(publicInquiry);

  // Step 3: Create a private inquiry
  const privateInquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productId,
          question: "Is there a discount for regular customers?",
          is_private: true,
        } satisfies IShoppingMallAiInquiry.ICreate,
      },
    );
  typia.assert(privateInquiry);

  // Step 4: List inquiries as the customer
  const result =
    await api.functional.shopping_mall_ai.customer.inquiries.index(connection);
  typia.assert(result);

  // Step 5: Validate the returned inquiries - must only contain this customer's inquiries (public or private)
  for (const inquiry of result.data) {
    TestValidator.equals("own inquiries only")(
      inquiry.shopping_mall_ai_customer_id,
    )(publicInquiry.shopping_mall_ai_customer_id);
    TestValidator.equals("product filter")(inquiry.shopping_mall_ai_product_id)(
      productId,
    );
  }

  // Step 6: Confirm our created public and private inquiries are present and correctly flagged
  const foundPublic = result.data.find((inq) => inq.id === publicInquiry.id);
  TestValidator.predicate("public inquiry found")(!!foundPublic);
  TestValidator.equals("public inquiry not private")(foundPublic?.is_private)(
    false,
  );

  const foundPrivate = result.data.find((inq) => inq.id === privateInquiry.id);
  TestValidator.predicate("private inquiry found")(!!foundPrivate);
  TestValidator.equals("private inquiry private")(foundPrivate?.is_private)(
    true,
  );

  // Step 7: (Edge) Ensure no inquiries for other customers - IDs all match
  for (const inquiry of result.data) {
    TestValidator.equals("all are my inquiries")(
      inquiry.shopping_mall_ai_customer_id,
    )(publicInquiry.shopping_mall_ai_customer_id);
  }
}

