/**
 * Validates that an admin can list all product inquiries (Q&A), regardless of
 * seller, customer, or privacy flag.
 *
 * ## Business Context
 *
 * Admins require the ability to audit, moderate, and analyze all customer
 * inquiries across the shopping mall platform, including those marked private
 * (is_private=true) and those submitted by any customer or associated with any
 * seller/product.
 *
 * ## Test Steps
 *
 * 1. Register two products under different sellers
 * 2. Simulate two customers, each submitting both a public and a private inquiry
 *    for both products
 * 3. As an admin, fetch the paginated inquiry list
 * 4. Confirm that every inquiry created is present in the admin's list, regardless
 *    of privacy flag
 */
export async function test_api_shopping_mall_ai_admin_inquiries_test_admin_sees_all_inquiries(
  connection: api.IConnection,
) {
  // 1. Register two products under different sellers (simulate difference by separate calls)
  const product1 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          price: 100 + Math.round(Math.random() * 900),
          status: "active",
          sku: RandomGenerator.alphaNumeric(10),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product1);

  const product2 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          price: 100 + Math.round(Math.random() * 900),
          status: "active",
          sku: RandomGenerator.alphaNumeric(10),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product2);

  // Prepare unique (but simulated) customer ids (not directly used in inquiry request)
  // Just for logical separation when accounting in-memory, not API-level
  const customerScenarios = [{ label: "customerA" }, { label: "customerB" }];

  // Hold all created inquiry entities for verification
  const createdInquiries: IShoppingMallAiInquiry[] = [];

  // 2. Each customer submits both a public and private inquiry for each product
  for (const customer of customerScenarios) {
    for (const product of [product1, product2]) {
      // public inquiry
      const inquiryPublic =
        await api.functional.shopping_mall_ai.customer.inquiries.create(
          connection,
          {
            body: {
              shopping_mall_ai_product_id: product.id,
              question: RandomGenerator.paragraph()(),
              is_private: false,
            } satisfies IShoppingMallAiInquiry.ICreate,
          },
        );
      typia.assert(inquiryPublic);
      createdInquiries.push(inquiryPublic);

      // private inquiry
      const inquiryPrivate =
        await api.functional.shopping_mall_ai.customer.inquiries.create(
          connection,
          {
            body: {
              shopping_mall_ai_product_id: product.id,
              question: RandomGenerator.paragraph()(),
              is_private: true,
            } satisfies IShoppingMallAiInquiry.ICreate,
          },
        );
      typia.assert(inquiryPrivate);
      createdInquiries.push(inquiryPrivate);
    }
