  const page =
    await api.functional.shopping_mall_ai.admin.inquiries.index(connection);
  typia.assert(page);

  // 4. Check that each inquiry created is included in admin results
  for (const expected of createdInquiries) {
    const found = page.data.find((i) => i.id === expected.id);
    TestValidator.predicate(`Admin can see inquiry ${expected.id}`)(!!found);
    if (found) {
      TestValidator.equals(`Inquiry full match ${expected.id}`)(found)(
        expected,
      );
    }
  }
}

