/**
 * Test the creation of a new compliance/cross-domain audit log entry with valid
 * attributes.
 *
 * This test verifies that the audit log system correctly stores
 * business-critical event records, covering compliance and traceability
 * requirements. It ensures the system accepts a fully valid request and
 * preserves all relevant attributes in the stored log. The test also validates
 * optionality and immutability for key audit-log fields.
 *
 * Steps:
 *
 * 1. Build a complete IShoppingMallAiAuditLog.ICreate payload with realistic
 *    values for all attributes (entity_type, entity_id, actor_id [uuid],
 *    actor_role, operation, detailed payload, occurred_at, context).
 * 2. Call api.functional.shopping_mall_ai.admin.auditLogs.create with this body.
 * 3. Assert typia conformity and check returned values match those input, except
 *    for id (must be uuid) and deleted_at (must be null for new logs).
 * 4. Additionally, create a minimal log (omitting actor_id/context) and verify
 *    null handling in response.
 */
export async function test_api_shopping_mall_ai_admin_auditLogs_create(
  connection: api.IConnection,
) {
  // 1. Build a full audit log creation request
  const fullLogInput: IShoppingMallAiAuditLog.ICreate = {
    entity_type: "order",
    entity_id: typia.random<string>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_role: "admin",
    operation: "update",
    detail: JSON.stringify({
      before: { status: "pending" },
      after: { status: "confirmed" },
    }),
    occurred_at: new Date().toISOString(),
    context: "192.168.0.25",
  };
  // 2. Create the audit log
  const output = await api.functional.shopping_mall_ai.admin.auditLogs.create(
    connection,
    { body: fullLogInput },
  );
  typia.assert(output);
  // Validate returned values
  TestValidator.equals("entity_type")(output.entity_type)(
    fullLogInput.entity_type,
  );
  TestValidator.equals("entity_id")(output.entity_id)(fullLogInput.entity_id);
  TestValidator.equals("actor_id")(output.actor_id)(fullLogInput.actor_id);
  TestValidator.equals("actor_role")(output.actor_role)(
    fullLogInput.actor_role,
  );
  TestValidator.equals("operation")(output.operation)(fullLogInput.operation);
  TestValidator.equals("detail")(output.detail)(fullLogInput.detail);
  TestValidator.equals("context")(output.context)(fullLogInput.context);
  TestValidator.equals("occurred_at")(output.occurred_at)(
    fullLogInput.occurred_at,
  );
  TestValidator.predicate("id is uuid string")(
    typeof output.id === "string" && /[0-9a-fA-F-]{32,36}/.test(output.id),
  );
  TestValidator.equals("deleted_at is null")(output.deleted_at)(null);

  // 4. Minimal log: only required fields, missing actor_id/context (should become null in output)
  const minimalInput: IShoppingMallAiAuditLog.ICreate = {
    entity_type: "product",
    entity_id: typia.random<string>(),
    actor_role: "system",
    operation: "delete",
    detail: "System-initiated product removal.",
    occurred_at: new Date().toISOString(),
  };
  const minimalOutput =
    await api.functional.shopping_mall_ai.admin.auditLogs.create(connection, {
      body: minimalInput,
    });
  typia.assert(minimalOutput);
  TestValidator.equals("actor_id is null")(minimalOutput.actor_id)(null);
  TestValidator.equals("context is null")(minimalOutput.context)(null);
}

