import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiPolicyChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiPolicyChange";
import type { IPageIShoppingMallAiPolicyChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiPolicyChange";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for complex searching of policy change/version records using various
 * advanced filters.
 *
 * This function validates the search endpoint that supports compliance and
 * legal audits, where filters such as policy code, policy version, approving
 * admin, date range, and free-text summary are available. This test helps
 * ensure auditors, legal counsel, or head compliance officers can retrieve
 * accurate lists matching audit criteria and that all search logic, pagination,
 * and filtering are robust even with complicated query combinations.
 *
 * Steps:
 *
 * 1. Prepare a complex multi-filter object (policy code, version string, approving
 *    admin id, date-from/to, summary keyword, deleted records).
 * 2. Call the admin search endpoint with the constructed filter.
 * 3. Assert the API responds with correct paginated structure (pagination fields
 *    and array data).
 * 4. Validate that all summary results actually fulfill the filter criteria (e.g.,
 *    correct code, version, approver, date ranges).
 * 5. Try edge cases: a) No filters (simple fetch), b) Only by date range, c) Only
 *    policy code, d) All fields together, e) Non-matching query should yield
 *    zero results, f) Deleted record filter.
 * 6. Confirm robust type assertions and fail on logic mismatch.
 */
export async function test_api_shopping_mall_ai_admin_policyChanges_search_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Base: Fetch with no filters (should return any available results)
  const baseOutput =
    await api.functional.shopping_mall_ai.admin.policyChanges.search(
      connection,
      {
        body: {},
      },
    );
  typia.assert(baseOutput);
  TestValidator.predicate("base fetch is paginated and array present")(
    Array.isArray(baseOutput.data) && baseOutput.pagination !== undefined,
  );

  // 2. Pick a real value sample from base to use as filter reference
  const sample = baseOutput.data[0];
  if (sample) {
    // 3. Search by policy_code only
    const byCode =
      await api.functional.shopping_mall_ai.admin.policyChanges.search(
        connection,
        {
          body: { policy_code: sample.policy_code },
        },
      );
    typia.assert(byCode);
    for (const rec of byCode.data)
      TestValidator.equals("policy_code matches")(rec.policy_code)(
        sample.policy_code,
      );

    // 4. Search by version string only
    const byVersion =
      await api.functional.shopping_mall_ai.admin.policyChanges.search(
        connection,
        {
          body: { policy_version: sample.policy_version },
        },
      );
    typia.assert(byVersion);
    for (const rec of byVersion.data)
      TestValidator.equals("policy_version matches")(rec.policy_version)(
        sample.policy_version,
      );

    // 5. Search by approver only
    const byApprover =
      await api.functional.shopping_mall_ai.admin.policyChanges.search(
        connection,
        {
          body: { approved_by: sample.approved_by },
        },
      );
    typia.assert(byApprover);
    for (const rec of byApprover.data)
      TestValidator.equals("approved_by matches")(rec.approved_by)(
        sample.approved_by,
      );

    // 6. Search in date range of sample approval
    const byDate =
      await api.functional.shopping_mall_ai.admin.policyChanges.search(
        connection,
        {
          body: {
            approved_at_from: sample.approved_at,
            approved_at_to: sample.approved_at,
          },
        },
      );
    typia.assert(byDate);
    for (const rec of byDate.data)
      TestValidator.equals("approved_at in range")(rec.approved_at)(
        sample.approved_at,
      );

    // 7. Search by summary substring
    if (sample.change_summary.length >= 3) {
      const keyword = sample.change_summary.substring(0, 3);
      const bySummary =
        await api.functional.shopping_mall_ai.admin.policyChanges.search(
          connection,
          {
            body: { change_summary: keyword },
          },
        );
      typia.assert(bySummary);
      for (const rec of bySummary.data)
        TestValidator.predicate("summary includes keyword")(
          rec.change_summary.includes(keyword),
        );
    }
  }

  // 8. Non-matching combination (should return zero records)
  const nothing =
    await api.functional.shopping_mall_ai.admin.policyChanges.search(
      connection,
      {
        body: {
          policy_code: "non-existent-code",
          policy_version: "v9999.9",
          approved_by: "00000000-0000-0000-0000-000000000000",
        },
      },
    );
  typia.assert(nothing);
  TestValidator.equals("empty results")(nothing.data.length)(0);

  // 9. (Optional) Search soft-deleted only (simulate if data present)
  const deletedCandidate = baseOutput.data.find((x) => x.deleted_at != null);
  if (deletedCandidate && deletedCandidate.deleted_at != null) {
    const deleted =
      await api.functional.shopping_mall_ai.admin.policyChanges.search(
        connection,
        {
          body: { deleted_at: deletedCandidate.deleted_at },
        },
      );
    typia.assert(deleted);
    for (const rec of deleted.data)
      if (rec.deleted_at != null && deletedCandidate.deleted_at != null)
        TestValidator.equals("deleted_at matches")(rec.deleted_at)(
          deletedCandidate.deleted_at,
        );
  }
}

