/**
 * 쇼핑몰 정책 변경 이력 고급 검색에서 아무 결과도 반환되지 않는 상황을 검증한다.
 *
 * 본 테스트는 정책 코드(policy_code)와 같이 지나치게 특이한 필터(예: 실제 존재하지 않는 정책 코드)를 사용하여 아무 정책 변경
 * 이력도 조회되지 않는 케이스를 시뮬레이션한다. 이때 반환 결과가 정상적인 빈 페이지네이션 형식이며, 검색/페이징 정보 등도 모두 적절히
 * 반환되는지 확인해야 한다.
 *
 * 테스트 절차:
 *
 * 1. 존재하지 않을 확률이 높은 임의의 policy_code, policy_version, approved_by 값 등으로 검색 필터를
 *    작성한다.
 * 2. Search API를 호출하여 결과를 조회한다.
 * 3. 반환된 data 배열이 빈 배열([])임을 확인한다.
 * 4. Pagination 정보에 현재 페이지(current), 페이지 당 개수(limit), 전체 레코드 수(records), 전체 페이지
 *    수(pages) 등이 0 또는 정상적으로 반환되는지 검증한다.
 */
export async function test_api_shopping_mall_ai_admin_policyChanges_test_search_policy_change_versions_when_no_results_found(
  connection: api.IConnection,
) {
  // 1. 특이한(존재하지 않는) 필터 값 입력 준비
  const noMatchRequest: IShoppingMallAiPolicyChange.IRequest = {
    policy_code: "nonexistent-policy-" + typia.random<string>(),
    policy_version: "v999.9",
    approved_by: typia.random<string & tags.Format<"uuid">>(),
    change_summary: "임의의조건",
    approved_at_from: "2099-01-01T00:00:00.000Z",
    approved_at_to: "2099-12-31T23:59:59.999Z",
    // deleted_at: undefined  // undefined이 아니라 아예 key 생략(옵셔널)
  };

  // 2. 정책 변경 이력 검색 API 호출
  const output =
    await api.functional.shopping_mall_ai.admin.policyChanges.search(
      connection,
      {
        body: noMatchRequest,
      },
    );
  typia.assert(output);

  // 3. 결과 데이터와 페이지네이션 정보 검증
  TestValidator.equals("policy change 검색 결과 0건이어야 함")(
    output.data.length,
  )(0);
  TestValidator.equals("페이지네이션 전체 건수 0")(output.pagination.records)(
    0,
  );
  // 전체 페이지는 0이거나 1(빈 페이지를 1로 처리하는 시스템도 있으므로)
  TestValidator.predicate("전체 페이지 숫자 0 또는 1")(
    output.pagination.pages === 0 || output.pagination.pages === 1,
  );
}

