import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiLoyaltyEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiLoyaltyEvent";
import type { IPageIShoppingMallAiLoyaltyEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiLoyaltyEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced filtering, pagination, and access control for loyalty event
 * search (admin dashboard).
 *
 * This test exercises the PATCH /shopping-mall-ai/admin/loyaltyEvents endpoint
 * to ensure robust filtering and accurate pagination for loyalty events, as
 * well as proper admin-only access. Multiple filter scenarios are verified
 * including:
 *
 * - Filter by specific customer UUID
 * - Filter by event type (e.g., "awarded")
 * - Points range (min, max)
 * - Occurred_at date/time ranges
 * - Combined filter criteria
 * - Pagination: fetch two different pages and validate pagination meta
 * - Malformed/invalid filter values to verify validation errors
 * - Confirm non-admins CANNOT access this endpoint if possible
 *
 * Steps:
 *
 * 1. As an authenticated admin, perform a search with only a customer_id filter,
 *    verify all returned events belong to the requested customer.
 * 2. Search with event_type filter, check all events are of that type.
 * 3. Search using points_min and points_max, validate that all returned point
 *    values are within range.
 * 4. Search by occurred_at range, validate timestamps fall within the specified
 *    window.
 * 5. Combine multiple filters for a more advanced query, verify compound
 *    conditions are respected.
 * 6. Test pagination (page + limit): fetch two consecutive pages, check correct
 *    event count, no overlap, and accurate pagination.meta.
 * 7. Attempt invalid filter (e.g., malformed UUID, string for points), assert
 *    error is thrown.
 * 8. Attempt access as a non-admin (if roles supported), expect access denied.
 */
export async function test_api_shopping_mall_ai_admin_loyaltyEvents_search(
  connection: api.IConnection,
) {
  // Preparation: fetch all available events (test assumes fixture/sample data exists)
  const allEvents =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {},
      },
    );
  typia.assert(allEvents);
  const firstCustomerId =
    allEvents.data[0]?.shopping_mall_ai_customer_id ??
    typia.random<string & tags.Format<"uuid">>();
  if (!firstCustomerId) throw new Error("No events available for filter test");

  // 1. Filter by customer UUID
  const byCustomer =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {
          shopping_mall_ai_customer_id: firstCustomerId,
        },
      },
    );
  typia.assert(byCustomer);
  for (const event of byCustomer.data) {
    TestValidator.equals("customer id matches")(
      event.shopping_mall_ai_customer_id,
    )(firstCustomerId);
  }

  // 2. Filter by event_type
  const firstEventType = allEvents.data[0]?.event_type ?? "awarded";
  const byType =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {
          event_type: firstEventType,
        },
      },
    );
  typia.assert(byType);
  for (const event of byType.data) {
    TestValidator.equals("event type match")(event.event_type)(firstEventType);
  }

  // 3. Points range
  const withPoints = allEvents.data.filter((e) => typeof e.points === "number");
  if (withPoints.length) {
    const minPoints = Math.min(...withPoints.map((e) => e.points ?? 0));
    const maxPoints = Math.max(...withPoints.map((e) => e.points ?? 0));
    const byPointsRange =
      await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
        connection,
        {
          body: {
            points_min: minPoints,
            points_max: maxPoints,
          },
        },
      );
    typia.assert(byPointsRange);
    for (const event of byPointsRange.data) {
      if (typeof event.points === "number")
        TestValidator.predicate("within points range")(
          event.points >= minPoints && event.points <= maxPoints,
        );
    }
  }

  // 4. Occurred_at date/time range
  const byDateSorted = [...allEvents.data].sort(
    (a, b) =>
      new Date(a.occurred_at).getTime() - new Date(b.occurred_at).getTime(),
  );
  const occurredFrom = byDateSorted[0]?.occurred_at;
  const occurredTo = byDateSorted[byDateSorted.length - 1]?.occurred_at;
  if (occurredFrom && occurredTo) {
    const byDateRange =
      await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
        connection,
        {
          body: {
            occurred_from: occurredFrom,
            occurred_to: occurredTo,
          },
        },
      );
    typia.assert(byDateRange);
    for (const event of byDateRange.data) {
      TestValidator.predicate("occurred_at within range")(
        new Date(event.occurred_at).getTime() >=
          new Date(occurredFrom).getTime() &&
          new Date(event.occurred_at).getTime() <=
            new Date(occurredTo).getTime(),
      );
    }
  }

  // 5. Combined filters
  const combinedResult =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {
          shopping_mall_ai_customer_id: firstCustomerId,
          event_type: firstEventType,
        },
      },
    );
  typia.assert(combinedResult);
  for (const event of combinedResult.data) {
    TestValidator.equals("customer id matches")(
      event.shopping_mall_ai_customer_id,
    )(firstCustomerId);
    TestValidator.equals("event type match")(event.event_type)(firstEventType);
  }

  // 6. Pagination
  const paged1 =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {
          page: 1,
          limit: 2,
        },
      },
    );
  typia.assert(paged1);
  const paged2 =
    await api.functional.shopping_mall_ai.admin.loyaltyEvents.search(
      connection,
      {
        body: {
          page: 2,
          limit: 2,
        },
      },
    );
  typia.assert(paged2);
  TestValidator.notEquals("page 1 vs page 2 data")(paged1.data)(paged2.data);
  TestValidator.equals("page 1 meta.current")(paged1.pagination.current)(1);
  TestValidator.equals("page 2 meta.current")(paged2.pagination.current)(2);
  TestValidator.equals("page 1 size")(paged1.data.length)(
    paged1.pagination.limit,
  );

  // 7. Invalid filter value: malformed UUID for customer ID
  await TestValidator.error("invalid uuid should fail")(() =>
    api.functional.shopping_mall_ai.admin.loyaltyEvents.search(connection, {
      body: {
        shopping_mall_ai_customer_id: "not-a-uuid" as any,
      },
    }),
  );

  // 8. Invalid filter type: points_min as string
  await TestValidator.error("invalid points type")(() =>
    api.functional.shopping_mall_ai.admin.loyaltyEvents.search(connection, {
      body: {
        points_min: "not-a-number" as any,
      } as any,
    }),
  );

  // 9. Admin-only endpoint: non-admin should be denied, but not testable unless non-admin session available.
}

