 * This test ensures that an admin user can perform complex filtered queries
 * against file access logs using all available filters (actor_type, file_id,
 * outcome, access_type, ip_address, date range, pagination) and that the
 * returned data matches all filter criteria.
 *
 * It also validates edge cases like overlapping date-time windows and partial
 * filter matches. Proper pagination behavior (respecting current page/limit
 * fields and data size) is checked. Filtered results are fully validated to
 * assure that no records outside criteria are included.
 *
 * Steps:
 *
 * 1. Execute a search with all major filter fields set.
 * 2. Check every returned record matches provided filters.
 * 3. Validate pagination fields and that page data count is in range.
 * 4. Repeat with overlapping date window as edge case.
 * 5. Repeat with partial match/looser filter (actor_type and outcome only).
 */
export async function test_api_shopping_mall_ai_file_access_log_test_search_file_access_logs_with_advanced_filters(
  connection: api.IConnection,
) {
  // Step 1: Advanced query with all filters
  const now = new Date();
  const dateFrom = new Date(now.getTime() - 60 * 60 * 1000).toISOString(); // 1 hour ago
  const dateTo = now.toISOString();
  const requestBody = {
    file_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    access_type: "view",
    outcome: "success",
    ip_address: "192.168.0.1",
    date_from: dateFrom,
    date_to: dateTo,
    page: 1,
    limit: 5,
  } satisfies IShoppingMallAiFileAccessLog.IRequest;
  const result =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.search(
      connection,
      { body: requestBody },
    );
  typia.assert(result);
  for (const log of result.data) {
    if (requestBody.file_id)
      TestValidator.equals("file_id matches")(log.shopping_mall_ai_file_id)(
        requestBody.file_id,
      );
    if (requestBody.actor_type)
      TestValidator.equals("actor_type matches")(log.actor_type)(
        requestBody.actor_type,
      );
    if (requestBody.access_type)
      TestValidator.equals("access_type matches")(log.access_type)(
        requestBody.access_type,
      );
    if (requestBody.outcome)
      TestValidator.equals("outcome matches")(log.outcome)(requestBody.outcome);
    if (requestBody.ip_address)
      TestValidator.equals("ip_address matches")(log.ip_address)(
        requestBody.ip_address,
      );
    if (requestBody.date_from)
      TestValidator.predicate("accessed_at >= date_from")(
        log.accessed_at >= requestBody.date_from,
      );
    if (requestBody.date_to)
      TestValidator.predicate("accessed_at <= date_to")(
        log.accessed_at <= requestBody.date_to,
      );
  }
  TestValidator.equals("page matches")(result.pagination.current)(
    requestBody.page,
  );
  TestValidator.equals("limit matches")(result.pagination.limit)(
    requestBody.limit,
  );
  TestValidator.predicate("results <= limit")(
    result.data.length <= requestBody.limit,
  );

  // Step 2: Edge case with overlapping date window
  const overlapFrom = new Date(now.getTime() - 30 * 60 * 1000).toISOString(); // 30 min ago
  const overlapRequest = {
    date_from: overlapFrom,
    date_to: dateTo,
    page: 1,
    limit: 10,
  } satisfies IShoppingMallAiFileAccessLog.IRequest;
  const overlapResult =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.search(
      connection,
      { body: overlapRequest },
    );
  typia.assert(overlapResult);
  for (const log of overlapResult.data) {
    TestValidator.predicate("accessed_at >= overlap date_from")(
      log.accessed_at >= overlapFrom,
    );
    TestValidator.predicate("accessed_at <= overlap date_to")(
      log.accessed_at <= dateTo,
    );
  }

  // Step 3: Partial filter—actor_type and outcome only
  const partialRequest = {
    actor_type: "system",
    outcome: "error",
    page: 1,
    limit: 3,
  } satisfies IShoppingMallAiFileAccessLog.IRequest;
  const partialResult =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.search(
      connection,
      { body: partialRequest },
    );
  typia.assert(partialResult);
  for (const log of partialResult.data) {
    TestValidator.equals("actor_type matches")(log.actor_type)(
      partialRequest.actor_type,
    );
    TestValidator.equals("outcome matches")(log.outcome)(
      partialRequest.outcome,
    );
  }
}

