import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFileAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAccessLog";

/**
 * Validate admin ability to update mutable fields of a file access log.
 *
 * This test ensures an admin can update the allowed mutable fields of a
 * specific file access log (such as outcome, actor_type, actor_id, channel,
 * access_type, ip_address, or accessed_at). The test first creates a log, then
 * performs a valid update on certain fields. It asserts that the changes are
 * correctly reflected and type-safe in the response. Attempts to update
 * immutable or non-existent fields must be rejected (negative testing is
 * planned but limited to possible real API contract behavior).
 *
 * Test Steps:
 *
 * 1. Create a file access log (using the admin-privileged endpoint)
 * 2. Update mutable fields (e.g., outcome and actor_type)
 * 3. Assert the update response correctly reflects the new values and all
 *    unchanged fields remain the same
 * 4. Attempt to update an undefined (non-existent) field and verify rejection
 *    (should cause error)
 */
export async function test_api_shopping_mall_ai_file_access_logs_test_update_file_access_log_successful_admin(
  connection: api.IConnection,
) {
  // Step 1: Create a file access log
  const original: IShoppingMallAiFileAccessLog =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          actor_type: "admin",
          actor_id: typia.random<string & tags.Format<"uuid">>(),
          access_type: "download",
          channel: "web",
          outcome: "success",
          ip_address: "192.168.1.100",
          accessed_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
  typia.assert(original);

  // Step 2: Update outcome and actor_type fields
  const updateParams = {
    outcome: "denied",
    actor_type: "system",
  } satisfies IShoppingMallAiFileAccessLog.IUpdate;
  const updated: IShoppingMallAiFileAccessLog =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.update(
      connection,
      {
        shoppingMallAiFileAccessLogId: original.id,
        body: updateParams,
      },
    );
  typia.assert(updated);
  // Step 3: Assert updated fields and unchanged fields
  TestValidator.equals("outcome field updated")(updated.outcome)("denied");
  TestValidator.equals("actor_type updated")(updated.actor_type)("system");
  TestValidator.equals("id unchanged")(updated.id)(original.id);
  TestValidator.equals("shopping_mall_ai_file_id unchanged")(
    updated.shopping_mall_ai_file_id,
  )(original.shopping_mall_ai_file_id);
  TestValidator.equals("access_type unchanged")(updated.access_type)(
    original.access_type,
  );
  TestValidator.equals("channel unchanged")(updated.channel)(original.channel);
  TestValidator.equals("ip_address unchanged")(updated.ip_address)(
    original.ip_address,
  );
  TestValidator.equals("accessed_at unchanged")(updated.accessed_at)(
    original.accessed_at,
  );

  // Step 4: Attempt to update a non-existent/immutable field (should fail, negative test)
  await TestValidator.error("rejection for non-existent field")(async () => {
    // Prepare a payload with an extra property (not allowed by API contract)
    const payloadWithExtra = {
      outcome: "success",
      some_undefined_field: "should_fail", // This is NOT a real DTO member
    } as any; // Note: for runtime negative test only
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.update(
      connection,
      {
        shoppingMallAiFileAccessLogId: original.id,
        body: payloadWithExtra,
      },
    );
  });
}

