 * 2. Simulate a non-admin user by removing admin tokens from the connection
 *    header.
 * 3. Attempt to update the log record as non-admin and assert a forbidden error is
 *    thrown.
 * 4. (Optional) Skipped: No means to re-fetch the log to confirm no changes, as
 *    there is no GET endpoint in provided SDK.
 *
 * Notes:
 *
 * - Non-admin (seller/customer) login cannot be simulated, since authentication
 *   APIs for those roles are not provided by the SDK.
 * - Header manipulation is used to simulate absence of admin privileges (by
 *   removing Authorization header).
 * - Only fields from IShoppingMallAiFileAccessLog.IUpdate are attempted for
 *   mutation; payload minimized.
 * - Access control logic must ensure that only admins are authorized to make this
 *   update.
 */
export async function test_api_shopping_mall_ai_file_access_log_test_update_file_access_log_forbidden_for_non_admin(
  connection: api.IConnection,
) {
