import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * E2E Test: Admin soft deletion of a review in Shopping Mall AI
 *
 * Validates the full workflow and business logic for admin soft-deletion (not a
 * hard delete) of a product review:
 *
 * 1. Create a new product (as seller, via seller products API)
 * 2. Create an order for a customer referencing that product (as admin, via admin
 *    orders API)
 * 3. Create a review (as customer, referencing that order and product)
 * 4. As admin, soft-delete the review by its reviewId (via admin erase endpoint)
 *
 * Due to current SDK/API limitations, the following runtime validations are
 * performed:
 *
 * - Each created entity is typia.assert-validated against its DTO
 * - The DELETE/soft-delete completes without error (implying successful
 *   operation)
 * - There is no available SDK call to directly fetch reviews post-delete for
 *   further verification, nor any log/audit endpoint; this is noted as
 *   limitation in coverage.
 *
 * @business-context This flow is central to compliance, moderation, and content management, ensuring admins can auditably and reversibly hide reviews without hard deletion from the database. It verifies that data linkage and referencing works as expected between product, order, and review entities.
 * @limitations No API available to confirm post-delete review state or fetch from the deleted state. Journaling/audit validation is not possible with current SDK.
 */
export async function test_api_shopping_mall_ai_test_delete_review_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a product as seller
  const product =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          price: Math.ceil(Math.random() * 10000) + 100,
          status: "active",
          sku: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(product);

  // 2. Create an order for this product/customer (simulate by linking via admin order API)
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      },
    },
  );
  typia.assert(order);

  // 3. Create a review for the product/order as a customer
  const review = await api.functional.shopping_mall_ai.customer.reviews.create(
    connection,
    {
      body: {
        shopping_mall_ai_product_id: product.id,
        shopping_mall_ai_order_id: order.id,
        rating: 5,
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(review);

  // 4. Soft delete the review by its reviewId as admin
