import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingContentModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingContentModeration";
import type { IPageIShoppingContentModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingContentModeration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced content moderation log search via the PATCH endpoint.
 *
 * This test simulates an admin filtering moderation logs based on action type
 * and date range. It begins by inserting several moderation records with
 * different actions ('delete', 'warn', 'restore') within various acted_at times
 * to create meaningful search conditions. The test then issues a search request
 * (PATCH) targeting a specific action type (e.g., 'delete') and a date range
 * that includes only some of the records. The response should:
 *
 * - Contain only moderation records matching the specified action type and within
 *   the provided acted_at range.
 * - Correctly reflect page size, if pagination is used.
 * - Not include moderation records with unmatched actions or out-of-range dates.
 *
 * Steps:
 *
 * 1. Create several moderation log entries with different `action` values and
 *    timestamps (e.g., three each for 'delete', 'warn', 'restore').
 * 2. Search for logs with action='delete' and acted_at range that includes only
 *    the 'delete' events.
 * 3. Assert that all returned events have action='delete' and their acted_at
 *    timestamps fall within the queried range.
 * 4. Assert the correct number of results is returned (matches inserted count for
 *    'delete').
 * 5. Optionally, test pagination by setting limit less than the count and
 *    confirming pagination fields.
 */
export async function test_api_shopping_mall_ai_admin_contentModerations_test_advanced_search_content_moderations_by_action_type(
  connection: api.IConnection,
) {
  // 1. Insert moderation events (delete, warn, restore) with varying timestamps
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const baseDate = new Date();
  const actions = ["delete", "warn", "restore"];
  const records = [] as IShoppingContentModeration[];
  for (const [i, action] of actions.entries()) {
    for (let j = 0; j < 3; ++j) {
      // Each group has distinct acted_at times for searchability
      const actedAt = new Date(
        baseDate.getTime() - (i * 3 + j) * 60 * 60 * 1000,
      ).toISOString();
      const record =
        await api.functional.shopping_mall_ai.admin.contentModerations.create(
          connection,
          {
            body: {
              shopping_mall_ai_admin_id: adminId,
              content_type: "review",
              content_id: typia.random<string & tags.Format<"uuid">>(),
              action,
              message: action + " reason " + j,
              acted_at: actedAt,
            } satisfies IShoppingContentModeration.ICreate,
          },
        );
      typia.assert(record);
      records.push(record);
    }
  }

  // 2. Build a search range that includes only the 'delete' actions
  const deleteRecords = records.filter((r) => r.action === "delete");
  const actedAtFrom = deleteRecords.reduce(
    (min, r) => Math.min(min, Date.parse(r.acted_at)),
    Number.POSITIVE_INFINITY,
  );
  const actedAtTo = deleteRecords.reduce(
    (max, r) => Math.max(max, Date.parse(r.acted_at)),
    Number.NEGATIVE_INFINITY,
  );
  const actedAtFromStr = new Date(actedAtFrom).toISOString();
  const actedAtToStr = new Date(actedAtTo).toISOString();

  // 3. Search for 'delete' actions in the proper date range
  const limit = 2;
  const searchResult =
    await api.functional.shopping_mall_ai.admin.contentModerations.search(
      connection,
      {
        body: {
          action: "delete",
          acted_at_from: actedAtFromStr,
          acted_at_to: actedAtToStr,
          limit,
          page: 1,
        } satisfies IShoppingContentModeration.IRequest,
      },
    );
  typia.assert(searchResult);

  // 4. Assert all returned records are correct
  for (const entry of searchResult.data) {
    TestValidator.equals("action must be 'delete'")(entry.action)("delete");
    const actedAtMs = Date.parse(entry.acted_at);
    TestValidator.predicate("acted_at within range")(
      actedAtMs >= actedAtFrom && actedAtMs <= actedAtTo,
    );
  }
  // 5. Assert limit/pagination correctness
  TestValidator.equals("result page limit")(searchResult.pagination.limit)(
    limit,
  );
  TestValidator.equals("result page number")(searchResult.pagination.current)(
    1,
  );
  TestValidator.predicate("number of results <= limit")(
    searchResult.data.length <= limit,
  );
  // 6. Optionally: compare total records matched
  TestValidator.equals(
    "total records matched should equal number of delete records",
  )(searchResult.pagination.records)(deleteRecords.length);
}

