import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate nested reply creation on a shopping mall BBS post up to the maximum
 * depth and error on exceeding.
 *
 * This test ensures admin users can create nested (reply) comments on a forum
 * post, up to the schema-allowed maximum depth (three levels).
 *
 * Steps:
 *
 * 1. Create a new BBS post (admin role).
 * 2. Create a top-level comment on the post.
 * 3. Add a level-2 reply to the top-level comment (parent_id set to level-1
 *    comment).
 * 4. Add a level-3 reply to the level-2 comment (parent_id set to level-2
 *    comment).
 * 5. Attempt to add a level-4 reply (parent_id set to level-3 comment); expect
 *    error since depth limit is 3 as per documentation
 *    (IShoppingMallAiBbsComment.ICreate.parent_id allows up to 3-level, not
 *    4).
 * 6. For each successful insertion, assert correct parent-child linkage.
 * 7. For the expected error, use TestValidator.error to verify the endpoint
 *    enforces the nesting constraint (do not check error message, only that
 *    error occurs).
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_bbsComments_test_create_nested_reply_comment_to_existing_comment(
  connection: api.IConnection,
) {
  // 1. Create BBS post
  const post = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Top level post for nested comment test",
        body: "This is a test post to verify nested BBS comments.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create top-level comment (level 1)
  const commentLevel1 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "First top-level comment.",
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(commentLevel1);
  TestValidator.equals("top level comment is not a reply")(
    commentLevel1.parent_id,
  )(null);
  TestValidator.equals("comment attached to correct post")(
    commentLevel1.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 3. Create second-level reply (level 2)
  const commentLevel2 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          parent_id: commentLevel1.id,
          body: "First reply (level 2).",
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(commentLevel2);
  TestValidator.equals("level 2 reply links to level 1")(
    commentLevel2.parent_id,
  )(commentLevel1.id);
  TestValidator.equals("level 2 reply attached to post")(
    commentLevel2.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 4. Create third-level reply (level 3)
  const commentLevel3 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          parent_id: commentLevel2.id,
          body: "Second reply (level 3).",
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(commentLevel3);
  TestValidator.equals("level 3 reply links to level 2")(
    commentLevel3.parent_id,
  )(commentLevel2.id);
  TestValidator.equals("level 3 reply attached to post")(
    commentLevel3.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 5. Attempt to create level-4 reply (should fail)
  await TestValidator.error("exceeding max nesting depth triggers error")(
    async () => {
      await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
        connection,
        {
          bbsPostId: post.id,
          body: {
            shopping_mall_ai_bbs_post_id: post.id,
            parent_id: commentLevel3.id,
            body: "Illegal reply beyond allowed nesting.",
          } satisfies IShoppingMallAiBbsComment.ICreate,
        },
      );
    },
  );
}

