/**
 * Validate that a seller can update their own comment on a BBS post.
 *
 * This test follows the full workflow:
 *
 * 1. Create a BBS post as a seller (using required dependencies).
 * 2. Add a comment to the BBS post as the same seller.
 * 3. Update the comment content via the seller's update endpoint.
 * 4. Retrieve the updated comment and verify content change.
 * 5. Assert the updated_at timestamp has advanced relative to creation, confirming
 *    real update.
 *
 * Business logic:
 *
 * - Only the comment author (seller) should be allowed to update.
 * - The update must mutate the body and update audit fields, while keeping all
 *   other fields (id, bbsPost reference, author, etc.) intact.
 * - The change should be visible immediately in subsequent GET/read operations
 *   (if the flow supported GET, but here we reuse returned objects).
 * - The IP and author must remain unchanged.
 *
 * Edge cases not covered (due to API limitations):
 *
 * - Permission errors when updating another seller's comment (no foreign-user
 *   flows tested here).
 * - Soft-deleted comment update attempts (no deletion endpoint available).
 * - Content policy rejection (moderation not enforced in workflow).
 */
export async function test_api_shopping_mall_ai_seller_bbsPosts_bbsComments_update(
  connection: api.IConnection,
) {
  // 1. Create post as seller
  const postInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(15),
    body: RandomGenerator.content()()(25),
  };
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 2. Add comment as seller
  const commentInput: IShoppingMallAiBbsComment.ICreate = {
    shopping_mall_ai_bbs_post_id: post.id,
    body: RandomGenerator.content()()(6),
    parent_id: null,
  };
  const comment =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      { bbsPostId: post.id, body: commentInput },
    );
  typia.assert(comment);

  // 3. Update the comment content via PUT
  const updatedBody = RandomGenerator.content()()(7) + " - edited";
  await new Promise((resolve) => setTimeout(resolve, 1000)); // ensure timestamp difference
  const updateInput: IShoppingMallAiBbsComment.IUpdate = {
    body: updatedBody,
  };
  const updated =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.update(
      connection,
      { bbsPostId: post.id, bbsCommentId: comment.id, body: updateInput },
    );
  typia.assert(updated);

  // 4. Validate body change and author/IP/audit integrity
  TestValidator.equals("comment body updated")(updated.body)(updatedBody);
  TestValidator.equals("author remains same")(
    updated.shopping_mall_ai_customer_id,
  )(comment.shopping_mall_ai_customer_id);
  TestValidator.equals("IP remains same")(updated.ip)(comment.ip);
  TestValidator.equals("post id remains same")(
    updated.shopping_mall_ai_bbs_post_id,
  )(comment.shopping_mall_ai_bbs_post_id);

  // 5. updated_at must be chronologically after original created_at
  TestValidator.predicate("updated_at is after created_at")(
    new Date(updated.updated_at) > new Date(comment.updated_at),
  );
}

