        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Seller's top-level comment",
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(sellerComment);

  // 2.b. Simulate a customer writing another top-level comment (as role switching is unavailable, use same session)
  const customerComment =
