import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IPageIShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validates that the BBS comment list endpoint properly excludes soft-deleted
 * comments from its returned data.
 *
 * This test simulates realistic forum usage by:
 *
 * 1. Creating a new BBS post as the thread context.
 * 2. Adding multiple comments, including roots and replies.
 * 3. Soft-deleting a mix of root and nested comments.
 * 4. Retrieving the comment list and verifying:
 *
 *    - Only non-deleted comments (deleted_at is null or undefined) are present in
 *         the results.
 *    - No soft-deleted comments appear at any position (root or as threads).
 *
 * This ensures soft-deletion (deleted_at) is correctly respected by the comment
 * listing endpoint for both root-level and nested comments.
 */
export async function test_api_shopping_mall_ai_test_list_bbs_comments_excludes_soft_deleted_comments(
  connection: api.IConnection,
) {
  // 1. Create a new BBS post (thread)
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        title: RandomGenerator.paragraph()(6),
        body: RandomGenerator.paragraph()(24),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Add several comments: 3 roots, each with 1 reply
  const comments: IShoppingMallAiBbsComment[] = [];
  for (let i = 0; i < 3; ++i) {
    // Root-level comment
    const root =
      await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
        connection,
        {
          bbsPostId: post.id,
          body: {
            shopping_mall_ai_bbs_post_id: post.id,
            body: `Root Comment #${i}`,
          } satisfies IShoppingMallAiBbsComment.ICreate,
        },
      );
    typia.assert(root);
    comments.push(root);

    // Reply (child) to root
    const reply =
      await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
        connection,
        {
          bbsPostId: post.id,
          body: {
            shopping_mall_ai_bbs_post_id: post.id,
            body: `Reply to Root #${i}`,
            parent_id: root.id,
          } satisfies IShoppingMallAiBbsComment.ICreate,
        },
      );
    typia.assert(reply);
    comments.push(reply);
  }

  // 3. Soft delete the second root, its reply, and reply to third root
  //    This covers both root and nested soft deletions
  const deletedIndices = [2, 3, 5]; // 2nd root, its reply, reply to 3rd root
  for (const idx of deletedIndices) {
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.erase(
      connection,
      {
        bbsPostId: post.id,
        bbsCommentId: comments[idx].id,
      },
    );
  }

  // 4. Retrieve the list of comments and verify
  const page =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.index(
      connection,
      {
        bbsPostId: post.id,
      },
    );
  typia.assert(page);

  // 5. Assert only non-deleted comments are present in output
  const deletedIds = deletedIndices.map((idx) => comments[idx].id);
  for (const comment of page.data) {
    TestValidator.predicate("comment is not soft-deleted")(
      !deletedIds.includes(comment.id),
    );
    TestValidator.equals("deleted_at should be null or undefined")(
      comment.deleted_at === null || typeof comment.deleted_at === "undefined",
    )(true);
  }

  // 6. Ensure all deleted comments are completely absent
  for (const id of deletedIds) {
    TestValidator.predicate("deleted comment is excluded")(
      page.data.every((c) => c.id !== id),
    );
  }
}

