/**
 * Verify that an admin can retrieve all non-deleted comments, including
 * thread/nesting, for a specific BBS post, regardless of author role or comment
 * sensitivity.
 *
 * This test ensures:
 *
 * 1. Admins can view the full discussion thread of any post for audit, compliance,
 *    or moderation.
 * 2. Threading structure (parent_id) is preserved and accurately reflects replies.
 * 3. All fields needed for audit (body, author, ip, timestamps, etc.) are present
 *    on comments.
 *
 * Steps:
 *
 * 1. Create a neutral BBS post as admin.
 * 2. Seed at least three comments/replies: a root comment, its direct reply, and a
 *    second root comment.
 * 3. Retrieve all threaded comments for the post as admin.
 * 4. Assert that:
 *
 *    - All seeded, non-deleted comments are visible.
 *    - Threading (parent_id) is respected for replies.
 *    - All expected fields (body, ip, timestamps, etc.) are populated and comments
 *         are not soft-deleted.
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_bbsComments_index(
