      body: {
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        title: "Audit scenario test post",
        body: "Main content for testing audit visibility of comments.",
      },
    },
  );
  typia.assert(post);

  // 2. Seed the post with threaded comments
  // 2.1 Top-level comment
  const comment1 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "First comment for visibility test",
          parent_id: null,
        },
      },
    );
  typia.assert(comment1);
  // 2.2 Nested reply to comment1
  const comment2 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Reply to first comment",
          parent_id: comment1.id,
        },
      },
    );
  typia.assert(comment2);
  // 2.3 Second top-level comment
  const comment3 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Second top-level comment",
          parent_id: null,
        },
