  // 4. Assertions
  // All non-deleted comments found
  const commentIds = result.data.map((c) => c.id);
  TestValidator.predicate("All seed comments found")(
    commentIds.includes(comment1.id) &&
      commentIds.includes(comment2.id) &&
      commentIds.includes(comment3.id),
