  // Threading assertions
  const foundComment1 = result.data.find((c) => c.id === comment1.id);
  TestValidator.equals("comment1 is root")(foundComment1?.parent_id)(null);
  const foundComment2 = result.data.find((c) => c.id === comment2.id);
  TestValidator.equals("reply links to parent")(foundComment2?.parent_id)(
    comment1.id,
  );
  const foundComment3 = result.data.find((c) => c.id === comment3.id);
  TestValidator.equals("comment3 is root")(foundComment3?.parent_id)(null);
  // All returned comments are on this post and are soft-active
  for (const comment of result.data) {
    TestValidator.equals("bbs_post_id")(comment.shopping_mall_ai_bbs_post_id)(
      post.id,
    );
    TestValidator.equals("not soft-deleted")(comment.deleted_at)(null);
    TestValidator.predicate("fields populated")(
      !!comment.body &&
        !!comment.created_at &&
        !!comment.updated_at &&
        !!comment.ip,
