/**
 * Validate advanced filtering and pagination of comments on a seller's BBS
 * post.
 *
 * This scenario verifies that the search endpoint for BBS post comments by
 * seller correctly filters comments by author (customer) and by creation date
 * window.
 *
 * 1. Create a BBS post as seller
 * 2. Seed the post with several comments authored by different user IDs and at
 *    different timestamps
 * 3. Use the PATCH /shopping-mall-ai/seller/bbsPosts/{bbsPostId}/bbsComments
 *    endpoint to perform a filtered search of only those comments:
 *
 *    - Written by a particular customer (author)
 *    - Within a specified created_at date window
 *    - Use pagination parameters page/limit as needed
 * 4. Validate the returned comments all have the expected author and timestamps
 *    fall within the search window
 * 5. Confirm that comments from other users and outside of the date range are not
 *    present in results
 */
export async function test_api_shopping_mall_ai_seller_bbsPosts_bbsComments_test_advanced_filter_comments_by_author_and_timeframe_seller(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as seller
  const bbsPost = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(bbsPost);

  // 2. Seed comments from multiple authors at varying times
  // Simulate 3 authors: authorA, authorB, authorC
  const authorA = typia.random<string & tags.Format<"uuid">>();
  const authorB = typia.random<string & tags.Format<"uuid">>();
  const authorC = typia.random<string & tags.Format<"uuid">>();

  // Simulate multiple comments for each author (noting we cannot assign author via API directly, so verification must use actual returned values)
  const now = new Date();
  const commentPayloads = [
    { author: authorA, count: 3 },
    { author: authorB, count: 2 },
    { author: authorC, count: 1 },
  ];

  // Track created comments
  const allComments: IShoppingMallAiBbsComment[] = [];

  for (const { author, count } of commentPayloads) {
    for (let i = 0; i < count; i++) {
      const comment =
        await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
          connection,
          {
            bbsPostId: bbsPost.id,
            body: {
              shopping_mall_ai_bbs_post_id: bbsPost.id,
              body: `Comment body from author ${author}, i=${i}`,
            } satisfies IShoppingMallAiBbsComment.ICreate,
          },
        );
      typia.assert(comment);
      allComments.push(comment);
    }
  }
  // Select a test author from actual created comments (simulate authorB)
  // In real scenario, would extract real .shopping_mall_ai_customer_id
  const referenceComment = allComments[3]; // arbitrarily the 4th (authorB)
  const testAuthor = referenceComment.shopping_mall_ai_customer_id;

  // Date window: include all comments created_at after some threshold (e.g., most recent 10 minutes)
  const minCreated = new Date(
    Math.max(...allComments.map((c) => new Date(c.created_at).getTime())) -
      10 * 60 * 1000,
  ).toISOString();
  const maxCreated = new Date().toISOString();

  // 3. Search with filter: author + created_at window; test with page/limit
  const filter: any = {
    shopping_mall_ai_customer_id: testAuthor,
    created_at: { $gte: minCreated, $lte: maxCreated },
  };

  const request: IShoppingMallAiBbsComment.IRequest = {
    filter,
    page: 1,
    limit: 2,
  };

  const searchResult =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.search(
      connection,
      {
        bbsPostId: bbsPost.id,
        body: request,
      },
    );
  typia.assert(searchResult);

  // 4. Validate all returned comments match author and created_at filter (in window)
  for (const comment of searchResult.data) {
