import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";
import type { IPageIShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Advanced search for nested comments by parent_id and body content (admin)
 *
 * This test validates that, for a BBS post, searching for comments by their
 * parent comment ID (i.e., nested replies) and a body keyword as an admin
 * returns only comments meeting both criteria.
 *
 * Steps:
 *
 * 1. Create a BBS post as admin.
 * 2. Add two root comments (A and B) to this post.
 * 3. Reply to A with two child (nested) comments (A1, A2), each containing keyword
 *    'needle' in body.
 * 4. Reply to B with one child (B1) _without_ the keyword.
 * 5. Perform search using parent_id=A and keyword filter ('needle').
 * 6. Assert only A1 & A2 are returned, and their threading/parent structure is
 *    correct.
 * 7. Confirm B1 and unrelated roots are excluded.
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_bbsComments_test_admin_search_comments_by_nested_parent_and_body_content(
  connection: api.IConnection,
) {
  // 1. Create BBS post (admin)
  const post = await api.functional.shopping_mall_ai.admin.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Threaded Comment Search Test",
        body: "Test for advanced nested comment search.",
      },
    },
  );
  typia.assert(post);

  // 2. Add two root comments (A, B)
  const commentA =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Root comment A",
          parent_id: null,
        },
      },
    );
  typia.assert(commentA);
  const commentB =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Root comment B",
          parent_id: null,
        },
      },
    );
  typia.assert(commentB);

  // 3. Reply to A with A1/A2, each with 'needle'
  const commentA1 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "A1 reply containing needle phrase",
          parent_id: commentA.id,
        },
      },
    );
  typia.assert(commentA1);
  const commentA2 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "A2 reply with needle somewhere",
          parent_id: commentA.id,
        },
      },
    );
  typia.assert(commentA2);

  // 4. Reply to B (B1, no 'needle')
  const commentB1 =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Reply to B no match keyword",
          parent_id: commentB.id,
        },
      },
    );
  typia.assert(commentB1);

  // 5. Search with parent_id=A and body contains 'needle'
  const keyword = "needle";
  const searchResp =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.search(
      connection,
      {
        bbsPostId: post.id,
        body: {
          filter: {
            parent_id: commentA.id,
            body: keyword,
          },
        },
      },
    );
  typia.assert(searchResp);

  // 6. Assert only A1/A2 are returned with correct parent/threading
  const foundIds = searchResp.data.map((c) => c.id).sort();
  TestValidator.equals("Correct matched comments")(foundIds)(
    [commentA1.id, commentA2.id].sort(),
  );
  for (const c of searchResp.data) {
    TestValidator.equals("has correct parent")(c.parent_id)(commentA.id);
    TestValidator.predicate("body contains keyword")(
      c.body.toLowerCase().includes("needle"),
    );
  }
  // 7. Confirm B1/root not present
  for (const excluded of [commentA.id, commentB.id, commentB1.id]) {
    TestValidator.predicate("no unmatched comment")(
      foundIds.includes(excluded) === false,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
