/**
 * Validate admin update of a BBS forum post for Shopping Mall AI.
 *
 * This E2E test verifies that as an admin user, content and metadata (title,
 * body) of an existing forum post can be updated, and proper audit trail is
 * maintained. It ensures:
 *
 * - A post can be created as a test subject
 * - Allowed fields (title, body) are modifiable via the admin update endpoint
 * - Update is reflected in the response and not affecting immutable fields
 * - The post retains normal audit and system metadata
 *
 * Steps:
 *
 * 1. Create a new forum post as admin using valid data
 * 2. Update the title and body fields using the corresponding update endpoint
 * 3. Confirm the response reflects the changes and only editable fields are
 *    modified
 * 4. Validate audit fields (created_at, updated_at) are logical and only
 *    updated_at changes
 * 5. Confirm that non-editable fields (IDs, author, created_at) remain unchanged
 */
export async function test_api_shopping_mall_ai_admin_bbsPosts_test_update_bbs_post_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new BBS post as admin using valid random data
  const createInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const created: IShoppingMallAiBbsPost =
    await api.functional.shopping_mall_ai.admin.bbsPosts.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Update editable fields (title, body) as admin
  const updateInput: IShoppingMallAiBbsPost.IUpdate = {
    title: RandomGenerator.paragraph()(1) + " (UPDATED)",
    body: RandomGenerator.content()()(1) + " (modified content)",
  };
  const updated: IShoppingMallAiBbsPost =
    await api.functional.shopping_mall_ai.admin.bbsPosts.update(connection, {
      bbsPostId: created.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 3. Confirm changes on response
  TestValidator.equals("title updated")(updated.title)(updateInput.title);
  TestValidator.equals("body updated")(updated.body)(updateInput.body);

  // 4. Check non-editable fields stay the same
  TestValidator.equals("id unchanged")(updated.id)(created.id);
  TestValidator.equals("author unchanged")(
    updated.shopping_mall_ai_customer_id,
  )(created.shopping_mall_ai_customer_id);
  TestValidator.equals("channel unchanged")(
    updated.shopping_mall_ai_channel_id,
  )(created.shopping_mall_ai_channel_id);
  TestValidator.equals("section unchanged")(
    updated.shopping_mall_ai_section_id,
  )(created.shopping_mall_ai_section_id);
  TestValidator.equals("ip unchanged")(updated.ip)(created.ip);
  TestValidator.equals("created_at unchanged")(updated.created_at)(
    created.created_at,
  );

  // 5. Audit: updated_at should be newer or equal (if clock drift)
  TestValidator.predicate("updated_at updated")(
    new Date(updated.updated_at) >= new Date(created.updated_at),
  );

  // 6. Post should not be deleted
  TestValidator.equals("not deleted")(updated.deleted_at)(
    created.deleted_at ?? null,
  );
}

