import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IPageIShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate fetching the comment list for a BBS post as a customer.
 *
 * This test covers:
 *
 * 1. Creating a new BBS post (as a customer).
 * 2. Creating several comments (top-level) and nested replies (up to 3 levels) on
 *    the created post.
 * 3. Fetching the list of comments via the comments index API.
 *
 * Expectations:
 *
 * - All created (non-deleted) comments and replies are included in the fetched
 *   list.
 * - The data respects the thread structure (parent-child relationship), within
 *   the nesting limit.
 * - Pagination info is present and sane.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_bbsComments_test_list_comments_for_existing_bbs_post(
  connection: api.IConnection,
) {
  // 1. Create a new BBS post
  const channelId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const sectionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: channelId,
        shopping_mall_ai_section_id: sectionId,
        title: `Post for comment thread ` + RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create several top-level comments on the post
  const commentCount = 3;
  const comments: IShoppingMallAiBbsComment[] = [];
  for (let i = 0; i < commentCount; ++i) {
    const comment =
      await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
        connection,
        {
          bbsPostId: post.id,
          body: {
            shopping_mall_ai_bbs_post_id: post.id,
            body: `C${i + 1}: ` + RandomGenerator.paragraph()(1),
          } satisfies IShoppingMallAiBbsComment.ICreate,
        },
      );
    typia.assert(comment);
    comments.push(comment);
  }

  // 3. Create replies (nesting up to 3 levels) on the first comment
  const replies: IShoppingMallAiBbsComment[] = [];
  let parent = comments[0];
  for (let depth = 0; depth < 2; ++depth) {
    // max 3-level nesting
    const reply =
      await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
        connection,
        {
          bbsPostId: post.id,
          body: {
            shopping_mall_ai_bbs_post_id: post.id,
            body:
              `R${depth + 1} (to ${parent.id.slice(0, 8)}): ` +
              RandomGenerator.paragraph()(1),
            parent_id: parent.id,
          } satisfies IShoppingMallAiBbsComment.ICreate,
        },
      );
    typia.assert(reply);
    replies.push(reply);
    parent = reply;
  }

  // 4. Fetch the comment thread for the BBS post
  const result =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.index(
      connection,
      {
        bbsPostId: post.id,
      },
    );
  typia.assert(result);

  // 5. Validate that the returned comments match those created (by id) and are not soft-deleted
  const idsInResult = result.data.map((x) => x.id);
  const idToResultComment = Object.fromEntries(
    result.data.map((v) => [v.id, v]),
  );

  for (const c of [...comments, ...replies]) {
    TestValidator.predicate(`comment ${c.id} is present in result`)(
      idsInResult.includes(c.id),
    );
    TestValidator.equals(`comment ${c.id} is not deleted`)(
      idToResultComment[c.id].deleted_at,
    )(null);
  }

  // 6. Validate parent-child structure from returned thread
  if (replies.length === 2) {
    const reply1 = idToResultComment[replies[0].id];
    const reply2 = idToResultComment[replies[1].id];
    TestValidator.equals("reply1 parent_id")(reply1.parent_id)(comments[0].id);
    TestValidator.equals("reply2 parent_id")(reply2.parent_id)(replies[0].id);
  }

  // 7. Check pagination info exists and structure
  TestValidator.predicate("pagination info present")(
    typeof result.pagination === "object",
  );
  TestValidator.predicate("pagination records nonzero")(
    result.pagination.records > 0,
  );
}

