 * This test verifies that when a customer creates a new BBS post but does not
 * add any comments, fetching the comment list returns an empty, properly
 * paginated result set. This ensures the API does not produce errors or ghost
 * comment objects when none exist.
 *
 * Business justification: Customers expect to see an empty comment list, not
 * errors or invalid data, when viewing their new posts with no replies. It also
 * validates that pagination info is logical for empty datasets.
 *
 * Test Steps:
 *
 * 1. Create a BBS post as a customer (simulate standard flow).
 * 2. Fetch the list of comments attached to the created post.
 * 3. Assert that:
 *
 *    - The returned comment data array is empty (length 0).
 *    - Pagination metadata "records" and "pages" are 0.
 *    - The current page is 1 (typical paging default).
 *    - Optionally, pagination "limit" matches the API's default (commonly 100).
 */
export async function test_api_shopping_mall_ai_test_list_comments_for_bbs_post_with_no_comments_returns_empty(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as a customer
  const postInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(3),
    body: RandomGenerator.content()(1)(),
  };

  const bbsPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.create(connection, {
      body: postInput,
    });
  typia.assert(bbsPost);

