import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IPageIShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced product search functionality for customers, ensuring all
 * filters (title, price range, category, status) work and pagination is
 * respected. Ensure business rules only expose active/available products
 * (exclude inactive sellers/hidden categories).
 *
 * Steps:
 *
 * 1. Search with no filters – should return active/available products only.
 * 2. Search with multiple filters (e.g., title partial match, price limits,
 *    category, status) – results should match all filters.
 * 3. Search with pagination (page/limit) – confirm page structure and data are
 *    correct.
 */
export async function test_api_shopping_mall_ai_test_search_products_with_multiple_filter_criteria(
  connection: api.IConnection,
) {
  // 1. Search with no filters (should return only active/available products)
  const allProducts =
    await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.search(
      connection,
      { body: {} satisfies IShoppingMallAiProduct.IRequest },
    );
  typia.assert(allProducts);
  for (const item of allProducts.data) {
    // Only active status products should be returned to customers
    TestValidator.equals("product status is active")(item.status)("active");
  }

  // 2. Search with multiple filters (title, price, category, status)
  const dummyCategoryId = typia.random<string & tags.Format<"uuid">>();
  const output =
    await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.search(
      connection,
      {
        body: {
          title: "Test",
          min_price: 100,
          max_price: 50000,
          category_id: dummyCategoryId,
          status: "active",
        } satisfies IShoppingMallAiProduct.IRequest,
      },
    );
  typia.assert(output);
  for (const item of output.data) {
    if (item.title && !item.title.toLowerCase().includes("test".toLowerCase()))
      throw new Error(
        `Product title '${item.title}' does not contain filter string 'Test'`,
      );
    if (item.price < 100 || item.price > 50000)
      throw new Error(`Product price '${item.price}' outside 100-50000`);
    TestValidator.equals("product status matches filter")(item.status)(
      "active",
    );
    TestValidator.equals("product category matches filter")(
      item.shopping_mall_ai_product_category_id,
    )(dummyCategoryId);
  }

  // 3. Pagination test (page & limit)
  const paged =
    await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.search(
      connection,
      {
        body: { page: 1, limit: 3 } satisfies IShoppingMallAiProduct.IRequest,
      },
    );
  typia.assert(paged);
  TestValidator.equals("pagination page")(paged.pagination.current)(1);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(3);
  TestValidator.predicate("data length <= limit")(paged.data.length <= 3);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IPageIShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching for products with invalid or unauthorized filters as a
 * customer.
 *
 * The purpose of this test is to verify that the product search endpoint
 * correctly rejects invalid queries and does not expose admin-only fields or
 * sensitive data when customers attempt to use them.
 *
 * Steps:
 *
 * 1. Attempt to search with an invalid property that isn't defined in the request
 *    schema
 * 2. Attempt to send a malformed (non-object) request body
 * 3. Attempt to filter on the `seller_id` field as a customer (admin-only)
 * 4. Attempt to use wrong property types for price fields
 * 5. Validate that each attempt results in error and that no sensitive data is
 *    leaked
 */
export async function test_api_shopping_mall_ai_customer_shoppingMallAiProducts_test_search_products_invalid_filters_and_unauthorized_fields(
  connection: api.IConnection,
) {
  // 1. Invalid additional property that doesn't exist in IRequest
  await TestValidator.error("should reject queries with extra property")(
    async () => {
      await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.search(
        connection,
        {
          body: {
            ...typia.random<IShoppingMallAiProduct.IRequest>(),
            extraneousField: "foo",
          } as any,
        },
      );
    },
  );

  // 2. Malformed non-object body (e.g., array instead of object)
  await TestValidator.error("should reject queries with malformed body type")(
    async () => {
      await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.search(
        connection,
        {
          // Deliberate invalid body: array
          body: [] as any,
        },
      );
    },
  );

