 * fields)
 *
 * This test verifies the following:
 *
 * - A seller can create a new product with all mandatory fields (title,
 *   description, price, SKU, category, and status).
 * - The product creation response includes all expected product data, including a
 *   generated UUID, audit fields (created_at, updated_at), and proper
 *   propagation of input properties.
 * - The system enforces SKU uniqueness per seller: a duplicate SKU creation for
 *   the same seller should result in an error.
 * - Random valid UUIDs are used for required category/seller references due to
 *   the absence of entity creation/setup APIs. (Actual referential validation
 *   cannot be tested in this scenario, and the test only checks the API's
 *   handling of UUID structure/form.)
 *
 * Steps performed:
 *
 * 1. Generate a unique SKU and random UUIDs for category and seller.
 * 2. Prepare a fully-populated product creation DTO per
 *    IShoppingMallAiProduct.ICreate.
 * 3. Call the API to create the product; verify all input properties are reflected
 *    in the response and audit fields are present.
 * 4. Attempt to create another product with the same SKU for the same seller;
 *    expect a runtime/business rule error.
 */
export async function test_api_shopping_mall_ai_products_test_create_product_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Generate unique SKU and required relation UUIDs
  const sku: string = `SKU-${typia.random<string & tags.Format<"uuid">>()}`;
  const shopping_mall_ai_seller_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const shopping_mall_ai_product_category_id: string & tags.Format<"uuid"> =
    typia.random<string & tags.Format<"uuid">>();

  // 2. Product creation DTO with all required fields
  const createDto: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id,
    title: `Test Product ${RandomGenerator.alphabets(6)}`,
    description: `Auto-generated description ${RandomGenerator.paragraph()()}`,
    price: 199.95,
    status: "active",
    sku,
  };

  // 3. Call API to create product and validate response
  const product =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: createDto },
    );
  typia.assert(product);
  TestValidator.equals("title matches")(product.title)(createDto.title);
  TestValidator.equals("description matches")(product.description)(
    createDto.description,
  );
  TestValidator.equals("sku matches")(product.sku)(createDto.sku);
  TestValidator.equals("category matches")(
    product.shopping_mall_ai_product_category_id,
  )(createDto.shopping_mall_ai_product_category_id);
  TestValidator.equals("status matches")(product.status)(createDto.status);
  TestValidator.equals("price matches")(product.price)(createDto.price);

  TestValidator.predicate("id is uuid")(
    typeof product.id === "string" && product.id.length > 0,
  );
  TestValidator.predicate("created_at is date-time")(
    typeof product.created_at === "string" && product.created_at.length > 0,
  );
  TestValidator.predicate("updated_at is date-time")(
    typeof product.updated_at === "string" && product.updated_at.length > 0,
  );

  // 4. Attempt to create product with duplicate SKU for same seller; should fail
  const createDuplicateSkuDto: IShoppingMallAiProduct.ICreate = {
    ...createDto,
    title: `Duplicate SKU Test ${RandomGenerator.alphabets(6)}`,
  };
  await TestValidator.error("duplicate SKU should fail")(() =>
    api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: createDuplicateSkuDto },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
