import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";

/**
 * Validate the SKU uniqueness constraint per seller when creating products.
 *
 * This test ensures that attempting to register two products with identical
 * SKUs under the same seller will result in the second attempt failing due to
 * the SKU uniqueness enforcement. This is critical for inventory integrity,
 * fulfillment logic, and catalog management in the shopping mall system.
 *
 * **Test steps:**
 *
 * 1. Generate a new product payload with a random but fixed SKU string and all
 *    required fields.
 * 2. Create the first product by calling the product creation API with those
 *    payload details — expect success.
 * 3. Attempt to create a second product as the same seller, with the same SKU, but
 *    the other fields randomized (category, title, etc.) — expect an error due
 *    to duplicate SKU.
 * 4. Confirm the error is thrown and output is not a successful product object.
 *
 * **Edge Case/Negative Validation:**
 *
 * - SKU uniqueness must only be enforced per seller; if there were multiple
 *   sellers, the same SKU could exist across them, but not for the same seller.
 *   However, as the API does not let us choose the seller (authentication is
 *   handled elsewhere), the test is scoped to a single seller session.
 */
export async function test_api_shopping_mall_ai_product_test_create_product_with_duplicate_sku(
  connection: api.IConnection,
) {
  // 1. Produce a unique SKU for test and random payload details
  const fixedSku = RandomGenerator.alphaNumeric(12);
  const payload1: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    price: 49.99,
    status: "active",
    sku: fixedSku,
  };
  // 2. Successfully create first product
  const product1 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: payload1 },
    );
  typia.assert(product1);
  TestValidator.equals("SKU of first product matches")(product1.sku)(fixedSku);

  // 3. Attempt to create duplicate SKU product for the same seller
  const payload2: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    price: 88.5,
    status: "active",
    sku: fixedSku, // Deliberately duplicate
  };
  // 4. Expect SKU uniqueness violation (error thrown)
  await TestValidator.error("SKU uniqueness must be enforced")(() =>
    api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: payload2 },
    ),
  );
}

