  TestValidator.equals("seller ref matches")(output.shopping_mall_ai_seller_id)(
    sellerId,
  );
  TestValidator.predicate("uuid id")(
    typeof output.id === "string" && output.id.length > 0,
  );
  TestValidator.predicate("created_at format")(
    !!output.created_at &&
      new Date(output.created_at).toISOString() === output.created_at,
  );
  TestValidator.predicate("updated_at format")(
    !!output.updated_at &&
      new Date(output.updated_at).toISOString() === output.updated_at,
  );
}

