import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";

/**
 * Validate updating a shopping mall AI product as its owning seller.
 *
 * This test ensures that when a seller updates a product:
 *
 * - Only permitted fields are changed (title, description, price, status)
 * - Immutable properties (id, created_at) remain unchanged
 * - SKU uniqueness is enforced within the seller's product catalog on update
 *
 * Workflow steps:
 *
 * 1. Create an initial product with a unique SKU and all valid required data
 * 2. Update that product, modifying title, description, price, and status
 * 3. Assert the update is fully reflected in the response and immutable fields are
 *    preserved
 * 4. Create another product under the same seller with a different SKU
 * 5. Attempt to update the second product to use the initial SKU -- expect a
 *    business logic error (SKU must remain unique per seller)
 */
export async function test_api_shopping_mall_ai_test_update_product_with_valid_fields_as_owner(
  connection: api.IConnection,
) {
  // 1. Create initial product with unique SKU
  const initialSku = RandomGenerator.alphaNumeric(12);
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: categoryId,
    title: "Sample Title",
    description: "Sample initial description.",
    price: 19999.99,
    status: "active",
    sku: initialSku,
  };
  const product =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: createInput },
    );
  typia.assert(product);

  // 2. Update fields: title, description, price, and status
  const updatedTitle = "Updated Title";
  const updatedDescription = "Updated product description.";
  const updatedPrice = 22999.95;
  const updatedStatus = "inactive";
  const updateInput: IShoppingMallAiProduct.IUpdate = {
    title: updatedTitle,
    description: updatedDescription,
    price: updatedPrice,
    status: updatedStatus,
  };
  const updatedProduct =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: product.id,
        body: updateInput,
      },
    );
  typia.assert(updatedProduct);

  // Validate mutable fields have changed and immutable are preserved
  TestValidator.equals("id unchanged")(updatedProduct.id)(product.id);
  TestValidator.equals("sku unchanged")(updatedProduct.sku)(product.sku);
  TestValidator.equals("category unchanged")(
    updatedProduct.shopping_mall_ai_product_category_id,
  )(product.shopping_mall_ai_product_category_id);
  TestValidator.equals("title updated")(updatedProduct.title)(updatedTitle);
  TestValidator.equals("description updated")(updatedProduct.description)(
    updatedDescription,
  );
  TestValidator.equals("price updated")(updatedProduct.price)(updatedPrice);
  TestValidator.equals("status updated")(updatedProduct.status)(updatedStatus);
  TestValidator.equals("createdAt unchanged")(updatedProduct.created_at)(
    product.created_at,
  );
  TestValidator.notEquals("updated_at changed")(updatedProduct.updated_at)(
    product.updated_at,
  );

  // 4. Create another product with a new SKU
  const anotherSku = RandomGenerator.alphaNumeric(12);
  const secondProductInput: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: categoryId,
    title: "Second Product",
    description: "Another product for SKU uniqueness test.",
    price: 11999.75,
    status: "active",
    sku: anotherSku,
  };
  const anotherProduct =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: secondProductInput },
    );
  typia.assert(anotherProduct);

  // 5. Attempt forbidden update: set SKU to the first product's SKU (should fail)
  await TestValidator.error("SKU must be unique to the seller")(async () => {
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: anotherProduct.id,
        body: {
          sku: initialSku,
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
