import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";

/**
 * 상품 수정 API의 권한 및 유효성 검증 테스트
 *
 * - 타 판매자가 상품을 수정 시도할 경우 권한 거부(FORBIDDEN)가 동작하는지 검증
 * - 음수 가격, 허용치 않은 status, 변경불가 필드(id 등)등 비정상 데이터 update 시 개별적으로 에러 발생 및 레코드 미변경을
 *   확인
 * - Type level/compile 단계에서 허용하지 않는 값(예: body에 id 삽입)은 E2E 테스트에서 제외
 * - 각 에러 케이스 후 정보 불변 검증(조회 API 미제공시 skip)
 *
 * [절차]
 *
 * 1. 판매자1로 정상 상품 등록
 * 2. 판매자2로 교체(가능하면)/연결하여 타인 상품 수정 시도 후 권한 에러 확인
 * 3. 판매자1로 허용 범위 벗어난 데이터 (음수 가격, 이상 상태 등) update 시도 후 각 에러 확인
 */
export async function test_api_shopping_mall_ai_test_update_product_attempt_unauthorized_or_invalid_data(
  connection: api.IConnection,
) {
  // 1. 판매자1이 정상적으로 상품 등록
  const product: IShoppingMallAiProduct =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "E2E권한유효성검증상품",
          description: "권한/유효성 동시 검증용",
          price: 20000,
          status: "active",
          sku: `SKU-${typia.random<string>()}`,
        },
      },
    );
  typia.assert(product);

  // 2. (가정: connection 교체/Authorization 조작 등으로 판매자2 권한 시나리오 모킹)
  // 판매자2가 타인 상품에 update 시도 → 권한 거부 에러 발생
  await TestValidator.error("타 판매자 update Forbidden")(async () => {
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.update(
      connection, // 실제 테스트 환경서 판매자2 전환 불가시 동일 connection 사용
      {
        shoppingMallAiProductId: product.id,
        body: {
          title: "타 판매자소유권 침범",
          price: 12345,
        },
      },
    );
  });

  // 3-1. 음수 가격 업데이트 시도 → 입력값 오류
  await TestValidator.error("음수 가격 update 오류")(async () => {
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: product.id,
        body: {
          price: -10000,
        },
      },
    );
  });

  // 3-2. 허용치 않은 status(예: 'deleted') 입력 시도 → status 오류
  await TestValidator.error("허용된 status 외 값 update 오류")(async () => {
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: product.id,
        body: {
          status: "deleted",
        },
      },
    );
  });

  // 3-3. 업데이트 DTO에 없는 필드(id 등)로의 변경 시도는 타입상 허용되지 않아 E2E에서는 시도 불가(자동 누락)
  // (상품 정보 재조회 API 없으므로 update 실패 후 레코드 불변 검증은 생략)
}

