  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      {
        body: {
          original_name: RandomGenerator.alphaNumeric(12),
          uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(24)}`,
          extension: "txt",
          mime_type: "text/plain",
          size: 128,
          hash: RandomGenerator.alphaNumeric(32),
          actor_type: "admin",
          actor_id: null,
        } satisfies IShoppingMallAiFile.ICreate,
      },
    );
  typia.assert(file);

  // 2. Create a file access log referencing the file
  const accessLog =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          actor_type: "admin",
          actor_id: null,
          access_type: "view",
          channel: "web",
          outcome: "success",
          ip_address: "127.0.0.1",
          accessed_at: new Date().toISOString(),
        } satisfies IShoppingMallAiFileAccessLog.ICreate,
      },
    );
  typia.assert(accessLog);

  // 3. Delete the file access log with valid admin authorization
  await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.erase(
    connection,
    { shoppingMallAiFileAccessLogId: accessLog.id },
  );

  // 4. Try to fetch/read the deleted access log (should error)
  await TestValidator.error("deleted access log should not be found")(
    async () => {
      // No GET/read endpoint for direct fetch, so simulate by attempting to delete again and expecting failure
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.erase(
        connection,
        { shoppingMallAiFileAccessLogId: accessLog.id },
      );
    },
  );
