 *
 * Steps:
 *
 * 1. Create a new file metadata record.
 * 2. Soft-delete the file record by fileId.
 * 3. GET the file by fileId.
 * 4. Validate the response includes the expected file metadata, and 'deleted_at'
 *    is a non-null ISO 8601 date-time string.
 * 5. (Business rule) Optionally validate that business logic would block
 *    functional access to its 'uri' based on deleted status.
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiFiles_test_get_file_metadata_for_soft_deleted_file(
  connection: api.IConnection,
) {
  // 1. Create a file metadata record
  const fileInput: IShoppingMallAiFile.ICreate = {
    original_name: RandomGenerator.paragraph()(5),
    uri: `https://blob.cdn.example.com/${typia.random<string & tags.Format<"uuid">>()}.${RandomGenerator.alphabets(3)}`,
    extension: RandomGenerator.alphabets(3),
    mime_type: "application/pdf",
    size: 83700,
