import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IPageIShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced order search with complex filters for admin orders.
 *
 * This test ensures that an admin can query orders with various combinations of
 * filters:
 *
 * - Status, customer id, channel id, creation and update date range, with
 *   pagination.
 * - Asserts only matching orders are returned.
 * - Checks proper handling when no orders match the search (empty results).
 * - Confirms that the pagination meta data (page, limit, records, pages) is
 *   accurate.
 *
 * Testing workflow:
 *
 * 1. Use a broad query (no filters) and verify orders are returned and pagination
 *    is present.
 * 2. Query with a specific status and assert only orders with that status are
 *    returned.
 * 3. Query with customer id, then channel id, and assert filtered results.
 * 4. Query with creation date range to select a subset, then with a range that
 *    returns no results.
 * 5. Query with multiple filters (status, customer, channel, date) and check
 *    intersection behavior.
 * 6. Test with a limit parameter to check pagination works; query next page if
 *    available and validate navigation.
 * 7. Always type-check and assert the schema on responses, including handling for
 *    empty lists.
 */
export async function test_api_shopping_mall_ai_admin_orders_test_advanced_order_search_with_complex_filters(
  connection: api.IConnection,
) {
  // 1. Broad query (no filters)
  const allOrders = await api.functional.shopping_mall_ai.admin.orders.search(
    connection,
    { body: {} },
  );
  typia.assert(allOrders);
  TestValidator.predicate("at least 'pagination' present")(
    !!allOrders.pagination,
  );

  // 2. Pick a status value if possible
  const knownStatus = allOrders.data[0]?.status ?? "pending";
  const byStatus = await api.functional.shopping_mall_ai.admin.orders.search(
    connection,
    { body: { status: knownStatus } },
  );
  typia.assert(byStatus);
  for (const order of byStatus.data) {
    TestValidator.equals("status should match filter")(order.status)(
      knownStatus,
    );
  }

  // 3. Pick a customer id
  const knownCustomerId = allOrders.data[0]?.shopping_mall_ai_customer_id;
  if (knownCustomerId) {
    const byCustomer =
      await api.functional.shopping_mall_ai.admin.orders.search(connection, {
        body: { shopping_mall_ai_customer_id: knownCustomerId },
      });
    typia.assert(byCustomer);
    for (const order of byCustomer.data) {
      TestValidator.equals("customer id matches")(
        order.shopping_mall_ai_customer_id,
      )(knownCustomerId);
    }
  }

  // 4. Pick a channel id
  const knownChannelId = allOrders.data[0]?.shopping_mall_ai_channel_id;
  if (knownChannelId) {
    const byChannel = await api.functional.shopping_mall_ai.admin.orders.search(
      connection,
      { body: { shopping_mall_ai_channel_id: knownChannelId } },
    );
    typia.assert(byChannel);
    for (const order of byChannel.data) {
      TestValidator.equals("channel id matches")(
        order.shopping_mall_ai_channel_id,
      )(knownChannelId);
    }
  }

  // 5. Created date range: Use earliest and latest from loaded orders
  if (allOrders.data.length > 0) {
    const createdDates = allOrders.data.map((o) => o.created_at).sort();
    const from = createdDates[0];
    const to = createdDates[createdDates.length - 1];
    const byDateRange =
      await api.functional.shopping_mall_ai.admin.orders.search(connection, {
        body: { created_from: from, created_to: to },
      });
    typia.assert(byDateRange);
    for (const order of byDateRange.data) {
      TestValidator.predicate("order within created date range")(
        order.created_at >= from && order.created_at <= to,
      );
    }
    // Query with impossible future date range
    const futureFrom = new Date(
      Date.now() + 1000 * 60 * 60 * 24 * 30,
    ).toISOString();
    const futureTo = new Date(
      Date.now() + 1000 * 60 * 60 * 24 * 31,
    ).toISOString();
    const byFutureDate =
      await api.functional.shopping_mall_ai.admin.orders.search(connection, {
        body: { created_from: futureFrom, created_to: futureTo },
      });
    typia.assert(byFutureDate);
    TestValidator.equals("no matches for future date range")(
      byFutureDate.data.length,
    )(0);
  }

  // 6. Query with intersection of filters
  if (knownStatus && knownCustomerId && knownChannelId) {
    const intersect = await api.functional.shopping_mall_ai.admin.orders.search(
      connection,
      {
        body: {
          status: knownStatus,
          shopping_mall_ai_customer_id: knownCustomerId,
          shopping_mall_ai_channel_id: knownChannelId,
        },
      },
    );
    typia.assert(intersect);
    for (const order of intersect.data) {
      TestValidator.equals("status matches")(order.status)(knownStatus);
      TestValidator.equals("customer matches")(
        order.shopping_mall_ai_customer_id,
      )(knownCustomerId);
      TestValidator.equals("channel matches")(
        order.shopping_mall_ai_channel_id,
      )(knownChannelId);
    }
  }

  // 7. Pagination test: limit param with more than one page if available
  if (allOrders.pagination.records > 1) {
    const pageSize = 1;
    const page1 = await api.functional.shopping_mall_ai.admin.orders.search(
      connection,
      { body: { limit: pageSize, page: 1 } },
    );
    typia.assert(page1);
    TestValidator.equals("pagination limit")(page1.pagination.limit)(pageSize);
    if (page1.pagination.pages > 1) {
      const page2 = await api.functional.shopping_mall_ai.admin.orders.search(
        connection,
        { body: { limit: pageSize, page: 2 } },
      );
      typia.assert(page2);
      TestValidator.equals("second page current idx")(page2.pagination.current)(
        2,
      );
    }
  }
}

