import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";

/**
 * Validate the update of an order's status and/or channel id via admin PUT
 * endpoint.
 *
 * Business context: This test ensures that an admin can successfully update an
 * existing order's `status` and/or `shopping_mall_ai_channel_id` fields. It
 * also checks audit traceability by verifying the `updated_at` timestamp, and
 * enforces business rules such as only allowing valid status strings or a valid
 * channel id. Invalid updates must cause errors, confirming backend business
 * logic enforcement.
 *
 * Steps:
 *
 * 1. Create an order as an admin (using IShoppingMallAiOrder.ICreate DTO)
 * 2. Update only the `status` field and verify changes
 * 3. Update only the `shopping_mall_ai_channel_id` and verify changes
 * 4. Update both fields together and verify changes
 * 5. Attempt update with invalid status, expect error
 * 6. Attempt update with invalid channel id, expect error
 */
export async function test_api_shopping_mall_ai_admin_orders_test_update_order_status_and_channel_as_admin(
  connection: api.IConnection,
) {
  // 1. Create an order as admin
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const initialChannelId = typia.random<string & tags.Format<"uuid">>();
  const initialStatus = "pending";

  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customerId,
        shopping_mall_ai_channel_id: initialChannelId,
        status: initialStatus,
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Update only status
  const newStatus = "paid";
  const updated1 = await api.functional.shopping_mall_ai.admin.orders.update(
    connection,
    {
      orderId: order.id,
      body: {
        status: newStatus,
      } satisfies IShoppingMallAiOrder.IUpdate,
    },
  );
  typia.assert(updated1);
  TestValidator.equals("status updated")(updated1.status)(newStatus);
  TestValidator.equals("channel id unchanged")(
    updated1.shopping_mall_ai_channel_id,
  )(order.shopping_mall_ai_channel_id);
  TestValidator.notEquals("updated_at changed")(updated1.updated_at)(
    order.updated_at,
  );

  // 3. Update only channel id
  const newChannelId = typia.random<string & tags.Format<"uuid">>();
  const updated2 = await api.functional.shopping_mall_ai.admin.orders.update(
    connection,
    {
      orderId: order.id,
      body: {
        shopping_mall_ai_channel_id: newChannelId,
      } satisfies IShoppingMallAiOrder.IUpdate,
    },
  );
  typia.assert(updated2);
  TestValidator.equals("channel id updated")(
    updated2.shopping_mall_ai_channel_id,
  )(newChannelId);
  TestValidator.equals("status unchanged")(updated2.status)(updated1.status);
  TestValidator.notEquals("updated_at changed")(updated2.updated_at)(
    updated1.updated_at,
  );

  // 4. Update both fields together
  const newestStatus = "completed";
  const newestChannelId = typia.random<string & tags.Format<"uuid">>();
  const updated3 = await api.functional.shopping_mall_ai.admin.orders.update(
    connection,
    {
      orderId: order.id,
      body: {
        status: newestStatus,
        shopping_mall_ai_channel_id: newestChannelId,
      } satisfies IShoppingMallAiOrder.IUpdate,
    },
  );
  typia.assert(updated3);
  TestValidator.equals("both updated status")(updated3.status)(newestStatus);
  TestValidator.equals("both updated channel")(
    updated3.shopping_mall_ai_channel_id,
  )(newestChannelId);
  TestValidator.notEquals("updated_at changed")(updated3.updated_at)(
    updated2.updated_at,
  );

  // 5. Attempt update with invalid status
  await TestValidator.error("invalid status")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.update(connection, {
      orderId: order.id,
      body: {
        status: "NOT_A_VALID_STATUS",
      } satisfies IShoppingMallAiOrder.IUpdate,
    });
  });

  // 6. Attempt update with invalid channel id
  await TestValidator.error("invalid channel id")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.update(connection, {
      orderId: order.id,
      body: {
        shopping_mall_ai_channel_id:
          "00000000-0000-0000-0000-000000000000" as string &
            tags.Format<"uuid">,
      } satisfies IShoppingMallAiOrder.IUpdate,
    });
  });
}

