import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInventory";
import type { IPageIShoppingMallAiInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiInventory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced seller inventory search with product scope enforcement.
 *
 * This test ensures that when a seller performs an advanced inventory search
 * using the PATCH endpoint, the API returns only those inventory entries that
 * are associated with the authenticated seller's products. Inventories outside
 * their portfolio must not be visible. The test also covers various filter
 * combinations: product filter, option filter, stock threshold (min/max
 * quantity), reservation, and restock window filters. These cases reflect
 * dashboard analytics and operational inventory use-cases.
 *
 * 1. (Prerequisite) Assume seller is authenticated (connection contains seller
 *    token).
 * 2. Call inventory search API with empty filter (wildcard) and verify all results
 *    belong to seller's products.
 * 3. Call with specific product id filter (use id from first response); expect
 *    only that product's inventories.
 * 4. If product has optioned inventory, call with option filter (use referenced
 *    option id); expect only matching records.
 * 5. Call with min/max quantity filters, verify returned inventories are in the
 *    specified thresholds.
 * 6. Call with has_reservations true/false (if data permits), verify
 *    reserved_quantity values in result.
 * 7. Call with restock_before/restock_after filters using valid datetime
 *    boundaries; check restock_at compliance.
 * 8. Attempt to filter with product id not belonging to this seller; verify no
 *    data is returned.
 *
 * Edge cases:
 *
 * - Option and restock_at fields may be null; test should handle these cases
 *   gracefully.
 * - Pagination fields present; test only first page for brevity.
 */
export async function test_api_shopping_mall_ai_test_seller_advanced_inventory_search_with_product_scope(
  connection: api.IConnection,
) {
  // 1. Inventory search with empty filter (should return only seller's products' inventories)
  const allResult =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      { body: {} },
    );
  typia.assert(allResult);
  // There should be at least one result for the seller, otherwise skip further checks.
  if (!allResult.data.length) return;

  // Map distinct product and option ids from the results
  const firstInventory = allResult.data[0];
  const productId = firstInventory.shopping_mall_ai_product_id;
  const optionId = firstInventory.shopping_mall_ai_product_option_id;
  // 2. Search with product id filter
  const prodResult =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      { body: { shopping_mall_ai_product_id: productId } },
    );
  typia.assert(prodResult);
  for (const inv of prodResult.data) {
    TestValidator.equals("belongs to filtered product")(
      inv.shopping_mall_ai_product_id,
    )(productId);
  }
  // 3. Search with option id filter (if available)
  if (optionId) {
    const optResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { shopping_mall_ai_product_option_id: optionId } },
      );
    typia.assert(optResult);
    for (const inv of optResult.data) {
      TestValidator.equals("option id match")(
        inv.shopping_mall_ai_product_option_id,
      )(optionId);
    }
  }
  // 4. Search with stock threshold
  const minQty = firstInventory.quantity;
  const maxQty = minQty;
  const thresholdResult =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      { body: { min_quantity: minQty, max_quantity: maxQty } },
    );
  typia.assert(thresholdResult);
  for (const inv of thresholdResult.data) {
    TestValidator.predicate("within min quantity")(inv.quantity >= minQty);
    TestValidator.predicate("within max quantity")(inv.quantity <= maxQty);
  }
  // 5. Search with has_reservations true/false (if distinct cases present)
  const hasReservation = allResult.data.some((i) => i.reserved_quantity > 0);
  if (hasReservation) {
    const reservationResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { has_reservations: true } },
      );
    typia.assert(reservationResult);
    for (const inv of reservationResult.data) {
      TestValidator.predicate("reservation quantity present")(
        inv.reserved_quantity > 0,
      );
    }
  }
  const hasNoReservation = allResult.data.some(
    (i) => i.reserved_quantity === 0,
  );
  if (hasNoReservation) {
    const noReservationResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { has_reservations: false } },
      );
    typia.assert(noReservationResult);
    for (const inv of noReservationResult.data) {
      TestValidator.predicate("no reservation")(inv.reserved_quantity === 0);
    }
  }
  // 6. Search by restock window (if restock_at present)
  const withRestock = allResult.data.find((i) => i.restock_at);
  if (withRestock && withRestock.restock_at) {
    const restockDate = withRestock.restock_at;
    // Before date
    const beforeResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { restock_before: restockDate } },
      );
    typia.assert(beforeResult);
    for (const inv of beforeResult.data) {
      TestValidator.predicate("before restock")(
        inv.restock_at == null || inv.restock_at <= restockDate,
      );
    }
    // After date
    const afterResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { restock_after: restockDate } },
      );
    typia.assert(afterResult);
    for (const inv of afterResult.data) {
      TestValidator.predicate("after restock")(
        inv.restock_at == null || inv.restock_at >= restockDate,
      );
    }
  }
  // 7. Negative: filter by product id that can't belong to seller
  const fakeProductId = typia.random<string & tags.Format<"uuid">>();
  if (fakeProductId !== productId) {
    const wrongResult =
      await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
        connection,
        { body: { shopping_mall_ai_product_id: fakeProductId } },
      );
    typia.assert(wrongResult);
    TestValidator.equals("no inventory for other product")(
      wrongResult.data.length,
    )(0);
  }
}

