 * records by using another seller's product or option ID as a filter.
 *
 * Business context: Sellers should only be able to view or search inventory
 * items associated with their own products and options. This test ensures that
 * using another seller's product or option ID in advanced inventory search
 * returns no inventory data and does not leak any records or details outside
 * their scope.
 *
 * Step-by-step process:
 *
 * 1. Prepare a random UUID to represent another seller's product_id.
 * 2. Prepare a random UUID to represent another seller's product_option_id.
 * 3. Attempt to search inventory using a foreign product_id only; assert the data
 *    array is empty.
 * 4. Attempt to search inventory using a foreign product_option_id only; assert
 *    the data array is empty.
 * 5. Attempt search with both fields set to foreign values; assert the data array
 *    is empty.
 */
export async function test_api_shopping_mall_ai_test_seller_search_inventories_with_other_seller_product(
  connection: api.IConnection,
) {
