    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: foreign_product_id,
        },
      },
    );
  typia.assert(resp_by_product);
  TestValidator.predicate(
    "No inventory should be returned for a foreign product ID",
  )(resp_by_product.data.length === 0);

  // 4. Attempt inventory search using only the foreign product_option_id
  const resp_by_option =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_option_id: foreign_product_option_id,
        },
      },
    );
  typia.assert(resp_by_option);
  TestValidator.predicate(
    "No inventory should be returned for a foreign product option ID",
  )(resp_by_option.data.length === 0);

  // 5. Attempt inventory search with both fields set to unrelated values
  const resp_by_both =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: foreign_product_id,
          shopping_mall_ai_product_option_id: foreign_product_option_id,
        },
      },
    );
  typia.assert(resp_by_both);
  TestValidator.predicate(
    "No inventory should be returned for a combination of foreign product and option IDs",
  )(resp_by_both.data.length === 0);
}

