import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";

/**
 * E2E test for updating a product inquiry by the customer who created it.
 *
 * This test scenario verifies that a customer who previously created a product
 * inquiry (question) can update the contents of their question (such as the
 * text 'question' and/or privacy setting 'is_private'), and that such updates
 * are reflected correctly in API responses. It also implicitly checks that
 * audit/history fields are preserved (timestamps, seller/customer IDs, etc.)
 *
 * Steps:
 *
 * 1. Create a product inquiry as a customer using the create endpoint.
 * 2. Update the inquiry's question text using the update endpoint, as the same
 *    customer.
 * 3. Update the inquiry's privacy setting (is_private) using the same endpoint, as
 *    the same customer.
 * 4. After each update, verify that changes are reflected in the API response and
 *    that fields not edited remain unchanged.
 * 5. Attempt to update a non-existent inquiry and verify an error is thrown.
 */
export async function test_api_shopping_mall_ai_customer_inquiries_test_update_inquiry_question_by_owner_customer(
  connection: api.IConnection,
) {
  // 1. Create a new inquiry as a customer
  const productId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IShoppingMallAiInquiry.ICreate = {
    shopping_mall_ai_product_id: productId,
    question:
      "Initial question for E2E update test - " + RandomGenerator.paragraph()(),
    is_private: false,
  };
  const inquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      { body: createInput },
    );
  typia.assert(inquiry);
  TestValidator.equals("question matches input")(inquiry.question)(
    createInput.question,
  );
  TestValidator.equals("privacy matches input")(inquiry.is_private)(
    createInput.is_private,
  );

  // 2. Update the inquiry's question text via PUT
  const updateQuestion =
    "Updated question text - " + RandomGenerator.content()()();
  const updated1 =
    await api.functional.shopping_mall_ai.customer.inquiries.update(
      connection,
      {
        inquiryId: inquiry.id,
        body: {
          question: updateQuestion,
        } satisfies IShoppingMallAiInquiry.IUpdate,
      },
    );
  typia.assert(updated1);
  TestValidator.equals("question updated")(updated1.question)(updateQuestion);
  TestValidator.equals("privacy unchanged")(updated1.is_private)(
    inquiry.is_private,
  );
  TestValidator.equals("created_at unchanged")(updated1.created_at)(
    inquiry.created_at,
  );
  TestValidator.equals("seller unchanged")(updated1.shopping_mall_ai_seller_id)(
    inquiry.shopping_mall_ai_seller_id,
  );
  TestValidator.equals("customer unchanged")(
    updated1.shopping_mall_ai_customer_id,
  )(inquiry.shopping_mall_ai_customer_id);
  TestValidator.equals("product unchanged")(
    updated1.shopping_mall_ai_product_id,
  )(inquiry.shopping_mall_ai_product_id);
  TestValidator.equals("answer unchanged")(updated1.answer)(inquiry.answer);
  TestValidator.equals("helpful unchanged")(updated1.answer_marked_helpful)(
    inquiry.answer_marked_helpful,
  );
  TestValidator.equals("deleted_at unchanged")(updated1.deleted_at)(
    inquiry.deleted_at,
  );

  // 3. Update the inquiry's privacy setting
  const updatePrivate = true;
  const updated2 =
    await api.functional.shopping_mall_ai.customer.inquiries.update(
      connection,
      {
        inquiryId: inquiry.id,
        body: {
          is_private: updatePrivate,
        } satisfies IShoppingMallAiInquiry.IUpdate,
      },
    );
  typia.assert(updated2);
  TestValidator.equals("privacy updated")(updated2.is_private)(updatePrivate);
  TestValidator.equals("question unchanged")(updated2.question)(updateQuestion);
  TestValidator.equals("created_at unchanged")(updated2.created_at)(
    inquiry.created_at,
  );
  TestValidator.equals("seller unchanged")(updated2.shopping_mall_ai_seller_id)(
    inquiry.shopping_mall_ai_seller_id,
  );
  TestValidator.equals("customer unchanged")(
    updated2.shopping_mall_ai_customer_id,
  )(inquiry.shopping_mall_ai_customer_id);
  TestValidator.equals("product unchanged")(
    updated2.shopping_mall_ai_product_id,
  )(inquiry.shopping_mall_ai_product_id);
  TestValidator.equals("answer unchanged")(updated2.answer)(inquiry.answer);
  TestValidator.equals("helpful unchanged")(updated2.answer_marked_helpful)(
    inquiry.answer_marked_helpful,
  );
  TestValidator.equals("deleted_at unchanged")(updated2.deleted_at)(
    inquiry.deleted_at,
  );

  // 4. Negative scenario: attempt to update a non-existent inquiry
  await TestValidator.error("update non-existent inquiry should fail")(
    async () => {
      await api.functional.shopping_mall_ai.customer.inquiries.update(
        connection,
        {
          inquiryId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            question: "Should fail",
          } satisfies IShoppingMallAiInquiry.IUpdate,
        },
      );
    },
  );
}

