import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";

/**
 * Validate admin update behavior on a soft-deleted product inquiry.
 *
 * This test checks if business rules for editing a soft-deleted inquiry (where
 * deleted_at is set) are followed. It asserts the admin can override or is
 * blocked according to policy, and that the result or error is handled
 * correctly and audit trail updated.
 *
 * Steps:
 *
 * 1. Customer creates a new inquiry through the customer endpoint.
 * 2. Customer soft-deletes the inquiry using the customer endpoint (this sets
 *    deleted_at).
 * 3. As admin, attempt to update the soft-deleted inquiry with new data
 *    (question/answer/privacy change).
 * 4. If the update is allowed for compliance, check that data is updated and audit
 *    (deleted_at may remain); else, verify error and that the record is
 *    unchanged.
 */
export async function test_api_shopping_mall_ai_admin_inquiries_test_admin_updates_inquiry_that_is_deleted(
  connection: api.IConnection,
) {
  // 1. Customer creates an inquiry
  const inquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          question: "What is the delivery time?",
          is_private: false,
        },
      },
    );
  typia.assert(inquiry);

  // 2. Customer soft-deletes (logical delete) the inquiry
  await api.functional.shopping_mall_ai.customer.inquiries.erase(connection, {
    inquiryId: inquiry.id,
  });

  // 3. As admin, attempt to update the soft-deleted inquiry
  let result: IShoppingMallAiInquiry | undefined = undefined;
  let updateError: unknown = undefined;

  const newQuestion = "Can I specify a delivery date?";
  const newAnswer = "Yes, please contact support with your order number.";

  try {
    result = await api.functional.shopping_mall_ai.admin.inquiries.update(
      connection,
      {
        inquiryId: inquiry.id,
        body: {
          question: newQuestion,
          answer: newAnswer,
          is_private: true,
        },
      },
    );
    typia.assert(result);
  } catch (err) {
    updateError = err;
  }

  // 4. Validation: Either update is allowed (compliance override), or system blocks it
  if (result) {
    // Compliance override: admin can update soft-deleted record
    TestValidator.equals("question updated")(result.question)(newQuestion);
    TestValidator.equals("answer updated")(result.answer)(newAnswer);
    TestValidator.equals("privacy updated")(result.is_private)(true);
    // Validate still soft-deleted
    TestValidator.predicate("inquiry remains soft-deleted")(
      typeof result.deleted_at === "string" && !!result.deleted_at,
    );
  } else {
    // Update not allowed: must throw error
    TestValidator.predicate("error thrown when updating soft-deleted inquiry")(
      !!updateError,
    );
  }
}

