        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(initialProduct);

  // 2. Generate new values for all mutable fields
  const updatedTitle = "Updated Product Title";
  const updatedDescription = "This is an updated description by admin.";
  const updatedCategoryId = typia.random<string & tags.Format<"uuid">>();
  const updatedPrice = 19999.99;
  const updatedStatus = "inactive";
  const updatedSku = `SKU-${RandomGenerator.alphaNumeric(8)}`;

  // 3. Perform update as admin
  const updatedProduct =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: initialProduct.id,
        body: {
          shopping_mall_ai_product_category_id: updatedCategoryId,
          title: updatedTitle,
          description: updatedDescription,
          price: updatedPrice,
          status: updatedStatus,
          sku: updatedSku,
        } satisfies IShoppingMallAiProduct.IUpdate,
      },
    );
