  // 4. Assert response fields match update and audit is correct
  TestValidator.equals("product id")(updatedProduct.id)(initialProduct.id);
  TestValidator.equals("category")(
    updatedProduct.shopping_mall_ai_product_category_id,
  )(updatedCategoryId);
  TestValidator.equals("title")(updatedProduct.title)(updatedTitle);
  TestValidator.equals("description")(updatedProduct.description)(
    updatedDescription,
  );
  TestValidator.equals("price")(updatedProduct.price)(updatedPrice);
  TestValidator.equals("status")(updatedProduct.status)(updatedStatus);
  TestValidator.equals("sku")(updatedProduct.sku)(updatedSku);
  TestValidator.notEquals("updated_at should differ after update")(
    updatedProduct.updated_at,
  )(initialProduct.updated_at);
  // created_at must remain unchanged
  TestValidator.equals("created_at should not change")(
    updatedProduct.created_at,
  )(initialProduct.created_at);
}

