 *    specific substring, with active=true and low limit.
 * 3. Check that only active, name-matching categories are returned, and pagination
 *    metadata is correct.
 * 4. Try to search for inactive categories (active=false) as a customer; ensure no
 *    categories are returned.
 */
export async function test_api_shopping_mall_ai_test_advanced_search_product_categories_by_name_and_status(
  connection: api.IConnection,
) {
  // 1. Create categories as admin (some active, some inactive, various names)
  const categoryActiveFoo =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: `FooBooks_${typia.random<number & tags.Type<"int32">>()}`,
          display_order: 1,
          active: true,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
    );
