  const categoryInactiveFoo =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: `FooElectronics_${typia.random<number & tags.Type<"int32">>()}`,
          display_order: 2,
          active: false,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
    );
  typia.assert(categoryInactiveFoo);

  const categoryActiveBar =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: `BarToys_${typia.random<number & tags.Type<"int32">>()}`,
          display_order: 3,
          active: true,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
