    ),
  )(true);
  TestValidator.equals("pagination limit matches")(
    searchResponse.pagination.limit,
  )(2);

  // 4. If more records exist than limit, check pagination.
  if (searchResponse.pagination.records > 2) {
    TestValidator.predicate("multiple pages for Foo")(
      searchResponse.pagination.pages > 1,
    );
