  )(base.shopping_mall_ai_channel_id);
  TestValidator.equals("metadata updated")(updated.metadata_json)(
    updateInput.metadata_json,
  );

  // 5. Ensure updated_at is newer or equal and created_at is unchanged
  TestValidator.equals("created_at constant")(updated.created_at)(
    base.created_at,
  );
  TestValidator.predicate("updated_at later or equal")(
    new Date(updated.updated_at).getTime() >=
      new Date(base.updated_at).getTime(),
  );
}

