/**
 * Test advanced cart search with filtering and pagination.
 *
 * This test verifies that the admin shopping cart search endpoint correctly
 * implements:
 *
 * - Filtering by customer, seller, channel, section, and a specified creation
 *   time window
 * - Pagination via page/limit parameters and accurate pagination metadata
 * - Result set integrity: all returned data match the filter criteria
 * - Sorting by created_at descending (latest first)
 *
 * Steps:
 *
 * 1. Generate a diverse set of carts (varied in customer, seller, channel,
 *    section, times)
 * 2. Perform a filtered search on a specific customer, seller, channel, section,
 *    and creation date window including page/limit parameters for pagination
 * 3. Validate that returned carts strictly match all filters, pagination reflects
 *    expectation, and that rows are sorted by created_at descending order
 *
 * Business context: This ensures operational tools/analytics work and catch
 * regressions in admin-filtered list APIs.
 */
export async function test_api_shopping_mall_ai_admin_carts_test_search_carts_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Prepare a pool of diverse attribute IDs
  const knownCustomers = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    undefined, // represent guest carts (no customer)
  ];
  const knownSellers = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const knownChannels = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const knownSections = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Pick filter criteria based on known pools
  const filterCustomer = knownCustomers[0];
  const filterSeller = knownSellers[0];
  const filterChannel = knownChannels[0];
  const filterSection = knownSections[0];

  // Reference date for cart creation
  const baseDate = new Date();

  // Step 1: Create 8 carts across different attribute combinations and times
  const allCarts: IShoppingMallAiCart[] = [];
  for (let i = 0; i < 8; ++i) {
    const cartCustomer = knownCustomers[i % knownCustomers.length];
    const cartSeller = knownSellers[i % knownSellers.length];
    const cartChannel = knownChannels[i % knownChannels.length];
    const cartSection = knownSections[i % knownSections.length];
    // createAt: simulate carts as if created in the past N hours
    const cart: IShoppingMallAiCart =
      await api.functional.shopping_mall_ai.admin.carts.create(connection, {
        body: {
          shopping_mall_ai_customer_id: cartCustomer,
          shopping_mall_ai_seller_id: cartSeller,
          shopping_mall_ai_channel_id: cartChannel,
          shopping_mall_ai_section_id: cartSection,
        } satisfies IShoppingMallAiCart.ICreate,
      });
    allCarts.push(cart);
  }
  typia.assert(allCarts);

  // Use middle portion of created carts for filter window
  const dateFrom = allCarts[2].created_at;
  const dateTo = allCarts[6].created_at;

  // Step 2: Search with filters and paging (page 1, limit 3)
  const page = 1;
  const limit = 3;
  const searchRequest: IShoppingMallAiCart.IRequest = {
    shopping_mall_ai_customer_id: filterCustomer,
    shopping_mall_ai_seller_id: filterSeller,
    shopping_mall_ai_channel_id: filterChannel,
    shopping_mall_ai_section_id: filterSection,
    created_at_from: dateFrom,
    created_at_to: dateTo,
    page,
    limit,
  };
  const result = await api.functional.shopping_mall_ai.admin.carts.search(
    connection,
    { body: searchRequest },
  );
  typia.assert(result);

  // Step 3: Validate that returned carts match all filter fields
  for (const cart of result.data) {
    TestValidator.equals("customer id filter")(
      cart.shopping_mall_ai_customer_id,
    )(searchRequest.shopping_mall_ai_customer_id);
    TestValidator.equals("seller id filter")(cart.shopping_mall_ai_seller_id)(
      searchRequest.shopping_mall_ai_seller_id,
    );
    TestValidator.equals("channel id filter")(cart.shopping_mall_ai_channel_id)(
      searchRequest.shopping_mall_ai_channel_id,
    );
    TestValidator.equals("section id filter")(cart.shopping_mall_ai_section_id)(
      searchRequest.shopping_mall_ai_section_id,
    );
    TestValidator.predicate("created_at after or equal from")(
      cart.created_at >= dateFrom,
    );
    TestValidator.predicate("created_at before or equal to")(
      cart.created_at <= dateTo,
    );
  }
  // Validate pagination meta
  TestValidator.equals("pagination limit")(result.pagination.limit)(limit);
  TestValidator.equals("pagination current")(result.pagination.current)(page);
  TestValidator.predicate("data length <= limit")(result.data.length <= limit);
  // Validate that rows are sorted by created_at descending order
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate("sorted by created_at desc")(
      result.data[i - 1].created_at >= result.data[i].created_at,
    );
  }
}

