/**
 * Test handling of invalid filter parameters in shopping cart search.
 *
 * This test ensures that the admin cart search endpoint strictly enforces
 * schema validation on incoming filters. If unsupported fields are supplied
 * (fields not in IShoppingMallAiCart.IRequest schema) or values are malformed
 * (e.g., not a uuid, not a date-time, or an out-of-range int), the backend must
 * reject them with a validation error. Correctly formed requests must succeed.
 *
 * Steps:
 *
 * 1. Attempt to search with an unsupported (non-existent) field – should trigger a
 *    validation error.
 * 2. Search with a clearly malformed UUID value – should fail validation.
 * 3. Search with an invalid date-time string – should fail validation.
 * 4. Search with an int32 field out of allowed range – should fail validation.
 * 5. As a positive control, search with valid filters and verify normal operation.
 */
export async function test_api_shopping_mall_ai_admin_carts_test_search_carts_with_invalid_filters(
  connection: api.IConnection,
) {
  // 1. Attempt: Extra unsupported property (should fail validation)
  await TestValidator.error("unsupported field in filter")(async () => {
    // TypeScript will block extra properties at compile time, so we simulate by casting through unknown.
    await api.functional.shopping_mall_ai.admin.carts.search(connection, {
      body: {
        ...({
          not_a_real_field: "not-recognized",
        } as unknown as IShoppingMallAiCart.IRequest),
      },
    });
  });

  // 2. Malformed UUID filter
  await TestValidator.error("invalid uuid in filter")(async () => {
    await api.functional.shopping_mall_ai.admin.carts.search(connection, {
      body: {
        shopping_mall_ai_customer_id: "invalid-uuid",
      },
    });
  });

  // 3. Malformed date-time filter
  await TestValidator.error("invalid date-time in filter")(async () => {
    await api.functional.shopping_mall_ai.admin.carts.search(connection, {
      body: {
        created_at_from: "not-a-date",
      },
    });
  });

  // 4. Out-of-range int32 (page=0, must be >=1)
  await TestValidator.error("invalid int32 in filter")(async () => {
    await api.functional.shopping_mall_ai.admin.carts.search(connection, {
      body: {
        page: 0,
      },
    });
  });

  // 5. Control: Send valid search
  const validOutput = await api.functional.shopping_mall_ai.admin.carts.search(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(validOutput);
}

