 *
 * Steps:
 *
 * 1. Create a valid product via the admin API
 * 2. Create a valid inventory row for this product
 * 3. Attempt to update inventory with negative quantity
 * 4. Attempt to update inventory with reserved_quantity > quantity
 * 5. Attempt to set product ID to a non-existent product
 * 6. Validate that updates fail and state remains unchanged
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiInventories_test_admin_update_inventory_with_invalid_data(
