/**
 * Test successful update of inventory quantity by seller.
 *
 * This function verifies that a seller can update the quantity of an inventory
 * record they own. Preparation involves creating a new product owned by the
 * seller, setting up an associated inventory row, and then updating the
 * quantity. After updating, the test checks that the new value is correctly
 * reflected and the audit data (timestamps) is updated, ensuring the update was
 * properly recorded.
 *
 * STEP-BY-STEP:
 *
 * 1. Create a new product as a seller.
 * 2. Create an inventory row for that product.
 * 3. Update the inventory's quantity.
 * 4. Confirm the response includes the new quantity, ID matches, and updated_at
 *    field has changed.
 */
export async function test_api_shopping_mall_ai_seller_shoppingMallAiInventories_test_seller_update_inventory_success(
  connection: api.IConnection,
) {
  // 1. Create a product as seller
  const productInput: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    price: typia.random<number & tags.JsonSchemaPlugin<{ format: "double" }>>(),
    status: "active",
    sku: RandomGenerator.alphaNumeric(8),
  };
  const product =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      { body: productInput },
    );
  typia.assert(product);

  // 2. Create an inventory row for this product
  const inventoryCreate: IShoppingMallAiInventory.ICreate = {
    shopping_mall_ai_product_id: product.id,
    shopping_mall_ai_product_option_id: null,
    quantity: 50,
    reserved_quantity: 0,
    restock_at: null,
  };
  const inventory =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.create(
      connection,
      { body: inventoryCreate },
    );
  typia.assert(inventory);

  // 3. Update the inventory quantity
  const newQuantity = inventory.quantity + 12;
  const updatedInventory =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiInventories.update(
      connection,
      {
        shoppingMallAiInventoryId: inventory.id,
        body: {
          quantity: newQuantity,
        } satisfies IShoppingMallAiInventory.IUpdate,
      },
    );
  typia.assert(updatedInventory);

  // 4. Confirm the update is reflected and audited
  TestValidator.equals("inventory id matches")(updatedInventory.id)(
    inventory.id,
  );
  TestValidator.equals("new quantity")(updatedInventory.quantity)(newQuantity);
  TestValidator.notEquals("updated_at changed")(updatedInventory.updated_at)(
    inventory.updated_at,
  );
  // updated_at should be at/after created_at (should never get earlier!)
  TestValidator.predicate("update timestamp increases")(
    new Date(updatedInventory.updated_at).getTime() >=
      new Date(inventory.created_at).getTime(),
  );
}

