import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Test that a customer can retrieve the details of a comment they authored on a
 * BBS post.
 *
 * Business context: In a shopping mall's BBS (Bulletin Board System), a
 * customer writes a post and then authors a comment on that post. This test
 * ensures that the comment author (customer) can successfully retrieve the full
 * detail of their own comment using the detail endpoint, and that all expected
 * fields—such as content, post linkage, author ID, parent, timestamps, and
 * soft-deletion—are present and correct.
 *
 * Step-by-step process:
 *
 * 1. Create a BBS post as the customer using the API endpoint (this simulates a
 *    forum post by the customer).
 * 2. As the same customer, author a top-level comment on that post (no parent, not
 *    deleted) by calling the comment-create endpoint.
 * 3. Retrieve the detail of that comment as the author, using the comment detail
 *    endpoint (with bbsPostId and bbsCommentId).
 * 4. Validate by assertions:
 *
 *    - Comment ID matches created comment
 *    - Post ID links back to the post
 *    - Customer ID matches comment author
 *    - Comment body matches original content
 *    - Parent ID is null (top-level comment)
 *    - Deleted_at is null (not deleted)
 *    - Ip, created_at, and updated_at are present and valid (format)
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_bbsComments_test_get_bbs_comment_detail_as_comment_author_success(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as the customer
  const postInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 2. Author a top-level comment as the same customer
  const commentInput: IShoppingMallAiBbsComment.ICreate = {
    shopping_mall_ai_bbs_post_id: post.id,
    body: RandomGenerator.paragraph()(1),
  };
  const comment =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: commentInput,
      },
    );
  typia.assert(comment);

  // 3. Retrieve the detail of this comment as the author
  const output =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.at(
      connection,
      {
        bbsPostId: post.id,
        bbsCommentId: comment.id,
      },
    );
  typia.assert(output);

  // 4. Validate all required output fields and business rules
  // Check ID and linkage
  TestValidator.equals("id")(output.id)(comment.id);
  TestValidator.equals("post id")(output.shopping_mall_ai_bbs_post_id)(post.id);
  // Author matches
  TestValidator.equals("customer id matches")(
    output.shopping_mall_ai_customer_id,
  )(comment.shopping_mall_ai_customer_id);
  // Content matches
  TestValidator.equals("body matches")(output.body)(comment.body);
  // Parent ID is top-level
  TestValidator.equals("parent_id is null")(output.parent_id)(null);
  // Not deleted
  TestValidator.equals("deleted_at is null")(output.deleted_at)(null);
  // Timestamps are present and ISO8601 (typia.assert)
  typia.assert(output.created_at);
  typia.assert(output.updated_at);
  // IP string present
  typia.assert(output.ip);
}

