import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate that a customer cannot access a BBS comment in a restricted
 * section/channel.
 *
 * This test covers the scenario where an admin creates a BBS post in a
 * section/channel not visible to a regular customer and then creates a comment
 * in it. When a customer attempts to retrieve details of that comment by its
 * post and comment ID, the operation should fail with an authorization or not
 * found error according to business logic.
 *
 * Steps:
 *
 * 1. Admin creates a restricted BBS post (in a channel/section inaccessible to
 *    customer).
 * 2. Admin creates a comment in the restricted post.
 * 3. Simulate customer session and attempt to retrieve the comment with GET
 *    /shopping-mall-ai/customer/bbsPosts/{bbsPostId}/bbsComments/{bbsCommentId}.
 * 4. Expect an error: HttpError (authorization or not found).
 */
export async function test_api_shopping_mall_ai_test_get_bbs_comment_detail_without_permission_fails(
  connection: api.IConnection,
) {
  // 1. Admin creates a BBS post in a restricted channel/section (simulate restriction by using random UUIDs for channel/section)
  const restrictedPost =
    await api.functional.shopping_mall_ai.admin.bbsPosts.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Restricted Post",
        body: "This is a restricted post only visible to admins.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    });
  typia.assert(restrictedPost);

  // 2. Admin creates a comment in the restricted post
  const comment =
    await api.functional.shopping_mall_ai.admin.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: restrictedPost.id,
        body: {
          shopping_mall_ai_bbs_post_id: restrictedPost.id,
          body: "Restricted comment content.",
          parent_id: null,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment);

  // 3. Simulate customer attempting to access the comment (should fail)
  await TestValidator.error("customer cannot access restricted BBS comment")(
    async () => {
      await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.at(
        connection,
        {
          bbsPostId: restrictedPost.id,
          bbsCommentId: comment.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate that a seller can retrieve details for a comment posted on their own
 * BBS post.
 *
 * Preconditions: The seller must have at least one BBS post and at least one
 * comment on that post (the comment could be authored by the seller or another
 * participant).
 *
 * Workflow:
 *
 * 1. Create a BBS post as the seller.
 * 2. Add a comment to the created BBS post as the seller.
 * 3. Retrieve the details of that comment as the seller using the target GET
 *    endpoint.
 * 4. Assert that the returned comment matches what was created according to the
 *    IShoppingMallAiBbsComment schema.
 * 5. Validate that all returned fields are well-formed and that the seller can
 *    view their own post's comments.
 */
export async function test_api_shopping_mall_ai_test_get_bbs_comment_detail_as_seller_on_own_post(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as seller
  const postInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(10),
    body: RandomGenerator.content()()(30),
  };
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 2. Add a comment to the seller's BBS post
  const commentInput: IShoppingMallAiBbsComment.ICreate = {
    shopping_mall_ai_bbs_post_id: post.id,
    body: RandomGenerator.content()()(16),
  };
  const comment =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      { bbsPostId: post.id, body: commentInput },
    );
  typia.assert(comment);

  // 3. Retrieve the details of that comment as seller
  const retrieved =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.at(
      connection,
      { bbsPostId: post.id, bbsCommentId: comment.id },
    );
  typia.assert(retrieved);

  // 4. Assert that the returned comment matches what was created
  TestValidator.equals("comment.id matches")(retrieved.id)(comment.id);
  TestValidator.equals("comment.body matches")(retrieved.body)(comment.body);
  TestValidator.equals("comment.bbs_post_id matches")(
    retrieved.shopping_mall_ai_bbs_post_id,
  )(post.id);
  TestValidator.equals("comment.deleted_at is null or undefined")(
    retrieved.deleted_at,
  )(null);

  // 5. Validate the comment type, ensuring all fields are present
  typia.assert<IShoppingMallAiBbsComment>(retrieved);
}

