import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * E2E test for customer creating a top-level BBS comment on an existing BBS
 * post.
 *
 * This test validates the process where an authenticated customer creates a new
 * top-level (i.e., not a reply) comment under an existing BBS post. It ensures
 * required setup of BBS post creation beforehand due to the comment's foreign
 * key dependency. The test verifies all expected metadata on response and the
 * correct association with the BBS post. Steps:
 *
 * 1. Create a BBS post as a customer (using
 *    api.functional.shopping_mall_ai.customer.bbsPosts.create).
 * 2. As the same customer, create a new top-level comment (with parent_id
 *    null/undefined) on the post using the 'create comment' API.
 * 3. Validate the comment response: proper assignment of post and customer foreign
 *    keys, matches the BBS post, is top-level, and contains full required
 *    metadata (id, content, author, IP, timestamps, etc). Also verify that
 *    parent_id is not present or is null.
 *
 * Edge case: No parent_id provided should yield a top-level comment; test null
 * and undefined parent_id acceptance if both are allowed. Optionally, re-query
 * the post's comment listing (if supported in future) to check for presence of
 * the new comment.
 */
export async function test_api_shopping_mall_ai_customer_bbsPosts_bbsComments_create_top_level_success(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as a customer
  const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create a top-level comment on the created post (parent_id omitted)
  const comment =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: RandomGenerator.paragraph()(),
          // parent_id omitted intentionally for top-level
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment);

  // 3. Validate response fields and top-level linkage
  TestValidator.equals("bbs post id")(comment.shopping_mall_ai_bbs_post_id)(
    post.id,
  );
  TestValidator.equals("top-level comment: parent_id is undefined OR null")(
    comment.parent_id ?? null,
  )(null);
  TestValidator.predicate("has comment id")(
    typeof comment.id === "string" && comment.id.length > 0,
  );
  TestValidator.predicate("has body")(
    typeof comment.body === "string" && comment.body.length > 0,
  );
  TestValidator.predicate("ip present")(
    typeof comment.ip === "string" && comment.ip.length > 0,
  );
  TestValidator.predicate("created_at present")(!!comment.created_at);
  TestValidator.predicate("updated_at present")(!!comment.updated_at);
  TestValidator.equals("comment not deleted")(comment.deleted_at ?? null)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate customer ability to reply to an existing BBS comment (nested reply).
 *
 * This tests the 2nd and 3rd level comment nesting in a thread for a BBS post,
 * ensuring parent/child relationship is stored and preserved.
 *
 * Steps:
 *
 * 1. Create a BBS post as a customer.
 * 2. Add a top-level comment (no parent_id) to the post.
 * 3. Add a reply (level 2, with parent_id set to first comment).
 * 4. Add a nested reply (level 3, with parent_id set to the reply in 3).
 * 5. Validate:
 *
 *    - Each comment is created and parent_id linkage is correct.
 *    - Thread structure is properly nested by parent_id.
 *    - Level 3 reply cannot have its own child (Nesting limit enforced, but as
 *         system has no error-path API, we do not test beyond allowed nesting
 *         here).
 */
export async function test_api_shopping_mall_ai_test_customer_create_reply_bbs_comment_to_existing_comment(
  connection: api.IConnection,
) {
  // 1. Create a BBS post
  const postInput: IShoppingMallAiBbsPost.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(3),
    body: RandomGenerator.content()()(2),
  };
  const post = await api.functional.shopping_mall_ai.customer.bbsPosts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);
  TestValidator.equals("title")(post.title)(postInput.title);
  TestValidator.equals("body")(post.body)(postInput.body);

  // 2. Add top-level comment
  const topCommentInput: IShoppingMallAiBbsComment.ICreate = {
    shopping_mall_ai_bbs_post_id: post.id,
    body: RandomGenerator.paragraph()(2),
    parent_id: null,
  };
  const topComment =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: topCommentInput,
      },
    );
  typia.assert(topComment);
  TestValidator.equals("comment for post")(
    topComment.shopping_mall_ai_bbs_post_id,
  )(post.id);
  TestValidator.equals("top level comment has no parent")(topComment.parent_id)(
    null,
  );
  TestValidator.equals("comment body")(topComment.body)(topCommentInput.body);

  // 3. Add reply (level 2)
  const replyL2Input: IShoppingMallAiBbsComment.ICreate = {
