      connection,
      {
        bbsPostId: post.id,
        body: replyL2Input,
      },
    );
  typia.assert(replyL2);
  TestValidator.equals("reply references top comment")(replyL2.parent_id)(
    topComment.id,
  );
  TestValidator.equals("reply for post")(replyL2.shopping_mall_ai_bbs_post_id)(
    post.id,
  );
  TestValidator.equals("reply body")(replyL2.body)(replyL2Input.body);

  // 4. Add reply to level 2 reply (level 3)
  const replyL3Input: IShoppingMallAiBbsComment.ICreate = {
    shopping_mall_ai_bbs_post_id: post.id,
    body: RandomGenerator.paragraph()(1),
    parent_id: replyL2.id,
  };
  const replyL3 =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: replyL3Input,
      },
    );
  typia.assert(replyL3);
  TestValidator.equals("level 3 reply references replyL2")(replyL3.parent_id)(
    replyL2.id,
  );
  TestValidator.equals("reply for post")(replyL3.shopping_mall_ai_bbs_post_id)(
    post.id,
  );
  TestValidator.equals("reply body")(replyL3.body)(replyL3Input.body);

  // 5. [Cannot test further nesting due to API surface] Validate parent/child
  TestValidator.equals("level 3 reply parent_id == level 2 reply id")(
    replyL3.parent_id,
  )(replyL2.id);
  TestValidator.equals("level 2 reply parent_id == top comment id")(
    replyL2.parent_id,
  )(topComment.id);
}

