import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validates that BBS forum comment nesting does not exceed the 3-level depth
 * limit.
 *
 * This test ensures that the system prevents creating replies deeper than three
 * levels for forum (BBS) posts. This is important for ensuring comment
 * structure remains manageable and prevents abuse or unreadable thread nesting
 * in high-traffic forums.
 *
 * Business rules: A top-level comment (level 1) can be created, as can replies
 * to it (level 2) and to those replies (level 3). Creating a further reply
 * (level 4, a "great-grandchild" comment) must fail with an error.
 *
 * Steps performed:
 *
 * 1. Create a new forum post to serve as the thread root.
 * 2. Add a top-level comment (no parent).
 * 3. Add a reply to that comment.
 * 4. Add another reply to the level-2 comment (reaching the 3rd level, which is
 *    permitted).
 * 5. Attempt to add a reply to the level-3 comment, which must be rejected by the
 *    API. Confirm an error occurs and the illegal 4th-level comment is not
 *    created.
 */
export async function test_api_shopping_mall_ai_test_customer_create_bbs_comment_exceeds_nesting_fails(
  connection: api.IConnection,
) {
  // 1. Create a new BBS forum post
  const bbsPost =
    await api.functional.shopping_mall_ai.customer.bbsPosts.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(5),
        body: RandomGenerator.content()()(),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    });
  typia.assert(bbsPost);

  // 2. Add a top-level comment (level 1)
  const comment1 =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: bbsPost.id,
        body: {
          shopping_mall_ai_bbs_post_id: bbsPost.id,
          body: RandomGenerator.paragraph()(3),
          parent_id: null,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment1);
  TestValidator.equals("comment1 references post")(
    comment1.shopping_mall_ai_bbs_post_id,
  )(bbsPost.id);
  TestValidator.equals("comment1 is top-level")(comment1.parent_id)(null);

  // 3. Add a reply to comment1 (level 2)
  const comment2 =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: bbsPost.id,
        body: {
          shopping_mall_ai_bbs_post_id: bbsPost.id,
          body: RandomGenerator.paragraph()(3),
          parent_id: comment1.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment2);
  TestValidator.equals("comment2 parent = comment1")(comment2.parent_id)(
    comment1.id,
  );
  TestValidator.equals("comment2 references post")(
    comment2.shopping_mall_ai_bbs_post_id,
  )(bbsPost.id);

  // 4. Add a reply to comment2 (level 3)
  const comment3 =
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: bbsPost.id,
        body: {
          shopping_mall_ai_bbs_post_id: bbsPost.id,
          body: RandomGenerator.paragraph()(3),
          parent_id: comment2.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment3);
  TestValidator.equals("comment3 parent = comment2")(comment3.parent_id)(
    comment2.id,
  );
  TestValidator.equals("comment3 references post")(
    comment3.shopping_mall_ai_bbs_post_id,
  )(bbsPost.id);

  // 5. Attempt to add a forbidden 4th-level reply (must fail)
  await TestValidator.error("reject 4th-level comment nesting")(async () => {
    await api.functional.shopping_mall_ai.customer.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: bbsPost.id,
        body: {
          shopping_mall_ai_bbs_post_id: bbsPost.id,
          body: RandomGenerator.paragraph()(3),
          parent_id: comment3.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
