import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Test that a seller can create both a top-level and a reply comment on their
 * own BBS post.
 *
 * This test validates that:
 *
 * 1. A seller can successfully create a new BBS post using their credentials.
 * 2. The seller can comment on their own post as a top-level comment.
 * 3. The created comment is correctly associated with the BBS post, and the author
 *    (customer id) matches the post author (seller context).
 * 4. The seller can create a reply comment (threaded) with its parent set to the
 *    previously created comment, and all relationships are preserved.
 * 5. Both comment types (top-level and reply) properly show correct parent_id,
 *    post association, and author linkage.
 *
 * Business context:
 *
 * - Ensures BBS/forum comments function correctly for sellers, both for direct
 *   comment and reply scenarios.
 * - Confirms comment authorship always matches session (seller as customer).
 * - Validates thread structure works for up to 3 levels (here up to level 2).
 *
 * Test workflow:
 *
 * 1. Create a seller-owned BBS post (using create endpoint as seller).
 * 2. Use seller session to create a top-level comment on that post.
 * 3. Assert the comment is correctly attached to post and authored by the seller.
 * 4. Use seller session to create a reply (child) comment with parent_id set to
 *    original comment id; assert child relationships and author, as above.
 */
export async function test_api_shopping_mall_ai_test_seller_create_bbs_comment_on_own_post_success(
  connection: api.IConnection,
) {
  // 1. Create a new seller-owned BBS post
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(4),
        body: RandomGenerator.content()(2)(3),
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create a top-level comment on the created post
  const comment =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
          parent_id: null,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(comment);

  // Check: comment is attached to post, correct author, is top-level
  TestValidator.equals("comment references correct post")(
    comment.shopping_mall_ai_bbs_post_id,
  )(post.id);
  TestValidator.equals("comment's author matches post author")(
    comment.shopping_mall_ai_customer_id,
  )(post.shopping_mall_ai_customer_id);
  TestValidator.equals("top-level comment")(comment.parent_id)(null);

  // 3. Create a reply comment (threaded, parent_id set to the previous comment)
  const reply =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
          parent_id: comment.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(reply);

  // Check reply comment is properly parented and authorship matches
  TestValidator.equals("reply references correct post")(
    reply.shopping_mall_ai_bbs_post_id,
  )(post.id);
  TestValidator.equals("reply's parent_id")(reply.parent_id)(comment.id);
  TestValidator.equals("reply's author matches post author")(
    reply.shopping_mall_ai_customer_id,
  )(post.shopping_mall_ai_customer_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import type { IShoppingMallAiBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsComment";

/**
 * Validate that a seller can reply (nested comment) to their own BBS post via
 * the seller BBS post comment API, testing up to the maximum allowed nesting
 * level (3, per schema).
 *
 * This test ensures correct linkage within the thread: reply comments must
 * reference the correct parent comment, and parent_id is set appropriately as
 * per business and schema constraints. Also confirms that attempts to exceed
 * the maximum allowed nesting level are properly rejected.
 *
 * Test Workflow:
 *
 * 1. Create a BBS post as the seller.
 * 2. Create a parent (level 1) comment for that post (parent_id:null).
 * 3. Reply to this parent comment to create a level 2 comment (parent_id = level 1
 *    comment).
 * 4. Reply again to the level 2 comment to create a level 3 comment (parent_id =
 *    level 2 comment).
 * 5. Attempt to reply to the level 3 comment and confirm an error is thrown
 *    (business rule prevents nesting >3).
 * 6. For each comment, assert parent_id and thread linkage is correct.
 */
export async function test_api_shopping_mall_ai_test_seller_create_reply_bbs_comment_to_existing_comment(
  connection: api.IConnection,
) {
  // 1. Create a BBS post as seller
  const post = await api.functional.shopping_mall_ai.seller.bbsPosts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test Post for Nested Comments",
        body: "This is to test max nesting of BBS comments.",
      } satisfies IShoppingMallAiBbsPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create a parent (level 1/top-level) comment (no parent_id)
  const parentComment =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Parent comment (level 1)",
          // parent_id omitted/null for top-level comment
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(parentComment);
  TestValidator.equals("parentId is null for top-level comment")(
    parentComment.parent_id,
  )(null);
  TestValidator.equals("top-level comment references correct post")(
    parentComment.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 3. Reply to parent (level 2)
  const replyLevel2 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Reply to parent (level 2)",
          parent_id: parentComment.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(replyLevel2);
  TestValidator.equals("level 2 reply parent id")(replyLevel2.parent_id)(
    parentComment.id,
  );
  TestValidator.equals("level 2 reply references correct post")(
    replyLevel2.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 4. Reply to level 2 (level 3)
  const replyLevel3 =
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Reply to level 2 (level 3)",
          parent_id: replyLevel2.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  typia.assert(replyLevel3);
  TestValidator.equals("level 3 reply parent id")(replyLevel3.parent_id)(
    replyLevel2.id,
  );
  TestValidator.equals("level 3 reply references correct post")(
    replyLevel3.shopping_mall_ai_bbs_post_id,
  )(post.id);

  // 5. Try to reply to level 3 (should fail: max depth)
  await TestValidator.error("Cannot nest beyond 3 levels")(async () => {
    await api.functional.shopping_mall_ai.seller.bbsPosts.bbsComments.create(
      connection,
      {
        bbsPostId: post.id,
        body: {
          shopping_mall_ai_bbs_post_id: post.id,
          body: "Reply to level 3 (should fail)",
          parent_id: replyLevel3.id,
        } satisfies IShoppingMallAiBbsComment.ICreate,
      },
    );
  });
}

