 * 4. 서버에서 부여되는 감사 필드(id, consented_at 등) 및 기본 값이 정확히 반영되었는지 검증합니다.
 * 5. Withdrawn_at, deleted_at 등 nullable 필드가 null이거나 undefined인 상태임을 검증합니다.
 */
export async function test_api_shopping_mall_ai_customer_legalConsents_test_create_legal_consent_as_customer_success(
  connection: api.IConnection,
) {
