      "127.0.0.1",
      "192.168.0.1",
      "172.16.1.23",
      null,
    ]),
  };

  // 2. 법적 동의 생성 요청
  const result: IShoppingMallAiLegalConsent =
    await api.functional.shopping_mall_ai.customer.legalConsents.create(
      connection,
      { body: legalConsentInput },
    );
