  TestValidator.error("omitting user_id should fail")(async () => {
    const { user_id, ...rest } = validBody;
    await api.functional.shopping_mall_ai.seller.legalConsents.create(
      connection,
      {
        body: rest as any,
      },
    );
  });

  // 3. 'policy_code' set to null
