    const body = { ...validBody, user_id: null };
    await api.functional.shopping_mall_ai.seller.legalConsents.create(
      connection,
      {
        body: body as any,
      },
    );
  });

  // 5. All required fields set to null (or missing)
  TestValidator.error("all required null should fail")(async () => {
    const nullBody = {
      user_id: null,
      policy_code: null,
      policy_version: null,
      consented_at: null,
      consent_method: null,
    } as any;
    await api.functional.shopping_mall_ai.seller.legalConsents.create(
