import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductCategory";

/**
 * Validate updating editable fields of a shopping mall AI product category as
 * an admin.
 *
 * This test ensures that an admin can successfully update a product category's
 * editable fields: name, parent_id, display_order, and active. It verifies that
 * the update is persisted, that timestamps (created_at, updated_at) reflect
 * changes as expected, and that referential integrity is maintained when
 * setting a parent_id.
 *
 * Test steps:
 *
 * 1. Create two categories (catA, catB):
 *
 *    - CatA will be the main update target.
 *    - CatB is created so catA can be moved under catB by updating parent_id.
 * 2. Update catA:
 *
 *    - Change name to a new random string.
 *    - Set parent_id to catB.id.
 *    - Change display_order to a new value.
 *    - Toggle the active flag.
 * 3. Assert the update response:
 *
 *    - All edited fields reflect updated values.
 *    - Parent_id is set to catB.id.
 *    - Updated_at is newer than original; created_at and id remain unchanged.
 * 4. Optionally, attempt to set parent_id to an invalid UUID and confirm an error
 *    is thrown.
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiProductCategories_test_update_product_category_details_success(
  connection: api.IConnection,
) {
  // Step 1: Create initial category catA (update target)
  const catA =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: RandomGenerator.paragraph()(1),
          display_order: typia.random<number & tags.Type<"int32">>(),
          active: true,
          parent_id: null,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
    );
  typia.assert(catA);

  // Create category catB (to serve as parent)
  const catB =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: RandomGenerator.paragraph()(1),
          display_order: (catA.display_order || 1) + 1, // make sure it's a different order
          active: true,
          parent_id: null,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
    );
  typia.assert(catB);

  // Sleep briefly to ensure updated_at will differ
  await new Promise((resolve) => setTimeout(resolve, 1000));

  // Step 2: Update catA's editable fields
  const updatedName = RandomGenerator.paragraph()(1);
  const updatedDisplayOrder = (catA.display_order || 1) + 2;
  const updatedActive = !catA.active;
  const updateResult =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.update(
      connection,
      {
        shoppingMallAiProductCategoryId: catA.id,
        body: {
          parent_id: catB.id,
          name: updatedName,
          display_order: updatedDisplayOrder,
          active: updatedActive,
        } satisfies IShoppingMallAiProductCategory.IUpdate,
      },
    );
  typia.assert(updateResult);

  // Step 3: Assert all fields updated as expected
  TestValidator.equals("id unchanged")(updateResult.id)(catA.id);
  TestValidator.equals("created_at unchanged")(updateResult.created_at)(
    catA.created_at,
  );
  TestValidator.notEquals("updated_at changed")(updateResult.updated_at)(
    catA.updated_at,
  );
  TestValidator.equals("parent_id set")(updateResult.parent_id)(catB.id);
  TestValidator.equals("name updated")(updateResult.name)(updatedName);
  TestValidator.equals("display_order updated")(updateResult.display_order)(
    updatedDisplayOrder,
  );
  TestValidator.equals("active updated")(updateResult.active)(updatedActive);

  // Optional Step 4: Attempt to set an invalid parent_id and verify error
  const invalidParentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid parent_id must fail")(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.update(
      connection,
      {
        shoppingMallAiProductCategoryId: catA.id,
        body: {
          parent_id: invalidParentId,
        },
      },
    );
  });
}

