 * bundles. Precondition: At least two product bundles must exist in the
 * system.
 *
 * Steps:
 *
 * 1. Create the first product bundle using the admin endpoint.
 * 2. Create the second product bundle using the admin endpoint.
 * 3. Retrieve the product bundle list using the public endpoint.
 * 4. Validate that both created bundles are present in the result data array, and
 *    that pagination structure is included.
 * 5. Validate that all summary fields are correct and match the bundle creation
 *    input.
 * 6. Confirm the output type using typia.assert().
 */
export async function test_api_shopping_mall_ai_test_list_all_product_bundles_success(
  connection: api.IConnection,
) {
  // 1. Create the first product bundle
  const bundleInput1: IShoppingMallAiProductBundle.ICreate = {
    title: `Bundle 1 - ${RandomGenerator.alphabets(6)}`,
    description: `Description for bundle 1 - ${RandomGenerator.paragraph()()}`,
    price: 19900,
    active: true,
  };
  const created1: IShoppingMallAiProductBundle =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      { body: bundleInput1 },
    );
  typia.assert(created1);

  // 2. Create the second product bundle
  const bundleInput2: IShoppingMallAiProductBundle.ICreate = {
    title: `Bundle 2 - ${RandomGenerator.alphabets(6)}`,
    description: `Description for bundle 2 - ${RandomGenerator.paragraph()()}`,
    price: 24900,
    active: true,
  };
  const created2: IShoppingMallAiProductBundle =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductBundles.create(
      connection,
      { body: bundleInput2 },
    );
  typia.assert(created2);

  // 3. Retrieve the bundle list
  const summary: IPageIShoppingMallAiProductBundle.ISummary =
    await api.functional.shopping_mall_ai.shoppingMallAiProductBundles.index(
      connection,
    );
  typia.assert(summary);

  // 4. Assert that both created bundles are present in the output
  const ids = summary.data.map((b) => b.id);
  TestValidator.predicate("created bundle 1 is present")(
    ids.includes(created1.id),
  );
  TestValidator.predicate("created bundle 2 is present")(
    ids.includes(created2.id),
  );
  TestValidator.predicate("at least two bundles exist")(
    summary.data.length >= 2,
  );

  // 5. Validate the summary output fields for both bundles (title, price, active)
  const found1 = summary.data.find((b) => b.id === created1.id);
  const found2 = summary.data.find((b) => b.id === created2.id);
  if (found1) {
    TestValidator.equals("bundle 1 title")(found1.title)(bundleInput1.title);
    TestValidator.equals("bundle 1 price")(found1.price)(bundleInput1.price);
    TestValidator.equals("bundle 1 active")(found1.active)(bundleInput1.active);
  }
  if (found2) {
    TestValidator.equals("bundle 2 title")(found2.title)(bundleInput2.title);
    TestValidator.equals("bundle 2 price")(found2.price)(bundleInput2.price);
    TestValidator.equals("bundle 2 active")(found2.active)(bundleInput2.active);
  }

  // 6. Validate pagination is present
  TestValidator.predicate("pagination structure")(
    typeof summary.pagination.current === "number",
  );
  TestValidator.predicate("pagination structure")(
    typeof summary.pagination.limit === "number",
  );
  TestValidator.predicate("pagination structure")(
    typeof summary.pagination.records === "number",
  );
  TestValidator.predicate("pagination structure")(
    typeof summary.pagination.pages === "number",
  );
}

