import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IShoppingMallAiMediaAsset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiMediaAsset";

/**
 * Validate that admin can update allowed metadata fields of a media asset.
 *
 * This test ensures that an admin can update fields such as asset_type,
 * asset_uri, width, and height on an existing media asset. It covers the entire
 * workflow:
 *
 * 1. Create a base file metadata record (file registration)
 * 2. Register a new media asset record referencing this file
 * 3. Update valid asset fields with new values via the update API
 * 4. Confirm the API response reflects the update (fields changed as intended)
 * 5. Confirm that the created_at (or an audit field) remains valid after the
 *    update
 *
 * If the API exposed an updated_at or audit log field, we would check that it
 * changes on update, but since only created_at is available, we confirm it
 * remains a valid ISO string post-update.
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiMediaAssets_test_update_media_asset_metadata_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Register a base file
  const fileCreateInput: IShoppingMallAiFile.ICreate = {
    original_name: "sample-image.png",
    uri: "https://cdn.example.com/image/sample-image.png",
    extension: "png",
    mime_type: "image/png",
    size: 512000,
    hash: RandomGenerator.alphaNumeric(64),
    actor_type: "admin",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      { body: fileCreateInput },
    );
  typia.assert(file);

  // 2. Register a media asset referencing the new file
  const assetCreateInput: IShoppingMallAiMediaAsset.ICreate = {
    shopping_mall_ai_file_id: file.id,
    asset_type: "thumb",
    asset_uri: "https://cdn.example.com/image/thumb-sample-image.png",
    width: 200,
    height: 150,
    duration: null,
  };
  const asset =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.create(
      connection,
      { body: assetCreateInput },
    );
  typia.assert(asset);

  // 3. Update the asset's type, URI, and dimensions
  const updateInput: IShoppingMallAiMediaAsset.IUpdate = {
    asset_type: "preview",
    asset_uri: "https://cdn.example.com/image/preview-sample-image.png",
    width: 400,
    height: 400,
    duration: null,
  };
  const updated =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.update(
      connection,
      {
        shoppingMallAiMediaAssetId: asset.id,
        body: updateInput,
      },
    );
  typia.assert(updated);

  // 4. Assert updated fields reflect changes
  TestValidator.equals("asset_type updated")(updated.asset_type)("preview");
  TestValidator.equals("asset_uri updated")(updated.asset_uri)(
    "https://cdn.example.com/image/preview-sample-image.png",
  );
  TestValidator.equals("width updated")(updated.width)(400);
  TestValidator.equals("height updated")(updated.height)(400);

  // 5. Confirm that audit/created_at remains valid
  TestValidator.predicate("created_at remains valid ISO")(
    !isNaN(Date.parse(updated.created_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
