import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IShoppingMallAiMediaAsset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiMediaAsset";

/**
 * Validate rejection of invalid field values when updating a media asset
 * variant.
 *
 * This test ensures that the update endpoint for media assets ( PUT
 * /shopping-mall-ai/admin/shoppingMallAiMediaAssets/{shoppingMallAiMediaAssetId}
 * ) delivers proper validation error responses and does not alter the existing
 * asset when provided with clearly invalid data, such as negative dimensions, a
 * malformed asset_uri, or asset_type strings outside expected domain enums.
 *
 * Step-by-step process:
 *
 * 1. Create a valid file object to use for asset parent using the file
 *    registration endpoint.
 * 2. Create a valid initial media asset via the media asset creation endpoint.
 * 3. Attempt to update this asset with several types of invalid IUpdate inputs,
 *    e.g.:
 *
 *    - Negative width/height/duration
 *    - Clearly malformed asset_uri (not a URI or missing scheme, e.g. 'not-a-uri')
 *    - Garbage/unsupported asset_type (e.g., empty string, strange symbols)
 * 4. For each invalid attempt:
 *
 *    - Confirm that an error (validation error, HTTP 400/422, or similar) is thrown
 *    - (Re-fetch to verify unchanged asset is skipped, as no single-get endpoint is
 *         exposed)
 *
 * Only fields in the official DTO schema are used.
 */
export async function test_api_shopping_mall_ai_media_assets_test_update_media_asset_with_invalid_field_values(
  connection: api.IConnection,
) {
  // 1. Create a valid file for asset registration
  const validFile =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      {
        body: {
          original_name: "some_image.png",
          uri: "https://cdn.example.com/media/some_image.png",
          extension: "png",
          mime_type: "image/png",
          size: 102400,
          hash: "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824",
        },
      },
    );
  typia.assert(validFile);

  // 2. Register a valid media asset
  const validAsset =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: validFile.id,
          asset_type: "thumb",
          asset_uri: "https://cdn.example.com/media/thumb_some_image.png",
          width: 256,
          height: 256,
          duration: null, // not relevant for images
        },
      },
    );
  typia.assert(validAsset);

  // 3. Test invalid updates
  const invalidUpdates = [
    // Negative width
    { width: -10 },
    // Negative height
    { height: -5 },
    // Negative duration
    { duration: -1 },
    // Malformed asset_uri
    { asset_uri: "not-a-uri" },
    // Empty asset_type
    { asset_type: "" },
    // Strange asset_type
    { asset_type: "@@@###$$$" },
  ];

  for (const patch of invalidUpdates) {
    await TestValidator.error(
      "invalid field values result in validation or business error",
    )(async () => {
      await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.update(
        connection,
        {
          shoppingMallAiMediaAssetId: validAsset.id,
          body: patch,
        },
      );
    });
    // No re-fetch/asset integrity check, as no endpoint for GET by ID is exposed
  }
}

