import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IShoppingMallAiMediaAsset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiMediaAsset";
import type { IPageIShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFileAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAttachment";

/**
 * Validates retrieval of all file attachments with admin permissions.
 *
 * This test ensures that admin access returns a paginated list of all file
 * attachment records in the platform. The flow is as follows:
 *
 * 1. Register a base AI file.
 * 2. Register a derivative media asset linked to the file.
 * 3. Create two file attachment records: a) One referencing the base file (only
 *    shopping_mall_ai_file_id set). b) One referencing the media asset variant
 *    (only shopping_mall_ai_media_asset_id set).
 * 4. Call the GET endpoint to list all attachments.
 * 5. Verify that both new attachments are present in the result, with correct
 *    linkage IDs, target_type/id, and timestamp metadata.
 * 6. For each returned attachment, check referential links: appropriate file ID or
 *    media asset ID is populated and matches what was created.
 * 7. Pagination/data structure is validated and at least the created entries
 *    exist.
 */
export async function test_api_shopping_mall_ai_test_list_all_file_attachments_with_admin_access(
  connection: api.IConnection,
) {
  // 1. Register a file (base file for attachment)
  const fileCreate = {
    original_name: RandomGenerator.alphaNumeric(10) + ".jpg",
    uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(20)}.jpg`,
    extension: "jpg",
    mime_type: "image/jpeg",
    size: typia.random<number & tags.Type<"int32">>(),
    hash: RandomGenerator.alphaNumeric(64),
    actor_type: "admin",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallAiFile.ICreate;
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      { body: fileCreate },
    );
  typia.assert(file);

  // 2. Register a media asset (e.g., thumbnail variant)
  const mediaAssetCreate = {
    shopping_mall_ai_file_id: file.id,
    asset_type: "thumb",
    asset_uri: `https://cdn.example.com/assets/${RandomGenerator.alphaNumeric(20)}.jpg`,
    width: 100,
    height: 100,
    duration: null,
  } satisfies IShoppingMallAiMediaAsset.ICreate;
  const mediaAsset =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiMediaAssets.create(
      connection,
      { body: mediaAssetCreate },
    );
  typia.assert(mediaAsset);

  // 3. Create file attachment linked to base file
  const attachmentBase =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          shopping_mall_ai_media_asset_id: null,
          target_type: "product",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          attached_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(attachmentBase);

  // 4. Create file attachment linked to the media asset
  const attachmentMediaAsset =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: null,
          shopping_mall_ai_media_asset_id: mediaAsset.id,
          target_type: "review",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          attached_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAttachment.ICreate,
      },
    );
  typia.assert(attachmentMediaAsset);

  // 5. Retrieve all attachments
  const list =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.index(
      connection,
    );
  typia.assert(list);
  TestValidator.predicate("returns paginated structure")(
    !!list.pagination && Array.isArray(list.data),
  );

  // 6. Validate two recently created attachments exist and correct refs
  const foundBase = list.data.find((a) => a.id === attachmentBase.id);
  const foundMedia = list.data.find((a) => a.id === attachmentMediaAsset.id);
  TestValidator.predicate("base file attachment found")(!!foundBase);
  TestValidator.predicate("media asset attachment found")(!!foundMedia);
  if (foundBase) {
    TestValidator.equals("linked to file ID")(
      foundBase.shopping_mall_ai_file_id,
    )(file.id);
    TestValidator.equals("media asset null")(
      foundBase.shopping_mall_ai_media_asset_id,
    )(null);
    TestValidator.equals("target type")(foundBase.target_type)("product");
    TestValidator.equals("target id")(foundBase.target_id)(
      attachmentBase.target_id,
    );
  }
  if (foundMedia) {
    TestValidator.equals("linked to media asset ID")(
      foundMedia.shopping_mall_ai_media_asset_id,
    )(mediaAsset.id);
    TestValidator.equals("file attachment null")(
      foundMedia.shopping_mall_ai_file_id,
    )(null);
    TestValidator.equals("target type")(foundMedia.target_type)("review");
    TestValidator.equals("target id")(foundMedia.target_id)(
      attachmentMediaAsset.target_id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IPageIShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFileAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAttachment";

/**
 * Validates that the file attachment listing endpoint enforces pagination and
 * accurately limits results.
 *
 * This test creates enough base files and file attachment records to exceed a
 * typical page size (e.g., 25 > 20). It then lists attachments via the admin
 * endpoint, verifies that the returned data respects pagination shape and
 * limits (per schema), and checks that record counts and metadata match the
 * number of attachments created. Randomized type-safe data is used for all
 * DTOs. Edge cases are addressed as far as allowed by the API (which does not
 * accept explicit page/limit parameters).
 *
 * Steps:
 *
 * 1. Register 5 new file metadata base records for use in attachment creation.
 * 2. Create 25 file attachment records, each linked to one random base file.
 * 3. List the attachments. Assert that the returned page structure and data count
 *    do not exceed per-page limits, and that the reported total count matches
 *    the number created.
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiFileAttachments_test_list_file_attachments_with_pagination(
  connection: api.IConnection,
) {
  // 1. Register several file base records for attaching
  const numFiles = 5;
  const files = await ArrayUtil.asyncRepeat(numFiles)(async () => {
    const file =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
        connection,
        {
          body: {
            original_name: RandomGenerator.paragraph()(),
            uri: RandomGenerator.alphaNumeric(24),
            extension: RandomGenerator.pick(["jpg", "png", "pdf", "txt"]),
            mime_type: RandomGenerator.pick([
              "image/jpeg",
              "image/png",
              "application/pdf",
              "text/plain",
            ]),
            size: typia.random<number & tags.Type<"int32">>(),
            hash: RandomGenerator.alphaNumeric(32),
            actor_type: "admin",
            actor_id: null,
          } satisfies IShoppingMallAiFile.ICreate,
        },
      );
    typia.assert(file);
    return file;
  });

  // 2. Create > default page count file attachments (e.g. 25, if default is 20)
  const totalAttachments = 25;
  const now = new Date();
  const attachments = await ArrayUtil.asyncRepeat(totalAttachments)(
    async (i) => {
      const file = RandomGenerator.pick(files);
      const attach =
        await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.create(
          connection,
          {
            body: {
              shopping_mall_ai_file_id: file.id,
              shopping_mall_ai_media_asset_id: null,
              target_type: RandomGenerator.pick([
                "product",
                "review",
                "bbs_post",
                "order",
              ]),
              target_id: typia.random<string & tags.Format<"uuid">>(),
              attached_at: new Date(now.getTime() + i * 1000).toISOString(),
            } satisfies IShoppingMallAiFileAttachment.ICreate,
          },
        );
      typia.assert(attach);
      return attach;
    },
  );

  // 3. List the attachments and verify pagination shape and record counts
  const result =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAttachments.index(
      connection,
    );
  typia.assert(result);

  // Assert basic page structure
  TestValidator.predicate("paged result IPage structure")(
    !!result.pagination && Array.isArray(result.data),
  );
  // Assert total count matches
  TestValidator.equals("attachment record count matches")(
    result.pagination.records,
  )(attachments.length);
  // Assert returned results do not exceed limit per page (if schema default is 20, verify so)
  TestValidator.predicate("records per page <= page limit")(
    result.data.length <= result.pagination.limit,
  );
}

