import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";
import type { IPageIShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCartSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Comprehensive admin cart session search/filter test (dashboard E2E).
 *
 * Validates that the cart session search endpoint allows admin users to perform
 * advanced filtered queries using session_token substrings, cart ID, and
 * pagination parameters. All filters are asserted to only return correct
 * matches, with edge-case handling for empty results and pagination.
 *
 * Critical security is validated by attempting access with a non-admin
 * connection and expecting an error (RBAC enforced).
 *
 * Steps:
 *
 * 1. Seed distinct cart sessions (admin auth)
 * 2. Search by session_token substring (assert only matching records returned)
 * 3. Search by cart ID (all results match cartId)
 * 4. Paginated search (respect page/limit)
 * 5. Edge: Search for non-existent session_token returns 0 results
 * 6. RBAC check: Non-admin connection denied
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_test_search_cart_sessions_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Seed the database with several distinct cart sessions
  const cartSessions = await ArrayUtil.asyncRepeat(5)(async () => {
    const input = {
      shopping_mall_ai_cart_id: typia.random<string & tags.Format<"uuid">>(),
      session_token: RandomGenerator.alphaNumeric(12),
      created_at: new Date().toISOString(),
      last_active_at: new Date(
        Date.now() +
          typia.random<
            number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<60000>
          >() *
            1000,
      ).toISOString(),
    } satisfies IShoppingMallAiCartSession.ICreate;
    const created =
      await api.functional.shopping_mall_ai.admin.cartSessions.create(
        connection,
        { body: input },
      );
    typia.assert(created);
    return created;
  });

  // 2. Search by session_token substring
  const partialToken = cartSessions[0].session_token.substring(0, 6);
  const resByToken =
    await api.functional.shopping_mall_ai.admin.cartSessions.search(
      connection,
      {
        body: {
          session_token: partialToken,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resByToken);
  TestValidator.predicate(
    "every returned session_token includes the substring",
  )(resByToken.data.every((row) => row.session_token.includes(partialToken)));

  // 3. Search by cart ID
  const cartId = cartSessions[1].shopping_mall_ai_cart_id;
  const resByCartId =
    await api.functional.shopping_mall_ai.admin.cartSessions.search(
      connection,
      {
        body: {
          shopping_mall_ai_cart_id: cartId,
          page: 1,
          limit: 5,
        },
      },
    );
  typia.assert(resByCartId);
  TestValidator.predicate("all returned records have cartId")(
    resByCartId.data.every((row) => row.shopping_mall_ai_cart_id === cartId),
  );

  // 4. Paginated filter (limit check)
  const pagedRes =
    await api.functional.shopping_mall_ai.admin.cartSessions.search(
      connection,
      {
        body: { page: 1, limit: 2 },
      },
    );
  typia.assert(pagedRes);
  TestValidator.predicate("limit respected on paged results")(
    pagedRes.data.length <= 2,
  );

  // 5. Edge: Search for non-existent session_token (should return empty)
  const noneRes =
    await api.functional.shopping_mall_ai.admin.cartSessions.search(
      connection,
      {
        body: { session_token: "UNMATCHED_TOKEN" },
      },
    );
  typia.assert(noneRes);
  TestValidator.equals("no search result")(noneRes.data.length)(0);

  // 6. RBAC check: Non-admin connection gets permission error
  const nonAdminConn = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: "forbidden-or-insufficient",
    },
  };
  await TestValidator.error("non-admin search forbidden")(async () => {
    await api.functional.shopping_mall_ai.admin.cartSessions.search(
      nonAdminConn,
      {
        body: { page: 1, limit: 1 },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";

/**
 * Validates admin retrieval of a cart session by its unique ID (success) and
 * proper 404/error handling (not found) for invalid or deleted IDs.
 *
 * Business Context:
 *
 * - Verifies that administration staff can retrieve full atomic cart session
 *   entity by session ID for audit/root-cause analysis.
 * - Ensures RBAC/privacy: No session data is returned on not found, and no
 *   private info is leaked in error.
 * - End-to-end, starting from creation to retrieval, to error scenario.
 *
 * Steps:
 *
 * 1. Create a cart session (to get a valid cartSessionId)
 * 2. Fetch session by valid cartSessionId (success: validate all fields)
 * 3. Attempt fetch by random (non-existent) cartSessionId (expect 404/error, no
 *    data leakage)
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_test_get_cart_session_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a cart session to get a valid ID
  const cartSessionCreate: IShoppingMallAiCartSession.ICreate = {
    shopping_mall_ai_cart_id: typia.random<string & tags.Format<"uuid">>(),
    session_token: RandomGenerator.alphaNumeric(24),
    created_at: new Date().toISOString(),
    last_active_at: new Date().toISOString(),
  };
  const session: IShoppingMallAiCartSession =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      { body: cartSessionCreate },
    );
  typia.assert(session);

  // 2. Fetch by valid cartSessionId and check all properties
  const fetched: IShoppingMallAiCartSession =
    await api.functional.shopping_mall_ai.admin.cartSessions.at(connection, {
      cartSessionId: session.id,
    });
  typia.assert(fetched);
  TestValidator.equals("shopping_mall_ai_cart_id")(
    fetched.shopping_mall_ai_cart_id,
  )(cartSessionCreate.shopping_mall_ai_cart_id);
  TestValidator.equals("session_token")(fetched.session_token)(
    cartSessionCreate.session_token,
  );
  TestValidator.equals("created_at")(fetched.created_at)(
    cartSessionCreate.created_at,
  );
  TestValidator.equals("last_active_at")(fetched.last_active_at)(
    cartSessionCreate.last_active_at,
  );

  // 3. Attempt fetch with a random, non-existent cartSessionId (should throw – not found and no data leakage)
  await TestValidator.error(
    "fetching non-existent cartSessionId triggers error",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.cartSessions.at(connection, {
      cartSessionId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";

/**
 * Test creation of a new cart session with unique and duplicate token
 * scenarios.
 *
 * Business Context: This function tests the backend admin workflow for atomic
 * creation of a shopping cart session record, critical for device/guest-to-cart
 * binding, cross-device cart recovery, and analytics. The test verifies both a
 * successful creation path (with a unique session token) and expected conflict
 * handling (duplicate session token).
 *
 * Step-by-step process:
 *
 * 1. Create a new cart session with all required fields and a unique
 *    session_token.
 *
 *    - Assert the response contains all the required fields and is properly
 *         structured.
 *    - Validate that session_token is echoed and is unique.
 * 2. Attempt to create another cart session with the exact same session_token (and
 *    same cart ID).
 *
 *    - Confirm that the response fails by enforcing the unique constraint at the DB
 *         level.
 *
 * This test ensures backend safeguards for unique session_token enforcement at
 * DB level, guaranteeing one-to-one mapping between cart session token and
 * session record.
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_create(
  connection: api.IConnection,
) {
  // 1. Create a new cart session with unique values
  const cartId: string = typia.random<string & tags.Format<"uuid">>();
  const sessionToken: string = RandomGenerator.alphaNumeric(32);
  const timestamp: string = new Date().toISOString();

  const createInput: IShoppingMallAiCartSession.ICreate = {
    shopping_mall_ai_cart_id: cartId,
    session_token: sessionToken,
    created_at: timestamp,
    last_active_at: timestamp,
  };

  const created: IShoppingMallAiCartSession =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: createInput,
      },
    );
  typia.assert(created);

  // Assert the database echoes input fields correctly
  TestValidator.equals("shopping_mall_ai_cart_id")(
    created.shopping_mall_ai_cart_id,
  )(cartId);
  TestValidator.equals("session_token")(created.session_token)(sessionToken);

  // 2. Attempt to create another session with the same session_token (should fail)
  TestValidator.error("duplicate session_token should fail")(async () => {
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: createInput,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";

/**
 * Validate updating cart session attributes via admin endpoint.
 *
 * This test verifies that an admin can update the mutable fields of a cart
 * session (session_token, shopping_mall_ai_cart_id, last_active_at) and that
 * all changes persist correctly. It also ensures that:
 *
 * - Attempting to update session_token to a value that is already used by another
 *   session fails (enforces uniqueness constraint).
 * - Attempting to change shopping_mall_ai_cart_id to a non-existent cart ID fails
 *   validation.
 * - (If possible) Only admin can update cart sessions; attempts by non-admin
 *   users should be forbidden.
 *
 * Steps:
 *
 * 1. Create a valid cart session (dependency used for all updates).
 * 2. Update session_token to a new unique value and verify persistence.
 * 3. Update last_active_at to a new value and verify persistence.
 * 4. Create a second session to check token conflict.
 * 5. Attempt to update the original session's token to the second session's token
 *    (expect error).
 * 6. Attempt to update cart_id to a random UUID (likely non-existent, expect
 *    error).
 * 7. RBAC check: Skipped (only admin endpoints are available).
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_test_update_cart_session_with_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create an initial valid cart session for updates
  const cartId1 = typia.random<string & tags.Format<"uuid">>();
  const sessionToken1 = RandomGenerator.alphaNumeric(20);
  const now = new Date();
  const session1 =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: {
          shopping_mall_ai_cart_id: cartId1,
          session_token: sessionToken1,
          created_at: now.toISOString(),
          last_active_at: now.toISOString(),
        } satisfies IShoppingMallAiCartSession.ICreate,
      },
    );
  typia.assert(session1);

  // 2. Update session_token to a new unique value and verify persistence
  const newSessionToken = RandomGenerator.alphaNumeric(20);
  const updatedSession1 =
    await api.functional.shopping_mall_ai.admin.cartSessions.update(
      connection,
      {
        cartSessionId: session1.id,
        body: {
          session_token: newSessionToken,
        } satisfies IShoppingMallAiCartSession.IUpdate,
      },
    );
  typia.assert(updatedSession1);
  TestValidator.equals("session_token updated")(updatedSession1.session_token)(
    newSessionToken,
  );

  // 3. Update last_active_at to a new timestamp and verify persistence
  const newLastActive = new Date(now.getTime() + 60_000).toISOString();
  const updatedSession2 =
    await api.functional.shopping_mall_ai.admin.cartSessions.update(
      connection,
      {
        cartSessionId: session1.id,
        body: {
          last_active_at: newLastActive,
        } satisfies IShoppingMallAiCartSession.IUpdate,
      },
    );
  typia.assert(updatedSession2);
  TestValidator.equals("last_active_at updated")(
    updatedSession2.last_active_at,
  )(newLastActive);

  // 4. Create a second cart session for uniqueness checks
  const cartId2 = typia.random<string & tags.Format<"uuid">>();
  const sessionToken2 = RandomGenerator.alphaNumeric(20);
  const session2 =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: {
          shopping_mall_ai_cart_id: cartId2,
          session_token: sessionToken2,
          created_at: now.toISOString(),
          last_active_at: now.toISOString(),
        } satisfies IShoppingMallAiCartSession.ICreate,
      },
    );
  typia.assert(session2);

  // 5. Attempt to update session1's token to session2's token (expect uniqueness error)
  await TestValidator.error("duplicate session_token should fail")(async () => {
    await api.functional.shopping_mall_ai.admin.cartSessions.update(
      connection,
      {
        cartSessionId: session1.id,
        body: {
          session_token: session2.session_token,
        } satisfies IShoppingMallAiCartSession.IUpdate,
      },
    );
  });

  // 6. Attempt to update cart_id to a random (presumably non-existent) UUID (expect error)
  await TestValidator.error("invalid shopping_mall_ai_cart_id fails")(
    async () => {
      await api.functional.shopping_mall_ai.admin.cartSessions.update(
        connection,
        {
          cartSessionId: session1.id,
          body: {
            shopping_mall_ai_cart_id: typia.random<
              string & tags.Format<"uuid">
            >(),
          } satisfies IShoppingMallAiCartSession.IUpdate,
        },
      );
    },
  );

  // 7. RBAC: Only admin endpoint exists, unable to test non-admin user restrictions.
}

