 * 4. 삭제 후 별도 조회/검증 API 부재로 추가 데이터 검증 불가. 감사 로그 등은 E2E 영역 밖.
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_test_delete_cart_session_by_id_and_handle_already_deleted(
