import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";
import type { IPageIShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the admin's ability to search/filter cart items within a specific
 * cart using complex criteria.
 *
 * This test ensures that:
 *
 * - Only items from the specified cart are returned when searching.
 * - Advanced filtering (by product ID, option ID, date ranges) works correctly.
 * - Pagination and multi-page results are handled correctly for carts with many
 *   items.
 *
 * Test Steps:
 *
 * 1. Create a new customer cart (dependency).
 * 2. Insert several items with a wide variety of product IDs, options, quantities,
 *    and controlled add/update timestamps into the cart (dependency), so that
 *    filters can be meaningfully tested.
 * 3. Search by product ID and expect only the matching cart items of that product
 *    for that cart.
 * 4. Search by product option ID to confirm filtering correctly isolates items
 *    with that option.
 * 5. Search by date range (added_at, updated_at) and verify only correct results
 *    appear in the window.
 * 6. Search by combinations of filters.
 * 7. Test pagination: request results with low limit (e.g., limit=2) and verify
 *    total records/pages and page slicing.
 * 8. Ensure that items from a different cart are excluded from result set.
 */
export async function test_api_shopping_mall_ai_admin_carts_cartItems_test_admin_search_cart_items_with_complex_filters(
  connection: api.IConnection,
) {
  // 1. Create the primary customer cart
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cart);

  // 2. Generate some test product and option IDs for diverse items
  const productIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const optionIds = [
    typia.random<string & tags.Format<"uuid">>(),
    undefined,
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // 3. Insert cart items with different productIDs, optionIDs, timestamps
  const now = new Date();
  const dateA = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString();
  const dateB = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 1).toISOString();
  const dateC = now.toISOString();

  const items = [
    // 1st item
    await api.functional.shopping_mall_ai.admin.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productIds[0],
          shopping_mall_ai_product_option_id: optionIds[0],
          quantity: 1,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    ),
    // 2nd item, different product, no option
    await api.functional.shopping_mall_ai.admin.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productIds[1],
          quantity: 2,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    ),
    // 3rd item, same product as 1st but different option
    await api.functional.shopping_mall_ai.admin.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productIds[0],
          shopping_mall_ai_product_option_id: optionIds[2],
          quantity: 5,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    ),
  ];
  items.forEach((x) => typia.assert(x));

  // 4. Insert unrelated items in another cart to verify filtering by cartId
  const otherCart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  await api.functional.shopping_mall_ai.admin.carts.cartItems.create(
    connection,
    {
      cartId: otherCart.id,
      body: {
        shopping_mall_ai_cart_id: otherCart.id,
        shopping_mall_ai_product_id: productIds[2],
        shopping_mall_ai_product_option_id: optionIds[2],
        quantity: 3,
      } satisfies IShoppingMallAiCartItem.ICreate,
    },
  );

  // 5. Filter by productId: should find only items from this cart with that productId
  const resultProduct =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_product_id: productIds[0],
        },
      },
    );
  typia.assert(resultProduct);
  TestValidator.predicate("only items of product 0 in current cart")(
    resultProduct.data.every(
      (x) =>
        x.shopping_mall_ai_cart_id === cart.id &&
        x.shopping_mall_ai_product_id === productIds[0],
    ),
  );

  // 6. Filter by optionId: should only find items with that SKU in cart
  if (optionIds[0] !== undefined) {
    const resultOption =
      await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
        connection,
        {
          cartId: cart.id,
          body: {
            shopping_mall_ai_product_option_id: optionIds[0],
          },
        },
      );
    typia.assert(resultOption);
    TestValidator.predicate("only items with optionId[0] in current cart")(
      resultOption.data.every(
        (x) =>
          x.shopping_mall_ai_cart_id === cart.id &&
          x.shopping_mall_ai_product_option_id === optionIds[0],
      ),
    );
  }

  // 7. Filter by date ranges
  // (assuming at least some items have different added_at/updated_at spread across the stub API)
  const resultByDate =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {
          added_at_from: dateB,
        },
      },
    );
  typia.assert(resultByDate);
  TestValidator.predicate("added_at_from filters by date correctly")(
    resultByDate.data.every(
      (x) => x.shopping_mall_ai_cart_id === cart.id && x.added_at >= dateB,
    ),
  );

  // 8. Test pagination: limit 2
  const resultPage1 =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {
          page: 1,
          limit: 2,
        },
      },
    );
  typia.assert(resultPage1);
  TestValidator.equals("pagination.page=1")(resultPage1.pagination.current)(1);
  TestValidator.equals("pagination.limit=2")(resultPage1.pagination.limit)(2);
  TestValidator.predicate("one page only includes at most 'limit' items")(
    resultPage1.data.length <= 2,
  );
  if (resultPage1.pagination.pages > 1) {
    const resultPage2 =
      await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
        connection,
        {
          cartId: cart.id,
          body: { page: 2, limit: 2 },
        },
      );
    typia.assert(resultPage2);
    TestValidator.equals("pagination.page=2")(resultPage2.pagination.current)(
      2,
    );
    TestValidator.equals("pagination.limit=2")(resultPage2.pagination.limit)(2);
  }

  // 9. Ensure that items from other cart are not present
  const resultsAll =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.search(
      connection,
      {
        cartId: cart.id,
        body: {},
      },
    );
  typia.assert(resultsAll);
  TestValidator.predicate("all items belong to this cart only")(
    resultsAll.data.every((x) => x.shopping_mall_ai_cart_id === cart.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
