/**
 * Test the system's enforcement of cart ownership and privacy by ensuring that
 * searching for cart items with an invalid or unauthorized cartId triggers an
 * error (404 Not Found or permission denied).
 *
 * Business context:
 *
 * - Cart access must be limited to rightful owners or admins, preventing
 *   unauthorized or cross-user access even at admin endpoints.
 * - This test ensures that direct querying with an arbitrary or
 *   legitimate-but-unrelated cartId is handled securely and errors are surfaced
 *   as intended.
 *
 * Steps:
 *
 * 1. Create a new cart as a normal customer, so this cart is owned by the
 *    customer, not the admin.
 * 2. Attempt to search cart items for that cartId via the admin endpoint without
 *    any special ownership linkage.
 * 3. Confirm that the API returns an appropriate error (404 or permission denied)
 *    rather than allowing access.
 * 4. Attempt to search cart items with a truly invalid (random, non-existent)
 *    cartId and also confirm an error is returned.
 */
export async function test_api_shopping_mall_ai_test_admin_search_cart_items_invalid_cartid_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Create a new cart as a normal customer
  const customerCart =
    await api.functional.shopping_mall_ai.customer.carts.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    });
  typia.assert(customerCart);

  // 2. Try searching cart items from the admin endpoint with this customer-owned cartId
  await TestValidator.error("admin cannot access unrelated customer cart")(() =>
    api.functional.shopping_mall_ai.admin.carts.cartItems.search(connection, {
      cartId: customerCart.id,
      body: {}, // Use empty filter for simplicity
    }),
  );

  // 3. Try searching with a random, guaranteed-nonexistent cartId
  await TestValidator.error("admin receives not found for non-existent cartId")(
    () =>
      api.functional.shopping_mall_ai.admin.carts.cartItems.search(connection, {
        cartId: typia.random<string & tags.Format<"uuid">>(),
        body: {},
      }),
  );
}

