/**
 * 고객이 자신의 장바구니 내 특정 장바구니 아이템 상세를 정상적으로 조회할 수 있는지 검증합니다.
 *
 * 이 테스트는 다음의 일반적인 사용자 플로우를 모사합니다:
 *
 * 1. 고객이 새로운 장바구니를 생성합니다 (guest 또는 회원 시나리오 둘 다 지원)
 * 2. 생성된 장바구니에 상품을 하나 추가합니다 (상품, 옵션, 수량 랜덤 보장)
 * 3. 추가한 cartItemId 기반으로 상세조회 API를 호출해 cart 아이템 정보를 가져옵니다
 * 4. 반환받은 cart item의 주요 필드(cartId, cartItemId, productId, optionId, quantity,
 *    added_at, updated_at 등)가 모두 정확히 반환/연결되는지 검증합니다
 *
 * 본 시나리오는 고객의 장바구니 점검 혹은 최종 결제 전 검증 절차의 일부로서, 정상적인 cart detail confirm 플로우임을
 * 보장합니다.
 */
export async function test_api_shopping_mall_ai_test_get_cart_item_details_valid_for_cart_owner(
  connection: api.IConnection,
) {
  // 1. 고객용 장바구니 생성
  const cartInput: IShoppingMallAiCart.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
    // 필요시 shopping_mall_ai_customer_id 등 확장 가능
  };
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    { body: cartInput },
  );
  typia.assert(cart);

  // 2. cart에 상품 아이템 1건 추가
  const cartItemInput: IShoppingMallAiCartItem.ICreate = {
    shopping_mall_ai_cart_id: cart.id,
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    // 옵션 없는 베이직 시나리오 (option id null)
    shopping_mall_ai_product_option_id: null,
    quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
  };
  const cartItem =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: cartItemInput,
      },
    );
  typia.assert(cartItem);

  // 3. cartItems 상세 조회
  const item =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.at(
      connection,
      {
        cartId: cart.id,
        cartItemId: cartItem.id,
      },
    );
