  // 4. 주요 필드 검증 (정확한 일치)
  TestValidator.equals("cartId 일치")(item.shopping_mall_ai_cart_id)(cart.id);
  TestValidator.equals("cartItemId 일치")(item.id)(cartItem.id);
  TestValidator.equals("productId 일치")(item.shopping_mall_ai_product_id)(
    cartItem.shopping_mall_ai_product_id,
  );
  TestValidator.equals("optionId 일치")(
    item.shopping_mall_ai_product_option_id,
  )(cartItem.shopping_mall_ai_product_option_id);
  TestValidator.equals("수량 일치")(item.quantity)(cartItem.quantity);
  TestValidator.predicate("added_at 존재")(!!item.added_at);
  TestValidator.predicate("updated_at 존재")(!!item.updated_at);
}

