  TestValidator.error("non-existent cartItemId")(() =>
    api.functional.shopping_mall_ai.customer.carts.cartItems.at(connection, {
      cartId: cart.id,
      cartItemId: typia.random<string & tags.Format<"uuid">>(), // bogus, not in cart
    }),
  );

  // 3. Attempt to access with completely random/non-existent cartId and cartItemId
  TestValidator.error("bogus cartId and cartItemId")(() =>
    api.functional.shopping_mall_ai.customer.carts.cartItems.at(connection, {
      cartId: typia.random<string & tags.Format<"uuid">>(),
      cartItemId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. (Omitted): Cross-cart positive/negative scenarios cannot be performed as there is no cart item creation/list API.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
