import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validates that an admin can retrieve detailed information for any cart item
 * in any cart.
 *
 * Business context: An admin needs to be able to look up individual cart items
 * for compliance, support, or audit purposes, even if they are not the cart
 * owner. This scenario simulates the end-to-end workflow: a customer creates a
 * cart, adds a cart item, and then an admin fetches that item by its composite
 * (cartId, cartItemId) key. The test ensures that all fields expected for
 * admin-level visibility are returned and match original insertion data.
 *
 * Steps:
 *
 * 1. A customer creates a cart (with required channel and section context)
 * 2. The customer adds one item to the cart, specifying a product, (optionally) a
 *    product option, and a valid quantity
 * 3. The admin retrieves this cart item using its cartId and cartItemId
 * 4. The test asserts that all cart item fields match inserted values and that
 *    audit fields are present
 */
export async function test_api_shopping_mall_ai_test_admin_get_cart_item_details_for_any_cart(
  connection: api.IConnection,
) {
  // 1. Customer creates a cart
  const cartInput: IShoppingMallAiCart.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    { body: cartInput },
  );
  typia.assert(cart);

  // 2. Customer adds a cart item
  const cartItemInput: IShoppingMallAiCartItem.ICreate = {
    shopping_mall_ai_cart_id: cart.id,
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 2,
  };
  const createdItem =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      { cartId: cart.id, body: cartItemInput },
    );
  typia.assert(createdItem);

  // 3. Admin retrieves the cart item using GET /shopping-mall-ai/admin/carts/{cartId}/cartItems/{cartItemId}
  const adminItem =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.at(connection, {
      cartId: cart.id,
      cartItemId: createdItem.id,
    });
  typia.assert(adminItem);

  // 4. Verify all fields are present and match (except audit fields, which should just be present and valid)
  TestValidator.equals("cart ID matches")(adminItem.shopping_mall_ai_cart_id)(
    cart.id,
  );
  TestValidator.equals("product ID matches")(
    adminItem.shopping_mall_ai_product_id,
  )(cartItemInput.shopping_mall_ai_product_id);
  TestValidator.equals("quantity matches")(adminItem.quantity)(
    cartItemInput.quantity,
  );
  TestValidator.predicate("added_at is ISO date")(
    !!Date.parse(adminItem.added_at),
  );
  TestValidator.predicate("updated_at is ISO date")(
    !!Date.parse(adminItem.updated_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validates error handling when an admin tries to fetch details of a cart item
 * with a non-existent cartItemId in a valid cart context.
 *
 * Business context:
 *
 * - Ensures the system correctly returns an error (such as 404 Not Found) rather
 *   than data leakage or misleading responses when querying for an item ID not
 *   present in the cart.
 * - Confirms admin boundary and robustness for invalid cart item input.
 *
 * Workflow:
 *
 * 1. Create a base shopping cart via the customer cart creation API to obtain a
 *    valid cartId for testing.
 * 2. Attempt, as an admin, to fetch a cart item using this valid cartId but with a
 *    newly generated (random, non-existent) cartItemId.
 * 3. Expect an error response (such as 404 Not Found or other
 *    permission/validation error), and assert that this error is thrown as
 *    expected.
 */
export async function test_api_shopping_mall_ai_admin_carts_cartItems_test_admin_get_cart_item_with_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a base customer cart to get a valid cartId
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    },
  );
  typia.assert(cart);

  // 2. Attempt to get a non-existent cartItem as admin
  const nonExistentCartItemId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "admin fetches cart item with non-existent ID should error",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.carts.cartItems.at(connection, {
      cartId: cart.id,
      cartItemId: nonExistentCartItemId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validate that a customer can successfully add items to their shopping cart
 * with correct product, option, and quantity values.
 *
 * This e2e test covers both typical item addition (with no product option) and
 * item addition with an explicit option id (SKU/variant), ensuring correct
 * handling of variant logic and that the item appears in the cart afterwards.
 *
 * Step-by-step process:
 *
 * 1. Prepare a new empty cart for this customer using the shopping cart creation
 *    endpoint.
 * 2. Add a first cart item (with only mandatory product, quantity and cart id
 *    fields) to the cart, simulating a product without variants or default SKU
 *    selection.
 * 3. Add a second cart item with both a product and a populated product_option_id
 *    to simulate a user selecting a specific product option or variant.
 * 4. Validate that both items exist in the cart (with correct ids and fields) by
 *    directly asserting the returned responses contain the specified values
 *    (since there is no endpoint to list all items in a cart, just test the
 *    direct output).
 * 5. Confirm type validation for all responses to ensure contract compliance.
 */
export async function test_api_shopping_mall_ai_customer_carts_cartItems_test_customer_add_item_to_cart_success(
  connection: api.IConnection,
) {
  // 1. Create a new shopping cart for customer/session
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cart);

  // 2. Add a product (no variant/option) to the cart
  const productId1 = typia.random<string & tags.Format<"uuid">>();
  const quantity1 = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const item1 =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productId1,
          shopping_mall_ai_product_option_id: null,
          quantity: quantity1,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(item1);
  TestValidator.equals("cartId matches")(item1.shopping_mall_ai_cart_id)(
    cart.id,
  );
  TestValidator.equals("product id matches")(item1.shopping_mall_ai_product_id)(
    productId1,
  );
  TestValidator.equals("option id null")(
    item1.shopping_mall_ai_product_option_id,
  )(null);
  TestValidator.equals("quantity matches")(item1.quantity)(quantity1);

  // 3. Add a different product with a product option (variant/SKU)
  const productId2 = typia.random<string & tags.Format<"uuid">>();
  const productOptionId2 = typia.random<string & tags.Format<"uuid">>();
  const quantity2 = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const item2 =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: productId2,
          shopping_mall_ai_product_option_id: productOptionId2,
          quantity: quantity2,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(item2);
  TestValidator.equals("cartId matches")(item2.shopping_mall_ai_cart_id)(
    cart.id,
  );
  TestValidator.equals("product id matches")(item2.shopping_mall_ai_product_id)(
    productId2,
  );
  TestValidator.equals("option id matches")(
    item2.shopping_mall_ai_product_option_id,
  )(productOptionId2);
  TestValidator.equals("quantity matches")(item2.quantity)(quantity2);

  // 4. Both item1 and item2 have been added to the same cart, and their direct responses are validated.
  // (If cart listing endpoint is available, fetch all items and validate existence, otherwise, direct assertion suffices here.)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validate system enforcement of cart item referential integrity and duplicate
 * logic.
 *
 * This test ensures the shopping cart API prevents duplicate cart items (same
 * product/option tuple) and rejects creation of cart items referencing
 * invalid/non-existent products or product options. It verifies business logic
 * is consistent and referential integrity is upheld for the core shopping
 * flow.
 *
 * Step-by-step:
 *
 * 1. Create a new shopping cart for a simulated customer session.
 * 2. Add a valid product (A) with an optional option (A1) to the cart to seed an
 *    existing item.
 * 3. Attempt to add the exact same product (A) and option (A1) to the cart again.
 *    Should fail due to duplicate business logic—expect an error (likely HTTP
 *    409 or 400).
 * 4. Attempt to add a cart item with a non-existent product (random UUID) — should
 *    fail with not found or referential integrity error.
 * 5. Attempt to add a valid product but non-existent product option (random UUID)
 *    — should fail with not found or referential integrity error.
 *
 * Every case should be tested independently and errors validated using
 * TestValidator.error().
 *
 * The test enforces a real-world e-commerce rule: a cart cannot contain
 * duplicate items (product/option tuple), and all items must reference valid
 * products/options.
 */
export async function test_api_shopping_mall_ai_test_customer_add_duplicate_or_invalid_item_to_cart(
  connection: api.IConnection,
) {
  // 1. Create a new cart as test bed
  const cart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cart);

  // 2. Add a valid product to the cart (simulate with test product/option UUIDs)
  const validProductId = typia.random<string & tags.Format<"uuid">>();
  const validOptionId = typia.random<string & tags.Format<"uuid">>();
  const item =
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: validProductId,
          shopping_mall_ai_product_option_id: validOptionId,
          quantity: 1,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  typia.assert(item);

  // 3. Attempt to add duplicate item — should error due to duplicate business rule
  await TestValidator.error("duplicate item not allowed")(async () => {
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: validProductId,
          shopping_mall_ai_product_option_id: validOptionId,
          quantity: 1,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  });

  // 4. Attempt to add an item with a non-existent product
  await TestValidator.error("invalid product id - not found")(async () => {
    await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_ai_cart_id: cart.id,
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(), // another random, assume invalid
          shopping_mall_ai_product_option_id: validOptionId,
          quantity: 1,
        } satisfies IShoppingMallAiCartItem.ICreate,
      },
    );
  });

  // 5. Attempt to add an item with valid product but non-existent option
  await TestValidator.error("invalid product option id - not found")(
    async () => {
      await api.functional.shopping_mall_ai.customer.carts.cartItems.create(
        connection,
        {
          cartId: cart.id,
          body: {
            shopping_mall_ai_cart_id: cart.id,
            shopping_mall_ai_product_id: validProductId,
            shopping_mall_ai_product_option_id: typia.random<
              string & tags.Format<"uuid">
            >(), // invalid option id
            quantity: 1,
          } satisfies IShoppingMallAiCartItem.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validate the admin’s ability to add an item to any customer’s cart.
 *
 * This test ensures that with proper privileges, an admin user can add a cart
 * item to an arbitrary customer cart, by:
 *
 * 1. Creating a dummy customer cart (using the customer create cart endpoint)
 * 2. Using the admin endpoint to add a cart item to that customer cart
 * 3. Validating that the item returned references the correct parent cart and
 *    correct product/quantity values as per input.
 */
export async function test_api_shopping_mall_ai_test_admin_add_cart_item_for_any_cart(
  connection: api.IConnection,
) {
  // 1. Create a dummy customer cart (dependency)
  const customerCart =
    await api.functional.shopping_mall_ai.customer.carts.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      },
    });
  typia.assert(customerCart);

  // 2. As admin, add an item to this cart
  const cartItemCreate = {
    shopping_mall_ai_cart_id: customerCart.id,
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
  } satisfies IShoppingMallAiCartItem.ICreate;
  const cartItem =
    await api.functional.shopping_mall_ai.admin.carts.cartItems.create(
      connection,
      {
        cartId: customerCart.id,
        body: cartItemCreate,
      },
    );
  typia.assert(cartItem);

  // 3. Validate that the returned cart item references the correct parent cart and input
  TestValidator.equals("cart reference")(cartItem.shopping_mall_ai_cart_id)(
    customerCart.id,
  );
  TestValidator.equals("product reference")(
    cartItem.shopping_mall_ai_product_id,
  )(cartItemCreate.shopping_mall_ai_product_id);
  TestValidator.equals("quantity")(cartItem.quantity)(cartItemCreate.quantity);
  // Note: product_option_id intentionally not checked here (not supplied in input)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";

/**
 * Validates admin-side enforcement of cart item addition with invalid data and
 * business rule violations.
 *
 * This test ensures the admin API for adding cart items to a cart responds
 * correctly to invalid or problematic requests that could threaten data
 * integrity or operational rules. Specifically, it checks for the correct error
 * handling when the admin attempts to:
 *
 * 1. Add a cart item with an invalid (nonexistent) product ID
 * 2. Add a cart item with an invalid (nonexistent) product option ID
 * 3. Add a cart item with an over-limit quantity (e.g., quantity = 0 or negative)
 *
 * The API should respond with explicit error results (such as 400 Bad Request
 * or 409 Conflict) instead of succeeding or corrupting data.
 *
 * Steps:
 *
 * 1. Create a customer cart so that operations have a valid cart context
 * 2. Attempt to add cart items as an admin with the following scenarios: a.
 *    Nonexistent product ID (random UUID not expected to match any real
 *    product) b. Nonexistent product option ID (random UUID not expected to
 *    match any real option) c. Invalid quantity (zero or negative) d. Multiple
 *    violations at once (invalid product and quantity)
 * 3. Confirm that all error attempts throw exceptions using TestValidator.error(),
 *    with no cart items created.
 */
export async function test_api_shopping_mall_ai_test_admin_add_cart_item_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a customer cart for a valid target
  const customerCart =
    await api.functional.shopping_mall_ai.customer.carts.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    });
  typia.assert(customerCart);

  // Scenario 2a: Admin tries to add item with a nonexistent product ID
  await TestValidator.error("admin add with invalid product")(() =>
    api.functional.shopping_mall_ai.admin.carts.cartItems.create(connection, {
      cartId: customerCart.id,
      body: {
        shopping_mall_ai_cart_id: customerCart.id,
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(), // very unlikely to exist
        quantity: 1,
      } satisfies IShoppingMallAiCartItem.ICreate,
    }),
  );

  // Scenario 2b: Admin tries to add item with a nonexistent product option ID
  await TestValidator.error("admin add with invalid product option")(() =>
    api.functional.shopping_mall_ai.admin.carts.cartItems.create(connection, {
      cartId: customerCart.id,
      body: {
        shopping_mall_ai_cart_id: customerCart.id,
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(), // unlikely real
        shopping_mall_ai_product_option_id: typia.random<
          string & tags.Format<"uuid">
        >(), // random/invalid
        quantity: 1,
      } satisfies IShoppingMallAiCartItem.ICreate,
    }),
  );

  // Scenario 2c: Admin tries to add item with an invalid quantity (zero)
  await TestValidator.error("admin add with zero quantity")(() =>
    api.functional.shopping_mall_ai.admin.carts.cartItems.create(connection, {
      cartId: customerCart.id,
      body: {
        shopping_mall_ai_cart_id: customerCart.id,
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        quantity: 0 as number & tags.Type<"int32"> & tags.Minimum<1>, // invalid
      } satisfies IShoppingMallAiCartItem.ICreate,
    }),
  );

  // Scenario 2d: Admin tries to add item with both invalid product and invalid quantity (negative)
  await TestValidator.error("admin add with invalid product and quantity")(() =>
    api.functional.shopping_mall_ai.admin.carts.cartItems.create(connection, {
      cartId: customerCart.id,
      body: {
        shopping_mall_ai_cart_id: customerCart.id,
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        quantity: -3 as number & tags.Type<"int32"> & tags.Minimum<1>, // invalid
      } satisfies IShoppingMallAiCartItem.ICreate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";

/**
 * Validate creation of a new coupon by a seller.
 *
 * This test simulates an authorized seller successfully creating a new coupon
 * with all required and several optional attributes, ensuring proper creation,
 * response correctness, and field validation.
 *
 * Steps:
 *
 * 1. Prepare a seller-issued coupon data object with required and optional fields.
 * 2. Call the coupon creation API as an authenticated seller.
 * 3. Assert response validity, correct field values, propagation of optional/null
 *    fields, system metadata presence, and type correctness.
 * 4. Attempt to create a coupon while unauthenticated, and verify correct RBAC
 *    enforcement (forbidden).
 */
export async function test_api_shopping_mall_ai_test_create_coupon_with_valid_information_as_seller(
  connection: api.IConnection,
) {
  // 1. Prepare coupon data (simulate a seller issuing their own coupon; platform-level coupon if seller_id = null)
  const couponData: IShoppingMallAiCoupon.ICreate = {
    shopping_mall_ai_seller_id: typia.random<string & tags.Format<"uuid">>(), // Normally authenticated seller's id, but simulated here
    shopping_mall_ai_product_id: null, // Not specific to any product
    shopping_mall_ai_channel_id: null, // No channel limitation
    code: RandomGenerator.alphaNumeric(10), // Random, likely unique code for the test
    type: "fixed", // or "percent", etc. as per business rules
    value: 10000,
    min_order_value: 50000,
    max_usage: 100,
    max_usage_per_customer: 5,
    valid_from: new Date(Date.now() + 60 * 1000).toISOString(), // Valid from 1min in future
    valid_until: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // Expires in 30 days
    stackable: true,
  };
  // 2. Seller creates the coupon
  const created = await api.functional.shopping_mall_ai.seller.coupons.create(
    connection,
    { body: couponData },
  );
  typia.assert(created);
  // 3a. Field-by-field validation for input/output equivalency (required and optional fields)
  TestValidator.equals("code matches")(created.code)(couponData.code);
  TestValidator.equals("type matches")(created.type)(couponData.type);
  TestValidator.equals("value matches")(created.value)(couponData.value);
  TestValidator.equals("max_usage matches")(created.max_usage)(
    couponData.max_usage,
  );
  TestValidator.equals("max_usage_per_customer matches")(
    created.max_usage_per_customer,
  )(couponData.max_usage_per_customer);
  TestValidator.equals("stackable matches")(created.stackable)(
    couponData.stackable,
  );
