/**
 * Validate that the backend rejects coupon creation with an invalid date range.
 *
 * Business context: Administrators can create platform or seller coupons
 * specifying essential details (code, type, value, limits, validity period,
 * stacking rules, etc). However, validity dates (`valid_from`, `valid_until`)
 * are required to be a logically valid range: `valid_from` must be on or before
 * `valid_until`. This test ensures that when an admin attempts to create a
 * coupon where `valid_until` is before `valid_from`, the backend performs
 * proper validation and rejects the request with an error. This prevents
 * logical inconsistencies and potential coupon misuse.
 *
 * Steps:
 *
 * 1. Compose a coupon creation request body where `valid_until` < `valid_from`
 *    (e.g., valid_from = 2025-06-30, valid_until = 2025-06-29).
 * 2. As an admin, call the coupon creation API with this invalid body.
 * 3. Assert that an error occurs and the operation is rejected.
 * 4. Verify that the error is a validation error referencing the date constraint.
 * 5. Confirm that no coupon is created upon failure.
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_create_coupon_with_invalid_date_range_as_admin(
  connection: api.IConnection,
) {
  // 1. Compose an invalid coupon creation payload: end date before start date
  const now = new Date();
  const validFrom = new Date(now.getTime() + 24 * 60 * 60 * 1000); // Tomorrow
  const validUntil = new Date(now.getTime()); // Today

  const couponCreate = {
    code: RandomGenerator.alphaNumeric(10),
    type: "fixed",
    value: 10_000,
    max_usage: 100,
    max_usage_per_customer: 2,
    valid_from: validFrom.toISOString() as string & tags.Format<"date-time">,
    valid_until: validUntil.toISOString() as string & tags.Format<"date-time">,
    stackable: false,
  } satisfies IShoppingMallAiCoupon.ICreate;

  // 2. Attempt to create the coupon as admin
  await TestValidator.error("backend should reject invalid date range")(
    async () => {
      await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
        body: couponCreate,
      });
    },
  );
}

