import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiDeposit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiDeposit";
import type { IPageIShoppingMallAiDeposit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiDeposit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate successful search and filtering of a customer's own deposit (store
 * credit) records.
 *
 * This test ensures that the customer can only see their own deposits and that
 * filtering by status, origin, and date range works correctly. To do this,
 * first, create a deposit for this customer as setup (using admin privileges).
 * Then act as the customer and search their deposits with a variety of filter
 * criteria, confirming the results correspond to only their own records and all
 * filters work as expected.
 *
 * Workflow:
 *
 * 1. Generate a unique customer_id for deposit creation.
 * 2. As admin, create a deposit belonging to this customer via POST
 *    /shopping-mall-ai/admin/deposits.
 * 3. As the customer (customer_id), invoke PATCH
 *    /shopping-mall-ai/customer/deposits with no filters:
 *
 *    - Confirm the returned deposit is present and correct.
 * 4. With the same customer, invoke PATCH with filter 'status' matching the
 *    deposit's status:
 *
 *    - Confirm the deposit is returned and others are excluded.
 * 5. With the same customer, invoke PATCH with mismatched status (e.g.,
 *    'expired'):
 *
 *    - Confirm the deposit is NOT returned (empty list).
 * 6. Filter by correct 'origin' value:
 *
 *    - Deposit is returned.
 * 7. Filter by non-matching 'origin' value:
 *
 *    - Deposit NOT returned (empty list).
 * 8. Filter by date ranges encompassing and excluding 'updated_at' and/or
 *    'expires_at' values:
 *
 *    - Confirm records are properly included/excluded based on filter window.
 * 9. For all successful queries, verify deposit data belongs to this customer
 *    only.
 */
export async function test_api_shopping_mall_ai_customer_deposits_test_search_customer_deposits_success(
  connection: api.IConnection,
) {
  // 1. Generate a unique test customer_id
  const customer_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. As admin, create a deposit for this customer
  const now = new Date();
  const deposit = await api.functional.shopping_mall_ai.admin.deposits.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customer_id,
        balance: 1000,
        status: "active",
        origin: "promo",
        expires_at: new Date(
          now.getTime() + 1000 * 60 * 60 * 24 * 30,
        ).toISOString(), // 30 days later
      } satisfies IShoppingMallAiDeposit.ICreate,
    },
  );
  typia.assert(deposit);

  // 3. As customer, search with no filters (should get the deposit)
  let page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: { shopping_mall_ai_customer_id: customer_id },
    },
  );
  typia.assert(page);
  TestValidator.predicate("has deposit with matching customer")(
    page.data.some(
      (d) =>
        d.id === deposit.id && d.shopping_mall_ai_customer_id === customer_id,
    ),
  );

  // 4. Filter by status (should get the deposit when status matches)
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customer_id,
        status: deposit.status,
      },
    },
  );
  typia.assert(page);
  TestValidator.predicate("filtered by correct status")(
    page.data.some((d) => d.id === deposit.id),
  );

  // 5. Filter by mismatched status (should not get deposit)
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: { shopping_mall_ai_customer_id: customer_id, status: "expired" },
    },
  );
  typia.assert(page);
  TestValidator.equals("should be empty when status mismatches")(
    page.data.length,
  )(0);

  // 6. Filter by correct origin
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customer_id,
        origin: deposit.origin,
      },
    },
  );
  typia.assert(page);
  TestValidator.predicate("filtered by correct origin")(
    page.data.some((d) => d.id === deposit.id),
  );

  // 7. Filter by non-matching origin
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: { shopping_mall_ai_customer_id: customer_id, origin: "refund" },
    },
  );
  typia.assert(page);
  TestValidator.equals("should be empty when origin mismatches")(
    page.data.length,
  )(0);

  // 8. Filter by updated_at_from (should include the deposit)
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customer_id,
        updated_at_from: new Date(now.getTime() - 1000 * 60).toISOString(),
      },
    },
  );
  typia.assert(page);
  TestValidator.predicate("updated_at_from includes deposit")(
    page.data.some((d) => d.id === deposit.id),
  );

  // 9. Filter by updated_at_to (should exclude the deposit)
  page = await api.functional.shopping_mall_ai.customer.deposits.search(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customer_id,
        updated_at_to: new Date(now.getTime() - 1000 * 60).toISOString(),
      },
    },
  );
  typia.assert(page);
  TestValidator.equals("should be empty when updated_at too early")(
    page.data.length,
  )(0);
}

