import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiDeposit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiDeposit";
import type { IPageIShoppingMallAiDeposit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiDeposit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that customers cannot access other users' deposit (store credit)
 * records—even if they manipulate customer_id or related search filters.
 *
 * Business Context: Each shopping mall customer has their own deposit (store
 * credit) records, tracked by unique customer IDs. Customers must be prevented
 * from retrieving or viewing deposit records belonging to any other
 * customer—even if maliciously providing another customer_id as a filter when
 * searching their own deposits. This is critical for data isolation, privacy,
 * and compliance.
 *
 * Test Workflow:
 *
 * 1. (Setup) Use the admin API to create deposits for two distinct customers:
 *    customerA and customerB.
 * 2. As customerA (assumed authenticated), search their deposits using their own
 *    customer_id; verify only their own records appear.
 * 3. As customerA, attempt to search deposits by explicitly including customerB's
 *    customer_id in the filter; verify no results (no leakage).
 * 4. As customerA, search with no filters; verify only their own deposit(s) are
 *    returned.
 *
 * This test ensures that customers are fully prevented from accessing or
 * filtering for any deposit records belonging to other users, regardless of
 * query manipulation.
 */
export async function test_api_shopping_mall_ai_test_search_customer_deposits_permission_denied_to_others(
  connection: api.IConnection,
) {
  // --- SETUP ---
  // Create deposit for customerA
  const customerAId: string = typia.random<string & tags.Format<"uuid">>();
  const customerBId: string = typia.random<string & tags.Format<"uuid">>();
  const depositA = await api.functional.shopping_mall_ai.admin.deposits.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customerAId,
        balance: 100,
        status: "active",
        origin: "manual",
        expires_at: null,
      } satisfies IShoppingMallAiDeposit.ICreate,
    },
  );
  typia.assert(depositA);
  // Create deposit for customerB
  const depositB = await api.functional.shopping_mall_ai.admin.deposits.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customerBId,
        balance: 250,
        status: "active",
        origin: "manual",
        expires_at: null,
      } satisfies IShoppingMallAiDeposit.ICreate,
    },
  );
  typia.assert(depositB);

  // --- TEST: As customerA, can only retrieve their own deposit ---
  // (Assume `connection` represents customerA's authenticated session)
  const resultA =
    await api.functional.shopping_mall_ai.customer.deposits.search(connection, {
      body: { shopping_mall_ai_customer_id: customerAId },
    });
  typia.assert(resultA);
  for (const rec of resultA.data) {
    TestValidator.equals("CustomerA only sees their records")(
      rec.shopping_mall_ai_customer_id,
    )(customerAId);
  }

  // --- TEST: customerA attempts to filter using customerB's ID ---
  const resultB =
    await api.functional.shopping_mall_ai.customer.deposits.search(connection, {
      body: { shopping_mall_ai_customer_id: customerBId },
    });
  typia.assert(resultB);
  TestValidator.equals("CustomerA can't see B's data")(resultB.data.length)(0);

  // --- TEST: customerA searches with no filters (should see ONLY own deposit(s)) ---
  const resultNoFilter =
    await api.functional.shopping_mall_ai.customer.deposits.search(connection, {
      body: {},
    });
  typia.assert(resultNoFilter);
  for (const rec of resultNoFilter.data) {
    TestValidator.equals("No filter, only self's deposits")(
      rec.shopping_mall_ai_customer_id,
    )(customerAId);
  }
}

