 * This test ensures admin is able to:
 *
 * 1. Register a file as admin (setup dependency, as a log must reference a file).
 * 2. Create a file access log event relating to the above file (setup dependency,
 *    main deletion target).
 * 3. Delete this log using its ID as admin using the erase function.
 * 4. Attempt to fetch the deleted log and confirm it no longer exists (since
 *    GET/read-by-ID endpoint is not provided, deletion is confirmed by
 *    expecting error on a second DELETE attempt).
 * 5. Confirm the deletion is irreversible (no restore path, log does not reappear,
 *    hard delete semantics hold).
 * 6. Confirm audit trail compliance: all required log fields were present at
 *    create, and log content is not available after deletion.
 *
 * Edge cases:
 *
 * - Deletion of non-existent ID: not the mainline scenario for this test, but
 *   confirmed as error on second delete here.
 * - Deletion of already-deleted/hard-deleted item: not applicable here (since
 *   this test always uses fresh data, but scenario also tested by
 *   double-delete).
 *
 * Validation points:
 *
 * - Log exists after create, and can be deleted by admin
 * - Deletion operation results in no return value and log cannot be loaded or
 *   deleted again
 * - All log record fields present at initial create (via typia.assert)
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiFileAccessLogs_test_delete_file_access_log_successful(
  connection: api.IConnection,
) {
  // 1. Register a file (admin)
  const file =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFiles.create(
      connection,
      {
        body: {
          original_name: RandomGenerator.alphaNumeric(12) + ".pdf",
          uri: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}`,
          extension: "pdf",
          mime_type: "application/pdf",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1024> &
              tags.Maximum<10485760>
          >(),
          hash: RandomGenerator.alphaNumeric(64),
          actor_type: "admin",
          actor_id: null,
        },
      },
    );
  typia.assert(file);

  // 2. Create a file access log for this file
  const accessLog =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          actor_type: "admin",
          actor_id: null,
          access_type: "download",
          channel: "web",
          outcome: "success",
          ip_address: "127.0.0.1",
