  TestValidator.equals("File log links to file")(
    accessLog.shopping_mall_ai_file_id,
  )(file.id);

  // 3. Delete this access log entry as admin
  await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.erase(
    connection,
    {
      fileAccessLogId: accessLog.id,
    },
  );

  // 4. Attempt to delete again – Should throw error, confirming hard deletion
  await TestValidator.error("Second deletion should fail")(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiFileAccessLogs.erase(
      connection,
      {
        fileAccessLogId: accessLog.id,
      },
    );
  });
