import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductCategory";

/**
 * Test that a customer can retrieve a paginated list of products and that
 * listed products match business rules.
 *
 * Business Context: Customers should only see products that are 'active'.
 * Inactive or forbidden products must NOT appear in the listing. Products are
 * organized into categories. The test ensures that:
 *
 * - Active products show up with correct attributes
 * - Inactive products are hidden
 * - Pagination metadata is sane
 *
 * Test Workflow:
 *
 * 1. Create a product category as admin.
 * 2. Register an active product as seller (linked to category).
 * 3. Register an inactive product as seller.
 * 4. As customer, fetch product listing.
 * 5. Assert: the active product appears with matching fields.
 * 6. Assert: the inactive product does not appear.
 * 7. Validate pagination metadata structure and values.
 */
export async function test_api_shopping_mall_ai_customer_shoppingMallAiProducts_index(
  connection: api.IConnection,
) {
  // 1. Admin creates a product category
  const category =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductCategories.create(
      connection,
      {
        body: {
          name: RandomGenerator.alphaNumeric(8),
          display_order: 1,
          active: true,
        } satisfies IShoppingMallAiProductCategory.ICreate,
      },
    );
  typia.assert(category);

  // 2. Seller registers an active product in the category
  const activeProduct =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: category.id,
          title: RandomGenerator.paragraph()(1),
          description: RandomGenerator.content()()(),
          price: 4990,
          status: "active",
          sku: RandomGenerator.alphaNumeric(10),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(activeProduct);

  // 3. Seller registers an inactive product in the category
  const inactiveProduct =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: category.id,
          title: RandomGenerator.paragraph()(1),
          description: RandomGenerator.content()()(),
          price: 6990,
          status: "inactive",
          sku: RandomGenerator.alphaNumeric(10),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(inactiveProduct);

  // 4. Customer retrieves the product list
  const page =
    await api.functional.shopping_mall_ai.customer.shoppingMallAiProducts.index(
      connection,
    );
  typia.assert(page);

  // 5. Check that the active product is present, inactive one is not
  const foundActive = page.data.find((p) => p.id === activeProduct.id);
  TestValidator.predicate("active product appears")(!!foundActive);
  if (foundActive) {
    TestValidator.equals("title matches")(foundActive.title)(
      activeProduct.title,
    );
    TestValidator.equals("category matches")(
      foundActive.shopping_mall_ai_product_category_id,
    )(category.id);
    TestValidator.equals("status is active")(foundActive.status)("active");
    TestValidator.equals("price matches")(foundActive.price)(
      activeProduct.price,
    );
    TestValidator.equals("sku matches")(foundActive.sku)(activeProduct.sku);
    TestValidator.equals("description matches")(foundActive.description)(
      activeProduct.description,
    );
  }
  const foundInactive = page.data.find((p) => p.id === inactiveProduct.id);
  TestValidator.equals("inactive product should not appear")(foundInactive)(
    undefined,
  );

  // 6. Validate pagination (if total records > limit, paginate)
  TestValidator.predicate("pagination structure")(!!page.pagination);
  TestValidator.predicate("current page is 1")(page.pagination.current === 1);
  TestValidator.predicate("limit is valid")(page.pagination.limit > 0);
  TestValidator.predicate("total records matches")(
    page.pagination.records >= 1,
  );
  TestValidator.predicate("pages valid")(page.pagination.pages >= 1);
}

