import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";

/**
 * Test valid transition of shipment status from 'pending' to 'shipped' for an
 * order's shipment.
 *
 * Business scenario:
 *
 * - Seller has an existing order and has registered a shipment for it, which is
 *   in 'pending' status.
 * - The seller wants to mark the shipment as 'shipped', update its tracking
 *   number, and assign a logistics provider.
 * - This must enforce shipment status transitions, only allowing valid next
 *   statuses and updating only mutable fields.
 *
 * Test flow:
 *
 * 1. (Dependency) Create initial shipment in 'pending' state for a random orderId
 *    (simulate existing order context).
 * 2. Attempt to update the shipment's status to 'shipped' with newly generated
 *    tracking number and provider name. Only mutable fields may be changed.
 * 3. Assert that the update succeeds, that status moves to 'shipped', and
 *    tracking/provider fields are updated accordingly.
 * 4. Assert that immutable fields and audit timestamps are preserved or updated as
 *    expected.
 * 5. Validate all business rules (e.g., no forbidden fields are mutated, response
 *    reflects audit/transition, etc.).
 */
export async function test_api_shopping_mall_ai_test_update_shipment_status_valid_transition(
  connection: api.IConnection,
) {
  // 1. Create a shipment in 'pending' state for a random orderId
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const shipmentCreation =
    await api.functional.shopping_mall_ai.seller.orders.shipments.create(
      connection,
      {
        orderId,
        body: {
          shopping_mall_ai_order_id: orderId,
          status: "pending",
          tracking_number: null,
          provider: null,
        } satisfies IShoppingMallAiShipment.ICreate,
      },
    );
  typia.assert(shipmentCreation);

  // 2. Update the shipment: transition to 'shipped', add tracking number and provider
  const newTracking = "TRK" + Date.now();
  const newProvider = "LogisticsCo";
  const updated =
    await api.functional.shopping_mall_ai.seller.orders.shipments.update(
      connection,
      {
        orderId: shipmentCreation.shopping_mall_ai_order_id,
        shipmentId: shipmentCreation.id,
        body: {
          status: "shipped",
          tracking_number: newTracking,
          provider: newProvider,
        } satisfies IShoppingMallAiShipment.IUpdate,
      },
    );
  typia.assert(updated);

  // 3. Validate updated fields
  TestValidator.equals("status updated")(updated.status)("shipped");
  TestValidator.equals("tracking updated")(updated.tracking_number)(
    newTracking,
  );
  TestValidator.equals("provider updated")(updated.provider)(newProvider);
  TestValidator.equals("order id not changed")(
    updated.shopping_mall_ai_order_id,
  )(orderId);
  TestValidator.equals("shipment id not changed")(updated.id)(
    shipmentCreation.id,
  );

  // 4. Validate updated_at is later or equal (ISO 8601)
  TestValidator.predicate("updated_at reflects update")(
    new Date(updated.updated_at).getTime() >=
      new Date(shipmentCreation.updated_at).getTime(),
  );
}

