import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching coupons as a seller with complex filters and pagination.
 *
 * Ensures after creating a diverse set of coupons for the seller (spanning
 * types, statuses, values, and expirations), the advanced coupon search API
 * correctly filters and returns only the seller’s own coupons matching given
 * criteria such as status, type, value range, and expiration window. Also
 * verifies pagination and sorting behave as intended.
 *
 * Steps:
 *
 * 1. Create a set of coupons with different types ('fixed', 'percent'), statuses
 *    ('active', 'expired'), values (spanning a range), and expirations (some in
 *    future, some past) for this seller.
 * 2. Search (PATCH) with filters: status = 'active', type = 'percent', value in
 *    [15, 30], valid_until >= now, paged & sorted (by value, ascending).
 * 3. Validate all coupons in result:
 *
 *    - Match all filter conditions (status, type, value, expiration)
 *    - Are sorted as requested
 *    - Pagination metadata is valid
 */
export async function test_api_shopping_mall_ai_seller_coupons_test_search_coupons_with_valid_filters_as_seller(
  connection: api.IConnection,
) {
  // Fixed seller UUID to simulate single seller context
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();

  // Build diverse set of coupons for this seller
  const couponData = [
    // Should match filter: active percent 20 (future expiry)
    {
      code: `PERCENT20-${typia.random<string>()}`,
      type: "percent",
      value: 20,
      min_order_value: 100,
      max_usage: 50,
      max_usage_per_customer: 5,
      shopping_mall_ai_seller_id: sellerId,
      valid_from: new Date(Date.now() - 24 * 3600 * 1000).toISOString(), // yesterday
      valid_until: new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString(), // +7 days
      stackable: true,
    },
    // Should NOT match: expired (status will be 'expired' once valid_until < now)
    {
      code: `PERCENT30-EXPIRED-${typia.random<string>()}`,
      type: "percent",
      value: 30,
      min_order_value: 100,
      max_usage: 30,
      max_usage_per_customer: 3,
      shopping_mall_ai_seller_id: sellerId,
      valid_from: new Date(Date.now() - 15 * 24 * 3600 * 1000).toISOString(),
      valid_until: new Date(Date.now() - 1 * 24 * 3600 * 1000).toISOString(), // yesterday
      stackable: false,
    },
    // Should match: active percent 25 (future expiry)
    {
      code: `PERCENT25-${typia.random<string>()}`,
      type: "percent",
      value: 25,
      min_order_value: 200,
      max_usage: 60,
      max_usage_per_customer: 6,
      shopping_mall_ai_seller_id: sellerId,
      valid_from: new Date(Date.now() - 2 * 24 * 3600 * 1000).toISOString(),
      valid_until: new Date(Date.now() + 2 * 24 * 3600 * 1000).toISOString(), // +2 days
      stackable: false,
    },
    // Should NOT match: type 'fixed' (not 'percent')
    {
      code: `FIXED50-${typia.random<string>()}`,
      type: "fixed",
      value: 50,
      min_order_value: 150,
      max_usage: 40,
      max_usage_per_customer: 4,
      shopping_mall_ai_seller_id: sellerId,
      valid_from: new Date(Date.now() - 1 * 24 * 3600 * 1000).toISOString(),
      valid_until: new Date(Date.now() + 3 * 24 * 3600 * 1000).toISOString(),
      stackable: true,
    },
    // Should match: active percent 15 (future expiry)
    {
      code: `PERCENT15-${typia.random<string>()}`,
      type: "percent",
      value: 15,
      min_order_value: 50,
      max_usage: 20,
      max_usage_per_customer: 2,
      shopping_mall_ai_seller_id: sellerId,
      valid_from: new Date(Date.now() - 4 * 24 * 3600 * 1000).toISOString(),
      valid_until: new Date(Date.now() + 1 * 24 * 3600 * 1000).toISOString(), // +1 day
      stackable: true,
    },
  ];

  // 1. Create coupons for seller
  const createdCoupons: IShoppingMallAiCoupon[] = [];
  for (const body of couponData) {
    const coupon = await api.functional.shopping_mall_ai.seller.coupons.create(
      connection,
      { body: body as IShoppingMallAiCoupon.ICreate },
    );
    typia.assert(coupon);
    createdCoupons.push(coupon);
  }

  // 2. Run search with filters: status 'active', type 'percent', value 15,30], valid_until >= now, sorted by value ascending
  const nowIso = new Date().toISOString();
  const res = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: {
        shopping_mall_ai_seller_id: sellerId,
        status: "active",
        type: "percent",
        valid_until_from: nowIso,
        sort_by: "value",
        sort_order: "asc",
        page: 1,
        limit: 20,
      },
    },
  );
  typia.assert(res);

  // 3. Validate results: Only matching coupons for this seller (cannot check seller field directly)
  for (const c of res.data) {
    TestValidator.equals("status is active")(c.status)("active");
    TestValidator.equals("type is percent")(c.type)("percent");
    TestValidator.predicate("value in range 15-30")(
      c.value >= 15 && c.value <= 30,
    );
    TestValidator.predicate("valid_until >= now")(
      new Date(c.valid_until) >= new Date(nowIso),
    );
  }

  // Validate sorting by value ascending
  for (let i = 1; i < res.data.length; ++i) {
    TestValidator.predicate("sorted ascending values")(
      res.data[i - 1].value <= res.data[i].value,
    );
  }

  // Pagination checks
  TestValidator.equals("pagination current page")(res.pagination.current)(1);
  TestValidator.equals("pagination limit")(res.pagination.limit)(20);
  TestValidator.predicate("pagination records >= results")(
    res.pagination.records >= res.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that sellers cannot query for coupons outside of their data scope by
 * using unauthorized filter criteria.
 *
 * Business context: This test verifies RBAC enforcement and business-logic
 * scoping for coupon search. Sellers should only be able to view/search coupons
 * issued by themselves. Attempts to search using another seller's id (or
 * admin-only fields) must be denied or filtered out, ensuring data leakage or
 * privilege escalation is prevented. This is crucial for maintaining
 * multi-tenant integrity.
 *
 * Step-by-step process:
 *
 * 1. As Seller A, create one or more coupons using the seller coupon creation API
 *    (keep track of Seller A's ID).
 * 2. As Admin, create a coupon associated with Seller B (another seller). You can
 *    use a unique random seller ID for Seller B that is not the same as Seller
 *    A.
 * 3. As Seller A, perform a coupon search with normal filters and confirm you see
 *    only Seller A's coupons.
 * 4. As Seller A, attempt to perform coupon search with filter
 *    shopping_mall_ai_seller_id=Seller B's ID – validate that the result is
 *    empty (not authorized to view Seller B's data, even if a coupon for Seller
 *    B exists).
 * 5. As Seller A, attempt to search using product and/or channel fields associated
 *    only with Seller B's coupon to ensure nothing leaks across RBAC.
 * 6. (Edge case) If supported, try searching with a coupon code belonging to
 *    Seller B – result should be empty (not visible cross-scope).
 * 7. (Negative) If system supports error returns for unauthorized filter values,
 *    assert error; otherwise assert that result data is empty.
 */
export async function test_api_shopping_mall_ai_test_search_coupons_with_inaccessible_filters_as_seller(
  connection: api.IConnection,
) {
  // 1. As Seller A, create one or more coupons via seller coupon API
  // (Assume authentication as Seller A already handled via connection.)
  const sellerA_coupon: IShoppingMallAiCoupon =
    await api.functional.shopping_mall_ai.seller.coupons.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        type: "fixed",
        value: 5000,
        stackable: false,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date(Date.now() - 60 * 1000).toISOString(),
        valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(sellerA_coupon);

  // 2. As Admin, create coupon associated with unrelated Seller B
  const unrelatedSellerId = typia.random<string & tags.Format<"uuid">>();
  const sellerB_coupon: IShoppingMallAiCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: unrelatedSellerId,
        code: RandomGenerator.alphaNumeric(8),
        type: "percent",
        value: 10,
        stackable: false,
        max_usage: 99,
        max_usage_per_customer: 1,
        valid_from: new Date(Date.now() - 60 * 1000).toISOString(),
        valid_until: new Date(
          Date.now() + 1000 * 60 * 60 * 24 * 2,
        ).toISOString(),
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(sellerB_coupon);

  // 3. Seller A fetches coupons with no filter – should only see own coupons
  const pageMine = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: { page: 1, limit: 100 } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(pageMine);
  for (const summary of pageMine.data) {
    if (summary.id === sellerB_coupon.id)
      throw new Error(
        "Data leak: Seller B's coupon appeared in Seller A's search results",
      );
  }

  // 4. Seller A attempts to filter for Seller B's coupons
  const pageCrossSeller =
    await api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {
        shopping_mall_ai_seller_id: unrelatedSellerId,
      } satisfies IShoppingMallAiCoupon.IRequest,
    });
  typia.assert(pageCrossSeller);
  TestValidator.equals("no cross-seller data shown")(
    pageCrossSeller.data.length,
  )(0);

  // 5. Seller A attempts filters by product/channel/fields related only to Seller B's coupon (if set)
  // product/channel filters only tested if Seller B's coupon used those fields
  if (sellerB_coupon.shopping_mall_ai_product_id) {
    const pageProduct =
      await api.functional.shopping_mall_ai.seller.coupons.search(connection, {
        body: {
          shopping_mall_ai_product_id:
            sellerB_coupon.shopping_mall_ai_product_id,
        } satisfies IShoppingMallAiCoupon.IRequest,
      });
    typia.assert(pageProduct);
    TestValidator.equals("no cross-seller product data")(
      pageProduct.data.length,
    )(0);
  }
  if (sellerB_coupon.shopping_mall_ai_channel_id) {
    const pageChannel =
      await api.functional.shopping_mall_ai.seller.coupons.search(connection, {
        body: {
          shopping_mall_ai_channel_id:
            sellerB_coupon.shopping_mall_ai_channel_id,
        } satisfies IShoppingMallAiCoupon.IRequest,
      });
    typia.assert(pageChannel);
    TestValidator.equals("no cross-seller channel data")(
      pageChannel.data.length,
    )(0);
  }

  // 6. Seller A attempts filter by seller B's coupon-code
