import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated coupon search for sellers with a large coupon result set.
 *
 * Business context: A seller may own a large number of coupons in the system
 * (30+) and must be able to query/search these in a paginated interface
 * (dashboard, admin, etc). It's necessary to confirm that pagination
 * (page/limit), as well as sorting parameters (sort_by/sort_order), work
 * correctly and that the API returns the expected windowed subset and correct
 * ordering from the complete data set. This ensures the integrity of listing
 * UIs and that slicing works for large result sets.
 *
 * Steps:
 *
 * 1. Create >30 coupons for a seller with distinguishable codes & creation times
 * 2. Perform a paginated search with a specific limit (e.g., 10 per page)
 * 3. Confirm total records/pages reflect created coupons, and page slicing is
 *    correct
 * 4. Perform sorted search (sort_by=created_at, sort_order=desc) and verify
 *    ordering
 * 5. Optionally, test an intermediate page and verify correct coupon subset is
 *    returned
 */
export async function test_api_shopping_mall_ai_seller_coupons_test_search_coupons_with_pagination_and_large_result_set(
  connection: api.IConnection,
) {
  // 1. Bulk create over 30 coupons for the seller
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const createdAtBase = new Date(Date.now() - 1000 * 60 * 60 * 24 * 2); // base 2 days ago
  const coupons: IShoppingMallAiCoupon[] = [];
  for (let i = 0; i < 33; ++i) {
    const code = `COUPONTEST${i.toString().padStart(2, "0")}`;
    // Space created_at times by 60s for sorting testing
    const valid_from = new Date(
      createdAtBase.getTime() + 60000 * i,
    ).toISOString();
    const valid_until = new Date(
      createdAtBase.getTime() + 60000 * i + 10000000,
    ).toISOString();
    const coupon = await api.functional.shopping_mall_ai.seller.coupons.create(
      connection,
      {
        body: {
          shopping_mall_ai_seller_id: sellerId,
          code,
          type: "fixed",
          value: 123 + i,
          min_order_value: null,
          max_usage: 10,
          max_usage_per_customer: 2,
          valid_from,
          valid_until,
          stackable: true,
          shopping_mall_ai_product_id: null,
          shopping_mall_ai_channel_id: null,
        } satisfies IShoppingMallAiCoupon.ICreate,
      },
    );
    coupons.push(coupon);
  }

  // 2. Fetch first page of 10 coupons
  const pageSize = 10;
  const page1 = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: {
        shopping_mall_ai_seller_id: sellerId,
        page: 1,
        limit: pageSize,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 count")(page1.data.length)(pageSize);
  TestValidator.equals("pagination records")(page1.pagination.records)(
    coupons.length,
  );
  TestValidator.equals("total pages")(page1.pagination.pages)(
    Math.ceil(coupons.length / pageSize),
  );
  // Coupon order: oldest first in asc
  for (let i = 0; i < page1.data.length; ++i) {
    TestValidator.equals(`asc sort order [${i}]`)(page1.data[i].code)(
      `COUPONTEST${i.toString().padStart(2, "0")}`,
    );
  }

  // 3. Fetch 2nd page
  const page2 = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: {
        shopping_mall_ai_seller_id: sellerId,
        page: 2,
        limit: pageSize,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 count")(page2.data.length)(pageSize);
  for (let i = 0; i < page2.data.length; ++i) {
    TestValidator.equals(`asc sort order page2 [${i}]`)(page2.data[i].code)(
      `COUPONTEST${(i + pageSize).toString().padStart(2, "0")}`,
    );
  }

  // 4. Fetch last page and check remainder count
  const totalPages = page1.pagination.pages;
  const lastPage = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: {
        shopping_mall_ai_seller_id: sellerId,
        page: totalPages,
        limit: pageSize,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(lastPage);
  const lastPageCount =
    coupons.length % pageSize === 0 ? pageSize : coupons.length % pageSize;
  TestValidator.equals("last page count")(lastPage.data.length)(lastPageCount);

  // 5. Fetch first page with desc sort, check codes reversed
  const page1Desc = await api.functional.shopping_mall_ai.seller.coupons.search(
    connection,
    {
      body: {
        shopping_mall_ai_seller_id: sellerId,
        page: 1,
        limit: pageSize,
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IShoppingMallAiCoupon.IRequest,
    },
  );
  typia.assert(page1Desc);
  for (let i = 0; i < page1Desc.data.length; ++i) {
    TestValidator.equals(`desc sort order [${i}]`)(page1Desc.data[i].code)(
      `COUPONTEST${(coupons.length - 1 - i).toString().padStart(2, "0")}`,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
