/**
 * 쿠폰 검색 요청의 잘못된 쿼리 구조에 대한 검증 테스트
 *
 * 이 테스트는 쇼핑몰 AI 셀러 쿠폰 검색 API(/shopping-mall-ai/seller/coupons)에 비정상적인 쿼리(body:
 * IShoppingMallAiCoupon.IRequest) 구조를 입력했을 때, 서버가 적절하게 유효성 검사 에러를 반환하는지 확인하는
 * 목적입니다.
 *
 * 비즈니스 중요성:
 *
 * - 복잡한 필터·정렬·페이징 구조의 검색 API에서, 클라이언트가 잘못된 타입(예: page를 문자열 등)이나 범위를 벗어난 값, 필수값
 *   누락, 지원하지 않는 enum 등을 입력할 경우 서버가 안전하게 validation error를 반환하는지, 오류 메시지에 민감 정보가
 *   노출되지 않는지 보안 관점에서 특히 중요합니다.
 *
 * 테스트 단계:
 *
 * 1. 필수값(page, limit 등) 누락시 에러 반환
 * 2. 잘못된 타입(문자열, 음수값 등) 입력시 에러 반환
 * 3. 범위 초과 입력시 에러 반환
 * 4. Enum/const에 허용되지 않는 값 전달시 에러 반환
 * 5. 다중 복합 오류(여러 잘못된 값을 동시에)
 * 6. 모든 에러 응답에서 민감 정보 노출 방지 및 메시지 포맷의 적정성(실행 시 육안 점검)
 */
export async function test_api_shopping_mall_ai_test_search_coupons_invalid_query_structure(
  connection: api.IConnection,
) {
  // 1. 필수 파라미터(page, limit) 미포함: 빈 객체
  await TestValidator.error("필수값 누락 에러")(() =>
    api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {},
    }),
  );

  // 2. 타입 불일치 및 음수: page에 문자열, limit에 음수
  await TestValidator.error("type 불일치 및 음수 에러")(() =>
    api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {
        page: "one" as any,
        limit: -10 as any,
      },
    }),
  );

  // 3. 허용 범위 초과값: page=-1, limit=1,000,000
  await TestValidator.error("허용 범위 초과 에러")(() =>
    api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {
        page: -1 as any,
        limit: 1000000 as any,
      },
    }),
  );

  // 4. sort_order에 허용되지 않는 임의 문자열(enum 범위 밖)
  await TestValidator.error("enum 범위 초과 에러")(() =>
    api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {
        page: 1,
        limit: 20,
        sort_order: "upward" as any,
      },
    }),
  );

  // 5. 복수 조건 동시 포함(잘못된 타입 + 범위 초과 + 지원X enum)
  await TestValidator.error("복합 에러(다중 구조 오류)")(() =>
    api.functional.shopping_mall_ai.seller.coupons.search(connection, {
      body: {
        page: "two" as any,
        limit: -5 as any,
        sort_order: "sideways" as any,
      },
    }),
  );
  // 6. 각 에러 응답에서 민감정보 노출 및 메시지의 적정성은 실제 테스트 결과에서 확인 (코드 검증은 여기서 끝)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
