/**
 * E2E test for advanced admin coupon search with all filters (via PATCH
 * /shopping-mall-ai/admin/coupons)
 *
 * Validates that the admin can filter and sort by full set of coupon fields
 * (code, type, status, issuer, product, value, date ranges, channel, etc),
 * retrieve proper paginated and sorted coupon sets, and see both admin-issued
 * and seller-issued coupons without restriction.
 *
 * Steps:
 *
 * 1. Create multiple coupons:
 *
 *    - At least one global (platform/admin) coupon
 *    - At least one seller coupon for each of two sellers
 *    - Each coupon varies on type, status, value, product, channel, dates
 * 2. Pick filter criteria that should match a known subset of these coupons
 *    (including a mix of admin & seller coupons)
 * 3. Use PATCH search with these filters + sort + pagination
 * 4. Assert that all search results match the filters
 * 5. Validate that coupon summary DTOs are correct and all filter constraints are
 *    enforced
 * 6. Confirm sort order and pagination metadata
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_admin_advanced_coupon_search_with_all_filters(
  connection: api.IConnection,
) {
  // 1. Create sellers (two distinct sellers) to be used as coupon issuers
  const sellerId1 = typia.random<string & tags.Format<"uuid">>();
  const sellerId2 = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare product/channel (simulate diversity)
  const productId1 = typia.random<string & tags.Format<"uuid">>();
  const productId2 = typia.random<string & tags.Format<"uuid">>();
  const channelId1 = typia.random<string & tags.Format<"uuid">>();
  const channelId2 = typia.random<string & tags.Format<"uuid">>();

  // 3. Coupon set to span various combinations (some will fall in filter range, others not)
  const now = new Date();
  const hoursAgo4 = new Date(now.getTime() - 4 * 60 * 60 * 1000).toISOString();
  const hoursFrom2 = new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString();
  const hoursFrom10 = new Date(
    now.getTime() + 10 * 60 * 60 * 1000,
  ).toISOString();

  // Coupon types/statuses
  const typeFixed = "fixed";
  const typePercent = "percent";
  const typeShipping = "free_shipping";
  const statusActive = "active";
  const statusExpired = "expired";

  // 4. Create coupons
  const couponGlobal =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: null,
        shopping_mall_ai_channel_id: channelId1,
        shopping_mall_ai_product_id: productId1,
        code: "ADMINGLOBAL1",
        type: typeFixed,
        value: 2000,
        min_order_value: 10000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: hoursAgo4,
        valid_until: hoursFrom10,
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponGlobal);

  const couponSeller1 =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: sellerId1,
        shopping_mall_ai_channel_id: channelId2,
        shopping_mall_ai_product_id: productId2,
        code: "SELLER1PCT",
        type: typePercent,
        value: 15,
        min_order_value: 30000,
        max_usage: 50,
        max_usage_per_customer: 3,
        valid_from: hoursAgo4,
        valid_until: hoursFrom10,
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponSeller1);

  const couponSeller1Expired =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: sellerId1,
        shopping_mall_ai_channel_id: channelId2,
        shopping_mall_ai_product_id: productId2,
        code: "SELLER1EXP",
        type: typeFixed,
        value: 1000,
        min_order_value: 20000,
        max_usage: 20,
        max_usage_per_customer: 1,
        valid_from: hoursAgo4,
        valid_until: now.toISOString(), // Already expired
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponSeller1Expired);

  const couponSeller2 =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: sellerId2,
        shopping_mall_ai_channel_id: channelId1,
        shopping_mall_ai_product_id: productId1,
        code: "SELLER2SHIP",
        type: typeShipping,
        value: 0,
        min_order_value: null,
        max_usage: 5,
        max_usage_per_customer: 1,
        valid_from: hoursAgo4,
        valid_until: hoursFrom10,
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponSeller2);

  const couponSeller2Fixed =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        shopping_mall_ai_seller_id: sellerId2,
        shopping_mall_ai_channel_id: channelId2,
        shopping_mall_ai_product_id: productId2,
        code: "SELLER2FIX",
        type: typeFixed,
        value: 800,
        min_order_value: 9000,
        max_usage: 10,
        max_usage_per_customer: 2,
        valid_from: hoursAgo4,
        valid_until: hoursFrom10,
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(couponSeller2Fixed);

  // 5. Use advanced filter, only include properties actually used (never code: undefined, never null to string props)
  const filterType = typeFixed;
  const filterStatus = statusActive;
  const filterMinValue = 700;
  const filterMaxValue = 2500;
  const filterIssuerId = sellerId2; // pass only string, never null
  const filterProductId = productId2;
  const filterChannelId = channelId2;
  const filterFrom = hoursAgo4;
  const filterUntil = hoursFrom10;

  const searchResult =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: 2,
        type: filterType,
        status: filterStatus,
        valid_from_from: filterFrom,
        valid_from_to: filterUntil,
        valid_until_from: filterFrom,
        valid_until_to: filterUntil,
        shopping_mall_ai_seller_id: filterIssuerId,
        shopping_mall_ai_channel_id: filterChannelId,
        shopping_mall_ai_product_id: filterProductId,
        sort_by: "value",
        sort_order: "desc",
      } satisfies IShoppingMallAiCoupon.IRequest,
    });
  typia.assert(searchResult);

  // 6. Pagination
  TestValidator.equals("pagination current page")(
    searchResult.pagination.current,
  )(1);
  TestValidator.equals("pagination limit")(searchResult.pagination.limit)(2);
  TestValidator.predicate("pagination total records >= 1")(
    searchResult.pagination.records >= 1,
  );
  TestValidator.predicate("pagination total pages >= 1")(
    searchResult.pagination.pages >= 1,
  );

  // 7. Each coupon summary matches
  for (const c of searchResult.data) {
    typia.assert(c);
    TestValidator.equals("type")(c.type)(filterType);
    TestValidator.equals("status")(c.status)(filterStatus);
    TestValidator.predicate("value in range")(
      c.value >= filterMinValue && c.value <= filterMaxValue,
    );
    TestValidator.predicate("valid_from >= filterFrom")(
      c.valid_from >= filterFrom,
    );
    TestValidator.predicate("valid_until <= filterUntil")(
      c.valid_until <= filterUntil,
    );
  }

  // 8. Confirm sort order is descending by value
  const values = searchResult.data.map((d) => d.value);
  for (let i = 1; i < values.length; i++) {
    TestValidator.predicate("descending sort order")(
      values[i - 1] >= values[i],
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
