/**
 * Validate filtering on coupon search with invalid types, enums, or
 * non-existent values.
 *
 * Tests that the coupon admin search endpoint handles: malformed field values
 * (type errors), unsupported enum values, and valid fields referencing
 * bogus/non-existent data. API must respond with clear validation errors (not
 * server errors), or empty sets for valid fields but missing records.
 *
 * This implementation omits filters using bogus/non-schema fields as these
 * would not compile and cannot be constructed with strong DTO typing.
 *
 * Workflow:
 *
 * 1. Send a search request with valid fields but type violations (e.g., string for
 *    int, wrong enum, wrong format).
 * 2. Search for a clearly non-existent coupon (random uuid as code) and verify
 *    empty set.
 * 3. Vary formats (e.g., malformed date) and check error handling.
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_admin_coupon_search_by_invalid_filters_or_nonexistent_fields(
  connection: api.IConnection,
) {
  // 1. Invalid type for 'limit' (should be number)
  await TestValidator.error("type violation on 'limit'")(() =>
    api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: { limit: "notAnInt" as any },
    }),
  );

  // Invalid format for 'valid_from_from' (should be date-time ISO8601 string)
  await TestValidator.error("type violation on 'valid_from_from'")(() =>
    api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: { valid_from_from: "definitely-not-a-date" as any },
    }),
  );

  // Wrong enum value for 'sort_order' (should be 'asc' or 'desc')
  await TestValidator.error("wrong sort_order enum")(() =>
    api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: { sort_order: "sideways" as any },
    }),
  );

  // 2. Search with valid field referencing a non-existent coupon code
  const weirdCouponId = typia.random<string & tags.Format<"uuid">>();
  const emptyResult =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: { code: weirdCouponId },
    });
  typia.assert(emptyResult);
  TestValidator.equals("should be empty set")(emptyResult.data.length)(0);

  // 3. Malformed date filter (not ISO8601)
  await TestValidator.error("malformed valid_until_from")(() =>
    api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: { valid_until_from: "13/32/2025" as any },
    }),
  );
}

