 * This test ensures that the coupon search endpoint correctly supports:
 *
 * - Pagination through several pages worth of coupons
 * - Correct ordering by code, value, valid_from, valid_until fields (asc/desc)
 * - Coverage of page boundaries: first, middle, last page, and empty result
 *
 * Steps:
 *
 * 1. Bulk insert a diverse batch of coupons (over multiple pages worth)
 *
 *    - Vary coupon codes (for easy sorting)
 *    - Vary 'value', 'valid_from', 'valid_until', 'type', 'status', etc.
 *    - Ensure several unique codes and values for meaningful sort testing
 * 2. Search first page, default sort, validate order and count (limit)
 * 3. Search a middle page, validate continuity and correct records
 * 4. Search last page, validate trailing records
 * 5. Search with an out-of-range page (should return empty data)
 * 6. Sort by coupon code ascending and descending, check proper order
 * 7. Sort by value ascending and descending, check order
 * 8. Sort by valid_from ascending and descending, check order
 * 9. Sort by valid_until ascending and descending, check order
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_admin_coupon_search_pagination_and_sorting(
  connection: api.IConnection,
) {
  // Step 1: Create a batch of coupons for thorough pagination/sorting tests
  const totalCoupons = 37;
  const perPage = 10;
  const now = new Date();
  for (let i = 0; i < totalCoupons; ++i) {
    const code = `TESTCOUPON-${i.toString().padStart(3, "0")}`;
    const value = 10 + i;
    const valid_from = new Date(now.getTime() + i * 3600 * 1000).toISOString();
    const valid_until = new Date(
      now.getTime() + (i + 24) * 3600 * 1000,
    ).toISOString();
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: {
        code,
        type: i % 2 === 0 ? "fixed" : "percent",
        value,
        min_order_value: i % 3 === 0 ? 100 : null,
        max_usage: 100 + i,
        max_usage_per_customer: 5 + (i % 3),
        valid_from,
        valid_until,
        stackable: i % 2 === 0,
        shopping_mall_ai_seller_id: null,
        shopping_mall_ai_product_id: null,
        shopping_mall_ai_channel_id: null,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  }

  // Step 2: Search first page default sort
  let page1 = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: { page: 1, limit: perPage },
    },
  );
  typia.assert(page1);
  TestValidator.equals("first page size")(page1.data.length)(perPage);
  TestValidator.equals("current page")(page1.pagination.current)(1);

  // Step 3: Search middle page
  const midPage = Math.ceil(totalCoupons / perPage / 2);
  let pageMiddle = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: { page: midPage, limit: perPage },
    },
  );
  typia.assert(pageMiddle);
  TestValidator.equals("current page")(pageMiddle.pagination.current)(midPage);

  // Step 4: Search last page (may be partial)
  const lastPage = Math.ceil(totalCoupons / perPage);
  let pageLast = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: { page: lastPage, limit: perPage },
    },
  );
  typia.assert(pageLast);
  TestValidator.equals("current page")(pageLast.pagination.current)(lastPage);
  TestValidator.equals("last page size")(pageLast.data.length)(
    totalCoupons % perPage || perPage,
  );

  // Step 5: Search out-of-range page (should be empty)
  let pageOut = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: { page: lastPage + 1, limit: perPage },
    },
  );
  typia.assert(pageOut);
  TestValidator.equals("empty page")(pageOut.data.length)(0);

  // Step 6: Sort by code ASC
  let sortedAsc = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "code",
        sort_order: "asc",
      },
    },
  );
  typia.assert(sortedAsc);
  TestValidator.predicate("sorted coupon codes asc")(
    sortedAsc.data.every((a, i, arr) => i === 0 || a.code >= arr[i - 1].code),
  );

  // Step 7: Sort by code DESC
  let sortedDesc = await api.functional.shopping_mall_ai.admin.coupons.search(
    connection,
    {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "code",
        sort_order: "desc",
      },
    },
  );
  typia.assert(sortedDesc);
  TestValidator.predicate("sorted coupon codes desc")(
    sortedDesc.data.every((a, i, arr) => i === 0 || a.code <= arr[i - 1].code),
  );

  // Step 8: Sort by value ASC
  let sortedValueAsc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "value",
        sort_order: "asc",
      },
    });
  typia.assert(sortedValueAsc);
  TestValidator.predicate("sorted values asc")(
    sortedValueAsc.data.every(
      (a, i, arr) => i === 0 || a.value >= arr[i - 1].value,
    ),
  );

  // Step 9: Sort by value DESC
  let sortedValueDesc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "value",
        sort_order: "desc",
      },
    });
  typia.assert(sortedValueDesc);
  TestValidator.predicate("sorted values desc")(
    sortedValueDesc.data.every(
      (a, i, arr) => i === 0 || a.value <= arr[i - 1].value,
    ),
  );

  // Step 10: Sort by valid_from ASC
  let sortedValidFromAsc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "valid_from",
        sort_order: "asc",
      },
    });
  typia.assert(sortedValidFromAsc);
  TestValidator.predicate("sorted valid_from asc")(
    sortedValidFromAsc.data.every(
      (a, i, arr) => i === 0 || a.valid_from >= arr[i - 1].valid_from,
    ),
  );

  // Step 11: Sort by valid_from DESC
  let sortedValidFromDesc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "valid_from",
        sort_order: "desc",
      },
    });
  typia.assert(sortedValidFromDesc);
  TestValidator.predicate("sorted valid_from desc")(
    sortedValidFromDesc.data.every(
      (a, i, arr) => i === 0 || a.valid_from <= arr[i - 1].valid_from,
    ),
  );

  // Step 12: Sort by valid_until ASC
  let sortedValidUntilAsc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "valid_until",
        sort_order: "asc",
      },
    });
  typia.assert(sortedValidUntilAsc);
  TestValidator.predicate("sorted valid_until asc")(
    sortedValidUntilAsc.data.every(
      (a, i, arr) => i === 0 || a.valid_until >= arr[i - 1].valid_until,
    ),
  );

  // Step 13: Sort by valid_until DESC
  let sortedValidUntilDesc =
    await api.functional.shopping_mall_ai.admin.coupons.search(connection, {
      body: {
        page: 1,
        limit: totalCoupons,
        sort_by: "valid_until",
        sort_order: "desc",
      },
    });
  typia.assert(sortedValidUntilDesc);
  TestValidator.predicate("sorted valid_until desc")(
    sortedValidUntilDesc.data.every(
      (a, i, arr) => i === 0 || a.valid_until <= arr[i - 1].valid_until,
