 * must prevent customers from accessing coupons they should not see. This test
 * ensures correct detail fetch and field accuracy for in-scope coupons.
 *
 * Workflow steps:
 *
 * 1. Admin creates a public coupon (platform/global scope) via admin coupon
 *    creation API.
 * 2. Customer fetches coupon detail using the generated coupon ID via the customer
 *    coupon detail endpoint.
 * 3. Assert the returned coupon matches the created configuration in all fields
 *    (e.g., type, value, code, valid_from/until, scope fields).
 * 4. Validate that proper RBAC/scope enforcement occurs — for example, customer
 *    can view only if coupon is public or assigned, not unrelated private
 *    coupons.
 * 5. (Optional, if feasible with available APIs) Negative test: Attempt to fetch a
 *    coupon outside the user's eligibility and expect access denial/error.
 */
export async function test_api_shopping_mall_ai_customer_coupons_test_get_coupon_details_as_customer_within_scope(
  connection: api.IConnection,
) {
  // 1. Admin creates a public coupon
  const couponConfig: IShoppingMallAiCoupon.ICreate = {
    code: RandomGenerator.alphaNumeric(10),
    type: "fixed", // Or "percent" as supported by business logic
    value: 5000,
