    connection,
    { couponId: createdCoupon.id },
  );
  typia.assert(result);

  // 3. Assert all core fields match
  TestValidator.equals("ID match")(result.id)(createdCoupon.id);
  TestValidator.equals("code match")(result.code)(couponConfig.code);
  TestValidator.equals("type match")(result.type)(couponConfig.type);
  TestValidator.equals("value match")(result.value)(couponConfig.value);
  TestValidator.equals("max usage match")(result.max_usage)(
    couponConfig.max_usage,
  );
  TestValidator.equals("max usage per customer match")(
    result.max_usage_per_customer,
  )(couponConfig.max_usage_per_customer);
  TestValidator.equals("stackable match")(result.stackable)(
    couponConfig.stackable,
  );
  TestValidator.equals("valid_from match")(result.valid_from)(
    couponConfig.valid_from,
  );
  TestValidator.equals("valid_until match")(result.valid_until)(
    couponConfig.valid_until,
  );
  TestValidator.equals("seller match")(result.shopping_mall_ai_seller_id)(
    couponConfig.shopping_mall_ai_seller_id,
  );
  TestValidator.equals("product match")(result.shopping_mall_ai_product_id)(
    couponConfig.shopping_mall_ai_product_id,
  );
  TestValidator.equals("channel match")(result.shopping_mall_ai_channel_id)(
    couponConfig.shopping_mall_ai_channel_id,
  );
  TestValidator.equals("min_order_value match")(result.min_order_value)(
    couponConfig.min_order_value,
