        >(), // restrict by unrelated seller
        shopping_mall_ai_product_id: null,
        shopping_mall_ai_channel_id: null,
        min_order_value: null,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(restrictedCoupon);

  // 2. Customer attempts to retrieve the restricted coupon by ID
  await TestValidator.error("customer cannot access restricted coupon details")(
    async () => {
      await api.functional.shopping_mall_ai.customer.coupons.at(connection, {
        couponId: restrictedCoupon.id,
      });
    },
  );
}

