 *
 * Business Context: A seller issues a coupon and then accesses its own coupon
 * detail endpoint. As coupon issuing is a privileged operation, this test
 * ensures that the full detail retrieval (GET) returns all relevant coupon
 * fields and enforces RBAC (the coupon is accessible since the requestor is the
 * owner).
 *
 * Steps:
 *
 * 1. Seller creates a coupon via the coupon creation endpoint, ensuring known
 *    ownership and full field coverage.
 * 2. Seller requests full coupon details using the returned couponId via the
 *    seller's detail GET endpoint.
 * 3. Validate that GET response returns all key coupon fields such as type,
 *    status, scope fields (product/channel/seller/applicability), all usage
 *    limits and policy fields match those specified at creation, and assigned
 *    fields (such as customers/products) are returned or null if not assigned
 *    in the coupon scope.
 * 4. Confirm that RBAC is respected (coupon belongs to this seller), and all
 *    returned fields are as expected from creation.
 */
export async function test_api_shopping_mall_ai_test_get_coupon_details_as_seller_for_own_coupon(
  connection: api.IConnection,
) {
  // 1. Seller creates a coupon with specific fields to be easily checked
  const now = new Date();
  const validFrom = new Date(now.getTime() + 60 * 1000).toISOString(); // start in 1 minute
  const validUntil = new Date(
    now.getTime() + 7 * 24 * 3600 * 1000,
  ).toISOString(); // 7 days later
