    code: couponCode,
    type: "fixed", // simple type
    value: 10000,
    min_order_value: 20000,
    max_usage: 25,
    max_usage_per_customer: 2,
    valid_from: validFrom,
    valid_until: validUntil,
    stackable: false,
    // No product/channel: applies to all
  };

  const created = await api.functional.shopping_mall_ai.seller.coupons.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(created);

  // 2. Seller requests coupon detail by ID
  const detail = await api.functional.shopping_mall_ai.seller.coupons.at(
    connection,
    {
      couponId: created.id,
    },
  );
  typia.assert(detail);

  // 3. Validate key coupon fields and ownership
  TestValidator.equals("coupon id matches")(detail.id)(created.id);
  TestValidator.equals("coupon type matches")(detail.type)(createInput.type);
  TestValidator.equals("coupon code matches")(detail.code)(createInput.code);
  TestValidator.equals("coupon value matches")(detail.value)(createInput.value);
  TestValidator.equals("min order value matches")(detail.min_order_value)(
    createInput.min_order_value,
  );
  TestValidator.equals("max usage matches")(detail.max_usage)(
    createInput.max_usage,
  );
  TestValidator.equals("max usage per customer matches")(
    detail.max_usage_per_customer,
  )(createInput.max_usage_per_customer);
  TestValidator.equals("valid_from matches")(detail.valid_from)(
    createInput.valid_from,
  );
  TestValidator.equals("valid_until matches")(detail.valid_until)(
    createInput.valid_until,
  );
  TestValidator.equals("stackable matches")(detail.stackable)(
    createInput.stackable,
  );

  // Ownership (should have seller id matching current session's seller or not null)
  TestValidator.predicate("coupon has seller ID")(
    !!detail.shopping_mall_ai_seller_id,
  );

  // Scope-related
  TestValidator.equals("product scope is null")(
    detail.shopping_mall_ai_product_id,
  )(null);
  TestValidator.equals("channel scope is null")(
    detail.shopping_mall_ai_channel_id,
  )(null);

  // Coupon lifecycle status, created/updated_at present
  TestValidator.predicate("status present and non-empty")(!!detail.status);
  TestValidator.predicate("created_at is date-time")(
    !!detail.created_at && typeof detail.created_at === "string",
  );
  TestValidator.predicate("updated_at is date-time")(
    !!detail.updated_at && typeof detail.updated_at === "string",
  );
}

