 * coupon—regardless of whether it is a seller coupon or platform/global
 * coupon—using the admin API.
 *
 * Business context: Admins require access to all scope of coupons for
 * management and auditing. This test ensures the detail endpoint returns a full
 * coupon object matching the data created, covering issuer distinction, all
 * policy fields, and proper field population.
 *
 * Steps:
 *
 * 1. Create a platform-wide coupon (issuer null, global scope).
 * 2. Create a seller-issued coupon (issuer uuid provided, e.g. random).
 * 3. For each created coupon, call the admin coupon detail GET endpoint.
 * 4. Assert all fields in the returned coupon match the original creation input
 *    and required fields are present, regardless of coupon issuer or scope.
 * 5. Optionally check some outlier fields (e.g. min_order_value nullable, distinct
 *    status, field population for each type)
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_admin_get_coupon_details_for_any_coupon(
  connection: api.IConnection,
) {
  // 1. Create a platform/global coupon (issuer null)
  const globalCouponInput: IShoppingMallAiCoupon.ICreate = {
    shopping_mall_ai_seller_id: null,
    shopping_mall_ai_product_id: null,
    shopping_mall_ai_channel_id: null,
    code: RandomGenerator.alphaNumeric(10),
    type: "fixed",
    value: 5.0,
    min_order_value: null,
    max_usage: 100,
    max_usage_per_customer: 5,
    valid_from: new Date(Date.now() + 1000 * 60).toISOString(),
    valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(),
    stackable: true,
  };
  const globalCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: globalCouponInput,
    });
  typia.assert(globalCoupon);

  // 2. Create a seller coupon
  const sellerCouponInput: IShoppingMallAiCoupon.ICreate = {
    shopping_mall_ai_seller_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_product_id: null,
    shopping_mall_ai_channel_id: null,
    code: RandomGenerator.alphaNumeric(10),
    type: "percent",
    value: 12.5,
    min_order_value: 50,
    max_usage: 200,
    max_usage_per_customer: 2,
    valid_from: new Date(Date.now() + 1000 * 60).toISOString(),
    valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24 * 10).toISOString(),
    stackable: false,
  };
  const sellerCoupon =
    await api.functional.shopping_mall_ai.admin.coupons.create(connection, {
      body: sellerCouponInput,
    });
  typia.assert(sellerCoupon);

  // 3. For each created coupon, retrieve the detail as admin and check all fields
  const coupons = [globalCoupon, sellerCoupon];
  const correspondingInputs = [globalCouponInput, sellerCouponInput];
  for (let i = 0; i < coupons.length; ++i) {
    const input = correspondingInputs[i];
    const coupon = coupons[i];
    const output = await api.functional.shopping_mall_ai.admin.coupons.at(
      connection,
      { couponId: coupon.id },
    );
    typia.assert(output);
    // Check required fields match input, with admin visibility
    TestValidator.equals("id matches")(output.id)(coupon.id);
    TestValidator.equals("code matches")(output.code)(input.code);
    TestValidator.equals("type matches")(output.type)(input.type);
    TestValidator.equals("value matches")(output.value)(input.value);
    TestValidator.equals("stackable matches")(output.stackable)(
      input.stackable,
    );
    TestValidator.equals("issuer matches")(
      output.shopping_mall_ai_seller_id ?? null,
    )(input.shopping_mall_ai_seller_id ?? null);
    TestValidator.equals("product link matches")(
      output.shopping_mall_ai_product_id ?? null,
    )(input.shopping_mall_ai_product_id ?? null);
    TestValidator.equals("channel link matches")(
      output.shopping_mall_ai_channel_id ?? null,
    )(input.shopping_mall_ai_channel_id ?? null);
    TestValidator.equals("min_order_value matches")(
      output.min_order_value ?? null,
    )(input.min_order_value ?? null);
    TestValidator.equals("max_usage matches")(output.max_usage)(
      input.max_usage,
    );
    TestValidator.equals("max_usage_per_customer matches")(
      output.max_usage_per_customer,
    )(input.max_usage_per_customer);
    TestValidator.equals("valid_from matches")(output.valid_from)(
      input.valid_from,
    );
    TestValidator.equals("valid_until matches")(output.valid_until)(
      input.valid_until,
    );
    // Extra: ensure status and audit fields are present (not null/empty)
    TestValidator.predicate("status is populated")(
      typeof output.status === "string" && output.status.length > 0,
    );
    TestValidator.predicate("created_at present")(
      typeof output.created_at === "string" && output.created_at.length > 0,
    );
    TestValidator.predicate("updated_at present")(
      typeof output.updated_at === "string" && output.updated_at.length > 0,
    );
  }
}

