    if (asset.height !== undefined && asset.height !== null)
      TestValidator.predicate("height is int32")(
        Number.isInteger(asset.height),
      );
    if (asset.duration !== undefined && asset.duration !== null)
      TestValidator.predicate("duration is int32")(
        Number.isInteger(asset.duration),
      );
  }
  // 4. Non-admin access forbidden scenario not tested due to lack of such dependencies
}

