/**
 * Validates that a customer can retrieve all items in their order via the
 * customer-facing API.
 *
 * Business Context:
 *
 * - Only the customer who owns an order should be able to list all order items
 *   associated with it.
 * - Items must include the correct product references, quantities, pricing, and
 *   audit timestamps.
 *
 * Workflow Steps:
 *
 * 1. Create a test order as admin for a randomly generated customer/channel
 *    (simulates backend setup).
 * 2. Add two order items to the order via admin endpoint, each referencing
 *    different products/options.
 * 3. Call the customer order-items API for the created order as the owning
 *    customer.
 * 4. Assert the response includes both order items, with data matching the inserts
 *    (product refs, quantities, price, audit fields).
 * 5. Validate audit fields (created_at, updated_at) are valid ISO datetime
 *    strings.
 */
export async function test_api_shopping_mall_ai_test_retrieve_order_items_as_order_owner(
  connection: api.IConnection,
) {
  // 1. Create a test order as admin.
  const testCustomerId = typia.random<string & tags.Format<"uuid">>();
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: testCustomerId,
        shopping_mall_ai_channel_id: channelId,
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Add two items to the order.
  const productId1 = typia.random<string & tags.Format<"uuid">>();
  const productId2 = typia.random<string & tags.Format<"uuid">>();
  const item1 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: productId1,
          price: 4990,
          quantity: 2,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  const item2 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: productId2,
          price: 15900,
          quantity: 1,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(item1);
  typia.assert(item2);

  // 3. Retrieve order items as the owning customer.
  const page =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(page);

  // 4. Assertions: Items are present with expected fields.
  const ids = page.data.map((x) => x.id);
  TestValidator.predicate("item1 present")(ids.includes(item1.id));
  TestValidator.predicate("item2 present")(ids.includes(item2.id));

  const foundItem1 = page.data.find((x) => x.id === item1.id)!;
  const foundItem2 = page.data.find((x) => x.id === item2.id)!;
  TestValidator.equals("item1 product ref")(
    foundItem1.shopping_mall_ai_product_id,
  )(item1.shopping_mall_ai_product_id);
  TestValidator.equals("item1 quantity")(foundItem1.quantity)(item1.quantity);
  TestValidator.equals("item1 price")(foundItem1.price)(item1.price);
  TestValidator.predicate("item1 created_at valid ISO")(
    !!Date.parse(foundItem1.created_at),
  );
  TestValidator.predicate("item1 updated_at valid ISO")(
    !!Date.parse(foundItem1.updated_at),
  );

  TestValidator.equals("item2 product ref")(
    foundItem2.shopping_mall_ai_product_id,
  )(item2.shopping_mall_ai_product_id);
  TestValidator.equals("item2 quantity")(foundItem2.quantity)(item2.quantity);
  TestValidator.equals("item2 price")(foundItem2.price)(item2.price);
  TestValidator.predicate("item2 created_at valid ISO")(
    !!Date.parse(foundItem2.created_at),
  );
  TestValidator.predicate("item2 updated_at valid ISO")(
    !!Date.parse(foundItem2.updated_at),
  );
}

