import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IPageIShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";

/**
 * Validates that an admin can retrieve all items belonging to an order with
 * correct details.
 *
 * This test ensures end-to-end integrity for admin order management workflows:
 *
 * 1. Creates a new order as admin.
 * 2. Adds multiple (3) items to the order, including different products, quantity,
 *    and with/without a product option.
 * 3. Retrieves all order items for the order.
 * 4. Asserts that all items are returned and their data matches what was created:
 *    product IDs, option IDs, price, quantity, status, and audit timestamps.
 *
 * Steps:
 *
 * 1. Create a new order via admin API using a random channel id and 'pending'
 *    status.
 * 2. Create three order items for the order, mixing null and non-null option ids,
 *    random prices, quantities, and active status.
 * 3. Retrieve the order's items using the admin orderItems index endpoint.
 * 4. Assert all created items are returned, matching all details and audit fields.
 */
export async function test_api_shopping_mall_ai_admin_orders_test_admin_can_retrieve_all_order_items(
  connection: api.IConnection,
) {
  // 1. Create a new order as admin
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      },
    },
  );
  typia.assert(order);

  // 2. Add multiple items to the order (3 items, some with product_option_id=null)
  const itemInputs: IShoppingOrderItem.ICreate[] = ArrayUtil.repeat(3)((i) => ({
    shopping_mall_ai_order_id: order.id,
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_product_option_id:
      i === 0 ? null : typia.random<string & tags.Format<"uuid">>(),
    price: Number(
      typia
        .random<number & tags.JsonSchemaPlugin<{ format: "double" }>>()
        .toFixed(2),
    ),
    quantity: typia.random<number & tags.Type<"int32">>(),
    status: "active",
  }));

  const createdItems: IShoppingOrderItem[] = [];
  for (const input of itemInputs) {
    const created =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: input,
        },
      );
    typia.assert(created);
    createdItems.push(created);
  }

  // 3. Retrieve all items for this order as admin
  const page =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(page);

  // 4. Verify that all created items are present and details match
  TestValidator.equals("all items present")(page.data.length)(
    createdItems.length,
  );
  for (const created of createdItems) {
    const found = page.data.find((item) => item.id === created.id);
    TestValidator.predicate("item present in results")(!!found);
    if (!found) continue;
    TestValidator.equals("order id")(found.shopping_mall_ai_order_id)(
      created.shopping_mall_ai_order_id,
    );
    TestValidator.equals("product id")(found.shopping_mall_ai_product_id)(
      created.shopping_mall_ai_product_id,
    );
    TestValidator.equals("option id")(found.shopping_mall_ai_product_option_id)(
      created.shopping_mall_ai_product_option_id,
    );
