import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced order item search using SKU (product ID) and item status
 * filters.
 *
 * This test covers a real dashboard scenario where a customer (or admin with
 * customer context) wants to search for items in their order by criteria like
 * SKU/product and status (e.g., 'active', 'returned').
 *
 * Step-by-step process:
 *
 * 1. Create a new order as admin (simulates backend or admin workflow).
 * 2. Add several order items with unique product IDs and various statuses
 *    ('active', 'returned', 'cancelled').
 * 3. As the customer, perform searches for items by specific SKU/product ID and
 *    status, with pagination.
 * 4. Verify that the returned items exactly match the search criteria – correct
 *    SKU, correct status, correct page, with correct counts.
 * 5. Repeat for a product/SKU that does not exist, and test edge pagination cases.
 *
 * Validations:
 *
 * - Only matching items returned; unrelated items not returned.
 * - Pagination counts and returned items match expectations.
 */
export async function test_api_shopping_mall_ai_test_advanced_search_order_items_by_sku_and_status(
  connection: api.IConnection,
) {
  // 1. Create a new order as admin
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending", // start as pending
      },
    },
  );
  typia.assert(order);

  // 2. Add several order items (3 items, 2 SKUs, different statuses)
  const sku1 = typia.random<string & tags.Format<"uuid">>();
  const sku2 = typia.random<string & tags.Format<"uuid">>();

  const item1 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: sku1,
          price: 100,
          quantity: 1,
          status: "active",
        },
      },
    );
  const item2 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: sku2,
          price: 200,
          quantity: 2,
          status: "returned",
        },
      },
    );
  const item3 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: sku1,
          price: 150,
          quantity: 1,
          status: "cancelled",
        },
      },
    );
  typia.assert(item1);
  typia.assert(item2);
  typia.assert(item3);

  // 3. Search for SKU1 and status "active"
  const resultActive =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_product_id: sku1,
          status: "active",
        },
      },
    );
  typia.assert(resultActive);
  // Only item1 matches this filter
  TestValidator.equals("active sku1 count")(resultActive.data.length)(1);
  TestValidator.equals("active sku1, id matches")(resultActive.data[0].id)(
    item1.id,
  );

  // 4. Search for status "returned" only
  const resultReturned =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {
          status: "returned",
        },
      },
    );
  typia.assert(resultReturned);
  // Only item2 matches this filter
  TestValidator.equals("returned count")(resultReturned.data.length)(1);
  TestValidator.equals("returned, id matches")(resultReturned.data[0].id)(
    item2.id,
  );

  // 5. Pagination: limit = 1, page 2 (should return 2nd item out of 3 total)
  const resultPage2 =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {
          page: 2,
          limit: 1,
        },
      },
    );
  typia.assert(resultPage2);
  TestValidator.equals("pagination pages")(resultPage2.pagination.pages)(3);
  TestValidator.equals("pagination returns one item")(resultPage2.data.length)(
    1,
  );
  // For robustness, we could check the ID too, but any of items 1-3 could be order

  // 6. Search for non-existent product id (should return empty)
  const fakeSku = typia.random<string & tags.Format<"uuid">>();
  const resultNone =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_product_id: fakeSku,
        },
      },
    );
  typia.assert(resultNone);
  TestValidator.equals("no results for fake sku")(resultNone.data.length)(0);
}

