 *
 * This validates the enforcement of RBAC by ensuring that a non-admin actor
 * (such as a seller or customer) cannot delete coupons through an admin
 * endpoint. The test proceeds as follows:
 *
 * 1. Create a coupon with admin privileges (using the provided connection)
 * 2. Simulate a non-admin connection (imitate seller or customer role) by mutating
 *    the header/token inline
 * 3. Attempt to delete the coupon as a non-admin and expect a permission-denied
 *    error
 * 4. (Optionally) If a coupon GET endpoint existed, verify that the coupon was not
 *    deleted; otherwise skip
 * 5. Clean up: delete the coupon as admin
 *
 * Notes:
 *
 * - If there is no endpoint for real role switching, a simulated connection is
 *   constructed.
 * - If there is no endpoint to GET or list the coupon for existence verification,
 *   step 4 is omitted.
 * - The initial connection is assumed to represent an admin session.
 */
export async function test_api_shopping_mall_ai_admin_coupons_test_delete_coupon_with_insufficient_permission_fails(
  connection: api.IConnection,
) {
  // 1. Create a coupon as admin
  const coupon = await api.functional.shopping_mall_ai.admin.coupons.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        type: "fixed",
        value: 1000,
        max_usage: 100,
        max_usage_per_customer: 1,
        valid_from: new Date().toISOString(),
