  //    In a real system, you would perform a login as seller or customer to get a true token.
  //    Here, we mimic the role by cloning the connection and changing the Authorization header.
  const nonAdminConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: "Bearer NON_ADMIN_TOKEN_PLACEHOLDER",
    },
  };

  // 3. Attempt to delete the coupon as non-admin and expect a permission-denied error
  await TestValidator.error("non-admin cannot delete coupon")(() =>
    api.functional.shopping_mall_ai.admin.coupons.erase(nonAdminConnection, {
