  await api.functional.shopping_mall_ai.admin.coupons.erase(connection, {
    couponId: coupon.id,
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IPageIShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCouponEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCouponEvent";

/**
 * Validates listing of coupon event history for a seller's own coupon.
 *
 * Business Context: A seller, having created a coupon, should be able to record
 * and subsequently retrieve the full audit/history of that coupon's event
 * lifecycle (such as issuance, redemptions), including all metadata and event
 * fields.
 *
 * Steps:
 *
 * 1. Create a coupon as the seller.
 * 2. Generate multiple coupon events (e.g., 'issued', 'redeemed') for that coupon
 *    using the event creation endpoint.
 * 3. Perform a GET request as seller to retrieve all coupon events for the coupon.
 * 4. Assert all events are returned with correct, complete fields and associated
 *    metadata, matching what was written.
 * 5. Optional edge case: Confirm that another coupon (if present in the system)
 *    does not have its events visible here.
 */
export async function test_api_shopping_mall_ai_test_list_coupon_events_for_own_coupon(
  connection: api.IConnection,
) {
  // 1. Create a seller coupon
  const nowISO = new Date().toISOString();
  const coupon = await api.functional.shopping_mall_ai.seller.coupons.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        type: "fixed",
        value: 1000,
        min_order_value: 5000,
        max_usage: 10,
        max_usage_per_customer: 2,
        valid_from: nowISO,
        valid_until: new Date(
          Date.now() + 1000 * 60 * 60 * 24 * 7,
        ).toISOString(), // +7 days
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    },
  );
  typia.assert(coupon);

  // 2. Generate multiple coupon events for that coupon
  const eventsCreated = await Promise.all([
    api.functional.shopping_mall_ai.seller.coupons.couponEvents.create(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          event_type: "issued",
          occurred_at: nowISO,
          details: "Coupon issued to system",
        } satisfies IShoppingMallAiCouponEvent.ICreate,
      },
    ),
    api.functional.shopping_mall_ai.seller.coupons.couponEvents.create(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          event_type: "redeemed",
          occurred_at: new Date(Date.now() + 1000 * 60 * 60 * 1).toISOString(), // 1 hour later
          details: "Coupon redeemed by user",
        } satisfies IShoppingMallAiCouponEvent.ICreate,
      },
    ),
  ]);
  eventsCreated.forEach((event) => typia.assert(event));

  // 3. Retrieve all coupon events for the coupon
  const result =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.index(
      connection,
      { couponId: coupon.id },
    );
  typia.assert(result);
  TestValidator.predicate("All events for the coupon should be listed")(
    result.data.length >= 2,
  );

  // 4. Confirm all events are present and fields are correct
  for (const created of eventsCreated) {
    TestValidator.predicate("Event must be present in result")(
      result.data.some((e) => e.id === created.id),
    );
    const matched = result.data.find((e) => e.id === created.id);
    if (matched) {
      TestValidator.equals("Coupon association")(
        matched.shopping_mall_ai_coupon_id,
      )(coupon.id);
      TestValidator.equals("Event type matches")(matched.event_type)(
        created.event_type,
      );
      TestValidator.equals("Occurred at matches")(matched.occurred_at)(
        created.occurred_at,
      );
      TestValidator.equals("Details")(matched.details)(created.details);
    }
  }
}

