        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    },
  );
  typia.assert(coupon);

  // 2. Attempt to list coupon events on behalf of a seller who does not own the coupon
  await TestValidator.error("non-owner seller cannot list events for coupon")(
    () =>
      api.functional.shopping_mall_ai.seller.coupons.couponEvents.index(
        connection,
        {
          couponId: coupon.id,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
