import type { IShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCouponEvent";

/**
 * Validate that an admin can retrieve all coupon event records for any coupon,
 * including those created by sellers.
 *
 * Business context:
 *
 * - Coupon events (issuance, redemption, etc.) are stored as audit/history for
 *   compliance and analytics.
 * - Admins must be able to view a full log of coupon events, regardless of actor,
 *   for monitoring, troubleshooting, and auditing.
 *
 * The test process covers:
 *
 * 1. Create a coupon as a seller (to mimic real business coupon lifecycle).
 * 2. Create several distinct events for that coupon (issuance to user, redemption,
 *    etc.).
 * 3. As admin, fetch all coupon event logs by couponId using the admin endpoint.
 * 4. Validate that all events created are present and match details for type,
 *    actor, etc.
 * 5. Check that rich detail is returned in the events (type, timestamps,
 *    references).
 */
export async function test_api_shopping_mall_ai_test_admin_lists_coupon_events_for_any_coupon(
  connection: api.IConnection,
) {
  // Step 1: Seller creates a coupon
  const coupon: IShoppingMallAiCoupon =
    await api.functional.shopping_mall_ai.seller.coupons.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        type: "fixed",
        value: 5000,
        min_order_value: 20000,
        max_usage: 10,
        max_usage_per_customer: 2,
        valid_from: new Date(Date.now() - 10000).toISOString(),
        valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
        stackable: true,
      } satisfies IShoppingMallAiCoupon.ICreate,
    });
  typia.assert(coupon);

  // Step 2: Seller adds multiple event logs (issuance+redemption)
  const eventTypes = ["issued", "redeemed"];
  const generatedEvents: IShoppingMallAiCouponEvent[] = [];
  for (const etype of eventTypes) {
    const event: IShoppingMallAiCouponEvent =
      await api.functional.shopping_mall_ai.seller.coupons.couponEvents.create(
        connection,
        {
          couponId: coupon.id,
          body: {
            shopping_mall_ai_coupon_id: coupon.id,
            event_type: etype,
            occurred_at: new Date().toISOString(),
            details: `${etype} via E2E test`,
          } satisfies IShoppingMallAiCouponEvent.ICreate,
        },
      );
    typia.assert(event);
    generatedEvents.push(event);
  }

  // Step 3: Admin lists all event records for this coupon
  const page: IPageIShoppingMallAiCouponEvent =
    await api.functional.shopping_mall_ai.admin.coupons.couponEvents.index(
      connection,
      {
        couponId: coupon.id,
      },
    );
  typia.assert(page);

  // Step 4: Validate that all events are returned with correct event types and details
  for (const created of generatedEvents) {
    const found = page.data.find((e) => e.id === created.id);
    TestValidator.predicate("event is present and identical")(
      !!found &&
        found.event_type === created.event_type &&
        found.details === created.details &&
        found.shopping_mall_ai_coupon_id === coupon.id,
    );
  }
  TestValidator.equals("number of events fetched matches")(page.data.length)(
    generatedEvents.length,
  );
}

