import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCouponEvent";
import type { IPageIShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCouponEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search and filter logic for coupon event history from the
 * seller perspective.
 *
 * This test covers all key business workflows:
 *
 * 1. A new coupon is created by the seller.
 * 2. The test creates a set of historical coupon events attached to the coupon,
 *    ensuring diversity:
 *
 *    - At least three different event_type values (e.g., 'issued', 'redeemed',
 *         'expired')
 *    - At least one event has a customer ID set (for customer filtering)
 *    - Occurred_at timestamps are spread to allow time range filtering
 *    - Details field is varied
 * 3. It performs and validates the following:
 *
 *    - Fetching all events, asserting all created records are returned
 *    - Filtering by event_type ('redeemed')
 *    - Filtering by customer ID (matches the created 'redeemed' event)
 *    - Filtering using a narrow time window (should only return the 'expired' event)
 *    - Testing pagination (with limit=2, verifying multi-page results)
 *    - Filtering for a non-existent event_type and customer (should yield empty
 *         results)
 */
export async function test_api_shopping_mall_ai_test_search_filter_coupon_events_for_owned_coupon(
  connection: api.IConnection,
) {
  // 1. Create a coupon for the seller
  const coupon = await api.functional.shopping_mall_ai.seller.coupons.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        type: "fixed",
        value: 1000,
        min_order_value: 10000,
        max_usage: 20,
        max_usage_per_customer: 5,
        valid_from: new Date(Date.now() - 60 * 60 * 1000).toISOString(), // Valid from 1 hour ago
        valid_until: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // Valid until 1 day from now
        stackable: false,
      } satisfies IShoppingMallAiCoupon.ICreate,
    },
  );
  typia.assert(coupon);

  // 2. Create several coupon events with variety for filter testing
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const events = [
    // Event 1: issue event, 30 mins ago
    {
      event_type: "issued",
      occurred_at: new Date(Date.now() - 30 * 60 * 1000).toISOString(),
      details: "Issued to all",
    },
    // Event 2: redeemed event with a customer, 20 mins ago
    {
      event_type: "redeemed",
      shopping_mall_ai_customer_id: customerId,
      occurred_at: new Date(Date.now() - 20 * 60 * 1000).toISOString(),
      details: "Redeemed by customer",
    },
    // Event 3: expired event, 10 mins ago
    {
      event_type: "expired",
      occurred_at: new Date(Date.now() - 10 * 60 * 1000).toISOString(),
      details: "Expired automatically",
    },
  ];
  const createdEvents: IShoppingMallAiCouponEvent[] = [];
  for (const e of events) {
    const event =
      await api.functional.shopping_mall_ai.seller.coupons.couponEvents.create(
        connection,
        {
          couponId: coupon.id,
          body: {
            shopping_mall_ai_coupon_id: coupon.id,
            event_type: e.event_type,
            occurred_at: e.occurred_at,
            shopping_mall_ai_customer_id: e.shopping_mall_ai_customer_id,
            details: e.details,
          },
        },
      );
    typia.assert(event);
    createdEvents.push(event);
  }

  // 3. Fetch all events for this coupon and assert all are present
  const allResult =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: { shopping_mall_ai_coupon_id: coupon.id },
      },
    );
  typia.assert(allResult);
  TestValidator.equals("all events")(allResult.data.length)(3);
  for (const ev of createdEvents) {
    TestValidator.predicate(`event ${ev.event_type} (${ev.id}) present`)(
      allResult.data.some((d) => d.id === ev.id),
    );
  }

  // 4. Filter by event_type: only 'redeemed'
  const redeemedResult =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: { shopping_mall_ai_coupon_id: coupon.id, event_type: "redeemed" },
      },
    );
  typia.assert(redeemedResult);
  TestValidator.equals("only one redeemed")(redeemedResult.data.length)(1);
  TestValidator.equals("event_type")(redeemedResult.data[0].event_type)(
    "redeemed",
  );
  TestValidator.equals("customer id")(
    redeemedResult.data[0].shopping_mall_ai_customer_id,
  )(customerId);

  // 5. Filter by customer_id (should return only the 'redeemed' event)
  const customerResult =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          shopping_mall_ai_customer_id: customerId,
        },
      },
    );
  typia.assert(customerResult);
  TestValidator.equals("by customer_id")(customerResult.data.length)(1);
  TestValidator.equals("customer id")(
    customerResult.data[0].shopping_mall_ai_customer_id,
  )(customerId);

  // 6. Filter by occurred_at_from/occurred_at_to (should only match the 'expired' event)
  const from = new Date(Date.now() - 15 * 60 * 1000).toISOString(); // 15 min ago
  const to = new Date(Date.now() - 5 * 60 * 1000).toISOString(); // 5 min ago
  const timeResult =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          occurred_at_from: from,
          occurred_at_to: to,
        },
      },
    );
  typia.assert(timeResult);
  TestValidator.equals("filtered by time")(timeResult.data.length)(1);
  TestValidator.equals("event_type")(timeResult.data[0].event_type)("expired");

  // 7. Pagination test
  const page1 =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: { shopping_mall_ai_coupon_id: coupon.id, page: 1, limit: 2 },
      },
    );
  typia.assert(page1);
  TestValidator.equals("page 1: two events")(page1.data.length)(2);
  TestValidator.equals("current page")(page1.pagination.current)(1);
  if (page1.pagination.pages > 1) {
    const page2 =
      await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
        connection,
        {
          couponId: coupon.id,
          body: { shopping_mall_ai_coupon_id: coupon.id, page: 2, limit: 2 },
        },
      );
    typia.assert(page2);
    TestValidator.equals("current page 2")(page2.pagination.current)(2);
    TestValidator.predicate("page 2 not empty")(page2.data.length > 0);
  }

  // 8. Non-existent event_type or customer_id yields empty results
  const noneType =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          event_type: "not_exist",
        },
      },
    );
  typia.assert(noneType);
  TestValidator.equals("empty unknown event type")(noneType.data.length)(0);

  const noneCustomer =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.search(
      connection,
      {
        couponId: coupon.id,
        body: {
          shopping_mall_ai_coupon_id: coupon.id,
          shopping_mall_ai_customer_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        },
      },
    );
  typia.assert(noneCustomer);
  TestValidator.equals("empty unknown customer")(noneCustomer.data.length)(0);
}

