import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiShipmentList } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipmentList";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";
import type { IPageIShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiShipment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced shipment search for a seller's order using filters,
 * pagination, and access control.
 *
 * 1. Use the ordinary list API to fetch all shipments for a known seller order
 *    (setup baseline data).
 * 2. With the orderId, perform PATCH search with realistic filters:
 *
 *    - Filter by status (if available)
 *    - Filter by provider (if available, only if present)
 *    - Filter by date range covering at least one shipment
 *    - Use pagination (set limit=1) and verify correct shipment(s) are returned
 *    - Use sorting by 'created_at' or 'updated_at', test both asc and desc
 * 3. Validate all returned shipments have the correct orderId and match search
 *    criteria (status, provider, date)
 * 4. Confirm pagination info matches result set
 * 5. Test security: Attempt to search using a valid but unrelated orderId
 *    (simulate unauthorized attempt). Ensure shipments are empty or access is
 *    denied as required
 * 6. Confirm sensitive shipment information for unrelated orders is not exposed
 */
export async function test_api_shopping_mall_ai_test_search_order_shipments_with_valid_filters_for_seller(
  connection: api.IConnection,
) {
  // 1. Setup: Fetch all shipments for a known seller order
  const orderId: string = typia.random<string & tags.Format<"uuid">>();
  const indexResult =
    await api.functional.shopping_mall_ai.seller.orders.shipments.index(
      connection,
      {
        orderId,
      },
    );
  typia.assert(indexResult);

  // If there are no shipments, skip rest of function (can't validate filter, pagination, etc)
  TestValidator.predicate("at least one shipment exists")(
    indexResult.shipments.length > 0,
  );
  const baseShipment = indexResult.shipments[0];

  // 2. Advanced search: Filter by status, provider, date range, pagination, sorting
  const advancedSearchBody: IShoppingMallAiShipment.IRequest = {
    shopping_mall_ai_order_id: orderId,
    ...(baseShipment.status && { status: baseShipment.status }),
    ...(baseShipment.provider ? { provider: baseShipment.provider } : {}),
    created_from: baseShipment.created_at,
    created_to: baseShipment.updated_at,
    page: 1,
    limit: 1,
    sort_by: "created_at",
    sort_order: "asc",
  };
  const searchResult =
    await api.functional.shopping_mall_ai.seller.orders.shipments.search(
      connection,
      {
        orderId,
        body: advancedSearchBody,
      },
    );
  typia.assert(searchResult);
  // 3. Validate filters, pagination, sorting
  for (const shipment of searchResult.data) {
    TestValidator.equals("order id matches")(
      shipment.shopping_mall_ai_order_id,
    )(orderId);
    if (baseShipment.status)
      TestValidator.equals("status matches")(shipment.status)(
        baseShipment.status,
      );
    if (baseShipment.provider)
      TestValidator.equals("provider matches")(shipment.provider)(
        baseShipment.provider,
      );
    TestValidator.predicate("created_at in range")(
      shipment.created_at >= baseShipment.created_at &&
        shipment.created_at <= baseShipment.updated_at,
    );
  }
  TestValidator.equals("pagination: limit")(searchResult.pagination.limit)(1);

  // 4. Security check: Try searching using an unrelated orderId (simulate unauthorized access attempt)
  const unrelatedOrderId: string = typia.random<string & tags.Format<"uuid">>();
  const otherSearchResult =
    await api.functional.shopping_mall_ai.seller.orders.shipments.search(
      connection,
      {
        orderId: unrelatedOrderId,
        body: {
          shopping_mall_ai_order_id: unrelatedOrderId,
          limit: 1,
          page: 1,
        },
      },
    );
  typia.assert(otherSearchResult);
  // Should not expose unrelated shipments
  TestValidator.equals("no shipments for unrelated order")(
    otherSearchResult.data.length,
  )(0);
}

