/**
 * Verify robust input validation and error handling in the shipment search
 * endpoint for a seller order by submitting intentionally invalid filters.
 *
 * Business context: This test ensures the system properly rejects malformed or
 * logically impossible shipment filter criteria (such as invalid status,
 * impossible date ranges, or incorrectly formatted fields), rather than
 * returning data or failing silently. It also checks that no records are
 * returned when input is invalid, and appropriate errors are surfaced to
 * clients.
 *
 * Steps:
 *
 * 1. Construct a random orderId (not tied to a real order for maximum
 *    error-robustness).
 * 2. Create a request body for IShoppingMallAiShipment.IRequest with one or more
 *    clear invalid filters:
 *
 * - Use an impossible date range (created_from later than created_to)
 * - Use an invalid shipment status (not an allowed value, e.g., "NOT_A_STATUS")
 * - Use a badly formatted orderId (e.g., malformed UUID string)
 * - Optionally, set page/limit to invalid numbers (e.g., negative or zero)
 *
 * 3. For each invalid request, call
 *    api.functional.shopping_mall_ai.seller.orders.shipments.search and assert
 *    that:
 *
 *    - An error is thrown (API returns error)
 *    - No records are returned if the request is accepted (edge case for empty set)
 * 4. If API accepts an invalid request but returns data, assert a failure (because
 *    invalid filters must never return real data).
 * 5. Edge case: Attempt with non-existent, but well-formed UUID and reasonable
 *    filters, verify it returns an empty set not an error (to contrast
 *    malformed vs. well-formed but non-existent).
 */
export async function test_api_shopping_mall_ai_seller_orders_shipments_test_search_order_shipments_with_invalid_filters_returns_error(
  connection: api.IConnection,
) {
  // 1. Impossible date range: created_from after created_to
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const invalidDateFrom = "2099-12-31T23:59:59.000Z";
  const invalidDateTo = "1999-01-01T00:00:00.000Z";
  await TestValidator.error("impossible date range for shipment search")(
    async () => {
      await api.functional.shopping_mall_ai.seller.orders.shipments.search(
        connection,
        {
          orderId,
          body: {
            created_from: invalidDateFrom,
            created_to: invalidDateTo,
          } satisfies IShoppingMallAiShipment.IRequest,
        },
      );
    },
  );

  // 2. Invalid shipment status
  await TestValidator.error("invalid shipment status should error")(
    async () => {
      await api.functional.shopping_mall_ai.seller.orders.shipments.search(
        connection,
        {
          orderId,
          body: {
            status: "NOT_A_STATUS",
          } satisfies IShoppingMallAiShipment.IRequest,
        },
      );
    },
  );

  // 3. Malformed orderId
  await TestValidator.error("malformed orderId should error")(async () => {
    await api.functional.shopping_mall_ai.seller.orders.shipments.search(
      connection,
      {
        orderId: "not-a-uuid" as string & tags.Format<"uuid">,
        body: {},
      },
    );
  });

  // 4. Negative page or zero limit
  await TestValidator.error("invalid pagination fields should error")(
    async () => {
      await api.functional.shopping_mall_ai.seller.orders.shipments.search(
        connection,
        {
          orderId,
          body: {
            page: -1,
            limit: 0,
          } satisfies IShoppingMallAiShipment.IRequest,
        },
      );
    },
  );

  // 5. Well-formed but non-existent orderId should NOT error, just empty data
  const output =
    await api.functional.shopping_mall_ai.seller.orders.shipments.search(
      connection,
      {
        orderId,
        body: {},
      },
    );
  typia.assert(output);
  TestValidator.equals("non-existent orderId returns empty data")(
    output.data.length,
  )(0);
}

