import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiShipmentList } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipmentList";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";
import type { IPageIShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiShipment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin ability to search and filter shipments for a specific order
 * with various criteria.
 *
 * This test verifies that the PATCH
 * /shopping-mall-ai/admin/orders/{orderId}/shipments endpoint correctly
 * implements advanced search and pagination for shipments tied to an order. It
 * checks that filters like status, provider, date ranges, and sorting return
 * the correct shipments, that pagination boundaries work, and that filter
 * behavior is reliable under various real-world scenarios. The test establishes
 * a baseline by fetching all shipments via the GET endpoint and then compares
 * results returned for various search queries using the PATCH endpoint.
 *
 * Test Steps:
 *
 * 1. Retrieve the full list of shipments for a randomly selected order via GET to
 *    establish ground truth.
 * 2. Perform a search using PATCH with no filters (should match the full list,
 *    paginated if necessary).
 * 3. For each status value and provider in the retrieved set, search using that
 *    value as a filter and ensure results are correct subsets.
 * 4. Query with created_from / created_to (date range) filters and ensure only
 *    correctly ranged shipments are returned.
 * 5. Test sorting by created_at both ascending and descending and verify order of
 *    returned records.
 * 6. Test pagination (limit/page) to verify correct record partitioning across
 *    pages.
 * 7. Test with a non-existent status/provider to ensure empty result set is
 *    returned.
 */
export async function test_api_shopping_mall_ai_admin_orders_shipments_test_admin_search_order_shipments_with_various_criteria(
  connection: api.IConnection,
) {
  // 1. Establish baseline: fetch all shipments for a test order
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const baseline: IShoppingMallAiShipmentList =
    await api.functional.shopping_mall_ai.admin.orders.shipments.index(
      connection,
      { orderId },
    );
  typia.assert(baseline);
  const allShipments = baseline.shipments;

  // 2. Search with no filters (should match allShipments, possibly paginated)
  const pageSize = 3;
  const noFilterPage =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      {
        orderId,
        body: { limit: pageSize },
      },
    );
  typia.assert(noFilterPage);
  TestValidator.predicate("no-filter results subset of all shipments")(
    noFilterPage.data.every((x) => allShipments.some((y) => x.id === y.id)),
  );
  TestValidator.equals("records count matches baseline")(
    noFilterPage.pagination.records,
  )(allShipments.length);

  // 3. Filter by each unique status and provider
  const statuses = Array.from(
    new Set(allShipments.map((x) => x.status).filter(Boolean)),
  );
  for (const status of statuses) {
    const statusFiltered =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          orderId,
          body: { status },
        },
      );
    typia.assert(statusFiltered);
    TestValidator.predicate(`status filter: ${status}`)(
      statusFiltered.data.every((x) => x.status === status),
    );
    if (allShipments.some((x) => x.status === status)) {
      TestValidator.predicate(`status filter yields expected subset`)(
        statusFiltered.data.every((ship) =>
          allShipments.some((as) => as.id === ship.id),
        ),
      );
    }
  }
  // Correction: only use providers that are non-null/undefined (string)
  const providers = Array.from(
    new Set(
      allShipments
        .map((x) => x.provider)
        .filter((prov): prov is string => typeof prov === "string"),
    ),
  );
  for (const provider of providers) {
    const providerFiltered =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          orderId,
          body: { provider },
        },
      );
    typia.assert(providerFiltered);
    TestValidator.predicate(`provider filter: ${provider}`)(
      providerFiltered.data.every((x) => x.provider === provider),
    );
  }

  // 4. Filter by date range
  if (allShipments.length > 0) {
    const sorted = [...allShipments].sort((a, b) =>
      a.created_at.localeCompare(b.created_at),
    );
    const from = sorted[0].created_at;
    const to = sorted[sorted.length - 1].created_at;
    // Tight window – should include first shipment only
    const fromFilter =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          orderId,
          body: { created_from: from, created_to: from },
        },
      );
    typia.assert(fromFilter);
    TestValidator.predicate("created_from/to filter")(
      fromFilter.data.every((x) => x.created_at >= from && x.created_at < from),
    );
    // Open window – should yield all or close to all shipments
    const openFilter =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          orderId,
          body: { created_from: from, created_to: to },
        },
      );
    typia.assert(openFilter);
    TestValidator.predicate("created_from/to full span")(
      openFilter.data.every((x) => x.created_at >= from && x.created_at < to),
    );
  }

  // 5. Sort by created_at ascending/descending
  for (const order of ["asc", "desc"] as const) {
    const sortedResult =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          orderId,
          body: { sort_by: "created_at", sort_order: order },
        },
      );
    typia.assert(sortedResult);
    const dates = sortedResult.data.map((x) => x.created_at);
    const isOrdered =
      order === "asc"
        ? dates.every((dt, i, arr) => i === 0 || arr[i - 1] <= dt)
        : dates.every((dt, i, arr) => i === 0 || arr[i - 1] >= dt);
    TestValidator.predicate(`sort order: ${order}`)(isOrdered);
  }

  // 6. Pagination: ensure partitioning is correct
  if (allShipments.length > pageSize) {
    const p1 =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        { orderId, body: { limit: pageSize, page: 1 } },
      );
    const p2 =
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        { orderId, body: { limit: pageSize, page: 2 } },
      );
    typia.assert(p1);
    typia.assert(p2);
    TestValidator.notEquals("pagination pages do not overlap")(
      p1.data.map((x) => x.id),
    )(p2.data.map((x) => x.id));
    // All ids in both pages form a subset of all shipments
    TestValidator.predicate("pagination IDs in allShipments")(
      [...p1.data.map((x) => x.id), ...p2.data.map((x) => x.id)].every((id) =>
        allShipments.some((s) => s.id === id),
      ),
    );
  }

  // 7. Filter with non-existent status/provider yields empty set
  const noneStatus = "__non_existent_status_value__";
  const noneStatRes =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: { status: noneStatus } },
    );
  typia.assert(noneStatRes);
  TestValidator.equals("non-existent status yields empty")(
    noneStatRes.data.length,
  )(0);

  const noneProvider = "__non_existent_provider__";
  const noneProvRes =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: { provider: noneProvider } },
    );
  typia.assert(noneProvRes);
  TestValidator.equals("non-existent provider yields empty")(
    noneProvRes.data.length,
  )(0);
}

