) {
  // 1. Malformed orderId (not a UUID): should trigger input validation error
  await TestValidator.error("invalid orderId format returns validation error")(
    async () => {
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          // This is intentionally not a UUID string; will fail format validation early
          orderId: "bad-order-id-format" as unknown as string &
            tags.Format<"uuid">,
          body: {},
        },
      );
    },
  );

  // 2. Well-formed, random (non-existent) UUID orderId: should trigger not-found error
  await TestValidator.error("non-existent orderId returns not-found error")(
    async () => {
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        {
          // This generates a random UUID that does not exist in the system.
          orderId: typia.random<string & tags.Format<"uuid">>(),
          body: {},
        },
      );
    },
  );

  // In both cases, no shipment data should be leaked even upon failure
}

