import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";
import type { IPageIShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiShipment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test extreme/boundary-case pagination handling for the order shipment search
 * API as an admin.
 *
 * This test targets the /shopping-mall-ai/admin/orders/{orderId}/shipments
 * PATCH endpoint. It ensures that exotic pagination values (zero, negative,
 * excessively high, or omitted settings) are handled safely—returning
 * boundary-clamped output, empty arrays, or runtime errors as per contract.
 * This guards against unhandled edge cases and unsafe pagination logic in
 * shipment search workflow.
 *
 * Steps:
 *
 * 1. Prepare a random UUID as orderId for endpoint path param (real existence
 *    isn’t critical here; this is a structure/parameter edge-case test).
 * 2. Search with page=0 (should clamp to page=1 or be handled safely).
 * 3. Search with page=-3 (should throw error or handle gracefully).
 * 4. Search with a very large page value (e.g., 999999) expecting an empty result
 *    set (beyond available data).
 * 5. Search with limit=0 (no results expected; API should not crash).
 * 6. Search with negative limit (should trigger an error or be handled
 *    gracefully).
 * 7. Search with both pagination fields omitted (should use built-in defaults,
 *    e.g., page=1, limit=100).
 * 8. After each call, validate structure, error, array length, pagination
 *    coherence, or error response as appropriate.
 */
export async function test_api_shopping_mall_ai_test_admin_order_shipment_search_with_extreme_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare a random valid orderId (UUID format)
  const orderId = typia.random<string & tags.Format<"uuid">>();

  // 2. Search with page=0 (should handle as first page or clamp, but not error)
  const result_page0 =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      {
        orderId,
        body: { page: 0, limit: 10 },
      },
    );
  typia.assert(result_page0);
  TestValidator.predicate("page clamped or empty or handled")(
    result_page0.pagination.current === 0 ||
      result_page0.pagination.current === 1,
  );

  // 3. Search with negative page (should trigger error or be handled safely)
  await TestValidator.error("negative page gives error or handled")(
    async () => {
      await api.functional.shopping_mall_ai.admin.orders.shipments.search(
        connection,
        { orderId, body: { page: -3, limit: 10 } },
      );
    },
  );

  // 4. Search with very high page (expect empty data[] array, but not crash)
  const result_high_page =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: { page: 999999, limit: 10 } },
    );
  typia.assert(result_high_page);
  TestValidator.equals("empty on too-high page")(result_high_page.data.length)(
    0,
  );
  TestValidator.predicate("valid pages field")(
    result_high_page.pagination.pages >= 1,
  );

  // 5. Search with limit=0 (expect data empty but API does not error)
  const result_limit0 =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: { page: 1, limit: 0 } },
    );
  typia.assert(result_limit0);
  TestValidator.equals("no data returned when limit=0")(
    result_limit0.data.length,
  )(0);

  // 6. Search with negative limit (expect error)
  await TestValidator.error("negative limit triggers error")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: { page: 1, limit: -5 } },
    );
  });

  // 7. Search with missing page/limit (should use default pagination e.g. page=1, limit=100)
  const result_default =
    await api.functional.shopping_mall_ai.admin.orders.shipments.search(
      connection,
      { orderId, body: {} },
    );
  typia.assert(result_default);
  TestValidator.equals("pagination defaults to 1")(
    result_default.pagination.current,
  )(1);
  TestValidator.predicate("positive limit")(
    result_default.pagination.limit > 0,
  );

  // 8. General: data fits within returned limit, presence of necessary fields
  TestValidator.predicate("data array within stated limit")(
    result_page0.data.length <= 10,
  );
  TestValidator.predicate("data array within stated limit")(
    result_high_page.data.length <= 10,
  );
  TestValidator.predicate("data array within limit default")(
    result_default.data.length <= result_default.pagination.limit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiShipmentList } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipmentList";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";

/**
 * Validate shipment detail retrieval for a specific order as a customer.
 *
 * This test simulates an end-to-end workflow where a customer retrieves
 * detailed shipment information for an order they own. The goal is to ensure
 * that, given a valid order and shipment identifier, the shipment detail
 * endpoint returns complete metadata, including current status, tracking
 * number, provider (if present), and audit timestamps. This reflects a typical
 * customer order tracking use-case in the shopping mall system.
 *
 * Steps:
 *
 * 1. List all shipments for a specific order to obtain legitimate shipment IDs.
 * 2. Pick one valid shipment from the list.
 * 3. Fetch shipment detail using orderId and shipmentId.
 * 4. Assert the shipment details match those returned in the list and that all
 *    audit fields and primary properties exist and are correct.
 */
export async function test_api_shopping_mall_ai_test_get_order_shipment_detail_success_as_customer(
  connection: api.IConnection,
) {
  // Step 1: Retrieve the list of shipments for a random order.
  const orderId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const shipmentsList: IShoppingMallAiShipmentList =
    await api.functional.shopping_mall_ai.customer.orders.shipments.index(
      connection,
      { orderId },
    );
  typia.assert(shipmentsList);

  // Validate that at least one shipment exists for this order.
  TestValidator.predicate("at least one shipment exists for the order")(
    shipmentsList.shipments.length > 0,
  );

  // Step 2: Select a shipment to test detail fetch.
  const refShipment: IShoppingMallAiShipment = RandomGenerator.pick(
    shipmentsList.shipments,
  );

  // Step 3: Fetch that shipment's detail from the API.
  const shipmentDetail: IShoppingMallAiShipment =
    await api.functional.shopping_mall_ai.customer.orders.shipments.at(
      connection,
      {
        orderId,
        shipmentId: refShipment.id,
      },
    );
  typia.assert(shipmentDetail);

  // Step 4: Assert all primary properties and field correspondence.
  TestValidator.equals("shipment id matches")(shipmentDetail.id)(
    refShipment.id,
  );
  TestValidator.equals("order id matches")(
    shipmentDetail.shopping_mall_ai_order_id,
  )(orderId);
  TestValidator.equals("status matches")(shipmentDetail.status)(
    refShipment.status,
  );
  TestValidator.equals("created_at matches")(shipmentDetail.created_at)(
    refShipment.created_at,
  );
  TestValidator.equals("updated_at matches")(shipmentDetail.updated_at)(
    refShipment.updated_at,
  );
  // For possibly nullable fields, confirm identity or presence (can both be null or equal values).
  TestValidator.equals("tracking_number matches")(
    shipmentDetail.tracking_number,
  )(refShipment.tracking_number);
  TestValidator.equals("provider matches")(shipmentDetail.provider)(
    refShipment.provider,
  );
}

