 * 사용 목적:
 *
 * - 잘못된 배송 ID 입력 등으로 인해 발생하는 프론트 및 API 사용 측의 사용자 경험 보장
 * - 외부 호출에 대해 일관적 에러 응답 반환을 보장하기 위해 필요한 E2E 테스트
 *
 * 테스트 절차:
 *
 * 1. 테스트용 임의의 유효 uuid로 orderId, shipmentId 생성 (실제로 매칭되는 배송 데이터가 없다고 가정)
 * 2. 해당 orderId/ shipmentId 조합으로 배송 상세 조회 엔드포인트 호출
 * 3. 404 HttpError가 발생하는지 TestValidator.error로 검증
 */
export async function test_api_shopping_mall_ai_test_get_order_shipment_detail_not_found(
  connection: api.IConnection,
) {
  // 1. 테스트용 임의 uuid 값 준비 (존재하지 않는 주문ID 및 배송ID)
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const shipmentId = typia.random<string & tags.Format<"uuid">>();
  // 2. 주문 내 존재하지 않는 shipmentId로 조회 시도 → 404 not-found
  await TestValidator.error("존재하지 않는 shipmentId 호출시 not-found 오류")(
    async () =>
      api.functional.shopping_mall_ai.customer.orders.shipments.at(connection, {
        orderId,
        shipmentId,
      }),
  );
}

