 *
 * 이 테스트는 판매자가 주문 상세보기 혹은 출고배송 관리 화면 등에서, 실제로 자신의 주문에 포함된 배송건이 정상적으로 상세 조회되는지
 * 검증합니다.
 *
 * 1. 주문의 모든 배송건 목록을 조회해서 테스트용 orderId, shipmentId를 확보
 * 2. 해당 orderId, shipmentId로 배송 상세 조회 API 호출
 * 3. 응답 스키마의 모든 필드가 타입/필수성에 맞게 들어있는지 검증
 * 4. 주문-배송 연관성(orderId 값 일치) 및 각 필드의 유효성 확인
 */
export async function test_api_shopping_mall_ai_test_seller_get_shipment_detail_success(
  connection: api.IConnection,
) {
  // 1. 주문의 배송건 목록 조회하여 테스트 데이터 확보
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const shipmentsList =
    await api.functional.shopping_mall_ai.seller.orders.shipments.index(
      connection,
      { orderId },
    );
  typia.assert(shipmentsList);
  TestValidator.predicate("배송건 존재 확인")(
    Array.isArray(shipmentsList.shipments) &&
      shipmentsList.shipments.length > 0,
  );

  // 2. 샘플(첫번째) 배송건 선택
  const sampleShipment = shipmentsList.shipments[0];
  typia.assert(sampleShipment);

  // 3. 상세내역 API 호출
  const shipmentDetail =
    await api.functional.shopping_mall_ai.seller.orders.shipments.at(
      connection,
      { orderId, shipmentId: sampleShipment.id },
    );
  typia.assert(shipmentDetail);

  // 4. 응답 필드별 유효성 및 연관성 검증
  TestValidator.equals("orderId 일치 확인")(
    shipmentDetail.shopping_mall_ai_order_id,
  )(orderId);
  TestValidator.predicate("상태(status) 값 검증")(
    typeof shipmentDetail.status === "string" &&
      shipmentDetail.status.length > 0,
  );
  TestValidator.predicate("created_at ISO8601 검증")(
    typeof shipmentDetail.created_at === "string",
  );
  TestValidator.predicate("updated_at ISO8601 검증")(
    typeof shipmentDetail.updated_at === "string",
  );
  // tracking_number, provider 등은 null/undefined/문자열 모두 가능하므로 따로 추가 검증 불필요
}

