  const victimCart: IShoppingMallAiCart =
    await api.functional.shopping_mall_ai.customer.carts.create(connection, {
      body: {
        // Omit customer_id to simulate a guest/anonymous cart for deny-by-default access
        shopping_mall_ai_channel_id: typia.random<
