import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";
import type { IPageIShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCartSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";

/**
 * Validate admin paginated list of all cart sessions, ensuring empty state,
 * populated state, data integrity, and admin visibility.
 *
 * This test exercises the admin-only cart session listing endpoint by:
 *
 * 1. Fetching the cart session list prior to any session creation to verify the
 *    empty state and pagination structure
 * 2. Creating two carts (a customer cart and a guest cart)
 * 3. Admin-creating a session for each cart
 * 4. Invoking the cart session list to check all sessions are visible, all
 *    required properties are present, and sensitive fields are only present
 *    according to admin rights
 * 5. Verifying repeated polling returns expected results
 *
 * This protects analytics/audit use cases, ensures data privacy, and exercises
 * paginated list logic under both empty and populated conditions.
 */
export async function test_api_shopping_mall_ai_admin_cartSessions_index_pagination_and_visibility(
  connection: api.IConnection,
) {
  // 1. Request empty list (no sessions yet)
  const emptyList =
    await api.functional.shopping_mall_ai.admin.cartSessions.index(connection);
  typia.assert(emptyList);
  TestValidator.equals("Empty session data for admin")(emptyList.data.length)(
    0,
  );

  // 2. Create customer cart
  const cartA = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cartA);

  // Create guest cart
  const cartB = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_section_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallAiCart.ICreate,
    },
  );
  typia.assert(cartB);

  // 3. Create cart sessions for each
  const now = new Date().toISOString();
  const sessionA =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: {
          shopping_mall_ai_cart_id: cartA.id,
          session_token: typia.random<string>(),
          created_at: now,
          last_active_at: now,
        } satisfies IShoppingMallAiCartSession.ICreate,
      },
    );
  typia.assert(sessionA);

  const sessionB =
    await api.functional.shopping_mall_ai.admin.cartSessions.create(
      connection,
      {
        body: {
          shopping_mall_ai_cart_id: cartB.id,
          session_token: typia.random<string>(),
          created_at: now,
          last_active_at: now,
        } satisfies IShoppingMallAiCartSession.ICreate,
      },
    );
  typia.assert(sessionB);

  // 4. Admin fetches paginated session list (should include both)
  const list =
    await api.functional.shopping_mall_ai.admin.cartSessions.index(connection);
  typia.assert(list);

  TestValidator.predicate("Contains the created sessions")(
    list.data.some((s) => s.id === sessionA.id) &&
      list.data.some((s) => s.id === sessionB.id),
  );

  // Pagination presence
  TestValidator.predicate("Pagination present")(
    !!list.pagination &&
      typeof list.pagination.current === "number" &&
      typeof list.pagination.limit === "number",
  );

  // Property/sensitive data check for all returned sessions
  for (const s of list.data) {
    typia.assert(s);
    TestValidator.predicate("session_token string")(
      typeof s.session_token === "string",
    );
    const keys = Object.keys(s);
    TestValidator.equals("Allowed cart session properties only")(
      keys.sort().join(","),
    )(
      [
        "created_at",
        "id",
        "last_active_at",
        "session_token",
        "shopping_mall_ai_cart_id",
      ]
        .sort()
        .join(","),
    );
  }

  // 5. Repeat poll, expect >=2 sessions
  const repoll =
    await api.functional.shopping_mall_ai.admin.cartSessions.index(connection);
  typia.assert(repoll);
  TestValidator.predicate("Repoll >= 2 sessions")(repoll.data.length >= 2);
}

