 * - All fields (tracking number, status, provider, audit info) are correct
 * - The system returns an empty array (not error) for orders with no shipments
 *
 * Steps:
 *
 * 1. Create an order as admin (simulating customer order placement)
 * 2. Register a shipment for that order as admin
 * 3. As the customer (using same connection in this context), fetch shipments for
 *    the order
 * 4. Validate the returned shipment list: must contain the registered shipment and
 *    all expected info
 * 5. Create another order with no shipments and assert that an empty list is
 *    returned
 */
export async function test_api_shopping_mall_ai_test_get_shipments_for_customer_order_success(
  connection: api.IConnection,
) {
  // 1. Create an order
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
