  typia.assert(order);

  // 2. Register a shipment for the order
  const shipment =
    await api.functional.shopping_mall_ai.admin.orders.shipments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          status: "shipped",
          tracking_number: "TRACK1234567",
          provider: "MyShipCo",
        } satisfies IShoppingMallAiShipment.ICreate,
