  // 4. Validate that the created shipment is present and correct
  const found = customerShipments.shipments.find((s) => s.id === shipment.id);
  TestValidator.predicate("shipment is returned")(!!found);
  if (found) {
    TestValidator.equals("order id matches")(found.shopping_mall_ai_order_id)(
      shipment.shopping_mall_ai_order_id,
    );
    TestValidator.equals("status matches")(found.status)(shipment.status);
    TestValidator.equals("tracking number matches")(found.tracking_number)(
      shipment.tracking_number,
    );
    TestValidator.equals("provider matches")(found.provider)(shipment.provider);
    TestValidator.equals("created_at matches")(found.created_at)(
      shipment.created_at,
    );
    TestValidator.equals("updated_at matches")(found.updated_at)(
      shipment.updated_at,
    );
