  const orderNoShipments =
    await api.functional.shopping_mall_ai.admin.orders.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    });
