  const noShipmentsList =
    await api.functional.shopping_mall_ai.customer.orders.shipments.index(
      connection,
      {
        orderId: orderNoShipments.id,
      },
    );
  typia.assert(noShipmentsList);
  TestValidator.equals("no shipments should be returned")(
    noShipmentsList.shipments.length,
  )(0);
}

