import type { IShoppingMallAiShipmentList } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipmentList";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";

/**
 * Validate that a seller can retrieve the list of all shipments associated with
 * an order they fulfilled.
 *
 * Business Context: Sellers need to track and audit all shipment events related
 * to a specific order. In this workflow, a new order is created, then multiple
 * (2+) shipments are registered under that order. The seller then retrieves the
 * complete list of those shipments, expecting all details (status, tracking
 * numbers, timestamps, provider) to be accurate and complete. This prevents
 * issues of missing, partial, or incorrect shipment-listing behavior.
 *
 * Steps:
 *
 * 1. Admin creates a new order.
 * 2. Admin registers multiple shipment records under the created order.
 * 3. Seller requests the list of shipments for the order (GET endpoint).
 * 4. Assert all registered shipments are present in the response, and their key
 *    fields match exactly what was registered.
 * 5. Assert the returned array is chronologically ordered by creation timestamp.
 */
export async function test_api_shopping_mall_ai_test_get_shipments_for_seller_order_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a new order.
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "processing",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Admin registers multiple shipments under the created order.
  const shipmentsToCreate = [
    {
      status: "pending",
      tracking_number: "TRACK123456",
      provider: "LogiQuick",
    },
    {
      status: "shipped",
      tracking_number: "TRACK654321",
      provider: "ExpressShip",
    },
  ];

  const createdShipments: IShoppingMallAiShipment[] = [];
  for (const shipment of shipmentsToCreate) {
    const created =
      await api.functional.shopping_mall_ai.admin.orders.shipments.create(
        connection,
        {
          orderId: order.id,
          body: {
            shopping_mall_ai_order_id: order.id,
            status: shipment.status,
            tracking_number: shipment.tracking_number,
            provider: shipment.provider,
          } satisfies IShoppingMallAiShipment.ICreate,
        },
      );
    typia.assert(created);
    createdShipments.push(created);
  }
  TestValidator.equals("created shipments count")(createdShipments.length)(
    shipmentsToCreate.length,
  );

  // 3. Seller requests list of shipments for the order
  const response =
    await api.functional.shopping_mall_ai.seller.orders.shipments.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(response);

  // Assert count matches
  TestValidator.equals("all shipments returned")(response.shipments.length)(
    createdShipments.length,
  );

  // 4. Assert all registered shipments are present w/ matching key fields
  for (const intended of shipmentsToCreate) {
    const actual = response.shipments.find(
      (s) => s.tracking_number === intended.tracking_number,
    );
    TestValidator.predicate(
      `Shipment with tracking_number ${intended.tracking_number} exists`,
    )(!!actual);
    if (actual) {
      TestValidator.equals("orderId matches")(actual.shopping_mall_ai_order_id)(
        order.id,
      );
      TestValidator.equals("status matches")(actual.status)(intended.status);
      TestValidator.equals("provider matches")(actual.provider)(
        intended.provider,
      );
      TestValidator.equals("tracking matches")(actual.tracking_number)(
        intended.tracking_number,
      );
      TestValidator.predicate("created_at is ISO string")(
        !!Date.parse(actual.created_at),
      );
      TestValidator.predicate("updated_at is ISO string")(
        !!Date.parse(actual.updated_at),
      );
    }
  }

  // 5. Assert array chronologically ordered by created_at
  const createdAtValues = response.shipments.map((s) =>
    Date.parse(s.created_at),
  );
  for (let i = 1; i < createdAtValues.length; ++i) {
    TestValidator.predicate("shipments are ordered by created_at")(
      createdAtValues[i] >= createdAtValues[i - 1],
    );
  }
}

