import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";
import type { IPageIShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiShipment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the advanced filter and pagination for shipment search by customer.
 *
 * This test ensures that a customer can search their shipments for a specific
 * order using advanced filters (status, provider) and pagination. Shipments are
 * created under an order with varied statuses and providers. The test checks:
 *
 * 1. Filtering by status returns only shipments with that status and correct
 *    count.
 * 2. Filtering by provider returns only shipments of that provider and correct
 *    count.
 * 3. Pagination parameters (limit, page) work, data and meta info match.
 * 4. Filtering by a non-existing status+provider combination yields zero results.
 *
 * Step-by-step:
 *
 * 1. Admin creates a new order
 * 2. Admin creates four shipments for that order, each with varying
 *    status/provider
 * 3. Customer filters by status ('delivered'), validates shipment statuses and
 *    count
 * 4. Customer filters by provider ('CJ'), validates shipment providers and count
 * 5. Customer paginates (limit=2, page=1), checks count and meta
 * 6. Customer filters for not-matching combination, expects empty result
 */
export async function test_api_shopping_mall_ai_test_advanced_search_shipments_by_customer(
  connection: api.IConnection,
) {
  // 1. Admin creates a new order
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Admin creates 4 shipments with varying status/providers
  const shipmentInputs = [
    { status: "pending", provider: "DHL" },
    { status: "delivered", provider: "CJ" },
    { status: "shipped", provider: "FedEx" },
    { status: "delivered", provider: "CJ" },
  ];
  const createdShipments: IShoppingMallAiShipment[] = [];
  for (const input of shipmentInputs) {
    const shipment =
      await api.functional.shopping_mall_ai.admin.orders.shipments.create(
        connection,
        {
          orderId: order.id,
          body: {
            shopping_mall_ai_order_id: order.id,
            status: input.status,
            provider: input.provider,
          } satisfies IShoppingMallAiShipment.ICreate,
        },
      );
    typia.assert(shipment);
    createdShipments.push(shipment);
  }

  // 3a. Customer filters by status 'delivered'
  let res =
    await api.functional.shopping_mall_ai.customer.orders.shipments.search(
      connection,
      {
        orderId: order.id,
        body: {
          status: "delivered",
        } satisfies IShoppingMallAiShipment.IRequest,
      },
    );
  typia.assert(res);
  TestValidator.predicate("all returned shipments have status delivered")(
    res.data.every((s) => s.status === "delivered"),
  );
  TestValidator.equals("pagination records matches count")(
    res.pagination.records,
  )(createdShipments.filter((s) => s.status === "delivered").length);

  // 3b. Customer filters by provider 'CJ'
  res = await api.functional.shopping_mall_ai.customer.orders.shipments.search(
    connection,
    {
      orderId: order.id,
      body: { provider: "CJ" } satisfies IShoppingMallAiShipment.IRequest,
    },
  );
  typia.assert(res);
  TestValidator.predicate("all returned shipments have provider CJ")(
    res.data.every((s) => s.provider === "CJ"),
  );
  TestValidator.equals("pagination records matches count")(
    res.pagination.records,
  )(createdShipments.filter((s) => s.provider === "CJ").length);

  // 3c. Pagination: limit=2, page=1
  res = await api.functional.shopping_mall_ai.customer.orders.shipments.search(
    connection,
    {
      orderId: order.id,
      body: { limit: 2, page: 1 } satisfies IShoppingMallAiShipment.IRequest,
    },
  );
  typia.assert(res);
  TestValidator.predicate("number of shipments returned should not exceed 2")(
    res.data.length <= 2,
  );
  TestValidator.equals("pagination limit matches")(res.pagination.limit)(2);

  // 3d. Filter for non-existent combination
  res = await api.functional.shopping_mall_ai.customer.orders.shipments.search(
    connection,
    {
      orderId: order.id,
      body: {
        status: "shipped",
        provider: "NonExistentProvider",
      } satisfies IShoppingMallAiShipment.IRequest,
    },
  );
  typia.assert(res);
  TestValidator.equals("no results for unmatched filter")(res.data.length)(0);
  TestValidator.equals("pagination records is 0")(res.pagination.records)(0);
}

