import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import type { IShoppingMallAiCouponEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCouponEvent";

/**
 * Verify the seller can fetch a specific coupon event's details for their own
 * coupon.
 *
 * Business Context: This E2E test ensures end-to-end correctness for a normal
 * seller managing coupons. It verifies that a seller can successfully retrieve
 * the details of a coupon event that they created—ensuring field-by-field data
 * accuracy, permission checks, and business logic.
 *
 * Test Process Overview:
 *
 * 1. Create a new coupon using the seller's authentication (ownership context).
 * 2. Create a coupon event (e.g., 'issued') for that coupon as the owner.
 * 3. Retrieve the coupon event details using correct couponId/couponEventId
 *    combination.
 * 4. Validate all returned DTO fields for exactness, including correct
 *    associations, timestamps, and null-accepting fields.
 * 5. Enforce proper permission (should only succeed for coupon owned by this
 *    seller).
 *
 * This test does not cover permission error/failure (handled in negative
 * scenarios). All DTO/parameter properties are strictly within schema
 * definitions. No fictional/nonexistent fields are used.
 */
export async function test_api_shopping_mall_ai_test_get_coupon_event_details_as_seller_with_proper_permissions(
  connection: api.IConnection,
) {
  // 1. Create a coupon owned by this authenticated seller
  const couponInput: IShoppingMallAiCoupon.ICreate = {
    code: `COUPON-${typia.random<string>()}`,
    type: "fixed",
    value: 5000,
    min_order_value: 10000,
    max_usage: 10,
    max_usage_per_customer: 2,
    valid_from: new Date(Date.now() - 3_600_000).toISOString(), // 1 hour ago
    valid_until: new Date(Date.now() + 86_400_000).toISOString(), // 24 hours later
    stackable: true,
    // No need to set explicit seller, product, or channel id—it will default to this seller's context
  };
  const coupon = await api.functional.shopping_mall_ai.seller.coupons.create(
    connection,
    { body: couponInput },
  );
  typia.assert(coupon);

  // 2. Create a coupon event for this coupon (minimal fields, 'issued')
  const eventInput: IShoppingMallAiCouponEvent.ICreate = {
    shopping_mall_ai_coupon_id: coupon.id,
    event_type: "issued",
    occurred_at: new Date().toISOString(),
    // All optional association fields left as null to check null-handling
  };
  const event =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.create(
      connection,
      {
        couponId: coupon.id,
        body: eventInput,
      },
    );
  typia.assert(event);

  // 3. Retrieve the coupon event using couponId and couponEventId
  const got =
    await api.functional.shopping_mall_ai.seller.coupons.couponEvents.at(
      connection,
      {
        couponId: coupon.id,
        couponEventId: event.id,
      },
    );
  typia.assert(got);

  // 4. Validate all returned fields match saved/created values
  TestValidator.equals("coupon event id")(got.id)(event.id);
  TestValidator.equals("coupon association")(got.shopping_mall_ai_coupon_id)(
    coupon.id,
  );
  TestValidator.equals("event type")(got.event_type)(eventInput.event_type);
  TestValidator.equals("occurred_at")(got.occurred_at)(eventInput.occurred_at);
  TestValidator.equals("details (nullable)")(got.details ?? null)(
    eventInput.details ?? null,
  );
  TestValidator.equals("customer association")(
    got.shopping_mall_ai_customer_id ?? null,
  )(eventInput.shopping_mall_ai_customer_id ?? null);
  TestValidator.equals("order association")(
    got.shopping_mall_ai_order_id ?? null,
  )(eventInput.shopping_mall_ai_order_id ?? null);
  TestValidator.equals("actor association")(
    got.shopping_mall_ai_actor_id ?? null,
  )(eventInput.shopping_mall_ai_actor_id ?? null);

  // 5. Assert all expected fields are present and non-empty if required
  TestValidator.predicate("event id is uuid")(got.id.length > 0);
  TestValidator.predicate("coupon id is uuid")(
    got.shopping_mall_ai_coupon_id.length > 0,
  );
  TestValidator.predicate("event type string not empty")(
    !!got.event_type.length,
  );
  TestValidator.predicate("occurred_at timestamp present")(
    !!got.occurred_at.length,
  );
}

