import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";
import type { IPageIShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate complex product option search by admin, including filter, ownership,
 * pagination, and negative logic.
 *
 * This test validates admin can:
 *
 * - Search product options with complex filters (product ID, attribute
 *   name/value, SKU, date window)
 * - Receive only exact-matching results for each criterion
 * - Paginate results and see expected counts per page
 * - See all options, even if not owned by current seller (admin context)
 *
 * Steps covered:
 *
 * 1. Create a product as admin to get a testable product ID
 * 2. Create several product options with diverse names, values, SKUs, and
 *    timestamps
 * 3. Single criteria: Search by product ID and check all options are included
 * 4. Combine filters (by name/value, by SKU) and assert each narrows result
 * 5. Use created_at_from / created_at_to for temporal filters
 * 6. Paginate results, check structure and counts
 * 7. Negative: Nonexistent filter produces empty result
 */
export async function test_api_shopping_mall_ai_product_options_test_search_product_options_by_admin_with_complex_filters(
  connection: api.IConnection,
) {
  // 1. Create a product (admin context) to be used for registering options and filtering
  const product =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
          price: 129000,
          status: "active",
          sku: RandomGenerator.alphabets(7),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product);

  // 2. Register several product options with varying attributes for search baseline
  const options = await ArrayUtil.asyncRepeat(4)(async (idx) => {
    const name = idx % 2 === 0 ? "Color" : "Size";
    const value =
      idx === 0 ? "Red" : idx === 1 ? "Large" : idx === 2 ? "Blue" : "Medium";
    const option_sku = `${product.sku}-${RandomGenerator.alphaNumeric(3)}${idx}`;
    const opt =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id: product.id,
            name,
            value,
            option_sku,
          } satisfies IShoppingMallAiProductOption.ICreate,
        },
      );
    typia.assert(opt);
    return opt;
  });

  // 3. Filter: By product ID (all options registered above)
  let page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
        },
      },
    );
  typia.assert(page);
  TestValidator.equals("option count: by product")(page.data.length)(
    options.length,
  );
  options.forEach((opt) =>
    TestValidator.predicate("all match product ID")(
      page.data.some(
        (d) => d.id === opt.id && d.shopping_mall_ai_product_id === product.id,
      ),
    ),
  );

  // 4. Filter: By product ID + name + value (expect one unique match)
  const filterOpt = options[0];
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          name: filterOpt.name,
          value: filterOpt.value,
        },
      },
    );
  typia.assert(page);
  TestValidator.equals("filtered by name/value")(page.data.length)(1);
  TestValidator.equals("filter match")(page.data[0])(filterOpt);

  // 5. Filter: By product ID + SKU (unique option)
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          option_sku: options[1].option_sku,
        },
      },
    );
  typia.assert(page);
  TestValidator.equals("filtered by SKU")(page.data.length)(1);
  TestValidator.equals("option_sku matches")(page.data[0].option_sku)(
    options[1].option_sku,
  );

  // 6. Date window: created_at_from/created_at_to to restrict result span
  options.sort(
    (a, b) =>
      new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
  );
  const lower = options[1].created_at;
  const upper = options[2].created_at;
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          created_at_from: lower,
          created_at_to: upper,
        },
      },
    );
  typia.assert(page);
  TestValidator.predicate("created_at range")(
    page.data.every((o) => o.created_at >= lower && o.created_at <= upper),
  );

  // 7. Pagination: limit/results per page, page 2
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          limit: 2,
          page: 2,
        },
      },
    );
  typia.assert(page);
  TestValidator.predicate("pagination correct count")(
    page.data.length === Math.min(2, options.length - 2),
  );
  TestValidator.equals("pagination current page")(page.pagination.current)(2);
  TestValidator.equals("pagination limit")(page.pagination.limit)(2);

  // 8. Negative: non-existent value filter – expect no results
  page =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          value: "NON_EXISTENT_VALUE",
        },
      },
    );
  typia.assert(page);
  TestValidator.equals("no results for negative filter")(page.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";
import type { IPageIShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error handling for searching product options with invalid filters as
 * admin.
 *
 * This test ensures that if an admin user attempts to search product options
 * with fields that don't exist in the schema (e.g., randomField: 'foo'), or
 * uses clearly malformed values for filterable properties (such as an invalid
 * UUID in shopping_mall_ai_product_id, or a broken date string for
 * created_at_from), the API correctly rejects the request. It should return an
 * error for invalid filter parameters, and not return any data (or at least not
 * return successful filtered records based on bad input).
 *
 * Workflow:
 *
 * 1. Attempt search with a completely invalid field (not in schema) - should
 *    Trigger TypeScript error (NOT IMPLEMENTED)
 * 2. Attempt search with invalid value for a filterable property (e.g.,
 *    shopping_mall_ai_product_id: 'not-a-uuid') - should trigger runtime error
 * 3. Attempt search with malformed date in created_at_from (e.g., 'not-a-date') -
 *    should trigger runtime error
 * 4. Attempt search with malformed SKU (option_sku: '**broken!sku**') if any
 *    strict SKU validation exists - if rejected, should be runtime error,
 *    otherwise if accepted, API returns empty data.
 *
 * Only implement testable scenarios: skip sending properties that would produce
 * TypeScript errors due to strict typings (e.g., non-existent fields).
 */
export async function test_api_shopping_mall_ai_product_option_test_search_product_options_with_invalid_filter_fields(
  connection: api.IConnection,
) {
  // 1. Attempt to search with invalid shopping_mall_ai_product_id (must be UUID)
  await TestValidator.error("invalid uuid filter should error")(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: "not-a-uuid",
        } satisfies IShoppingMallAiProductOption.IRequest,
      },
    );
  });

  // 2. Attempt to search with invalid date (must be ISO 8601 format)
  await TestValidator.error("invalid date filter should error")(async () => {
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          created_at_from: "not-a-date",
        } satisfies IShoppingMallAiProductOption.IRequest,
      },
    );
  });

  // 3. Attempt to search with malformed SKU (may either error or return empty data)
  let errorOrEmpty = false;
  try {
    const result =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
        connection,
        {
          body: {
            option_sku: "**!!!broken_SKU??",
          } satisfies IShoppingMallAiProductOption.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.predicate("empty data for malformed SKU filter")(
      result.data.length === 0,
    );
    errorOrEmpty = true;
  } catch {
    errorOrEmpty = true;
  }
  TestValidator.predicate("should error or return empty for malformed SKU")(
    errorOrEmpty,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";
import type { IPageIShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate pagination and searching behavior for product options.
 *
 * This test creates a parent product, then registers multiple options on that
 * product, and tests the pagination and search endpoint using various page
 * numbers, limits, and name filters.
 *
 * 1. Create a single product as parent.
 * 2. Register multiple options (with distinguishable names) for that product.
 * 3. Search options using page+limit, asserting returned count, pagination data,
 *    and product association.
 * 4. Fetch last page and overflow page to test boundaries.
 * 5. Test filter by 'name' to validate the search and return value.
 * 6. Sorting cannot be meaningfully enforced without sort parameter in API.
 */
export async function test_api_shopping_mall_ai_product_options_test_search_product_options_pagination_and_sorting_behavior(
  connection: api.IConnection,
) {
  // 1. Create parent product (as admin)
  const product =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: `PaginateTest Parent ${RandomGenerator.alphabets(4)}`,
          description: "Parent for pagination option tests.",
          price: 123.45,
          status: "active",
          sku: `SKU-paginate-${RandomGenerator.alphabets(4)}`,
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product);

  // 2. Register a set of options with recognizable names
  const names = [
    "Alpha",
    "Bravo",
    "Charlie",
    "Delta",
    "Echo",
    "Foxtrot",
    "Golf",
    "Hotel",
  ];
  const options: IShoppingMallAiProductOption[] = [];
  for (const [idx, name] of names.entries()) {
    const option =
      await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id: product.id,
            name,
            value: `Value${idx + 1}`,
            option_sku: `SKU-${name}-${RandomGenerator.alphabets(2)}-${idx}`,
          } satisfies IShoppingMallAiProductOption.ICreate,
        },
      );
    typia.assert(option);
    options.push(option);
  }

  // 3. Search first page, size 3
  const pageSize = 3;
  let response =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          page: 1,
          limit: pageSize,
        },
      },
    );
  typia.assert(response);
  TestValidator.equals("page 1 record count")(response.data.length)(pageSize);
  TestValidator.equals("page 1 current")(response.pagination.current)(1);
  TestValidator.equals("page 1 limit")(response.pagination.limit)(pageSize);
  TestValidator.equals("options belong to product")(
    response.data.every((x) => x.shopping_mall_ai_product_id === product.id),
  )(true);

  // 4. Search last page and check results are as expected
  const lastPage = response.pagination.pages;
  response =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          page: lastPage,
          limit: pageSize,
        },
      },
    );
  typia.assert(response);
  const expectedLastCount =
    options.length % pageSize === 0 ? pageSize : options.length % pageSize;
  TestValidator.equals("last page record count")(response.data.length)(
    expectedLastCount,
  );
  TestValidator.equals("last page current")(response.pagination.current)(
    lastPage,
  );

  // 5. Search overflow page (one after last)
  response =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          page: lastPage + 1,
          limit: pageSize,
        },
      },
    );
  typia.assert(response);
  TestValidator.equals("no results on overflow page")(response.data.length)(0);
  TestValidator.equals("overflow page current")(response.pagination.current)(
    lastPage + 1,
  );

  // 6. Search for name 'Charlie'
  response =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          name: "Charlie",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(response);
  TestValidator.predicate("filter by name yields only Charlie")(
    response.data.length === 1 && response.data[0].name === "Charlie",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";
import type { IPageIShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify seller advanced product option search returns only their own product's
 * options, never options of other sellers.
 *
 * Business context:
 *
 * - Sellers may not view, filter, or obtain options belonging to other sellers'
 *   products, even via advanced search with arbitrary product_id.
 * - This protects data privacy, catalog integrity, and multi-tenant business
 *   rules.
 *
 * Steps:
 *
 * 1. Seller A creates their own product (productA).
 * 2. Seller A creates two options for productA.
 * 3. Seller B registers a separate product (productB) and an option for it.
 * 4. Seller A performs an option search, filtering by both productA (own) and
 *    productB (foreign) product IDs—result must only include their own
 *    options.
 * 5. Seller A performs a search with only productA—verifies correct options
 *    returned.
 * 6. Seller A searches for only productB as filter—expects empty results.
 */
export async function test_api_shopping_mall_ai_test_seller_advanced_search_only_own_product_options(
  connection: api.IConnection,
) {
  // 1. Seller A creates their own product (productA)
  const productA =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "SellerA's Product",
          description:
            "Product created by Seller A for option visibility test.",
          price: 19999,
          status: "active",
          sku: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  typia.assert(productA);

  // 2. Seller A creates two options for productA
  const optionA1 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productA.id,
          name: "Size",
          value: "Large",
          option_sku: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(optionA1);

  const optionA2 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productA.id,
          name: "Color",
          value: "Blue",
          option_sku: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(optionA2);

  // 3. Simulate Seller B: create separate product and option with a new connection
  const connectionSellerB = { ...connection };
  // (In a real system, switch user context to Seller B here)
  const productB =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connectionSellerB,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "SellerB's Product",
          description: "Product created by Seller B for privacy test.",
          price: 24999,
          status: "active",
          sku: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  typia.assert(productB);

  const optionB =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.create(
      connectionSellerB,
      {
        body: {
          shopping_mall_ai_product_id: productB.id,
          name: "Material",
          value: "Cotton",
          option_sku: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(optionB);

  // 4. Seller A: search for ALL options for BOTH productA and productB
  const searchBoth =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productB.id, // Malicious/invalid attempt; Seller A does not own productB
          // If API accepted multiple IDs, we'd test both, but as it's a single filter, we run 2
        },
      },
    );
  typia.assert(searchBoth);

  // 5. Assert that returned options do not contain Seller B's option
  if (searchBoth.data.length) {
    for (const opt of searchBoth.data) {
      TestValidator.notEquals("should not include options for productB")(
        opt.shopping_mall_ai_product_id,
      )(productB.id);
    }
  } else {
    TestValidator.equals("empty result when filtering for non-owned product")(
      searchBoth.data.length,
    )(0);
  }

  // 6. Seller A: search for options only for their own productA
  const searchOwn =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productA.id,
        },
      },
    );
  typia.assert(searchOwn);
  // Should contain exactly the two options created by Seller A
  TestValidator.equals("options count matches")(searchOwn.data.length)(2);
  const returnedSKUs = searchOwn.data.map((opt) => opt.option_sku).sort();
  const expectedSKUs = [optionA1.option_sku, optionA2.option_sku].sort();
