  const pageResult =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProductOptions.search(
      connection,
      {
        body: {
          page: 10000,
          limit: 10,
        },
      },
    );
  typia.assert(pageResult);
  // Expect .data = [] and pagination.current == 10000
  TestValidator.equals("empty result for huge page")(pageResult.data.length)(0);
  TestValidator.equals("reflect requested page")(pageResult.pagination.current)(
