 * changes are saved and reflected on read-back. It also checks type safety and
 * verifies audit context by ensuring the updated fields match input values.
 *
 * Business flow:
 *
 * 1. Register a file with relevant metadata (as admin)
 * 2. Create a file access log entry referencing the file
 * 3. Update one or more mutable fields (such as outcome and/or actor_type) of the
 *    log via update endpoint
 * 4. Assert that the updated fields are reflected in the return DTO
 *
 * The scenario assumes only fields allowed by IUpdate are mutated and update is
 * performed as admin.
 */
export async function test_api_shopping_mall_ai_admin_fileAccessLogs_test_update_file_access_log_with_valid_admin_correction(
  connection: api.IConnection,
) {
  // 1. Register a file to ensure a valid file id exists
  const file = await api.functional.shopping_mall_ai.admin.files.create(
    connection,
    {
      body: {
        original_name: "audit_report.pdf",
        uri: "https://cdn.example.com/audit_report.pdf",
        extension: "pdf",
        mime_type: "application/pdf",
        size: 123456,
        hash: "abc123def456",
