import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IShoppingMallAiFileAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAccessLog";

/**
 * Validates that attempts to update immutable fields of a file access log are
 * rejected.
 *
 * Business context: File access logs in the shopping mall AI platform are used
 * to track detailed file operations for auditing and compliance purposes.
 * Certain fields, such as the file reference (shopping_mall_ai_file_id) and the
 * initial access timestamp (accessed_at), are immutable after creation to
 * prevent tampering with audit trails.
 *
 * This test ensures the API enforces those rules by rejecting changes to these
 * fields via the update endpoint.
 *
 * Steps:
 *
 * 1. Register a file (create file metadata record) as an admin.
 * 2. Create a file access log event for the file.
 * 3. Attempt to update the file access log by changing the accessed_at (immutable
 *    field). This should result in a validation or business logic error.
 * 4. Validate that a mutable field (outcome) _can_ be changed in a regular update.
 */
export async function test_api_shopping_mall_ai_admin_fileAccessLogs_test_update_file_access_log_rejects_immutable_field_edit(
  connection: api.IConnection,
) {
  // 1. Register a file
  const fileInput: IShoppingMallAiFile.ICreate = {
    original_name: "example.txt",
    uri: `https://cdn.example.com/f/${typia.random<string & tags.Format<"uuid">>()}`,
    extension: "txt",
    mime_type: "text/plain",
    size: 1024,
    hash: typia.random<string>(),
    actor_type: "admin",
    actor_id: null,
  };
  const file = await api.functional.shopping_mall_ai.admin.files.create(
    connection,
    { body: fileInput },
  );
  typia.assert(file);

  // 2. Create a file access log event
  const logInput: IShoppingMallAiFileAccessLog.ICreate = {
    shopping_mall_ai_file_id: file.id,
    actor_type: "admin",
    actor_id: null,
    access_type: "view",
    channel: "web",
    outcome: "success",
    ip_address: "127.0.0.1",
    accessed_at: new Date().toISOString(),
  };
  const log = await api.functional.shopping_mall_ai.admin.fileAccessLogs.create(
    connection,
    { body: logInput },
  );
  typia.assert(log);

  // 3. Attempt to update the immutable field: accessed_at
  const invalidUpdate = {
    accessed_at: new Date(Date.now() + 100000).toISOString(),
  } satisfies IShoppingMallAiFileAccessLog.IUpdate;
  await TestValidator.error("should reject update to accessed_at")(() =>
    api.functional.shopping_mall_ai.admin.fileAccessLogs.update(connection, {
      fileAccessLogId: log.id,
      body: invalidUpdate,
    }),
  );

  // 4. Validate that a mutable field (outcome) *can* be changed
  const validUpdate = {
    outcome: "denied",
  } satisfies IShoppingMallAiFileAccessLog.IUpdate;
  const updatedLog =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.update(
      connection,
      {
        fileAccessLogId: log.id,
        body: validUpdate,
      },
    );
  typia.assert(updatedLog);
  TestValidator.equals("should update mutable field: outcome")(
    updatedLog.outcome,
  )("denied");
}

