 *
 * This test ensures that a file access log entry can be permanently deleted by
 * an admin, and that after deletion, the entry is no longer accessible or
 * listed. The workflow includes setup of file registration and dependent access
 * log creation, as well as verification of hard delete behavior (by attempting
 * to delete the same entry twice).
 *
 * 1. Register a file to associate with the file access log (as prerequisite)
 * 2. Create a file access log linked to that file.
 * 3. Delete the file access log via the admin API (hard delete)
 * 4. Test that a second delete attempt fails, validating the entry is truly purged
 * 5. (Repeatability/idempotency check): Create and delete another file access log
 */
export async function test_api_shopping_mall_ai_admin_fileAccessLogs_test_delete_file_access_log_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Register a new file in the system (used for file access logging)
  const file = await api.functional.shopping_mall_ai.admin.files.create(
    connection,
    {
      body: {
        original_name: "test_upload.png",
        uri: "https://cdn.example.com/test_upload.png",
        extension: "png",
        mime_type: "image/png",
        size: 54321,
        hash: "hash-value-test-1",
        actor_type: "admin",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallAiFile.ICreate,
    },
  );
  typia.assert(file);

  // 2. Create a file access log for the above file (admin as actor)
  const accessLog =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          actor_type: "admin",
          actor_id: file.actor_id ?? undefined,
          access_type: "view",
          channel: "web",
          outcome: "success",
          ip_address: "127.0.0.1",
          accessed_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAccessLog.ICreate,
      },
    );
