  // 3. Delete the file access log entry by its ID (admin hard delete)
  await api.functional.shopping_mall_ai.admin.fileAccessLogs.erase(connection, {
    fileAccessLogId: accessLog.id,
  });

  // 4. Ensure deletion is permanent: Repeat delete should cause error
  await TestValidator.error(
    "should fail to delete already-deleted file access log",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.erase(
      connection,
      {
        fileAccessLogId: accessLog.id,
      },
    );
  });

  // 5. (Repeatability) - create and delete another file access log to confirm normal lifecycle
  const accessLog2 =
    await api.functional.shopping_mall_ai.admin.fileAccessLogs.create(
      connection,
      {
        body: {
          shopping_mall_ai_file_id: file.id,
          actor_type: "admin",
          actor_id: file.actor_id ?? undefined,
          access_type: "download",
          channel: "api",
          outcome: "success",
          ip_address: "127.0.0.1",
          accessed_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingMallAiFileAccessLog.ICreate,
      },
    );
  typia.assert(accessLog2);

  await api.functional.shopping_mall_ai.admin.fileAccessLogs.erase(connection, {
    fileAccessLogId: accessLog2.id,
  });
}

