import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAuditLog";
import type { IPageIShoppingMallAiAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Tests advanced searching/filtering of compliance audit logs in the shopping
 * mall admin system.
 *
 * This scenario first creates several distinctive audit log entries, each with
 * different entity types, entity IDs, actor IDs, actor roles, operations,
 * timestamps, and context values. After setup, it runs a suite of searches to
 * validate that:
 *
 * 1. Filtering by entity_type correctly returns only matching logs
 * 2. Filtering by actor_id returns only logs by that actor
 * 3. Filtering by operation (e.g., 'update', 'delete') yields correct results
 * 4. Filtering by occurred_at_from/occurred_at_to returns only logs within that
 *    time window
 * 5. Filtering by context returns only relevant logs
 * 6. Pagination works (returns right set for page/limit, honors total count and
 *    pages)
 *
 * Steps:
 *
 * 1. Create 4+ audit log entries, each with unique
 *    entity_type/entity_id/actor_id/actor_role/operation and staggered
 *    occurred_at timestamps, and distinct context strings.
 * 2. Search with entity_type filter and verify only relevant entries are returned.
 * 3. Search with actor_id filter and verify only that actor's entries are
 *    returned.
 * 4. Search with operation filter (e.g., 'update') and validate results.
 * 5. Search with occurred_at_from/occurred_at_to filter for a 2-entry window and
 *    check both results and record count.
 * 6. Search with context filter and validate only matching logs are returned.
 * 7. Search with pagination (limit=2, page=2); validate result count and record
 *    identity.
 * 8. Negative tests: use mismatching filters (e.g., unused entity_id) and expect 0
 *    results.
 */
export async function test_api_shopping_mall_ai_admin_auditLogs_test_search_audit_logs_with_filter_criteria_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create 4+ distinctive audit log entries
  const now = new Date();
  // We'll space occurred_at by 1 minute for easy time window queries
  const occurredAts: string[] = [0, 1, 2, 3].map((i) =>
    new Date(now.getTime() + i * 60 * 1000).toISOString(),
  );
  // Prepare base data (deliberate differences to enable clean filter tests)
  const logInputs: IShoppingMallAiAuditLog.ICreate[] = [
    {
      entity_type: "order",
      entity_id: "entity-ord-1",
      actor_id: "actor-1111",
      actor_role: "admin",
      operation: "create",
      detail: "Order created for test",
      occurred_at: occurredAts[0],
      context: "CTX-aaa-001",
    },
    {
      entity_type: "product",
      entity_id: "entity-prod-2",
      actor_id: "actor-2222",
      actor_role: "seller",
      operation: "update",
      detail: "Product updated",
      occurred_at: occurredAts[1],
      context: "CTX-bbb-002",
    },
    {
      entity_type: "customer",
      entity_id: "entity-cust-3",
      actor_id: "actor-3333",
      actor_role: "customer",
      operation: "delete",
      detail: "Customer deleted",
      occurred_at: occurredAts[2],
      context: "CTX-ccc-003",
    },
    {
      entity_type: "product",
      entity_id: "entity-prod-4",
      actor_id: "actor-2222",
      actor_role: "seller",
      operation: "update",
      detail: "Second product update",
      occurred_at: occurredAts[3],
      context: "CTX-bbb-004",
    },
  ];
  // Create entries and collect results for later validation
  const createdLogs: IShoppingMallAiAuditLog[] = [];
  for (const input of logInputs) {
    const log = await api.functional.shopping_mall_ai.admin.auditLogs.create(
      connection,
      { body: input },
    );
    typia.assert(log);
    createdLogs.push(log);
  }

  // 2. Search by entity_type ('product') and ensure only matching logs returned
  const entityTypeSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: { entity_type: "product" },
    });
  typia.assert(entityTypeSearch);
  const entityTypeIds = createdLogs
    .filter((l) => l.entity_type === "product")
    .map((l) => l.id);
  TestValidator.equals("product entity_type")(
    entityTypeSearch.data.map((e) => e.id).sort(),
  )(entityTypeIds.sort());

  // 3. Search by actor_id ('actor-2222')
  const actorIdSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: { actor_id: "actor-2222" },
    });
  typia.assert(actorIdSearch);
  const actorLogIds = createdLogs
    .filter((l) => l.actor_id === "actor-2222")
    .map((l) => l.id);
  TestValidator.equals("actor_id 'actor-2222'")(
    actorIdSearch.data.map((e) => e.id).sort(),
  )(actorLogIds.sort());

  // 4. Search by operation ('update')
  const opSearch = await api.functional.shopping_mall_ai.admin.auditLogs.search(
    connection,
    { body: { operation: "update" } },
  );
  typia.assert(opSearch);
  const opIds = createdLogs
    .filter((l) => l.operation === "update")
    .map((l) => l.id);
  TestValidator.equals("operation 'update'")(
    opSearch.data.map((e) => e.id).sort(),
  )(opIds.sort());

  // 5. Search by occurred_at window (should catch exactly entries 2 and 3)
  const from = occurredAts[1]; // entry 2, index 1
  const to = occurredAts[2]; // entry 3, index 2
  const windowSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: { occurred_at_from: from, occurred_at_to: to },
    });
  typia.assert(windowSearch);
  const windowIds = createdLogs
    .filter((l) => l.occurred_at >= from && l.occurred_at <= to)
    .map((l) => l.id);
  TestValidator.equals("occurred_at from-to")(
    windowSearch.data.map((e) => e.id).sort(),
  )(windowIds.sort());

  // 6. Search by context ("CTX-bbb-002")
  const contextSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: { context: "CTX-bbb-002" },
    });
  typia.assert(contextSearch);
  const contextIds = createdLogs
    .filter((l) => l.context === "CTX-bbb-002")
    .map((l) => l.id);
  TestValidator.equals("context matches")(
    contextSearch.data.map((e) => e.id).sort(),
  )(contextIds.sort());

  // 7. Pagination test: limit=2, page=2; check result count and identity
  const pagedSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {},
    });
  typia.assert(pagedSearch);
  if (pagedSearch.pagination.records > 2) {
    const page2 = await api.functional.shopping_mall_ai.admin.auditLogs.search(
      connection,
      { body: {} },
    );
    typia.assert(page2);
    TestValidator.equals("pagination count")(page2.pagination.limit)(
      pagedSearch.pagination.limit,
    );
    TestValidator.equals("pagination pages")(page2.pagination.pages)(
      pagedSearch.pagination.pages,
    );
  }

  // 8. Negative: unused entity_id
  const negSearch =
    await api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: { entity_id: "unused-entity-id-999" },
    });
  typia.assert(negSearch);
  TestValidator.equals("negative entity_id")(negSearch.data.length)(0);
}

