/**
 * Test searching audit logs with invalid or nonsensical filter parameters.
 *
 * This test verifies that the audit log search endpoint correctly rejects
 * requests with invalid, out-of-range, or obviously incorrect filter values.
 * The goal is to confirm that the server responds with validation errors and
 * does not process any garbage queries successfully; this is important for both
 * robustness and security.
 *
 * Steps:
 *
 * 1. Attempt a search where 'occurred_at_from' is after 'occurred_at_to' (invalid
 *    time range).
 * 2. Attempt a search with an invalid UUID for 'actor_id'.
 * 3. Attempt a search with non-date strings in 'occurred_at_from', and numbers in
 *    a string field, all without suppressing type safety.
 * 4. Attempt a search with correctly-typed but illogical dates, and all string
 *    fields set to obviously nonsensical/gibberish values.
 * 5. For each invalid input, confirm using TestValidator.error that an error is
 *    thrown and no results are returned.
 */
export async function test_api_shopping_mall_ai_admin_auditLogs_test_search_audit_logs_invalid_filters(
  connection: api.IConnection,
) {
  // 1. occurred_at_from after occurred_at_to (invalid interval)
  await TestValidator.error("occurred_at_from after occurred_at_to")(() =>
    api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {
        occurred_at_from: "2099-01-02T00:00:00.000Z",
        occurred_at_to: "2000-01-01T00:00:00.000Z",
      },
    }),
  );

  // 2. invalid UUID value for actor_id
  await TestValidator.error("invalid UUID in actor_id")(() =>
    api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {
        actor_id: "not-a-valid-uuid",
      },
    }),
  );

  // 3. nonsensical strings for date-time fields
  await TestValidator.error("not-a-date string in occurred_at_from")(() =>
    api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {
        occurred_at_from: "definitely-not-a-datetime",
      },
    }),
  );
  await TestValidator.error("not-a-date string in deleted_at")(() =>
    api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {
        deleted_at: "not-a-real-date-time",
      },
    }),
  );

  // 4. Nonsensical values for multiple string fields and invalid context
  await TestValidator.error(
    "gibberish in all fields triggers validation error",
  )(() =>
    api.functional.shopping_mall_ai.admin.auditLogs.search(connection, {
      body: {
        entity_type: "💥💩!!",
        entity_id: "@@badid@@",
        actor_id: "🤖",
        actor_role: "nonsenseRole",
        operation: "><invalid>operation</invalid>",
        occurred_at_from: "2022-02-30T99:99:99.999Z",
        occurred_at_to: "1970-99-99T99:99:99.999Z",
        context: "\0\0INVALID",
        deleted_at: "12-34-5678",
      },
    }),
  );
}

