import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validates that an admin can successfully retrieve a single product review,
 * including all details reserved for admin view (such as deletion or internal
 * audit fields if applicable).
 *
 * Business context: Admins must be able to fetch and review individual customer
 * product reviews for moderation, auditing, or compliance—even for records not
 * visible to typical end users. This ensures transparent oversight and the
 * ability to investigate disputes or issues related to product feedback.
 *
 * Workflow:
 *
 * 1. A customer submits a product review (using the standard customer-facing
 *    review creation API).
 * 2. Retrieve that review record as an admin (using its reviewId via the admin
 *    API).
 * 3. Validate that the response contains all expected review fields (including
 *    fields only accessible to admins, such as soft-deleted timestamp
 *    (deleted_at) or any audit info present).
 * 4. Confirm that the record can be accessed by the admin and that important
 *    administrative fields conform to business logic.
 */
export async function test_api_shopping_mall_ai_admin_reviews_test_retrieve_review_success_by_admin_for_existing_review(
  connection: api.IConnection,
) {
  // 1. Customer submits a product review
  const createRequest: IShoppingMallAiReview.ICreate = {
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 5,
    body: "Excellent product - works as described. Highly recommended!",
  };
  const createdReview =
    await api.functional.shopping_mall_ai.customer.reviews.create(connection, {
      body: createRequest,
    });
  typia.assert(createdReview);

  // 2. Admin retrieves the review by reviewId
  const adminFetched = await api.functional.shopping_mall_ai.admin.reviews.at(
    connection,
    {
      reviewId: createdReview.id,
    },
  );
  typia.assert(adminFetched);

  // 3. Validate detailed admin fields
  TestValidator.equals("review id matches")(adminFetched.id)(createdReview.id);
  TestValidator.equals("product id matches")(
    adminFetched.shopping_mall_ai_product_id,
  )(createRequest.shopping_mall_ai_product_id);
  TestValidator.equals("order id matches")(
    adminFetched.shopping_mall_ai_order_id,
  )(createRequest.shopping_mall_ai_order_id);
  TestValidator.equals("rating matches")(adminFetched.rating)(
    createRequest.rating,
  );
  TestValidator.equals("body matches")(adminFetched.body)(createRequest.body);
  // All timestamp fields should be present and formatted
  if (!adminFetched.created_at || !adminFetched.updated_at) {
    throw new Error("Admin should see created_at and updated_at fields.");
  }
  // 'deleted_at' may be undefined or null for active record, but must not contain unexpected value (since just created)
  TestValidator.equals("deleted_at null or undefined")(
    adminFetched.deleted_at ?? null,
  )(null);
}

