/**
 * Validate failure cases for creating a product review with invalid input data.
 *
 * This test ensures the review creation endpoint properly rejects requests
 * where input values are invalid at runtime (while still forming valid
 * TypeScript objects). The API must return 400 validation errors and must not
 * create a new review for such cases. No resource should be created in any of
 * these error scenarios. Specifically covers out-of-range integer values for
 * the rating field and empty strings for the body.
 *
 * **Note:** Cases involving missing required fields (such as omitting rating,
 * body, product or order ID) are not implemented, because they would require
 * intentionally writing TypeScript code that does not compile (omitting
 * required fields from an object), which is prohibited. Only scenarios with
 * runtime invalid values that still compile are included.
 *
 * Test workflow:
 *
 * 1. Attempt to create a review with a rating below the valid minimum (e.g., 0,
 *    valid is 1-5).
 * 2. Attempt to create a review with a rating above the valid maximum (e.g., 6,
 *    valid is 1-5).
 * 3. Attempt to create a review with an empty string for body.
 *
 * For each scenario, verify that the API returns a 400 series validation error
 * and does not create a review.
 */
export async function test_api_shopping_mall_ai_test_create_review_fail_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Out of range rating (too low)
  await TestValidator.error("rating below minimum must fail")(async () => {
    await api.functional.shopping_mall_ai.customer.reviews.create(connection, {
      body: {
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
        rating: 0, // Below valid minimum (1)
        body: "Some review body",
      } satisfies IShoppingMallAiReview.ICreate,
    });
  });

  // 2. Out of range rating (too high)
  await TestValidator.error("rating above maximum must fail")(async () => {
    await api.functional.shopping_mall_ai.customer.reviews.create(connection, {
      body: {
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
        rating: 6, // Above valid maximum (5)
        body: "Some review body",
      } satisfies IShoppingMallAiReview.ICreate,
    });
  });

  // 3. Empty string body
  await TestValidator.error("empty body must fail")(async () => {
    await api.functional.shopping_mall_ai.customer.reviews.create(connection, {
      body: {
        shopping_mall_ai_product_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
        rating: 3,
        body: "", // Invalid: empty body
      } satisfies IShoppingMallAiReview.ICreate,
    });
  });
}

