import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validate that a customer can successfully update the content of their own
 * product review.
 *
 * This test ensures that:
 *
 * - The review exists and was originally created by the authenticated customer.
 * - The customer can update the review's rating, body, or both, as long as it has
 *   not been deleted.
 * - The system validates authorship, so only the original review author can
 *   perform the edit.
 * - When the update is performed, the review's updated_at field changes
 *   accordingly.
 * - The operation is successful, and the response reflects the updated review
 *   content.
 *
 * Step-by-step process:
 *
 * 1. Create a product review (precondition: the customer is authenticated and owns
 *    an order).
 * 2. Update the review by changing its rating and/or body through the provided
 *    API.
 * 3. Retrieve the review result and check:
 *
 *    - The fields (rating, body) reflect the change.
 *    - The updated_at field is changed (greater than created_at).
 *    - The authorship and reviewId remain consistent.
 *    - Deleted_at field remains null or unchanged.
 */
export async function test_api_shopping_mall_ai_test_update_product_review_content_success_by_customer(
  connection: api.IConnection,
) {
  // 1. Create an initial review as the customer; simulate a verified purchase.
  const reviewCreateInput: IShoppingMallAiReview.ICreate = {
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 4,
    body: "Initial review body.",
  };
  const originalReview =
    await api.functional.shopping_mall_ai.customer.reviews.create(connection, {
      body: reviewCreateInput,
    });
  typia.assert(originalReview);

  // 2. Update the review's rating and body (simulate user edit within business rules)
  const updateInput: IShoppingMallAiReview.IUpdate = {
    rating: 5,
    body: "Updated review body. Now with new insights.",
  };
  const updatedReview =
    await api.functional.shopping_mall_ai.customer.reviews.update(connection, {
      reviewId: originalReview.id,
      body: updateInput,
    });
  typia.assert(updatedReview);

  // 3. Confirm that the review fields have changed as expected
  TestValidator.equals("review rating updated")(updatedReview.rating)(
    updateInput.rating,
  );
  TestValidator.equals("review body updated")(updatedReview.body)(
    updateInput.body,
  );
  TestValidator.equals("reviewId unchanged")(updatedReview.id)(
    originalReview.id,
  );
  TestValidator.equals("product id unchanged")(
    updatedReview.shopping_mall_ai_product_id,
  )(originalReview.shopping_mall_ai_product_id);
  TestValidator.equals("customer id unchanged")(
    updatedReview.shopping_mall_ai_customer_id,
  )(originalReview.shopping_mall_ai_customer_id);
  TestValidator.equals("order id unchanged")(
    updatedReview.shopping_mall_ai_order_id,
  )(originalReview.shopping_mall_ai_order_id);
  // updated_at should be newer than created_at
  TestValidator.predicate("updated_at is newer")(
    new Date(updatedReview.updated_at).getTime() >
      new Date(updatedReview.created_at).getTime(),
  );
  // deleted_at should remain undefined or null (not deleted)
  TestValidator.predicate("not deleted")(
    updatedReview.deleted_at === undefined || updatedReview.deleted_at === null,
  );
}

