import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Verify review update authorization enforcement.
 *
 * This test ensures that only the original author (customer) or an admin can
 * update a review. We create a review using one customer account, then attempt
 * to update that review while authenticated as a different customer. The system
 * must enforce authorship restrictions and return a 403 Forbidden (or
 * equivalent authorization error), confirming that non-authors cannot update
 * someone else's review.
 *
 * Steps:
 *
 * 1. Customer A creates a valid review (POST /shopping-mall-ai/customer/reviews).
 * 2. Customer B attempts to update Customer A's review by calling PUT
 *    /shopping-mall-ai/customer/reviews/{reviewId} with valid data.
 * 3. Ensure the update is rejected with an authorization error (403 Forbidden).
 */
export async function test_api_shopping_mall_ai_customer_reviews_test_update_review_fail_unauthorized_edit_by_non_author(
  connection: api.IConnection,
) {
  // 1. Simulate Customer A account (test infra must provide unique identity/token for Customer A)
  //    If your e2e infra supports user authentication isolation, ensure this connection is Customer A

  // 1a. Prepare required IDs for product and order—these would be for a product Customer A purchased
  const productId: string = typia.random<string & tags.Format<"uuid">>();
  const orderId: string = typia.random<string & tags.Format<"uuid">>();
  const reviewCreate: IShoppingMallAiReview.ICreate = {
    shopping_mall_ai_product_id: productId,
    shopping_mall_ai_order_id: orderId,
    rating: 5,
    body: "Excellent product! Highly recommended.",
  };

  // 1b. Customer A creates the review
  const review = await api.functional.shopping_mall_ai.customer.reviews.create(
    connection,
    { body: reviewCreate },
  );
  typia.assert(review);

  // 2. Simulate Customer B identity for subsequent operation
  //    This step assumes test infra provides for token/user context swap.
  //    Make sure to swap connection credentials to Customer B before the update below.

  // 3. Attempt to update the review (owned by Customer A) with valid payload as Customer B
  const updateBody: IShoppingMallAiReview.IUpdate = {
    body: "Malicious unauthorized update!",
    rating: 1,
  };
  await TestValidator.error("should reject review update by non-author")(
    async () => {
      await api.functional.shopping_mall_ai.customer.reviews.update(
        connection,
        {
          reviewId: review.id,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validate admin moderation or override of an existing product review.
 *
 * Business context: In shopping mall operations, product reviews can be edited
 * or moderated by admins for reasons such as compliance, inappropriate content,
 * or user disputes. An admin must be able to update the rating or body, and/or
 * apply a soft delete (moderation action) after a review is submitted by a
 * customer.
 *
 * Preconditions:
 *
 * - There EXISTS a customer-submitted review, which the admin will moderate or
 *   edit.
 *
 * Steps:
 *
 * 1. A customer submits a product review using the POST
 *    /shopping-mall-ai/customer/reviews endpoint. The review contains a valid
 *    product, order, rating, and body.
 * 2. Admin (implicitly, via permissions on the connection) updates the review by
 *    calling PUT /shopping-mall-ai/admin/reviews/{reviewId} with new content
 *    (rating/body) and/or a moderation action (e.g., updating deleted_at for
 *    soft delete).
 *
 *    - Example 1: Change the review text and rating.
 *    - Example 2: Soft delete the review (set deleted_at to now).
 * 3. Assert that:
 *
 *    - The updated response reflects the admin's update (rating/body or deleted_at
 *         match input).
 *    - Updated_at is more recent than created_at.
 *    - Audit logic is satisfied (e.g., fields modified, no forbidden fields are
 *         changed).
 * 4. Edge case: The update should succeed even if review is soft-deleted (admin
 *    override). Test by first soft-deleting, then updating content again as
 *    admin.
 */
export async function test_api_shopping_mall_ai_admin_reviews_test_update_review_moderation_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Customer submits a product review
  const reviewCreateInput: IShoppingMallAiReview.ICreate = {
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 4,
    body: "Initial customer review text.",
  };
  const review = await api.functional.shopping_mall_ai.customer.reviews.create(
    connection,
    {
      body: reviewCreateInput,
    },
  );
  typia.assert(review);

  // 2. Admin edits rating and body
  const newRating = 2;
  const newBody = "Edited by admin for compliance issue.";
  const updateResponse =
    await api.functional.shopping_mall_ai.admin.reviews.update(connection, {
      reviewId: review.id,
      body: {
        rating: newRating,
        body: newBody,
      } satisfies IShoppingMallAiReview.IUpdate,
    });
  typia.assert(updateResponse);
  TestValidator.equals("updated rating")(updateResponse.rating)(newRating);
  TestValidator.equals("updated body")(updateResponse.body)(newBody);
  TestValidator.predicate("updated_at is newer")(
    new Date(updateResponse.updated_at) > new Date(review.updated_at),
  );

  // 3. Admin soft deletes the review (moderation action)
  const deletedAt = new Date().toISOString();
  const deletionResponse =
    await api.functional.shopping_mall_ai.admin.reviews.update(connection, {
      reviewId: review.id,
      body: {
        deleted_at: deletedAt,
      } satisfies IShoppingMallAiReview.IUpdate,
    });
  typia.assert(deletionResponse);
  TestValidator.equals("deleted_at set")(deletionResponse.deleted_at)(
    deletedAt,
  );
  TestValidator.predicate("updated_at after soft delete")(
    new Date(deletionResponse.updated_at) >=
      new Date(updateResponse.updated_at),
  );

  // 4. Edge case: Admin updates deleted review (should succeed)
  const resurrectedText = "Admin override edit after deletion.";
  const edgeResponse =
    await api.functional.shopping_mall_ai.admin.reviews.update(connection, {
      reviewId: review.id,
      body: {
        body: resurrectedText,
        rating: 5,
      } satisfies IShoppingMallAiReview.IUpdate,
    });
  typia.assert(edgeResponse);
  TestValidator.equals("body after override")(edgeResponse.body)(
    resurrectedText,
  );
  TestValidator.equals("rating after override")(edgeResponse.rating)(5);
  TestValidator.predicate("updated_at after resurrection")(
    new Date(edgeResponse.updated_at) > new Date(deletionResponse.updated_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
