/**
 * Validates that attempting to moderate (update) a product review as admin
 * fails when the specified reviewId does not exist.
 *
 * Business Context: Admins are allowed to perform moderation on product reviews
 * (such as soft deletion, editing body, or rating). However, if the provided
 * reviewId does not correspond to any existing review, the system must respond
 * with a "not found" error (404) and make no changes to the data.
 *
 * Test Process:
 *
 * 1. Compose a random, well-formed reviewId that is highly unlikely to exist
 *    (using UUID format).
 * 2. Prepare a valid moderation update (e.g., soft deletion with a 'deleted_at'
 *    timestamp, or updated body/rating).
 * 3. Call the admin review update API with the non-existent reviewId and the
 *    update payload.
 * 4. Confirm that the API call throws an HttpError (404 Not Found).
 * 5. Assert that no review data can be fetched using this reviewId and that no
 *    side effects have occurred.
 */
export async function test_api_shopping_mall_ai_test_update_review_moderation_fail_review_does_not_exist(
  connection: api.IConnection,
) {
  // 1. Compose a non-existent reviewId (well-formed UUID)
  const nonexistentReviewId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Prepare a valid review update payload
  const updatePayload: IShoppingMallAiReview.IUpdate = {
    body: "Admin moderation: removing due to violation.",
    deleted_at: new Date().toISOString() as string & tags.Format<"date-time">,
    rating: 1,
  };

  // 3. Attempt to update review as admin with non-existent reviewId
  await TestValidator.error(
    "should fail with 404 not found when updating non-existent review",
  )(async () => {
    await api.functional.shopping_mall_ai.admin.reviews.update(connection, {
      reviewId: nonexistentReviewId,
      body: updatePayload,
    });
  });
  // No further data fetch is possible as there is no direct get-by-id, and system side-effect check is covered by error assertion.
}

