import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validate soft delete (erase) failure scenarios for shopping mall AI product
 * reviews.
 *
 * This test covers two edge/failure cases:
 *
 * 1. An unauthorized user tries to delete (soft-erase) a review that they do NOT
 *    own. The API must deny this attempt, returning an error (403 forbidden or
 *    similar) and the review must remain unaffected.
 * 2. An author tries to delete a review that is already deleted (has deleted_at
 *    set). The API must deny the request (error 404 or 409 suggested), and must
 *    not modify review or perform duplicate action.
 *
 * Prerequisites:
 *
 * - Successfully create a product review (via POST
 *   /shopping-mall-ai/customer/reviews)
 * - Simulate at least two users: the owner (author) and a non-owner (unauthorized
 *   user)
 *
 * Steps:
 *
 * 1. UserA (author) creates a new review (capture reviewId)
 * 2. UserB (not the author) attempts to erase the review: should fail with a
 *    permission error (403), and the review remains not-deleted
 * 3. Switch to UserA, perform successful soft-delete of the review
 * 4. UserA tries to erase the already deleted review—should fail (404 or 409),
 *    confirming idempotent state handling
 */
export async function test_api_shopping_mall_ai_customer_reviews_test_delete_review_fail_non_author_or_already_deleted(
  connection: api.IConnection,
) {
  // --- Test Setup ---
  // Simulate two customer connections: userA (author) and userB (non-author)
  // These would be replaced with actual authentication if customer auth API is present
  const connectionUserA = { ...connection };
  const connectionUserB = { ...connection };

  // 1. UserA creates a review
  const reviewCreateBody: IShoppingMallAiReview.ICreate = {
    shopping_mall_ai_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_order_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 5,
    body: "Excellent product! Would buy again.",
  };
  const review = await api.functional.shopping_mall_ai.customer.reviews.create(
    connectionUserA,
    { body: reviewCreateBody },
  );
  typia.assert(review);
  const reviewId = review.id;

  // 2. UserB (non-owner) attempts to delete the review (should fail)
  await TestValidator.error("Unauthorized erase must fail")(
    async () =>
      await api.functional.shopping_mall_ai.customer.reviews.erase(
        connectionUserB,
        { reviewId },
      ),
  );

  // 3. UserA performs successful soft-delete
  await api.functional.shopping_mall_ai.customer.reviews.erase(
    connectionUserA,
    { reviewId },
  );

  // 4. UserA attempts to erase the already deleted review (should fail)
  await TestValidator.error("Erase already deleted review must fail")(
    async () =>
      await api.functional.shopping_mall_ai.customer.reviews.erase(
        connectionUserA,
        { reviewId },
      ),
  );
}

