import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAiContentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAiContentAudit";

/**
 * Validate deduplication or uniqueness policy for AI content audit events
 * (admin endpoint).
 *
 * This test verifies whether the system enforces or ignores duplicate audit
 * logs based on identical content_type, content_id, and audited_at timestamp.
 *
 * 1. Prepare a random audit event input with specific (content_type, content_id,
 *    audited_at) combination and other required fields.
 * 2. Call the admin API to insert the first AI content audit event, check success,
 *    and verify response matches input.
 * 3. Immediately submit another creation request with precisely the same input
 *    (exact duplicate event).
 * 4. Outcome:
 *
 *    - If duplicate insert is permitted (no deduplication), confirm new record
 *         creation and input field matching.
 *    - If duplicate is rejected (uniqueness enforced), verify the API throws an
 *         error and document that this is expected.
 */
export async function test_api_shopping_mall_ai_admin_aiContentAudits_test_create_ai_content_audit_with_duplicate_event(
  connection: api.IConnection,
) {
  // 1. Prepare a fixed test input for audit event
  const auditInput: IShoppingAiContentAudit.ICreate = {
    content_type: "review",
    content_id: typia.random<string & tags.Format<"uuid">>(),
    violation_type: "spam",
    confidence: 0.95,
    action_suggested: "review",
    audited_at: new Date().toISOString(),
  };

  // 2. Create the first event (should always succeed)
  const event1 =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.create(
      connection,
      { body: auditInput },
    );
  typia.assert(event1);
  TestValidator.equals("content_type matches")(event1.content_type)(
    auditInput.content_type,
  );
  TestValidator.equals("content_id matches")(event1.content_id)(
    auditInput.content_id,
  );
  TestValidator.equals("audited_at matches")(event1.audited_at)(
    auditInput.audited_at,
  );

  // 3. Attempt to insert duplicate event (identical input)
  let duplicateAllowed = false;
  let event2: IShoppingAiContentAudit | undefined = undefined;
  try {
    event2 = await api.functional.shopping_mall_ai.admin.aiContentAudits.create(
      connection,
      { body: auditInput },
    );
    typia.assert(event2);
    duplicateAllowed = true;
  } catch {
    duplicateAllowed = false;
  }

  // 4. Check and assert policy
  if (duplicateAllowed && event2) {
    // Duplicates allowed: event2 fields should match input again
    TestValidator.equals("duplicate content_type")(event2.content_type)(
      auditInput.content_type,
    );
    TestValidator.equals("duplicate content_id")(event2.content_id)(
      auditInput.content_id,
    );
    TestValidator.equals("duplicate audited_at")(event2.audited_at)(
      auditInput.audited_at,
    );
  }
  // If rejected, that is expected (uniqueness enforced).
}

