/**
 * Validate immutability of certain fields in AI content audit records during
 * update.
 *
 * This test ensures that immutable fields (content_type, content_id, id) in the
 * audit record cannot be changed after creation—enforced at both TypeScript
 * type and backend API level.
 *
 * Test Steps:
 *
 * 1. Create a new AI content audit record (admin-only endpoint).
 * 2. Attempt to update content_type or content_id via the update endpoint: not
 *    possible in TS (fields missing from IUpdate), thus confirmed at
 *    contract-level.
 * 3. (Mandatory E2E): Attempt a legal update to mutable fields (violation_type,
 *    confidence, action_suggested, audited_at) and verify changes registered.
 *
 * This confirms TypeScript DTO immutability and API compliance for audit log
 * records.
 */
export async function test_api_shopping_mall_ai_admin_aicontentaudits_test_update_ai_content_audit_with_immutable_field_change(
  connection: api.IConnection,
) {
  // 1. Create an AI content audit record
  const original: IShoppingAiContentAudit =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.create(
      connection,
      {
        body: {
          content_type: "bbs_post",
          content_id: typia.random<string & tags.Format<"uuid">>(),
          violation_type: "spam",
          confidence: 0.95,
          action_suggested: "review",
          audited_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies IShoppingAiContentAudit.ICreate,
      },
    );
  typia.assert(original);

  // 2. Confirm TypeScript contract prevents updating immutable fields
  // TypeScript will not allow content_type/content_id in IUpdate, so actual code cannot try to update them.
  // Here, we demonstrate an update only for allowed fields; actual attempts to set forbidden fields are blocked at compile time (API and DTO design compliance).

  // 3. (Mandatory runtime verification) Update mutable fields and verify
  const updatedViolationType = "personal_info";
  const updatedConfidence = 0.8;
  const updatedActionSuggested = "block";
  const updatedAuditedAt = new Date(
    Date.now() + 60_000,
  ).toISOString() as string & tags.Format<"date-time">;
  const updated: IShoppingAiContentAudit =
    await api.functional.shopping_mall_ai.admin.aiContentAudits.update(
      connection,
      {
        aiContentAuditId: original.id,
        body: {
          violation_type: updatedViolationType,
          confidence: updatedConfidence,
          action_suggested: updatedActionSuggested,
          audited_at: updatedAuditedAt,
        } satisfies IShoppingAiContentAudit.IUpdate,
      },
    );
  typia.assert(updated);

  // Confirm all mutable fields updated and immutable fields unchanged
  TestValidator.equals("violation_type updated")(updated.violation_type)(
    updatedViolationType,
  );
  TestValidator.equals("confidence updated")(updated.confidence)(
    updatedConfidence,
  );
  TestValidator.equals("action_suggested updated")(updated.action_suggested)(
    updatedActionSuggested,
  );
  TestValidator.equals("audited_at updated")(updated.audited_at)(
    updatedAuditedAt,
  );
  TestValidator.equals("content_type immutable")(updated.content_type)(
    original.content_type,
  );
  TestValidator.equals("content_id immutable")(updated.content_id)(
    original.content_id,
  );
  TestValidator.equals("id immutable")(updated.id)(original.id);
}

