import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";

/**
 * Validate the admin file list retrieval capability.
 *
 * This test ensures that an administrator can successfully retrieve the
 * complete list of all files uploaded to the shopping mall AI platform. Each
 * file metadata record should contain all relevant fields: original file name,
 * URI, extension, MIME type, size, hash, and timestamps (created_at and
 * optionally deleted_at). The test also confirms that soft-deleted files, if
 * any, are either included with a proper deleted_at indicator or all entries
 * have deleted_at as null, depending on business logic implementation.
 *
 * Steps:
 *
 * 1. (Assuming admin connection) Call the admin file list endpoint.
 * 2. Validate the array of metadata summary rows is present and has expected
 *    structure.
 * 3. For each file record, assert the presence and runtime types/formats of all
 *    expected fields, including optional handling of deleted_at (soft-deleted
 *    indicator).
 * 4. Check that if any files are soft-deleted (deleted_at not null), the value is
 *    a valid ISO 8601 timestamp; otherwise, all deleted_at are null.
 */
export async function test_api_shopping_mall_ai_admin_files_index(
  connection: api.IConnection,
) {
  // 1. Retrieve file list as admin
  const output =
    await api.functional.shopping_mall_ai.admin.files.index(connection);
  typia.assert(output);

  // 2. Validate that each file record contains all expected metadata fields and correct formats
  for (const file of output.data) {
    TestValidator.predicate("id exists and is uuid")(
      typeof file.id === "string" && /^[0-9a-fA-F-]{36}$/.test(file.id),
    );
    TestValidator.predicate("original_name is string")(
      typeof file.original_name === "string",
    );
    TestValidator.predicate("uri is string")(typeof file.uri === "string");
    TestValidator.predicate("extension is string")(
      typeof file.extension === "string",
    );
    TestValidator.predicate("mime_type is string")(
      typeof file.mime_type === "string",
    );
    TestValidator.predicate("size is integer")(
      typeof file.size === "number" && Number.isInteger(file.size),
    );
    TestValidator.predicate("hash is string")(typeof file.hash === "string");
    TestValidator.predicate("created_at is ISO date-time")(
      typeof file.created_at === "string" &&
        !Number.isNaN(Date.parse(file.created_at)),
    );
    TestValidator.predicate("deleted_at is null or ISO date-time")(
      file.deleted_at === null ||
        (typeof file.deleted_at === "string" &&
          !Number.isNaN(Date.parse(file.deleted_at))),
    );
  }

  // 3. Check soft-deletion indicator consistency
  if (output.data.some((file) => file.deleted_at !== null)) {
    // There are soft-deleted files (deleted_at not null)
    for (const file of output.data.filter((f) => f.deleted_at !== null)) {
      TestValidator.predicate("soft-deleted file deleted_at is ISO date-time")(
        typeof file.deleted_at === "string" &&
          !Number.isNaN(Date.parse(file.deleted_at)),
      );
    }
  } else {
    // All files have deleted_at as null
    TestValidator.predicate("all files not soft-deleted")(
      output.data.every((f) => f.deleted_at === null),
    );
  }
}

