      } satisfies IShoppingMallAiFile.ICreate,
    },
  );
  typia.assert(deletedFile);

  // 3. Soft delete the second file
  await api.functional.shopping_mall_ai.admin.files.erase(connection, {
    fileId: deletedFile.id,
  });

  // 4. List all files as admin
  const fileListing =
    await api.functional.shopping_mall_ai.admin.files.index(connection);
  typia.assert(fileListing);

  // 5. Assert both files are included and their soft deletion status is correct
  const foundActive = fileListing.data.find((f) => f.id === activeFile.id);
  const foundDeleted = fileListing.data.find((f) => f.id === deletedFile.id);

  TestValidator.predicate("active file is listed and not deleted")(
    !!foundActive &&
      (foundActive.deleted_at === null || foundActive.deleted_at === undefined),
  );
  TestValidator.predicate("soft-deleted file is listed and marked deleted")(
    !!foundDeleted && !!foundDeleted.deleted_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import type { IPageIShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFile";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced file search with a variety of filters and pagination for admin
 * file listings.
 *
 * This verifies that searching (PATCH /shopping-mall-ai/admin/files) with
 * various filters (name, extension, actor, upload range, pagination) yields
 * only matching files and returns correct page meta-info. Covers both positive
 * cases (finding files) and edge cases (no matches).
 *
 * Steps:
 *
 * 1. Register multiple files with unique and overlapping values for searchable
 *    fields (e.g. original_name, extension, actor_type, created_at)
 * 2. For each filterable field (except hash, actor_type, actor_id — these cannot
 *    be filtered or asserted using this endpoint), search to confirm only the
 *    matching files are returned
 * 3. Combine filters for AND-logical search if supported fields are filterable
 * 4. Confirm pagination splits results and meta is set correctly
 * 5. Test no-result (negative) case
 */
export async function test_api_shopping_mall_ai_test_search_files_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Setup - create several files with different original_name, extension, mime_type, and created_at
  const now = new Date();
  type Variant = {
    original_name: string;
    extension: string;
    mime_type: string;
    created_at: string;
  };
  const variantA: Variant = {
    original_name: `img_test_${RandomGenerator.alphaNumeric(6)}`,
    extension: "jpg",
    mime_type: "image/jpeg",
    created_at: new Date(now.getTime() - 600000).toISOString(), // 10min ago
  };
  const variantB: Variant = {
    original_name: `pdf_test_${RandomGenerator.alphaNumeric(6)}`,
    extension: "pdf",
    mime_type: "application/pdf",
    created_at: new Date(now.getTime() - 300000).toISOString(), // 5min ago
  };
  const variantC: Variant = {
    original_name: `txt_test_${RandomGenerator.alphaNumeric(6)}`,
    extension: "txt",
    mime_type: "text/plain",
    created_at: now.toISOString(),
  };
  const toCreate: Variant[] = [variantA, variantB, variantC];
  const files: Array<Variant & { id: string; uri: string }> = [];
  for (const v of toCreate) {
    const saved = await api.functional.shopping_mall_ai.admin.files.create(
      connection,
      {
        body: {
          original_name: v.original_name,
          uri: `https://cdn.test/${RandomGenerator.alphaNumeric(32)}`,
          extension: v.extension,
          mime_type: v.mime_type,
          size: typia.random<number & tags.Type<"int32">>(),
          hash: RandomGenerator.alphaNumeric(32),
        },
      },
    );
    typia.assert(saved);
    files.push({ ...v, id: saved.id, uri: saved.uri });
  }

  // 2. Search by individual filter
  for (const file of files) {
    // By original_name
    const byName = await api.functional.shopping_mall_ai.admin.files.search(
      connection,
      {
        body: { original_name: file.original_name },
      },
    );
    typia.assert(byName);
    TestValidator.predicate("original_name filter works")(
      byName.data.every((f) => f.original_name === file.original_name),
    );
    // By extension
    const byExt = await api.functional.shopping_mall_ai.admin.files.search(
      connection,
      {
        body: { extension: file.extension },
      },
    );
    typia.assert(byExt);
    TestValidator.predicate(`extension filter ${file.extension}`)(
      byExt.data.every((f) => f.extension === file.extension),
    );
    // By mime_type
    const byMime = await api.functional.shopping_mall_ai.admin.files.search(
      connection,
      {
        body: { mime_type: file.mime_type },
      },
    );
    typia.assert(byMime);
    TestValidator.predicate(`mime_type filter ${file.mime_type}`)(
      byMime.data.every((f) => f.mime_type === file.mime_type),
    );
  }

  // 3. By created_at range -- find those within last ~6min
  const from = new Date(now.getTime() - 360000).toISOString(); // 6min ago
  const rangeRes = await api.functional.shopping_mall_ai.admin.files.search(
    connection,
    {
      body: { created_from: from, created_to: now.toISOString() },
    },
  );
  typia.assert(rangeRes);
  TestValidator.predicate("created_at range match")(
    rangeRes.data.every(
      (f) => f.created_at >= from && f.created_at <= now.toISOString(),
    ),
  );

  // 4. Combined filter (AND): extension + mime_type
  const combos = [
    { extension: "jpg", mime_type: "image/jpeg" },
    { extension: "txt", mime_type: "text/plain" },
  ];
  for (const combo of combos) {
    const res = await api.functional.shopping_mall_ai.admin.files.search(
      connection,
      {
        body: { ...combo },
      },
    );
    typia.assert(res);
    TestValidator.predicate("combined filter AND")(
      res.data.every(
        (f) =>
          f.extension === combo.extension && f.mime_type === combo.mime_type,
      ),
    );
  }

  // 5. Pagination - limit=2
  const pag1 = await api.functional.shopping_mall_ai.admin.files.search(
    connection,
    {
      body: { limit: 2, page: 1 },
    },
  );
  typia.assert(pag1);
  TestValidator.equals("pagination page 1 count")(pag1.data.length)(2);
  const pag2 = await api.functional.shopping_mall_ai.admin.files.search(
    connection,
    {
      body: { limit: 2, page: 2 },
    },
  );
  typia.assert(pag2);
  TestValidator.predicate("pagination page 2 count")(
    pag2.data.length <= 2 && pag2.data.length >= 0,
  );
  TestValidator.equals("pagination meta page 2")(pag2.pagination.current)(2);
  TestValidator.equals("pagination meta limit")(pag2.pagination.limit)(2);

  // 6. Negative filter - bogus file name
  const neg = await api.functional.shopping_mall_ai.admin.files.search(
    connection,
    {
      body: { original_name: "this_file_does_not_exist_ABCDEFG" },
    },
  );
  typia.assert(neg);
  TestValidator.equals("empty result for nonexistent file")(neg.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
