import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the admin advanced file search endpoint correctly rejects
 * invalid filter parameters.
 *
 * This test attempts to use the admin files advanced search endpoint with
 * multiple forms of invalid input:
 *
 * - A malformed date string for created_from (not ISO8601)
 * - An unsupported value for extension (such as a string including illegal chars
 *   or not allowed)
 * - A non-existent MIME type (e.g., gibberish)
 * - Negative page and limit values (out-of-range for pagination)
 *
 * The expectation is that each of these inputs will cause validation errors,
 * and the endpoint will NOT process the query (no data returned). Instead,
 * detailed validation errors should be surfaced, preserving backend integrity
 * and UX standards.
 *
 * Steps:
 *
 * 1. Try to search with a malformed created_from date: API must reject the request
 *    with a validation error.
 * 2. Try to search with a negative page and/or limit value: API must reject the
 *    request with a validation error.
 * 3. Try to search with an invalid extension (such as one with illegal
 *    characters): Expect a validation error.
 * 4. Try to search with a nonsensical MIME type: Validation should reject or the
 *    API should not return normal search results.
 *
 * These validations protect backend resources and ensure that only well-formed
 * filter queries are processed.
 */
export async function test_api_shopping_mall_ai_admin_files_test_search_files_with_invalid_filter_parameters(
  connection: api.IConnection,
) {
  // 1. Malformed created_from date (not ISO 8601)
  await TestValidator.error("malformed date should be rejected")(async () => {
    await api.functional.shopping_mall_ai.admin.files.search(connection, {
      body: {
        created_from: "not-a-date",
      } satisfies IShoppingMallAiFile.IRequest,
    });
  });

  // 2. Negative page and limit values (invalid for pagination)
  await TestValidator.error("negative page should be rejected")(async () => {
    await api.functional.shopping_mall_ai.admin.files.search(connection, {
      body: {
        page: -1,
      } satisfies IShoppingMallAiFile.IRequest,
    });
  });
  await TestValidator.error("negative limit should be rejected")(async () => {
    await api.functional.shopping_mall_ai.admin.files.search(connection, {
      body: {
        limit: -5,
      } satisfies IShoppingMallAiFile.IRequest,
    });
  });

  // 3. Illegal extension string (illegal characters)
  await TestValidator.error("illegal extension should be rejected")(
    async () => {
      await api.functional.shopping_mall_ai.admin.files.search(connection, {
        body: {
          extension: "exe;rm -rf*",
        } satisfies IShoppingMallAiFile.IRequest,
      });
    },
  );

  // 4. Nonsensical MIME type string
  await TestValidator.error("invalid mime_type should be rejected")(
    async () => {
      await api.functional.shopping_mall_ai.admin.files.search(connection, {
        body: {
          mime_type: "not/a-mime-type",
        } satisfies IShoppingMallAiFile.IRequest,
      });
    },
  );
}

