  const impossibleName =
    "ZZZQWERTY_NONEXISTENT_FILE_NAME_" +
    typia.random<string & tags.Format<"uuid">>();

  // 2. Perform a search with page=1, limit=10, and the impossible filter
  const response = await api.functional.shopping_mall_ai.admin.files.search(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        original_name: impossibleName,
      } satisfies IShoppingMallAiFile.IRequest,
    },
  );
  typia.assert(response);

  // 3. Assert that data is empty
  TestValidator.equals("no results")(response.data)([]);

  // 4. Validate pagination meta for zero results
  TestValidator.equals("zero records")(response.pagination.records)(0);
  // Pages may be 0 or 1 on zero result depending on backend convention
  TestValidator.predicate("zero or one total page")(
    response.pagination.pages === 0 || response.pagination.pages === 1,
  );
  TestValidator.equals("current page")(response.pagination.current)(1);
  TestValidator.equals("limit")(response.pagination.limit)(10);
}

