import type { IShoppingMallAiProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductSnapshot";
import type { IPageIShoppingMallAiProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiProductSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search of product snapshots with action type and date range
 * filters.
 *
 * This test ensures the product snapshot search endpoint returns correct data
 * when using action-based and date-based filters. It simulates admin catalog
 * operations (create, update), verifies that snapshot audit trails are
 * generated, and asserts proper filtering.
 *
 * Steps:
 *
 * 1. Create a new shopping mall AI product as the admin.
 * 2. Update the product to trigger an 'updated' action event (generating a new
 *    snapshot).
 * 3. Run a snapshot search for the product's ID and action 'updated'. Ensure all
 *    results are for the target product and action type.
 * 4. Run a snapshot search for the product's ID, filtering to a specific recent
 *    time window (covering the test actions). Ensure only snapshots in the time
 *    range are present.
 * 5. Validate that action and date filters work correctly: data is nonempty when
 *    expected, and actions/timestamps match query filters.
 */
export async function test_api_shopping_mall_ai_product_snapshots_test_search_product_snapshots_with_filters(
  connection: api.IConnection,
) {
  // 1. Create a new product
  const productInput: IShoppingMallAiProduct.ICreate = {
    shopping_mall_ai_product_category_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    title: RandomGenerator.paragraph()(3),
    description: RandomGenerator.content()()(2),
    price: typia.random<number & tags.JsonSchemaPlugin<{ format: "double" }>>(),
    status: "active",
    sku: RandomGenerator.alphaNumeric(10),
  };
  const product =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.create(
      connection,
      {
        body: productInput,
      },
    );
  typia.assert(product);

  // 2. Update the product to trigger 'updated' action (new snapshot)
  const updatedTitle = product.title + " [EDITED]";
  const updateRes =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: product.id,
        body: { title: updatedTitle },
      },
    );
  typia.assert(updateRes);

  // 3. Search for snapshots by product ID and 'updated' action.
  const byAction =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          action: "updated",
        },
      },
    );
  typia.assert(byAction);
  TestValidator.predicate("has 'updated' snapshot for product")(
    byAction.data.some(
      (snap) =>
        snap.shopping_mall_ai_product_id === product.id &&
        snap.action === "updated",
    ),
  );
  for (const snap of byAction.data) {
    TestValidator.equals("filtered by correct product")(
      snap.shopping_mall_ai_product_id,
    )(product.id);
    TestValidator.equals("action filtered as 'updated'")(snap.action)(
      "updated",
    );
  }

  // 4. Search for snapshots by product ID and a recent date window (from creation to now)
  const now = new Date();
  const createdAfter = new Date(
    new Date(product.created_at).getTime() - 1000,
  ).toISOString();
  const createdBefore = new Date(now.getTime() + 1000).toISOString();
  const byDate =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: product.id,
          created_after: createdAfter,
          created_before: createdBefore,
        },
      },
    );
  typia.assert(byDate);
  TestValidator.predicate("all results are for the correct product")(
    byDate.data.every(
      (snap) => snap.shopping_mall_ai_product_id === product.id,
    ),
  );
  TestValidator.predicate("snapshots fall within date range")(
    byDate.data.every(
      (snap) =>
        snap.created_at >= createdAfter && snap.created_at <= createdBefore,
    ),
  );
}

