/**
 * 잘못된 검색 조건에 대한 상품 스냅샷 검색 안정성 검증
 *
 * 목적: 관리자가 존재하지 않는 action 타입이나 논리적으로 불가능한 날짜 범위로 상품 스냅샷을 검색할 때, 시스템이 크래시나 미처리
 * 예외 없이 정상적으로 빈 결과를 반환하거나, 허용되는 범위 내 적절한 에러를 반환하는지 검증합니다.
 *
 * 비즈니스 컨텍스트: 많은 기업이 역추적, 규제 감사, 롤백 분석을 위해 스냅샷 검색 기능을 활용합니다. 이때 잘못된 검색 조건이 시스템
 * 장애로 이어질 경우 SLA 및 보안 이슈가 발생할 수 있으므로, 에러 처리 및 무결성 보장을 위해 본 테스트가 필요합니다.
 *
 * 상세 시나리오:
 *
 * 1. 존재하지 않는 action 타입(예: 'nonexistent_action')으로 검색 - 0건 결과 확인
 * 2. 불가능한 날짜 범위(시작이 끝보다 늦은 경우)로 검색 - 0건 또는 허용 에러 응답 확인
 * 3. 모든 필드를 null로 하여 조건 없이 검색 - 데이터 정상 반환 확인
 * 4. 각 요청별 비즈니스 제약, 예외, 안정성을 검증
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiProductSnapshots_test_search_product_snapshots_with_invalid_criteria(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는 action 유형으로 검색: 반드시 빈 결과
  const output1 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.search(
      connection,
      {
        body: {
          action: "nonexistent_action",
        } satisfies IShoppingMallAiProductSnapshot.IRequest,
      },
    );
  typia.assert(output1);
  TestValidator.equals("존재하지 않는 action 타입 0건 결과")(
    output1.data.length,
  )(0);

  // 2. 불가능한 날짜 범위(created_after > created_before)
  const after = new Date("2025-08-08T15:24:00.000Z").toISOString();
  const before = new Date("2025-08-07T15:24:00.000Z").toISOString();
  const output2 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.search(
      connection,
      {
        body: {
          created_after: after,
          created_before: before,
        } satisfies IShoppingMallAiProductSnapshot.IRequest,
      },
    );
  typia.assert(output2);
  // 0건 반환 혹은 시스템에 따라 에러가 허용될 수 있으므로, 빈 결과만 검증
  TestValidator.equals("불가능한 날짜 범위 0건 결과")(output2.data.length)(0);

  // 3. 모든 필드를 null로 조건 없이 검색: 정상적으로 데이터 반환 또는 empty array
  const output3 =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProductSnapshots.search(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: null,
          action: null,
          created_after: null,
          created_before: null,
          page: null,
          limit: null,
        } satisfies IShoppingMallAiProductSnapshot.IRequest,
      },
    );
  typia.assert(output3);
  TestValidator.predicate("조건없이 전체 결과 배열 반환")(
    Array.isArray(output3.data),
  );
}

