 *
 * This scenario emulates the end-to-end life cycle of a shopping mall AI
 * product, focusing on product snapshots for audit and compliance workflows:
 *
 * 1. Create a new product (triggers an initial snapshot event 'created').
 * 2. Update the product (triggers an additional snapshot event 'updated').
 * 3. Retrieve the full list of product snapshots, filtering for at least one
 *    snapshot associated with the tested product (to get a valid snapshot ID).
 * 4. Retrieve the snapshot detail data by its ID using the
 *    /shopping-mall-ai/admin/shoppingMallAiProductSnapshots/{id} endpoint.
 * 5. Validate that the metadata (product ID linkage, action, and snapshot_json
 *    contents) matches expectations.
 * 6. Ensure required audit data and event metadata are present, including
 *    timestamps.
 *
 * This test ensures correct linkage between snapshot event records and the
 * audited product, as well as guaranteeing all fields and audit information are
 * delivered for regulatory retrieval.
 */
export async function test_api_shopping_mall_ai_admin_shoppingMallAiProductSnapshots_test_get_product_snapshot_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new product to trigger a 'created' snapshot
