  // 2. Update the created product to generate at least one more snapshot (e.g. 'updated')
  const updateInput: IShoppingMallAiProduct.IUpdate = {
    title: "Updated Product Title for Snapshot", // Only update the title
  };
  const updatedProduct =
    await api.functional.shopping_mall_ai.admin.shoppingMallAiProducts.update(
      connection,
      {
        shoppingMallAiProductId: product.id,
        body: updateInput,
