import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiDeposit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiDeposit";

/**
 * Validate that an admin can successfully update mutable fields of an existing
 * deposit record.
 *
 * This test ensures that:
 *
 * - Admin can update fields such as balance, status, and expires_at of a deposit.
 * - The deposit must be created first with valid initial data.
 * - Updates are persisted, and relevant business rules (e.g., non-negative
 *   balance) are enforced.
 * - Timestamps (such as updated_at) should reflect the update.
 * - (If possible) Audit log functionality is triggered - but this test only
 *   ensures update success and re-read of changed fields as no audit API is
 *   available for direct check.
 *
 * Steps:
 *
 * 1. Create a deposit record with valid initial data.
 * 2. Update the deposit with new values for (a) balance, (b) status, (c)
 *    expires_at.
 * 3. Check that the updated fields and the updated_at timestamp have changed
 *    appropriately.
 * 4. Validate that business constraints (no negative balances) are enforced—try to
 *    update with a negative balance and expect error.
 */
export async function test_api_shopping_mall_ai_admin_deposits_test_update_deposit_success(
  connection: api.IConnection,
) {
  // 1. Create a deposit record with valid initial data
  const depositCreateInput: IShoppingMallAiDeposit.ICreate = {
    shopping_mall_ai_customer_id: typia.random<string & tags.Format<"uuid">>(),
    balance: 100.0,
    status: "active",
    origin: "promo",
    expires_at: null,
  };

  const created: IShoppingMallAiDeposit =
    await api.functional.shopping_mall_ai.admin.deposits.create(connection, {
      body: depositCreateInput,
    });
  typia.assert(created);

  // 2. Update the deposit with new values for (a) balance, (b) status, (c) expires_at
  const updateInput: IShoppingMallAiDeposit.IUpdate = {
    balance: 200.0,
    status: "expired",
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  };

  const updated: IShoppingMallAiDeposit =
    await api.functional.shopping_mall_ai.admin.deposits.update(connection, {
      depositId: created.id,
      body: updateInput,
    });
  typia.assert(updated);
  // 3. Check updated fields and timestamps
  TestValidator.equals("id matches")(updated.id)(created.id);
  TestValidator.equals("customer id unchanged")(
    updated.shopping_mall_ai_customer_id,
  )(created.shopping_mall_ai_customer_id);
  TestValidator.equals("updated balance")(updated.balance)(updateInput.balance);
  TestValidator.equals("updated status")(updated.status)(updateInput.status);
  TestValidator.equals("updated expires_at")(updated.expires_at)(
    updateInput.expires_at,
  );
  // updated_at should differ after update
  TestValidator.notEquals("updated_at should be updated")(updated.updated_at)(
    created.updated_at,
  );

  // 4. Try to update deposit with a negative balance. The API should reject it.
  await TestValidator.error("negative balance should be rejected")(async () => {
    await api.functional.shopping_mall_ai.admin.deposits.update(connection, {
      depositId: created.id,
      body: { balance: -50 },
    });
  });
}

