 *
 * The admin should be able to query a paginated list of all mileage point
 * (loyalty) events for any customer in the system. This test verifies:
 *
 * - That the paginated endpoint returns correct metadata and empty results when
 *   no mileage event records exist.
 * - That after inserting multiple mileage events for different customers, the
 *   list endpoint returns accurate data and pagination fields (including page,
 *   limit, records, pages, etc.).
 *
 * The process will:
 *
 * 1. Query the endpoint before data insertion — expect empty results.
 * 2. Insert multiple (e.g., 6) mileage point records using the event creation
 *    endpoint, ensuring different customers and event types (e.g., "accrual",
 *    "redemption", "adjustment") and mixing data such as point values and
 *    dates.
 * 3. Query the list endpoint again and check:
 *
 *    - All created events appear in the dataset
 *    - Pagination metadata matches expected values
 *
 * Validations:
 *
 * - Result set is empty at first.
 * - After insertion, result set includes all created entries, and page metadata
 *   is correct for default (first page) paging behavior.
 * - Each returned entry conforms fully to the mileage point DTO schema.
 * - Can optionally check that the result sorting or grouping is consistent with
 *   business logic (e.g., default order by occurred_at descending, if so
 *   described).
 */
export async function test_api_mileagePoints_test_list_all_mileage_point_events_pagination(
  connection: api.IConnection,
) {
  // 1. List when DB is empty
  const emptyPage =
    await api.functional.shopping_mall_ai.admin.mileagePoints.index(connection);
  typia.assert(emptyPage);
  TestValidator.equals("empty count")(emptyPage.data.length)(0);

  // 2. Insert 6 sample mileage point events for random customers
  const createdPoints: IShoppingMallAiMileagePoint[] = [];
  for (let i = 0; i < 6; ++i) {
    const record =
      await api.functional.shopping_mall_ai.admin.mileagePoints.create(
        connection,
        {
          body: {
            shopping_mall_ai_customer_id: typia.random<
              string & tags.Format<"uuid">
            >(),
            point_type: ["accrual", "redemption", "adjustment"][i % 3],
            amount: typia.random<number & tags.Type<"int32">>(),
            details: i % 2 === 0 ? RandomGenerator.paragraph()() : null,
            occurred_at: new Date(Date.now() - i * 60_000).toISOString(),
          } satisfies IShoppingMallAiMileagePoint.ICreate,
        },
      );
    typia.assert(record);
    createdPoints.push(record);
  }

  // 3. List again after insertions
  const page =
    await api.functional.shopping_mall_ai.admin.mileagePoints.index(connection);
  typia.assert(page);
  // Confirm all created events are in the returned data
  for (const point of createdPoints) {
    TestValidator.predicate("created entry present")(
      page.data.find((r) => r.id === point.id) !== undefined,
    );
  }
  // Pagination metadata consistency
  TestValidator.equals("record count")(page.pagination.records)(
    createdPoints.length,
  );
  TestValidator.predicate("page >= 1")(page.pagination.current >= 1);
  TestValidator.predicate("limit >= created count")(
    page.pagination.limit >= createdPoints.length,
  );
  TestValidator.predicate("pages >= 1")(page.pagination.pages >= 1);
}

