 * Validates seller review list hides soft-deleted reviews (deleted_at is
 * non-null).
 *
 * Ensures that any reviews marked as soft-deleted (deleted_at set) do not
 * appear in the seller reviews endpoint; only non-deleted reviews are visible.
 *
 * **Test Steps:**
 *
 * 1. Fetch all reviews as seller.
 * 2. If there are at least two reviews, soft-delete the first review (as
 *    customer).
 * 3. Fetch the seller review list again.
 * 4. Assert no review returned has a non-null deleted_at field.
 * 5. (If applicable) Assert the non-deleted review remains visible.
 */
export async function test_api_shopping_mall_ai_test_get_product_reviews_for_seller_soft_deleted_views_are_hidden(
  connection: api.IConnection,
) {
  // 1. Fetch all reviews as seller
  const initialResult =
    await api.functional.shopping_mall_ai.seller.reviews.index(connection);
  typia.assert(initialResult);

  // 2. If at least two reviews, soft-delete the first review (simulates customer deletion)
  if (initialResult.data.length >= 2) {
    const reviewToDelete = initialResult.data[0];
    await api.functional.shopping_mall_ai.customer.reviews.erase(connection, {
      reviewId: reviewToDelete.id,
    });
  }

  // 3. Fetch seller review list again
  const result =
    await api.functional.shopping_mall_ai.seller.reviews.index(connection);
  typia.assert(result);

  // 4. Assert no review in the response has deleted_at set (non-null/defined)
  for (const review of result.data) {
    TestValidator.predicate("deleted_at must be null or undefined")(
      review.deleted_at == null,
    );
  }

  // 5. Optionally, assert that a control review still appears
  if (initialResult.data.length >= 2) {
    const controlReview = initialResult.data[1];
    const stillPresent = result.data.some((r) => r.id === controlReview.id);
    TestValidator.predicate("Non-deleted review remains present")(stillPresent);
  }
}

