import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validate that admin access exposes all product review data fields, including
 * sensitive and audit/compliance-related information, for moderation and
 * compliance needs.
 *
 * This test ensures the GET /shopping-mall-ai/admin/reviews endpoint returns a
 * paginated list of product reviews where each review contains all expected
 * fields per IShoppingMallAiReview:
 *
 * - Id (uuid)
 * - Shopping_mall_ai_product_id (uuid)
 * - Shopping_mall_ai_customer_id (uuid)
 * - Shopping_mall_ai_order_id (uuid)
 * - Rating (int32)
 * - Body (string)
 * - Created_at (ISO 8601)
 * - Updated_at (ISO 8601)
 * - Deleted_at (ISO 8601 | null or undefined) Additionally, pagination metadata
 *   (per IPage.IPagination) must be present.
 *
 * Steps:
 *
 * 1. (Assume test credentials grant admin permissions; no dependencies defined)
 * 2. Call GET /shopping-mall-ai/admin/reviews
 * 3. Assert the response matches IPageIShoppingMallAiReview: both pagination and
 *    data array.
 * 4. For each review in data, assert that all compliance/audit-related fields
 *    (order id, timestamps, deletion info) are present, non-empty, and properly
 *    typed (except for explicitly nullable fields).
 * 5. Negative: If authorization is missing/invalid, the endpoint must return an
 *    error (e.g., 401/403); this negative may be covered by a separate security
 *    test suite if not feasible in this test context.
 */
export async function test_api_shopping_mall_ai_admin_reviews_index(
  connection: api.IConnection,
) {
  // 1. Call GET /shopping-mall-ai/admin/reviews as an admin.
  const output =
    await api.functional.shopping_mall_ai.admin.reviews.index(connection);
  typia.assert(output);

  // 2. Validate pagination metadata structure.
  TestValidator.predicate("pagination metadata present")(
    typeof output.pagination === "object" && output.pagination !== null,
  );
  TestValidator.predicate("pagination current is number")(
    typeof output.pagination.current === "number",
  );
  TestValidator.predicate("pagination limit is number")(
    typeof output.pagination.limit === "number",
  );
  TestValidator.predicate("pagination records is number")(
    typeof output.pagination.records === "number",
  );
  TestValidator.predicate("pagination pages is number")(
    typeof output.pagination.pages === "number",
  );

  // 3. Each review must expose all audit/compliance fields per schema.
  for (const review of output.data) {
    TestValidator.predicate("review.id is string")(
      typeof review.id === "string",
    );
    TestValidator.predicate("review.shopping_mall_ai_product_id is string")(
      typeof review.shopping_mall_ai_product_id === "string",
    );
    TestValidator.predicate("review.shopping_mall_ai_customer_id is string")(
      typeof review.shopping_mall_ai_customer_id === "string",
    );
    TestValidator.predicate("review.shopping_mall_ai_order_id is string")(
      typeof review.shopping_mall_ai_order_id === "string",
    );
    TestValidator.predicate("review.rating is number")(
      typeof review.rating === "number",
    );
    TestValidator.predicate("review.body is string")(
      typeof review.body === "string",
    );
    TestValidator.predicate("review.created_at is string")(
      typeof review.created_at === "string",
    );
    TestValidator.predicate("review.updated_at is string")(
      typeof review.updated_at === "string",
    );
    if (review.deleted_at !== undefined && review.deleted_at !== null)
      TestValidator.predicate("review.deleted_at is string")(
        typeof review.deleted_at === "string",
      );
  }
  // (Optional) Negative auth scenario covered in separate suite.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
