import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";

/**
 * Validate admin retrieval of product reviews returns empty result when system
 * has no reviews.
 *
 * Business context:
 *
 * - Ensures the admin API for retrieving product reviews properly handles the
 *   boundary edge case where there are zero reviews in the system (e.g., new
 *   deployment, after database reset).
 * - Validates that the response is a well-formed paginated result, with empty
 *   data array, zero records, and zero pages, and that it does not cause any
 *   errors or exceptions.
 *
 * Steps:
 *
 * 1. Assume system is clean and contains no product reviews (precondition).
 * 2. Make admin API call to retrieve reviews.
 * 3. Assert response is correct: data array is empty, records/pages are zero,
 *    pagination metadata is valid.
 * 4. No error/exception should be thrown at any time.
 */
export async function test_api_shopping_mall_ai_admin_reviews_test_get_product_reviews_for_admin_empty_result(
  connection: api.IConnection,
) {
  // 1. Call the admin endpoint for product reviews
  const output =
    await api.functional.shopping_mall_ai.admin.reviews.index(connection);
  typia.assert(output);

  // 2. Confirm data array is empty
  TestValidator.equals("should return zero reviews")(output.data.length)(0);

  // 3. Confirm pagination fields are correct for empty data
  TestValidator.equals("pagination.records is zero")(output.pagination.records)(
    0,
  );
  TestValidator.equals("pagination.pages is zero")(output.pagination.pages)(0);

  // 4. Confirm current page is 1 and limit is a positive integer (default paging behavior)
  TestValidator.equals("current page is 1")(output.pagination.current)(1);
  TestValidator.predicate("limit is positive integer")(
    Number.isInteger(output.pagination.limit) && output.pagination.limit > 0,
  );
}

