import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";
import type { IPageIShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and pagination of inquiries for a seller.
 *
 * This test verifies that the seller inquiry search can properly filter by
 * product ID, customer ID, privacy flag, creation date, and answer status. It
 * also checks that only inquiries for the seller's products are visible, that
 * pagination and sorting work as expected, and that an empty result set is
 * correctly returned for unmatched filters.
 *
 * Steps:
 *
 * 1. Create a test seller's products
 * 2. For each product, create multiple inquiries from different (simulated)
 *    customers, varying the is_private (true/false) and answer states
 *    (answered, unanswered)
 * 3. Perform searches as the seller using advanced filter parameters:
 *
 *    - By product_id
 *    - By is_private
 *    - By answered status
 *    - With sorting by created_at and pagination
 * 4. Confirm search results match the filters and pagination/sorting specs
 * 5. Search with a non-existent product ID to confirm empty result is returned
 */
export async function test_api_shopping_mall_ai_seller_inquiries_test_search_inquiries_with_advanced_filters_and_pagination_as_seller(
  connection: api.IConnection,
) {
  // 1. Create two products for the test seller
  const productA =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "Product A",
          description: "Description for Product A",
          price: 100,
          status: "active",
          sku: RandomGenerator.alphaNumeric(8),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  const productB =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "Product B",
          description: "Description for Product B",
          price: 999,
          status: "active",
          sku: RandomGenerator.alphaNumeric(8),
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(productA);
  typia.assert(productB);

  // 2. Create inquiries from different simulated customers with various is_private and answered states
  // (Since the API doesn't expose customer creation, simulate with random UUIDs as stand-ins for separate customers)
  const customers: (string & tags.Format<"uuid">)[] = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const inquiries: IShoppingMallAiInquiry[] = [];
  for (const [idx, customerId] of customers.entries()) {
    // Public, unanswered inquiry for Product A
    const inquiry1 =
      await api.functional.shopping_mall_ai.customer.inquiries.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id: productA.id,
            question: `Question A${idx + 1} public`,
            is_private: false,
          } satisfies IShoppingMallAiInquiry.ICreate,
        },
      );
    typia.assert(inquiry1);
    inquiries.push(inquiry1);

    // Private, answered inquiry for Product A (simulate answer fields for filter testing)
    const inquiry2 =
      await api.functional.shopping_mall_ai.customer.inquiries.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id: productA.id,
            question: `Question A${idx + 1} private`,
            is_private: true,
          } satisfies IShoppingMallAiInquiry.ICreate,
        },
      );
    // For purposes of testing filter logic on answered, manually assign answer/answered_at
    Object.assign(inquiry2, {
      answer: "Test answer",
      answered_at: new Date().toISOString(),
    });
    inquiries.push(inquiry2);

    // Public, unanswered inquiry for Product B
    const inquiry3 =
      await api.functional.shopping_mall_ai.customer.inquiries.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id: productB.id,
            question: `Question B${idx + 1} public`,
            is_private: false,
          } satisfies IShoppingMallAiInquiry.ICreate,
        },
      );
    typia.assert(inquiry3);
    inquiries.push(inquiry3);
  }

  // 3. Search by product_id filter (should only show inquiries for that product)
  const resultByProduct =
    await api.functional.shopping_mall_ai.seller.inquiries.search(connection, {
      body: {
        filter: {
          shopping_mall_ai_product_id: productA.id,
        },
      },
    });
  typia.assert(resultByProduct);
  TestValidator.predicate("product_id filter")(
    resultByProduct.data.every(
      (i) => i.shopping_mall_ai_product_id === productA.id,
    ),
  );

  // 4. Search by is_private = true
  const resultPrivate =
    await api.functional.shopping_mall_ai.seller.inquiries.search(connection, {
      body: {
        filter: {
          is_private: true,
        },
      },
    });
  typia.assert(resultPrivate);
  TestValidator.predicate("private inquiries")(
    resultPrivate.data.every((i) => i.is_private === true),
  );

  // 5. Search for answered inquiries (by filter: answered = true)
  const resultAnswered =
    await api.functional.shopping_mall_ai.seller.inquiries.search(connection, {
      body: {
        filter: {
          answered: true,
        },
      },
    });
  typia.assert(resultAnswered);
  TestValidator.predicate("answered inquiries")(
    resultAnswered.data.every(
      (i) => i.answer !== undefined && i.answer !== null,
    ),
  );

  // 6. Pagination test: page 2 with limit 2, sorted ascending by created_at
  const page2 = await api.functional.shopping_mall_ai.seller.inquiries.search(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
        sort: "created_at",
        order: "asc",
      },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page")(page2.pagination.current)(2);
  TestValidator.equals("limit")(page2.pagination.limit)(2);

  // 7. Edge case: search with non-existent product ID to confirm empty result
  const emptyResult =
    await api.functional.shopping_mall_ai.seller.inquiries.search(connection, {
      body: {
        filter: {
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        },
      },
    });
  typia.assert(emptyResult);
  TestValidator.equals("empty data")(emptyResult.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";
import type { IPageIShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test for admin advanced search on product inquiries (cross-role and
 * privacy).
 *
 * Validates admin can:
 *
 * 1. Search/filter all inquiries (public, private, deleted, answered, unanswered)
 * 2. Access inquiries from various sellers and customers
 * 3. Pagination works correctly
 * 4. Error for invalid search criteria
 *
 * Steps:
 *
 * 1. Create two products with two different sellers (using random UUIDs for
 *    category)
 * 2. For each product, as two customers, create public and private inquiries
 * 3. As admin, perform PATCH /shopping-mall-ai/admin/inquiries:
 *
 *    - No filter (should get all inquiries)
 *    - Filter by is_private true/false, answered true/false
 *    - Pagination checks
 *    - Filter by customer or seller
 *    - Combination filters
 * 4. Assert results match filter
 * 5. Submit invalid filter type, expect error
 */
export async function test_api_shopping_mall_ai_admin_inquiries_test_admin_advanced_inquiry_search_for_all_roles_and_privacy(
  connection: api.IConnection,
) {
  // --- STEP 1: CREATE TWO PRODUCTS WITH DIFFERENT SELLERS ---
  // Simulate seller1
  // (Assume admin can create as either seller, as we cannot simulate seller authentication via API; use distinct valid category ids)
  const product1 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "Test Product 1",
          description: "Desc for product 1",
          price: 100.0,
          status: "active",
          sku: `SKU1-${RandomGenerator.alphaNumeric(6)}`,
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product1);

  // Simulate seller2
  const product2 =
    await api.functional.shopping_mall_ai.seller.shoppingMallAiProducts.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_category_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          title: "Test Product 2",
          description: "Desc for product 2",
          price: 200.0,
          status: "active",
          sku: `SKU2-${RandomGenerator.alphaNumeric(6)}`,
        } satisfies IShoppingMallAiProduct.ICreate,
      },
    );
  typia.assert(product2);

  // --- STEP 2: CREATE INQUIRIES AS DIFFERENT CUSTOMERS FOR BOTH PRODUCTS ---
  // We'll simulate 2 customers each submitting for both products, mixing privacy.
  // (Real authentication per customer is not feasible—API does not provide login—so will simulate with current connection context)
  const inquiries = [] as IShoppingMallAiInquiry[];
  for (let customerNo = 1; customerNo <= 2; ++customerNo) {
    for (const product of [product1, product2]) {
      // Public inquiry
      const inc1 =
        await api.functional.shopping_mall_ai.customer.inquiries.create(
          connection,
          {
            body: {
              shopping_mall_ai_product_id: product.id,
              question: `Customer${customerNo} public Q for ${product.title}`,
              is_private: false,
            } satisfies IShoppingMallAiInquiry.ICreate,
          },
        );
      typia.assert(inc1);
      inquiries.push(inc1);
      // Private inquiry
      const inc2 =
        await api.functional.shopping_mall_ai.customer.inquiries.create(
          connection,
          {
            body: {
              shopping_mall_ai_product_id: product.id,
              question: `Customer${customerNo} PRIVATE Q for ${product.title}`,
              is_private: true,
            } satisfies IShoppingMallAiInquiry.ICreate,
          },
        );
      typia.assert(inc2);
      inquiries.push(inc2);
    }
  }
  // Now we have 2 sellers, 2 customers, 2 inquiries (public/private) per customer/product ⇒ 8 total

  // --- STEP 3: AS ADMIN, PERFORM ADVANCED SEARCH QUERIES ---
  // 3-1: No filter (all inquiries, all privacies, all states)
  const output_all =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: {} satisfies IShoppingMallAiInquiry.IRequest,
    });
  typia.assert(output_all);
  // There should be at least 8 inquiries
  TestValidator.predicate("should get at least all created inquiries")(
    output_all.data.length >= inquiries.length,
  );
  // At least one inquiry from each seller/customer is present
  const sellersFound = new Set(
    output_all.data.map((i) => i.shopping_mall_ai_seller_id),
  );
  TestValidator.predicate("2 sellers present")(sellersFound.size >= 2);

  // 3-2: Filter by is_private true
  const output_private =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { filter: { is_private: true } },
    });
  typia.assert(output_private);
  for (const i of output_private.data)
    TestValidator.equals("is_private true")(i.is_private)(true);

  // 3-3: Filter by is_private false
  const output_public =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { filter: { is_private: false } },
    });
  typia.assert(output_public);
  for (const i of output_public.data)
    TestValidator.equals("is_private false")(i.is_private)(false);

  // 3-4: Pagination (limit = 2, page = 1)
  const output_page1 =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { limit: 2, page: 1 },
    });
  typia.assert(output_page1);
  TestValidator.equals("pagination, page1:")(output_page1.pagination.current)(
    1,
  );
  TestValidator.equals("pagination, page1, limit:")(
    output_page1.pagination.limit,
  )(2);
  TestValidator.equals("pagination, page1, count:")(
    output_page1.data.length <= 2,
  )(true);

  // 3-5: Pagination (limit = 2, page = 2)
  const output_page2 =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { limit: 2, page: 2 },
    });
  typia.assert(output_page2);
  TestValidator.equals("pagination, page2:")(output_page2.pagination.current)(
    2,
  );
  TestValidator.equals("pagination, page2, limit:")(
    output_page2.pagination.limit,
  )(2);

  // 3-6: Filter by seller
  const seller_id = product1.shopping_mall_ai_seller_id;
  const output_seller =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { filter: { shopping_mall_ai_seller_id: seller_id } },
    });
  typia.assert(output_seller);
  for (const i of output_seller.data)
    TestValidator.equals("seller id matches")(i.shopping_mall_ai_seller_id)(
      seller_id,
    );

  // 3-7: Filter by product
  const output_product =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: { filter: { shopping_mall_ai_product_id: product2.id } },
    });
  typia.assert(output_product);
  for (const i of output_product.data)
    TestValidator.equals("product id matches")(i.shopping_mall_ai_product_id)(
      product2.id,
    );

  // 3-8: Filter by is_private true and by product (should have only private inquiries for that product)
  const output_private_product =
    await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
      body: {
        filter: { is_private: true, shopping_mall_ai_product_id: product2.id },
      },
    });
  typia.assert(output_private_product);
  for (const i of output_private_product.data) {
    TestValidator.equals("is_private")(i.is_private)(true);
    TestValidator.equals("product id")(i.shopping_mall_ai_product_id)(
      product2.id,
    );
  }

  // --- STEP 4: ERROR CASE - INVALID FILTER PARAM TYPE ---
  await TestValidator.error("invalid is_private type should error")(
    async () => {
      await api.functional.shopping_mall_ai.admin.inquiries.search(connection, {
        body: { filter: { is_private: "not_a_bool" } } as any, // Intentional type error, checked at runtime
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";

/**
 * Validate that a customer can retrieve details of their own product inquiry by
 * inquiryId, with full access control.
 *
 * Scenario:
 *
 * 1. Create a product inquiry as Customer A.
 * 2. Retrieve the inquiry as Customer A and verify fields, ownership and
 *    not-deleted status.
 * 3. Skipped: Cannot test cross-customer access or deleted-inquiry fetch—no auth
 *    or delete APIs available.
 */
export async function test_api_shopping_mall_ai_customer_inquiries_test_get_inquiry_detail_by_customer_with_access_control(
  connection: api.IConnection,
) {
  // 1. 고객 A로 상품 문의(질문) 생성
  const createInput: IShoppingMallAiInquiry.ICreate = {
