/**
 * Validates the product review list endpoint for proper filtering and data
 * redaction by user role.
 *
 * Business context: Shopping mall reviews must be filtered by soft deletion and
 * the requesting user's role. Customers should only see non-deleted reviews,
 * sellers may see reviews related to their products (with potentially more
 * details), and admins can access all reviews, including soft-deleted. This
 * test verifies proper field redaction, visibility by role, and exclusion of
 * soft-deleted reviews where appropriate.
 *
 * Test steps:
 *
 * 1. Create several review records using multiple customers for several products.
 *    Some reviews are marked as soft-deleted (simulated if API lacks delete
 *    support).
 * 2. As a customer, request the list of reviews and: ensure only non-deleted
 *    reviews are visible; deleted reviews are excluded; and only public fields
 *    are present per business policy.
 * 3. As a seller, request the review list and check only their product reviews
 *    appear (data redacted if needed).
 * 4. As an admin, request review list and verify all reviews (including deleted)
 *    appear, with extra detail.
 * 5. Attempt to list as an unauthenticated/anonymous user, if policy allows;
 *    verify only public data/shown or proper fallback (access denied).
 */
export async function test_api_shopping_mall_ai_test_list_product_reviews_basic_access_and_data_redaction_by_role(
  connection: api.IConnection,
) {
  // Setup: Create two products and three customers
  const productIds: string[] = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const orderIds: string[] = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  // Test users and tokens (simulate auth via connection for role switching)
  const customerIds: string[] = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  // Create reviews: 3 active, 2 soft-deleted (simulate setting deleted_at)
  const reviewInputs: (Omit<IShoppingMallAiReview.ICreate, never> & {
    simulateDeleted?: boolean;
  })[] = [
    {
      shopping_mall_ai_product_id: productIds[0],
      shopping_mall_ai_order_id: orderIds[0],
      rating: 5,
      body: "Excellent!",
    },
    {
      shopping_mall_ai_product_id: productIds[0],
      shopping_mall_ai_order_id: orderIds[1],
      rating: 4,
      body: "Pretty good.",
    },
    {
      shopping_mall_ai_product_id: productIds[1],
      shopping_mall_ai_order_id: orderIds[2],
      rating: 2,
      body: "Not impressed.",
    },
    // Soft-deleted entries below (will be filtered from customer listing)
    {
      shopping_mall_ai_product_id: productIds[1],
      shopping_mall_ai_order_id: orderIds[3],
      rating: 1,
      body: "Terrible, and this will be marked as deleted.",
      simulateDeleted: true,
    },
    {
      shopping_mall_ai_product_id: productIds[1],
      shopping_mall_ai_order_id: orderIds[0],
      rating: 4,
      body: "Old, also deleted.",
      simulateDeleted: true,
    },
  ];
  const createdReviews: IShoppingMallAiReview[] = [];
  for (let i = 0; i < reviewInputs.length; ++i) {
    // Normally, review is created by an authenticated customer. Simulated via connection state.
    const review =
      await api.functional.shopping_mall_ai.customer.reviews.create(
        connection,
        {
          body: {
            shopping_mall_ai_product_id:
              reviewInputs[i].shopping_mall_ai_product_id,
            shopping_mall_ai_order_id:
              reviewInputs[i].shopping_mall_ai_order_id,
            rating: reviewInputs[i].rating,
            body: reviewInputs[i].body,
          } satisfies IShoppingMallAiReview.ICreate,
        },
      );
    // If we want to test deletion, but there's no delete API, simulate deleted_at in-memory (cannot update remote test DB)
    if (reviewInputs[i].simulateDeleted) {
      // Mark as deleted for our local assertions
      (review as any).deleted_at = new Date().toISOString();
    }
    createdReviews.push(review);
    typia.assert(review);
  }

  // 1. Customer role listing: should not see soft-deleted reviews
  const customerReviewList: IPageIShoppingMallAiReview =
    await api.functional.shopping_mall_ai.customer.reviews.index(connection);
  typia.assert(customerReviewList);
  for (const review of customerReviewList.data) {
    TestValidator.predicate(
      "customer-visible reviews must not be soft-deleted",
    )(!review.deleted_at);
  }

  // 2. Seller role view: simulate data—skipped, as there's no endpoint/role switching
  //    This test is limited to what SDK provides: only customer context and review fields.

  // 3. Admin role view: also skipped, as no admin review API or role switch supported in provided API set.

  // 4. Anonymous/unauth: no auth required for index, so same as customer.
  const anonReviewList: IPageIShoppingMallAiReview =
    await api.functional.shopping_mall_ai.customer.reviews.index(connection);
  typia.assert(anonReviewList);
  for (const review of anonReviewList.data) {
    TestValidator.predicate("anon list only active reviews")(
      !review.deleted_at,
    );
  }

  // Note: Only testable with provided SDK are customer-facing, public list; business roles/admin not instantiable with given materials.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";

/**
 * Validate that a customer can retrieve all payment records for their specific
 * order, including diverse payment events.
 *
 * BUSINESS CONTEXT: Customers must be able to audit their financial/payment
 * history for each order. This test ensures the endpoint exposes all payment
 * events (successful, pending, failed) strictly for the selected order, with
 * all audit/reconciliation attributes and no cross-order data leakage.
 *
 * STEPS:
 *
 * 1. Admin creates a new order for a simulated customer/channel (since only
 *    backend/admin flows are exposed)
 * 2. Admin registers several payment records for that order, including multiple
 *    methods and status values
 * 3. Customer-facing endpoint retrieves all payment records for this order
 * 4. Validate: all returned payments are only for the test order;
 *    status/method/amount/channel/fields match the created payments; audit
 *    fields exist; sum-of-success is accurate.
 */
export async function test_api_shopping_mall_ai_test_retrieve_all_payments_for_customer_order_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Admin creates an order for a test customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customerId,
        shopping_mall_ai_channel_id: channelId,
        status: "pending",
      },
    },
  );
  typia.assert(order);

  // 2. Admin registers several payments for this order (diverse status/method)
  const now = new Date();
  const paymentsToCreate: IShoppingPayment.ICreate[] = [
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: channelId,
      method: "card",
      status: "success",
      amount: 12000.5,
      initiated_at: new Date(now.getTime()).toISOString(),
      resolved_at: new Date(now.getTime() + 1000).toISOString(),
    },
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: channelId,
      method: "deposit",
      status: "pending",
      amount: 5500.0,
      initiated_at: new Date(now.getTime() + 2000).toISOString(),
    },
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: channelId,
      method: "card",
      status: "fail",
      amount: 3000.0,
      initiated_at: new Date(now.getTime() + 3000).toISOString(),
      resolved_at: null,
    },
  ];

  const createdPayments: IShoppingPayment[] = [];
  for (const body of paymentsToCreate) {
    const payment =
      await api.functional.shopping_mall_ai.admin.orders.payments.create(
        connection,
        {
          orderId: order.id,
          body,
        },
      );
    typia.assert(payment);
    createdPayments.push(payment);
  }

  // 3. Retrieve all payments for this order via the customer API
  const page =
    await api.functional.shopping_mall_ai.customer.orders.payments.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(page);

  // 4. Assert every returned payment matches created payments, and no stray records
  for (const payment of page.data) {
    TestValidator.equals("payment references correct order")(
      payment.shopping_mall_ai_order_id,
    )(order.id);
    const refPayment = createdPayments.find((p) => p.id === payment.id);
    TestValidator.predicate("payment comes from test data")(!!refPayment);
    if (refPayment) {
      TestValidator.equals("status")(payment.status)(refPayment.status);
      TestValidator.equals("method")(payment.method)(refPayment.method);
      TestValidator.equals("amount")(payment.amount)(refPayment.amount);
      TestValidator.equals("channel id")(payment.shopping_mall_ai_channel_id)(
        refPayment.shopping_mall_ai_channel_id,
      );
      // Audit datetime fields present and non-empty
      TestValidator.predicate("initiated_at valid")(
        typeof payment.initiated_at === "string" &&
          payment.initiated_at.length > 0,
      );
    }
  }
  // Validate that the total sum of success-status payments matches
  const expectedSuccessTotal = createdPayments
    .filter((p) => p.status === "success")
    .reduce((sum, p) => sum + p.amount, 0);
  const actualSuccessTotal = page.data
    .filter((p) => p.status === "success")
    .reduce((sum, p) => sum + p.amount, 0);
  TestValidator.equals("successful payment sum")(actualSuccessTotal)(
    expectedSuccessTotal,
  );

  // Ensure no records for other orders present
  TestValidator.equals("only our order payments")(
    page.data.every((p) => p.shopping_mall_ai_order_id === order.id),
  )(true);
}

