import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";

/**
 * Validate seller retrieval of payment records for their own order.
 *
 * This test verifies that a seller can retrieve all payment records for orders
 * associated with their products. The workflow simulates a real-world scenario
 * where an order is created (as admin), associated payment records are
 * registered, and then the seller retrieves them. The function checks that each
 * payment event created for the order is present in the list, ensures all
 * financial details match those posted, and that only payment-relevant data
 * appears (no customer PII). This ensures correct implementation of RBAC and
 * business logic for payment visibility.
 *
 * Steps:
 *
 * 1. Create an order (as admin) for a test channel and status
 * 2. Create multiple payments under that order (admin context)
 * 3. (Assume seller context/connection: in infra, role switch occurs)
 * 4. Seller queries payment records via GET
 *    /shopping-mall-ai/seller/orders/:orderId/payments
 * 5. Assert all created payment records are returned
 * 6. Validate financial fields (amount, method, status, timestamps)
 * 7. Confirm there is no sensitive customer data (by DTO schema restriction)
 */
export async function test_api_shopping_mall_ai_test_retrieve_payments_for_seller_order_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create an order as admin
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      },
    },
  );
  typia.assert(order);

  // 2. Register payment records under the order as admin
  const payments = await Promise.all([
    api.functional.shopping_mall_ai.admin.orders.payments.create(connection, {
      orderId: order.id,
      body: {
        shopping_mall_ai_order_id: order.id,
        shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
        method: "card",
        status: "success",
        amount: 12000.5,
        initiated_at: new Date().toISOString(),
        resolved_at: new Date().toISOString(),
      },
    }),
    api.functional.shopping_mall_ai.admin.orders.payments.create(connection, {
      orderId: order.id,
      body: {
        shopping_mall_ai_order_id: order.id,
        shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
        method: "deposit",
        status: "pending",
        amount: 7000,
        initiated_at: new Date().toISOString(),
        resolved_at: null,
      },
    }),
  ]);
  payments.forEach((payment) => typia.assert(payment));

  // 3. (Infra-level: switch connection to seller context)

  // 4. Seller fetches all payment records for the given order
  const response =
    await api.functional.shopping_mall_ai.seller.orders.payments.index(
      connection,
      { orderId: order.id },
    );
  typia.assert(response);

  // 5. Check all created payments are present in the seller's result
  const returnedIds = response.data.map((p) => p.id);
  payments.forEach((created) => {
    TestValidator.predicate("created payment is present in seller list")(
      returnedIds.includes(created.id),
    );
  });

  // 6. Check payment fields
  payments.forEach((created) => {
    const match = response.data.find((p) => p.id === created.id);
    if (!match)
      throw new Error("Expected payment not found in seller response");
    TestValidator.equals("amount matches")(match.amount)(created.amount);
    TestValidator.equals("status matches")(match.status)(created.status);
    TestValidator.equals("method matches")(match.method)(created.method);
    TestValidator.equals("resolved_at matches")(match.resolved_at)(
      created.resolved_at,
    );
    TestValidator.equals("initiated_at matches")(match.initiated_at)(
      created.initiated_at,
    );
    TestValidator.equals("order ID matches")(match.shopping_mall_ai_order_id)(
      order.id,
    );
    TestValidator.equals("channel matches")(match.shopping_mall_ai_channel_id)(
      order.shopping_mall_ai_channel_id,
    );
  });

  // 7. By schema, payments DTO includes only payment fields, so customer PII cannot be present
}

