  const paymentsData: IShoppingPayment.ICreate[] = [
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: channelId,
      method: "card",
      status: "success",
      amount: 10000,
      initiated_at: now.toISOString(),
      resolved_at: now.toISOString(),
    },
    {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: channelId,
      method: "card",
      status: "pending",
      amount: 500,
      initiated_at: now.toISOString(),
      resolved_at: null,
    },
