  for (const paymentBody of paymentsData) {
    const payment =
      await api.functional.shopping_mall_ai.admin.orders.payments.create(
        connection,
        {
          orderId: order.id,
          body: paymentBody,
        },
      );
    typia.assert(payment);
    createdPayments.push(payment);
  }
  // 3. Retrieve all payments for the order as admin
  const result =
    await api.functional.shopping_mall_ai.admin.orders.payments.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(result);
  // 4. Confirm all created payment records are present and correct
  TestValidator.equals("all admin payments for order present")(
    result.data.length,
