  for (const expected of createdPayments) {
    const found = result.data.find((p) => p.id === expected.id);
    TestValidator.predicate("payment record found")(!!found);
    if (found) {
      TestValidator.equals("order id matches")(found.shopping_mall_ai_order_id)(
        order.id,
      );
      TestValidator.equals("channel id matches")(
        found.shopping_mall_ai_channel_id,
      )(channelId);
      TestValidator.equals("amount matches")(found.amount)(expected.amount);
      TestValidator.equals("status matches")(found.status)(expected.status);
      TestValidator.equals("method matches")(found.method)(expected.method);
      TestValidator.equals("initiated_at matches")(found.initiated_at)(
        expected.initiated_at,
      );
      TestValidator.equals("resolved_at matches")(found.resolved_at ?? null)(
        expected.resolved_at ?? null,
      );
    }
  }
}

