import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";
import type { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate customer-side payment search in an order with multiple filters.
 *
 * This test ensures that, given an order with multiple payment records (created
 * with different methods, statuses, and dates), the customer can filter and
 * search those payments using various criteria such as status, method, and
 * initiated_at range, and receives precise results matching the filter.
 *
 * Steps:
 *
 * 1. Admin creates an order for a random customer and channel.
 * 2. Admin registers several payment records for that order, varying at least the
 *    method (e.g., card, deposit), status (e.g., success, fail), and
 *    initiated_at date.
 * 3. As a customer, use the PATCH search endpoint to filter payments by:
 *
 * - Status (e.g., only 'success')
 * - Method (e.g., only 'card')
 * - Date range (initiated_from/initiated_to)
 * - Combination of method and status
 *
 * 4. Validate that the payments in the response all match the filter, and that
 *    payments excluded by the filter are not present in results.
 * 5. Assert response pagination reflects the number of filtered records, and total
 *    is correct for each filter scenario.
 */
export async function test_api_shopping_mall_ai_customer_orders_payments_test_customer_search_payments_with_filtering(
  connection: api.IConnection,
) {
  // 1. Admin creates a new order
  const orderInput: IShoppingMallAiOrder.ICreate = {
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    status: "pending",
  };
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    { body: orderInput },
  );
  typia.assert(order);

  // 2. Admin creates diverse payments for this order
  const payVariants = [
    { method: "card", status: "success" },
    { method: "deposit", status: "fail" },
    { method: "card", status: "fail" },
  ];
  const allPayments: IShoppingPayment[] = [];
  const now = new Date();

  for (const [i, variant] of payVariants.entries()) {
    const initiatedAt = new Date(now.getTime() - i * 86400000).toISOString(); // today, yesterday, two days ago
    const payBody: IShoppingPayment.ICreate = {
      shopping_mall_ai_order_id: order.id,
      shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
      method: variant.method,
      status: variant.status,
      amount: 50000 + i * 1000,
      initiated_at: initiatedAt,
      resolved_at: variant.status === "success" ? initiatedAt : null,
    };
    const payment =
      await api.functional.shopping_mall_ai.admin.orders.payments.create(
        connection,
        { orderId: order.id, body: payBody },
      );
    typia.assert(payment);
    allPayments.push(payment);
  }

  // 3. Test filtering: by status
  const byStatus =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: { status: "success" },
      },
    );
  typia.assert(byStatus);
  TestValidator.predicate("All payments have status 'success'")(
    byStatus.data.every((p) => p.status === "success"),
  );

  // 4. Test filtering: by method
  const byMethod =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: { method: "card" },
      },
    );
  typia.assert(byMethod);
  TestValidator.predicate("All payments use method 'card'")(
    byMethod.data.every((p) => p.method === "card"),
  );

  // 5. Test filtering: by status & method
  const byStatusMethod =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: { method: "card", status: "fail" },
      },
    );
  typia.assert(byStatusMethod);
  TestValidator.predicate("All payments are card and fail")(
    byStatusMethod.data.every(
      (p) => p.method === "card" && p.status === "fail",
    ),
  );

  // 6. Test filtering: by initiated_at date range (should only include the latest payment)
  const latestInitiated = allPayments[0].initiated_at;
  const byDateFrom =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: { initiated_from: latestInitiated },
      },
    );
  typia.assert(byDateFrom);
  TestValidator.predicate("All payments initiated after date")(
    byDateFrom.data.every((p) => p.initiated_at >= latestInitiated),
  );

  // 7. Test filtering: combination (status+date window, expect only payments matching both)
  const midInitiated = allPayments[1].initiated_at;
  const byStatusAndDateRange =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {
          status: "fail",
          initiated_from: midInitiated,
          initiated_to: allPayments[0].initiated_at,
        },
      },
    );
  typia.assert(byStatusAndDateRange);
  TestValidator.predicate("All payments failed between dates")(
    byStatusAndDateRange.data.every(
      (p) =>
        p.status === "fail" &&
        p.initiated_at >= midInitiated &&
        p.initiated_at <= allPayments[0].initiated_at,
    ),
  );

  // 8. Negative filter case (no results expected: status 'refunded')
  const byRefunded =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: { status: "refunded" },
      },
    );
  typia.assert(byRefunded);
  TestValidator.equals("Should have no refunded payments")(
    byRefunded.data.length,
  )(0);

  // 9. Unfiltered: get all payments (should match created count)
  const unfiltered =
    await api.functional.shopping_mall_ai.customer.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {},
      },
    );
  typia.assert(unfiltered);
  TestValidator.equals("Unfiltered count matches")(unfiltered.data.length)(
    allPayments.length,
  );
}

