import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";
import type { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the seller's payment filtering for a specific order.
 *
 * This E2E test verifies that a seller can filter payment records belonging to
 * an order they fulfilled by status and method fields, and the system returns
 * only records actually matching the filter, no more and no less. It also
 * verifies filtering returns empty results when there is no match.
 *
 * Business flow:
 *
 * 1. Create an order (admin context)
 * 2. Register three payment records with varied method/status/amount
 * 3. Filter payments by 'success' status (should match two payments)
 * 4. Filter payments by method 'deposit' (should match exactly one payment)
 * 5. Filter by a status with no match (should return empty result)
 */
export async function test_api_shopping_mall_ai_test_seller_search_payments_with_filtering(
  connection: api.IConnection,
) {
  // 1. Create an order (admin context)
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Register three payment records, each with a distinct combination
  //    (so we can filter by status/method)
  const payment1 =
    await api.functional.shopping_mall_ai.admin.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
          method: "card",
          status: "success",
          amount: 10000,
          initiated_at: new Date().toISOString(),
          resolved_at: new Date().toISOString(),
        } satisfies IShoppingPayment.ICreate,
      },
    );
  typia.assert(payment1);

  const payment2 =
    await api.functional.shopping_mall_ai.admin.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
          method: "deposit",
          status: "pending",
          amount: 5000,
          initiated_at: new Date().toISOString(),
          resolved_at: null,
        } satisfies IShoppingPayment.ICreate,
      },
    );
  typia.assert(payment2);

  const payment3 =
    await api.functional.shopping_mall_ai.admin.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_channel_id: order.shopping_mall_ai_channel_id,
          method: "coupon",
          status: "success",
          amount: 3000,
          initiated_at: new Date().toISOString(),
          resolved_at: new Date().toISOString(),
        } satisfies IShoppingPayment.ICreate,
      },
    );
  typia.assert(payment3);

  // 3. Filter payments by 'success' status (should match payment1 & payment3)
  const filteredBySuccess =
    await api.functional.shopping_mall_ai.seller.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {
          status: "success",
          shopping_mall_ai_order_id: order.id,
        } satisfies IShoppingPayment.IRequest,
      },
    );
  typia.assert(filteredBySuccess);
  TestValidator.predicate("all filtered payments must have status 'success'")(
    filteredBySuccess.data.every(
      (p) => p.status === "success" && p.shopping_mall_ai_order_id === order.id,
    ),
  );
  TestValidator.equals("number of success payments")(2)(
    filteredBySuccess.data.length,
  );

  // 4. Filter payments by method 'deposit' (should match payment2 only)
  const filteredByDeposit =
    await api.functional.shopping_mall_ai.seller.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {
          method: "deposit",
          shopping_mall_ai_order_id: order.id,
        } satisfies IShoppingPayment.IRequest,
      },
    );
  typia.assert(filteredByDeposit);
  TestValidator.equals("filter deposit - only one item and method matches")(1)(
    filteredByDeposit.data.length,
  );
  TestValidator.equals("deposit payment method")(
    filteredByDeposit.data[0].method,
  )("deposit");
  TestValidator.equals("deposit payment id")(filteredByDeposit.data[0].id)(
    payment2.id,
  );

  // 5. Negative test: filter by status not present (should return empty)
  const filteredByNonexistent =
    await api.functional.shopping_mall_ai.seller.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {
          status: "fail",
          shopping_mall_ai_order_id: order.id,
        } satisfies IShoppingPayment.IRequest,
      },
    );
  typia.assert(filteredByNonexistent);
  TestValidator.equals("filter fail status - should be empty")(0)(
    filteredByNonexistent.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
