import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";
import type { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a seller cannot search payments for orders owned by other
 * sellers.
 *
 * This test ensures that the platform's RBAC rules prevent sellers from viewing
 * or filtering payment information of orders they do not own, preserving
 * sensitive payment data privacy between sellers.
 *
 * Workflow:
 *
 * 1. Create an order as an admin (order is not owned by the seller running this
 *    test).
 * 2. Attempt to search payments for this order as a random seller (using the
 *    search endpoint).
 * 3. Confirm that no payment data is revealed—either the API throws an access
 *    error or returns an empty dataset.
 */
export async function test_api_shopping_mall_ai_test_seller_search_payments_for_other_sellers_order_denied(
  connection: api.IConnection,
) {
  // 1. Admin creates an order, simulating a different seller's order
  const adminOrder = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(adminOrder);

  // 2. As a seller (NOT owner of the order), attempt to search payments for this order
  let forbiddenOrEmpty = false;
  try {
    const result =
      await api.functional.shopping_mall_ai.seller.orders.payments.search(
        connection,
        {
          orderId: adminOrder.id,
          body: {
            shopping_mall_ai_order_id: adminOrder.id,
            page: 1,
            limit: 20,
            method: null,
            status: null,
            initiated_from: null,
            initiated_to: null,
          } satisfies IShoppingPayment.IRequest,
        },
      );
    typia.assert(result);
    // In strict privacy, even if call is allowed, data must be empty
    TestValidator.equals("no data revealed")(result.data.length)(0);
    forbiddenOrEmpty = true;
  } catch (error) {
    // Accept either forbidden error, or empty result
    forbiddenOrEmpty = true;
  }
  TestValidator.predicate("seller cannot see other sellers' order payments")(
    forbiddenOrEmpty,
  );
}

