import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";
import type { IPageIShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced filtered and paginated search of order items as an admin.
 *
 * This test covers the admin order-item search endpoint:
 *
 * 1. Create a new order as an admin using the admin endpoint.
 * 2. Create multiple order items with different product IDs, product option IDs,
 *    prices and status values (e.g., "active", "returned").
 * 3. Search (PATCH) with no filter to confirm all items are returned.
 * 4. Search with `status` filter (for each status present e.g., "active",
 *    "returned").
 * 5. Search using `shopping_mall_ai_product_id` filter only, confirming precise
 *    filtering results.
 * 6. Search using pagination (limit/page).
 * 7. Issue a search with a page value that's out of range (e.g., page > total
 *    pages), expect empty results.
 * 8. Issue a search with invalid filter parameters (e.g., negative page).
 * 9. Validate that all returned paginated metadata and item fields are populated
 *    and correct.
 *
 * Permission error testing is omitted, as only admin context is possible with
 * available endpoints.
 */
export async function test_api_shopping_mall_ai_admin_orders_orderItems_test_search_order_items_with_various_filters_and_pagination_as_admin(
  connection: api.IConnection,
) {
  // Step 1: Create an order as admin
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // Step 2: Add several items to the order with diverse fields
  const productIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const productOptionIds = [typia.random<string & tags.Format<"uuid">>(), null];
  const statuses = ["active", "returned"];

  const items = [];
  for (let i = 0; i < 4; ++i) {
    const item =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: {
            shopping_mall_ai_order_id: order.id,
            shopping_mall_ai_product_id: productIds[i % productIds.length],
            shopping_mall_ai_product_option_id:
              productOptionIds[i % productOptionIds.length],
            price: 1000 + i * 200,
            quantity: 1 + i,
            status: statuses[i % statuses.length],
          } satisfies IShoppingOrderItem.ICreate,
        },
      );
    typia.assert(item);
    items.push(item);
  }

  // Step 3: Search PATCH - no filter (get all)
  const allResult =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {},
      },
    );
  typia.assert(allResult);
  TestValidator.equals("total count matches")(allResult.pagination.records)(
    items.length,
  );
  TestValidator.equals("data matches all created ids")(
    allResult.data.map((x) => x.id).sort(),
  )(items.map((x) => x.id).sort());

  // Step 4: Search with status filter
  for (const status of statuses) {
    const res =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: { status },
        },
      );
    typia.assert(res);
    TestValidator.predicate(`all items have status=${status}`)(
      res.data.every((x) => x.status === status),
    );
  }

  // Step 5: Search with product_id filter only (product_option_id filter is not supported)
  for (const pid of productIds) {
    const res =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: { shopping_mall_ai_product_id: pid },
        },
      );
    typia.assert(res);
    TestValidator.predicate(`all items have product_id=${pid}`)(
      res.data.every((x) => x.shopping_mall_ai_product_id === pid),
    );
  }

  // Step 6: Pagination
  const limit = 2;
  const page1 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { limit, page: 1 },
      },
    );
  typia.assert(page1);
  TestValidator.equals("limit matches")(page1.pagination.limit)(limit);

  const page2 =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { limit, page: 2 },
      },
    );
  typia.assert(page2);
  TestValidator.equals("page 2 valid")(page2.pagination.current)(2);

  // Step 7: Out-of-range page (should be empty data)
  const maxPage = page1.pagination.pages;
  const emptyRes =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { limit, page: maxPage + 1 },
      },
    );
  typia.assert(emptyRes);
  TestValidator.equals("out-of-range yields empty")(emptyRes.data.length)(0);

  // Step 8: Invalid parameter (negative page)
  await TestValidator.error("negative page fails")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { page: -1 },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
