import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";

/**
 * Test retrieving detailed information for a specific order item as a customer.
 *
 * This test covers the following scenario:
 *
 * 1. An order is placed via the admin API (representing backend/system creation).
 * 2. An order item is added to this order via the admin API.
 * 3. The customer (who placed the order) retrieves the order item detail using the
 *    customer API, and the full item data is validated.
 * 4. Attempting to access the item as another customer (different principal) must
 *    result in access denial (forbidden or not found).
 * 5. Attempting to access the item without authentication must not be allowed
 *    (forbidden or not found).
 *
 * Business purpose:
 *
 * - Ensures access controls strictly permit only the order-owning customer to
 *   read order items.
 * - Validates the correctness and completeness of item retrieval.
 * - Confirms that unauthorized access attempts are properly rejected according to
 *   business rules.
 *
 * Steps:
 *
 * 1. Create an order by admin (simulate system/backend-initiated order on behalf
 *    of customer).
 * 2. Add an item to the order as admin (test context setup).
 * 3. Retrieve the created item using the customer API with the order's rightful
 *    customer session.
 * 4. Attempt retrieval as a different customer (simulate forbidden/not found).
 * 5. Attempt retrieval without authentication.
 */
export async function test_api_shopping_mall_ai_test_get_order_item_details_as_customer_success_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create an order (admin API)
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Add an order item (admin API)
  const orderItem =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          price: 1000.0,
          quantity: 1,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(orderItem);

  // 3. Retrieve the order item as the rightful customer
  // (In real use, customer identity would be authenticated via session;
  // for this test, we assume the connection context allows retrieval)
  const fetched =
    await api.functional.shopping_mall_ai.customer.orders.orderItems.at(
      connection,
      {
        orderId: order.id,
        orderItemId: orderItem.id,
      },
    );
  typia.assert(fetched);
  TestValidator.equals("Customer retrieves their own item")(fetched)(orderItem);

  // 4. Attempt retrieval as another customer (simulate by modifying customer id in headers)
  const anotherCustomerConn = {
    ...connection,
    headers: {
      ...connection.headers,
      customer: typia.random<string & tags.Format<"uuid">>(), // simulate different customer
    },
  };
  await TestValidator.error("Should forbid access for another customer")(() =>
    api.functional.shopping_mall_ai.customer.orders.orderItems.at(
      anotherCustomerConn,
      {
        orderId: order.id,
        orderItemId: orderItem.id,
      },
    ),
  );

  // 5. Attempt access without authentication (simulate by clearing headers)
  const noAuthConn = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("Should forbid access for unauthenticated user")(
    () =>
      api.functional.shopping_mall_ai.customer.orders.orderItems.at(
        noAuthConn,
        {
          orderId: order.id,
          orderItemId: orderItem.id,
        },
      ),
  );
}

