import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";

/**
 * Validate that admin can fetch any order item detail for audit and compliance.
 *
 * This test ensures:
 *
 * 1. An order can be created by admin.
 * 2. Multiple order items can be added to the order.
 * 3. Admin can fetch each order item detail and the record is complete/correct.
 * 4. Attempting to fetch a missing order item or mismatched order-item combination
 *    as admin returns an error (404).
 * 5. Permission is enforced: a non-admin cannot access the order item detail and
 *    receives forbidden/unauthorized error.
 */
export async function test_api_shopping_mall_ai_test_admin_fetch_order_item_detail_for_audit(
  connection: api.IConnection,
) {
  // 1. Create an order as admin
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Add multiple order items to this order
  const items: IShoppingOrderItem[] = [];
  for (let i = 0; i < 3; ++i) {
    const item =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: {
            shopping_mall_ai_order_id: order.id,
            shopping_mall_ai_product_id: typia.random<
              string & tags.Format<"uuid">
            >(),
            shopping_mall_ai_product_option_id: null,
            price: typia.random<number>(),
            quantity: 1,
            status: "active",
          } satisfies IShoppingOrderItem.ICreate,
        },
      );
    typia.assert(item);
    items.push(item);
  }

  // 3. As admin, fetch each order item detail and confirm all fields
  for (const item of items) {
    const detail =
      await api.functional.shopping_mall_ai.admin.orders.orderItems.at(
        connection,
        {
          orderId: order.id,
          orderItemId: item.id,
        },
      );
    typia.assert(detail);
    TestValidator.equals("order item id matches")(detail.id)(item.id);
    TestValidator.equals("belongs to order")(detail.shopping_mall_ai_order_id)(
      order.id,
    );
  }

  // 4. Try fetching non-existent order item (should return error)
  await TestValidator.error("404 for non-existent order item")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.orderItems.at(
      connection,
      {
        orderId: order.id,
        orderItemId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });

  // 5. Try fetching with mismatched order and order item IDs (should return error)
  const anotherOrder =
    await api.functional.shopping_mall_ai.admin.orders.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    });
  typia.assert(anotherOrder);
  await TestValidator.error("404 for mismatched order-item pair")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.orderItems.at(
      connection,
      {
        orderId: anotherOrder.id,
        orderItemId: items[0].id,
      },
    );
  });

  // 6. Simulate non-admin (unauthorized) call: remove admin credentials if possible (would need another connection)
  // This would require a fresh connection without admin tokens
  // If framework supports, simulate non-admin:
  const nonAdmin: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("forbidden for non-admin")(async () => {
    await api.functional.shopping_mall_ai.admin.orders.orderItems.at(nonAdmin, {
      orderId: order.id,
      orderItemId: items[0].id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
