/**
 * Validate seller's ability to hard-delete an order item from their own order
 * and confirm business rules/error handling for edge cases.
 *
 * Covers:
 *
 * 1. Admin creates a new order and item (setup, admin-only)
 * 2. Seller deletes their own order item via the seller endpoint
 * 3. Item is no longer retrievable after deletion (delete is effective)
 * 4. Negative: Seller attempts to delete order item from an order they don't own
 *    (should yield forbidden error)
 * 5. Negative: Attempt to delete an item in an immutable state (should yield
 *    error)
 * 6. Audit logging side-effect is not verifiable externally and is skipped
 */
export async function test_api_shopping_mall_ai_test_delete_order_item_as_seller_on_own_order(
  connection: api.IConnection,
) {
  // 1. Admin creates a new order (order is assumed "owned" by acting seller by test setup)
  const adminOrder = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(adminOrder);

  // 2. Admin adds an order item to the new order
  const adminOrderItem =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: adminOrder.id,
        body: {
          shopping_mall_ai_order_id: adminOrder.id,
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          price: 1000.0,
          quantity: 1,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(adminOrderItem);

  // 3a. Seller deletes their own order item (success)
  await api.functional.shopping_mall_ai.seller.orders.orderItems.erase(
    connection,
    {
      orderId: adminOrder.id,
      orderItemId: adminOrderItem.id,
    },
  );
  // No output to assert; deletion is void

  // 3b. Confirm the same item cannot be deleted again (should throw)
  await TestValidator.error("second delete (already deleted) throws")(() =>
    api.functional.shopping_mall_ai.seller.orders.orderItems.erase(connection, {
      orderId: adminOrder.id,
      orderItemId: adminOrderItem.id,
    }),
  );

  // 4. Negative: Attempt to delete an order item on another order (not owned by acting seller)
  // Setup a second admin order/item (for edge test)
  const adminOrder2 = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "pending",
      } satisfies IShoppingMallAiOrder.ICreate,
    },
  );
  typia.assert(adminOrder2);
  const adminOrder2Item =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: adminOrder2.id,
        body: {
          shopping_mall_ai_order_id: adminOrder2.id,
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          price: 2000.0,
          quantity: 2,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(adminOrder2Item);
  // Try to delete as seller (should fail/forbidden)
  await TestValidator.error("delete not-owned order item throws")(() =>
    api.functional.shopping_mall_ai.seller.orders.orderItems.erase(connection, {
      orderId: adminOrder2.id,
      orderItemId: adminOrder2Item.id,
    }),
  );

  // 5. Negative: Attempt to delete immutable order item (simulate with locked status)
  const immutableOrder =
    await api.functional.shopping_mall_ai.admin.orders.create(connection, {
      body: {
        shopping_mall_ai_channel_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        status: "fulfilled", // Simulate fulfilled/locked order
      } satisfies IShoppingMallAiOrder.ICreate,
    });
  typia.assert(immutableOrder);
  const immutableOrderItem =
    await api.functional.shopping_mall_ai.admin.orders.orderItems.create(
      connection,
      {
        orderId: immutableOrder.id,
        body: {
          shopping_mall_ai_order_id: immutableOrder.id,
          shopping_mall_ai_product_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          price: 3000.0,
          quantity: 1,
          status: "active",
        } satisfies IShoppingOrderItem.ICreate,
      },
    );
  typia.assert(immutableOrderItem);

  // Try to delete from fulfilled (immutable) order as seller
  await TestValidator.error("delete immutable order item throws")(() =>
    api.functional.shopping_mall_ai.seller.orders.orderItems.erase(connection, {
      orderId: immutableOrder.id,
      orderItemId: immutableOrderItem.id,
    }),
  );

  // 6. Audit logging not externally testable - step is omitted
}

