  };
  const ownerCart = await api.functional.shopping_mall_ai.customer.carts.create(
    connection,
    { body: ownerCartInput },
  );
  typia.assert(ownerCart);

  // 2. 고객 B(비소유자)로 컨텍스트 분리 - 실제 환경에서 로그인/토큰 전환 필요, 여기선 id만 분리
  const nonOwnerCustomerId = typia.random<string & tags.Format<"uuid">>();

  // 3. 고객 B가 Owner의 cartId를 업데이트 시도하면 반드시 에러(권한 거부) 가 발생해야 한다
  await TestValidator.error(
    "비소유자는 타인의 장바구니 업데이트를 차단해야 함",
  )(() =>
    api.functional.shopping_mall_ai.customer.carts.update(
      {
        ...connection,
        // 실제 인증/사용자 전환 환경에 따라 이 부분(ID/토큰 등) 구현 필요
      },
      {
        cartId: ownerCart.id,
        body: {
          shopping_mall_ai_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          shopping_mall_ai_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        },
      },
    ),
