import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCart";

/**
 * Validate admin's ability to update the metadata of any shopping cart
 * (regardless of ownership).
 *
 * This test ensures that an administrator can update the contextual metadata
 * (channel, section) of any cart, regardless of which customer or seller may be
 * associated (including guest carts). The update should:
 *
 * - Apply to a cart created with arbitrary (random, possibly guest-owned) data.
 * - Reflect only channel/section changes—these are the only mutable fields for
 *   admin (other fields must remain unchanged).
 * - Changes must reflect in the returned updated cart record.
 * - The update must be atomic and meet audit-compliance: the full cart record is
 *   returned and timestamps/ownership remain valid.
 * - The update operation must not allow mutation of immutable fields (id,
 *   customer id, seller id, creation time).
 *
 * Steps:
 *
 * 1. Create a new cart (admin operation) with arbitrary values for
 *    ownership/channel/section—this could be a guest cart or customer-linked,
 *    potentially with seller context as well.
 * 2. As admin, update the cart's channel and section with new (different) values
 *    using PUT /shopping-mall-ai/admin/carts/{cartId}.
 * 3. Assert that:
 *
 *    - The returned cart has the same id and ownership bindings as before.
 *    - The channel and section fields are changed as requested.
 *    - The updated_at field is refreshed, and created_at remains unchanged.
 *    - No other fields are changed.
 *    - The operation is atomic and all invariants are maintained.
 */
export async function test_api_shopping_mall_ai_admin_carts_test_admin_update_cart_metadata_for_any_user(
  connection: api.IConnection,
) {
  // 1. Create cart with arbitrary owner/context (could be guest/customer/seller/etc.)
  const cartCreateInput: IShoppingMallAiCart.ICreate = {
    shopping_mall_ai_customer_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_seller_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_channel_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_ai_section_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const cart = await api.functional.shopping_mall_ai.admin.carts.create(
    connection,
    {
      body: cartCreateInput,
    },
  );
  typia.assert(cart);

  // 2. Generate new channel/section (guaranteed different from initial)
  let newChannelId = typia.random<string & tags.Format<"uuid">>();
  while (newChannelId === cart.shopping_mall_ai_channel_id)
    newChannelId = typia.random<string & tags.Format<"uuid">>();

  let newSectionId = typia.random<string & tags.Format<"uuid">>();
  while (newSectionId === cart.shopping_mall_ai_section_id)
    newSectionId = typia.random<string & tags.Format<"uuid">>();

  // 3. Update the cart's channel/section
  const updatedCart = await api.functional.shopping_mall_ai.admin.carts.update(
    connection,
    {
      cartId: cart.id,
      body: {
        shopping_mall_ai_channel_id: newChannelId,
        shopping_mall_ai_section_id: newSectionId,
      },
    },
  );
  typia.assert(updatedCart);

  // 4. Assert only allowed fields change: id and ownership/currency stay the same.
  TestValidator.equals("cart id unchanged")(updatedCart.id)(cart.id);
  TestValidator.equals("customer field unchanged")(
    updatedCart.shopping_mall_ai_customer_id,
  )(cart.shopping_mall_ai_customer_id);
  TestValidator.equals("seller field unchanged")(
    updatedCart.shopping_mall_ai_seller_id,
  )(cart.shopping_mall_ai_seller_id);
  TestValidator.equals("channel updated")(
    updatedCart.shopping_mall_ai_channel_id,
  )(newChannelId);
