import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";
import type { IPageIShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a seller can search and paginate order items within a specific
 * order using various filters.
 *
 * This test ensures that a seller can perform a filtered, paginated search for
 * items within an order. Criteria tested include product, status (e.g.,
 * returned), and standard pagination. The function verifies that only the
 * matching items from the correct order are returned and that the pagination
 * metadata matches expectations.
 *
 * Steps:
 *
 * 1. Create a test order ID (UUID).
 * 2. Create several order items in this order with varying product, status, and
 *    product option values.
 * 3. Search for items in this order filtering by status (e.g., 'returned') and
 *    confirm only matching items are returned.
 * 4. Search for items by a specific product, checking that only items for that
 *    product in this order are returned.
 * 5. Perform a paginated search (limit < total items) and assert pagination
 *    metadata and data count.
 * 6. Validate that all returned items belong to the test order and are accessible
 *    based on seller role.
 */
export async function test_api_shopping_mall_ai_test_search_order_items_by_seller_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Create a unique order ID for the test
  const orderId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Create several order items in this order, varying product, status, and option
  const products: string[] = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const statuses = ["active", "returned", "cancelled"];
  const optionIds = [null, typia.random<string & tags.Format<"uuid">>()];
  const createdItems: IShoppingOrderItem[] = [];
  for (let i = 0; i < 6; ++i) {
    const productId = RandomGenerator.pick(products);
    const status = RandomGenerator.pick(statuses);
    const optionId = RandomGenerator.pick(optionIds);
    const item: IShoppingOrderItem =
      await api.functional.shopping_mall_ai.seller.orders.orderItems.create(
        connection,
        {
          orderId,
          body: {
            shopping_mall_ai_order_id: orderId,
            shopping_mall_ai_product_id: productId,
            shopping_mall_ai_product_option_id: optionId,
            price: 100 * (i + 1),
            quantity: i + 1,
            status,
          } satisfies IShoppingOrderItem.ICreate,
        },
      );
    typia.assert(item);
    createdItems.push(item);
  }

  // 3. Search for order items by status (e.g., 'returned')
  const returnedSearch =
    await api.functional.shopping_mall_ai.seller.orders.orderItems.search(
      connection,
      {
        orderId,
        body: { status: "returned" } satisfies IShoppingOrderItem.IRequest,
      },
    );
  typia.assert(returnedSearch);
  TestValidator.predicate(
    "all returned items have status 'returned' and correct order",
  )(
    returnedSearch.data.every(
      (x) => x.status === "returned" && x.shopping_mall_ai_order_id === orderId,
    ),
  );

  // 4. Search for order items by a specific product within the order
  const specificProductId = createdItems[0].shopping_mall_ai_product_id;
  const productSearch =
    await api.functional.shopping_mall_ai.seller.orders.orderItems.search(
      connection,
      {
        orderId,
        body: {
          shopping_mall_ai_product_id: specificProductId,
        } satisfies IShoppingOrderItem.IRequest,
      },
    );
  typia.assert(productSearch);
  TestValidator.predicate(
    "all items filtered by product ID belong to same order and product",
  )(
    productSearch.data.every(
      (x) =>
        x.shopping_mall_ai_product_id === specificProductId &&
        x.shopping_mall_ai_order_id === orderId,
    ),
  );

  // 5. Paginated search: limit less than number of created items, check result size and pagination metadata
  const limit = 2;
  const paged =
    await api.functional.shopping_mall_ai.seller.orders.orderItems.search(
      connection,
      {
        orderId,
        body: { page: 1, limit } satisfies IShoppingOrderItem.IRequest,
      },
    );
  typia.assert(paged);
  TestValidator.equals("paginated data count matches limit or item count")(
    paged.data.length,
  )(Math.min(limit, createdItems.length));
  TestValidator.predicate("pagination metadata structure valid")(
    typeof paged.pagination.current === "number" &&
      typeof paged.pagination.limit === "number" &&
      typeof paged.pagination.records === "number" &&
      typeof paged.pagination.pages === "number",
  );
  TestValidator.equals("all paged items for correct order")(
    paged.data.every((x) => x.shopping_mall_ai_order_id === orderId),
  )(true);
}

