import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and pagination functionality for admin payments on a
 * specific order.
 *
 * This test ensures administrative users can filter, search, and page through
 * payment records for an order using various criteria (method, status, date)
 * and receive correct paginated results.
 *
 * Steps:
 *
 * 1. Create a new order using valid customer and channel references, and workflow
 *    status.
 * 2. Create two payments for this order, with distinct method, status, and amount
 *    attributes.
 * 3. Search payments for this order, filtering by method and status so only one
 *    payment matches.
 * 4. Verify the response contains exactly one result, correct pagination meta, and
 *    all fields accurate.
 * 5. Re-run searches with other filter combinations (such as only method, or only
 *    status, or both null) and check result count, page info, and record
 *    integrity.
 */
export async function test_api_shopping_mall_ai_admin_orders_payments_test_search_payments_for_order_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new order
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const orderStatus = "pending";
  const order = await api.functional.shopping_mall_ai.admin.orders.create(
    connection,
    {
      body: {
        shopping_mall_ai_customer_id: customerId,
        shopping_mall_ai_channel_id: channelId,
        status: orderStatus,
      },
    },
  );
  typia.assert(order);

  // 2. Register two payments with distinct attributes
  const paymentA =
    await api.functional.shopping_mall_ai.admin.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_channel_id: channelId,
          method: "card",
          status: "success",
          amount: 15000,
          initiated_at: new Date(Date.now() - 3600000).toISOString(),
          resolved_at: new Date(Date.now() - 3500000).toISOString(),
        },
      },
    );
  typia.assert(paymentA);
  const paymentB =
    await api.functional.shopping_mall_ai.admin.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          shopping_mall_ai_channel_id: channelId,
          method: "deposit",
          status: "pending",
          amount: 5000,
          initiated_at: new Date(Date.now() - 1800000).toISOString(),
          resolved_at: null,
        },
      },
    );
  typia.assert(paymentB);

  // 3. Search payments by method 'card' and status 'success' (should match only paymentA)
  let search =
    await api.functional.shopping_mall_ai.admin.orders.payments.search(
      connection,
      {
        orderId: order.id,
        body: {
          shopping_mall_ai_order_id: order.id,
          method: "card",
          status: "success",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(search);
  TestValidator.equals("found only one card/success payment")(
    search.data.length,
  )(1);
  TestValidator.equals("correct card payment")(search.data[0].id)(paymentA.id);
  TestValidator.equals("pagination metadata")(search.pagination.current)(1);

  // 4. Search by method only (should match only paymentA)
  search = await api.functional.shopping_mall_ai.admin.orders.payments.search(
    connection,
    {
      orderId: order.id,
      body: {
        shopping_mall_ai_order_id: order.id,
        method: "card",
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(search);
  TestValidator.equals("method filter only, length")(search.data.length)(1);

  // 5. Search by status only (should match only paymentB)
  search = await api.functional.shopping_mall_ai.admin.orders.payments.search(
    connection,
    {
      orderId: order.id,
      body: {
        shopping_mall_ai_order_id: order.id,
        status: "pending",
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(search);
  TestValidator.equals("status filter only, length")(search.data.length)(1);
  TestValidator.equals("correct deposit payment")(search.data[0].id)(
    paymentB.id,
  );

  // 6. Search with no filters (should match both payments)
  search = await api.functional.shopping_mall_ai.admin.orders.payments.search(
    connection,
    {
      orderId: order.id,
      body: {
        shopping_mall_ai_order_id: order.id,
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(search);
  TestValidator.equals("both payments returned")(search.data.length)(2);
  TestValidator.predicate("contains paymentA")(
    search.data.some((p) => p.id === paymentA.id),
  );
  TestValidator.predicate("contains paymentB")(
    search.data.some((p) => p.id === paymentB.id),
  );
}

