import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";
import type { IPageIShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test to validate customer search, filtering, and pagination for product
 * inquiries (Q&A), covering private and public questions.
 *
 * This test ensures:
 *
 * 1. A customer can create both public and private inquiries on one or more
 *    products.
 * 2. The system properly returns only this customer's private inquiries when
 *    filtering as that customer.
 * 3. Both private and public inquiries are correctly reflected in paged search
 *    results for the customer.
 * 4. Pagination and sorting work as expected (returns correct count/page).
 * 5. Filtering by product, privacy, or other field(s) works as expected.
 * 6. Private inquiries remain visible to only the owning customer (RBAC check
 *    cannot be tested without role-switching APIs, so assumed for customer
 *    context only, as per available APIs).
 *
 * Steps:
 *
 * 1. Create a random product (by UUID).
 * 2. Create a public inquiry for the customer.
 * 3. Create a private inquiry for the customer.
 * 4. Search inquiries as this customer; verify both inquiries are present, with
 *    correct privacy flags.
 * 5. Paginate with limit=1; ensure each page returns one inquiry, and total count
 *    covers both.
 * 6. Filter by is_private true/false; ensure only the correct inquiries are
 *    returned each time.
 * 7. Test sort by created_at both asc/desc.
 *
 * Note: RBAC for privacy is confirmed by only seeing the private inquiry as
 * this customer.
 */
export async function test_api_shopping_mall_ai_customer_inquiries_test_search_inquiries_by_customer_with_private_and_public_queries(
  connection: api.IConnection,
) {
  // 1. Generate a random product UUID for the inquiries
  const productId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a public inquiry for the product
  const publicInquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productId,
          question: `Public Q: ${RandomGenerator.paragraph()()}`,
          is_private: false,
        },
      },
    );
  typia.assert(publicInquiry);

  // 3. Create a private inquiry for the product
  const privateInquiry =
    await api.functional.shopping_mall_ai.customer.inquiries.create(
      connection,
      {
        body: {
          shopping_mall_ai_product_id: productId,
          question: `Private Q: ${RandomGenerator.paragraph()()}`,
          is_private: true,
        },
      },
    );
  typia.assert(privateInquiry);

  // 4. Search without filters (should return both inquiries)
  let output = await api.functional.shopping_mall_ai.customer.inquiries.search(
    connection,
    {
      body: {
        filter: {
          shopping_mall_ai_product_id: productId,
        },
      },
    },
  );
  typia.assert(output);
  TestValidator.predicate("should include private and public inquiry")(
    output.data.some((i) => i.id === publicInquiry.id) &&
      output.data.some((i) => i.id === privateInquiry.id),
  );

  // 5. Pagination with limit = 1
  const paged1 =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId },
          page: 1,
          limit: 1,
        },
      },
    );
  typia.assert(paged1);
  TestValidator.equals("pagination size")(paged1.pagination.limit)(1);
  TestValidator.equals("pagination records")(paged1.pagination.records)(2);
  TestValidator.equals("pagination pages")(paged1.pagination.pages)(2);
  TestValidator.equals("pagination page 1 count")(paged1.data.length)(1);

  const paged2 =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId },
          page: 2,
          limit: 1,
        },
      },
    );
  typia.assert(paged2);
  TestValidator.equals("pagination page 2 count")(paged2.data.length)(1);

  // 6. Filter by is_private = true (should return ONLY the private inquiry)
  const privResults =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId, is_private: true },
        },
      },
    );
  typia.assert(privResults);
  TestValidator.equals("private filtered count")(
    privResults.pagination.records,
  )(1);
  TestValidator.equals("private is_private true")(
    privResults.data[0].is_private,
  )(true);
  TestValidator.equals("private inquiry matches")(privResults.data[0].id)(
    privateInquiry.id,
  );

  // 7. Filter by is_private = false (ONLY public inquiry)
  const pubResults =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId, is_private: false },
        },
      },
    );
  typia.assert(pubResults);
  TestValidator.equals("public filtered count")(pubResults.pagination.records)(
    1,
  );
  TestValidator.equals("public is_private false")(
    pubResults.data[0].is_private,
  )(false);
  TestValidator.equals("public inquiry matches")(pubResults.data[0].id)(
    publicInquiry.id,
  );

  // 8. Test sorting by created_at ascending
  const ascResults =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId },
          sort: "created_at",
          order: "asc",
        },
      },
    );
  typia.assert(ascResults);
  TestValidator.equals("asc order inquiry1 is first")(ascResults.data[0].id)(
    publicInquiry.created_at < privateInquiry.created_at
      ? publicInquiry.id
      : privateInquiry.id,
  );

  // 9. Test sorting by created_at descending
  const descResults =
    await api.functional.shopping_mall_ai.customer.inquiries.search(
      connection,
      {
        body: {
          filter: { shopping_mall_ai_product_id: productId },
          sort: "created_at",
          order: "desc",
        },
      },
    );
  typia.assert(descResults);
  TestValidator.equals("desc order inquiry1 is newest")(descResults.data[0].id)(
    publicInquiry.created_at > privateInquiry.created_at
      ? publicInquiry.id
      : privateInquiry.id,
  );
}

