import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import { IPageIShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFile";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Advanced file search with filtering, sorting and pagination for file
 * metadata.
 *
 * Returns matched file metadata records from the shopping_mall_ai_files table
 * depending on advanced search and filter parameters defined in the request.
 *
 * This operation is only accessible by admins or compliance staff since it may
 * expose sensitive information or facilitate in-depth audits of system file
 * storage. Complete access and search patterns are also typically logged for
 * compliance.
 *
 * Related to audit logging and compliance modules, this function serves both
 * operational and legal requirements for traceable file management.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user. Only admins/compliance
 *   staff are authorized to use this endpoint.
 * @param props.body - Search, filter, and pagination criteria for querying
 *   files.
 * @returns Paginated and filtered file metadata records.
 * @throws {Error} When invalid filter parameters are supplied or database
 *   issues occur.
 */
export async function patch__shopping_mall_ai_admin_shoppingMallAiFiles(props: {
  admin: AdminPayload;
  body: IShoppingMallAiFile.IRequest;
}): Promise<IPageIShoppingMallAiFile> {
  const { admin, body } = props;

  // Pagination defaults
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Dynamic where clause for filters
  const where = {
    ...(body.original_name !== undefined &&
      body.original_name !== null && {
        original_name: {
          contains: body.original_name,
          mode: "insensitive" as const,
        },
      }),
    ...(body.extension !== undefined &&
      body.extension !== null && {
        extension: { equals: body.extension },
      }),
    ...(body.mime_type !== undefined &&
      body.mime_type !== null && {
        mime_type: { equals: body.mime_type },
      }),
    ...(body.actor_type !== undefined &&
      body.actor_type !== null && {
        actor_type: { equals: body.actor_type },
      }),
    ...(body.actor_id !== undefined &&
      body.actor_id !== null && {
        actor_id: body.actor_id,
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && {
                gte: body.created_from,
              }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && {
                lte: body.created_to,
              }),
          },
        }
      : {}),
    ...(body.deleted !== undefined && body.deleted !== null
      ? body.deleted
        ? { deleted_at: { not: null } }
        : { deleted_at: null }
      : {}),
  };

  // Fetch files & total count for pagination
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_files.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_files.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit) || 1,
    },
    data: rows.map((row) => ({
      id: row.id,
      original_name: row.original_name,
      uri: row.uri,
      extension: row.extension,
      mime_type: row.mime_type,
      size: row.size,
      hash: row.hash,
      actor_type: row.actor_type ?? null,
      actor_id: row.actor_id ?? null,
      created_at: toISOStringSafe(row.created_at),
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
