/**
 * Deletes (soft-deletes) a file metadata record by UUID.
 *
 * Marks the file metadata record as soft-deleted by setting its `deleted_at`
 * field to the current time. This does not remove the physical file from
 * storage/CDN, but prevents further access and enables compliance/audit
 * workflows. The operation is idempotent: if the file is already deleted, it
 * returns silently.
 *
 * File deletion requires admin privileges (enforced by controller/middleware).
 * All deletions are audited via compliance logs.
 *
 * @param props - Request parameters.
 * @param props.admin - Authenticated admin user payload.
 * @param props.shoppingMallAiFileId - UUID of the file metadata record to mark
 *   as deleted.
 * @returns Void. Operation completes successfully with no return value.
 * @throws {Error} If the file is not found (404)
 */
export async function delete__shopping_mall_ai_admin_shoppingMallAiFiles_$shoppingMallAiFileId(props: {
  admin: AdminPayload;
  shoppingMallAiFileId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { shoppingMallAiFileId } = props;
  const existing = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: shoppingMallAiFileId },
    select: { id: true, deleted_at: true },
  });
  if (!existing) throw new Error("File not found");
  if (existing.deleted_at !== null) return;
  await MyGlobal.prisma.shopping_mall_ai_files.update({
    where: { id: shoppingMallAiFileId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
