/**
 * Returns a paginated list of media asset records from the
 * shopping_mall_ai_media_assets table.
 *
 * Each asset represents a variant of a file, such as a preview or alternate
 * encoding, with technical metadata (type, URI, dimensions, timing, etc).
 * Supports admin digital asset management, analytic audit, and compliance
 * reporting. Does not include file contents. Pagination is static (page 1,
 * limit 100). Requires admin authentication.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin payload (required)
 * @returns Paginated media asset metadata records
 *   (IPageIShoppingMallAiMediaAsset)
 * @throws {Error} When admin is unauthorized or DB errors occur
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiMediaAssets(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiMediaAsset> {
  const page = 1;
  const limit = 100;

  // Query: total asset count for pagination
  const totalRecords =
    await MyGlobal.prisma.shopping_mall_ai_media_assets.count();

  // Query: fetch paged records (most recent first)
  const assets = await MyGlobal.prisma.shopping_mall_ai_media_assets.findMany({
    skip: (page - 1) * limit,
    take: limit,
    orderBy: { created_at: "desc" },
  });

  // Map Prisma results to API DTO (convert Date to ISO string)
  const data = assets.map((asset) => ({
