 * @param props - Request parameter object
 * @param props.admin - Authenticated admin user (must have type 'admin')
 * @param props.body - Search/filter/pagination DTO; supports asset_type, file
 *   ID, created_from/to, etc.
 * @returns Paginated result of matching media asset metadata records, strictly
 *   typed.
 * @throws {Error} When user is not authenticated as admin role
 */
export async function patch__shopping_mall_ai_admin_shoppingMallAiMediaAssets(props: {
  admin: AdminPayload;
  body: IShoppingMallAiMediaAsset.IRequest;
}): Promise<IPageIShoppingMallAiMediaAsset> {
  const { admin, body } = props;
  // Re-validate admin payload (defense-in-depth)
  if (!admin || admin.type !== "admin") {
    throw new Error("Access denied: must be admin role.");
  }

  // Defaults for page/limit
  const DEFAULT_PAGE = 1;
  const DEFAULT_LIMIT = 50;
  let page = body.page ?? DEFAULT_PAGE;
  let limit = body.limit ?? DEFAULT_LIMIT;
  // Defensive bounds for pagination
  if (typeof page !== "number" || !Number.isFinite(page) || page < 1) page = 1;
  if (
    typeof limit !== "number" ||
    !Number.isFinite(limit) ||
    limit < 1 ||
    limit > 200
  )
    limit = 50;

  // Build Prisma where conditions for advanced search
  const where = {
    ...(body.shopping_mall_ai_file_id !== undefined &&
      body.shopping_mall_ai_file_id !== null && {
        shopping_mall_ai_file_id: body.shopping_mall_ai_file_id,
      }),
    ...(body.asset_type !== undefined &&
      body.asset_type !== null &&
      body.asset_type.length > 0 && {
        asset_type: {
          contains: body.asset_type,
          mode: "insensitive" as const,
        },
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // Query database in parallel for paged results and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_media_assets.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.shopping_mall_ai_media_assets.count({ where }),
  ]);

  // API DTO mapping; handle all date and nullable/optional fields strictly
  const data: IShoppingMallAiMediaAsset[] = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_file_id: row.shopping_mall_ai_file_id,
    asset_type: row.asset_type,
    asset_uri: row.asset_uri,
    width: row.width ?? null,
    height: row.height ?? null,
    duration: row.duration ?? null,
    created_at: toISOStringSafe(row.created_at),
  }));

  // Pagination calculation per API contract
  const result: IPageIShoppingMallAiMediaAsset = {
    pagination: {
      current: page,
      limit: limit,
      records: total,
