/**
 * Retrieve all metadata and record attributes for a single uploaded file by its
 * unique fileId (UUID).
 *
 * Only the seller who uploaded the file may access its metadata. If the file is
 * soft deleted, metadata will reflect this and it is up to downstream systems
 * to block content access.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request (only
 *   permitted to view their own uploaded files)
 * @param props.fileId - UUID of the file to retrieve
 * @returns File metadata and attributes as IShoppingMallAiFile
 * @throws {Error} When the file does not exist or is not owned by the
 *   requesting seller
 */
export async function get__shopping_mall_ai_seller_shoppingMallAiFiles_$fileId(props: {
  seller: SellerPayload;
  fileId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiFile> {
  const { seller, fileId } = props;
  const file = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: fileId },
  });
  if (!file) throw new Error("File not found");
  // Authorization: Only allow seller who uploaded
  if (file.actor_type !== "seller" || file.actor_id !== seller.id) {
    throw new Error(
      "Unauthorized: You may only access files you have uploaded",
