 */
export async function patch__shopping_mall_ai_customer_shoppingMallAiProducts(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiProduct.IRequest;
}): Promise<IPageIShoppingMallAiProduct.ISummary> {
  const { body } = props;
  // Paging defaults with strong int32 typing required
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build filter object, only using verified fields per schema and rules
  const where = {
    status: "active", // Enforce only active products for customer role
    ...(body.seller_id !== undefined &&
      body.seller_id !== null && {
        shopping_mall_ai_seller_id: body.seller_id,
      }),
    ...(body.category_id !== undefined &&
      body.category_id !== null && {
        shopping_mall_ai_product_category_id: body.category_id,
      }),
    ...(body.sku !== undefined &&
      body.sku !== null && {
        sku: { contains: body.sku, mode: "insensitive" as const },
      }),
    ...(body.title !== undefined &&
      body.title !== null && {
        title: { contains: body.title, mode: "insensitive" as const },
      }),
    ...((body.min_price !== undefined && body.min_price !== null) ||
    (body.max_price !== undefined && body.max_price !== null)
      ? {
          price: {
            ...(body.min_price !== undefined &&
              body.min_price !== null && { gte: body.min_price }),
            ...(body.max_price !== undefined &&
              body.max_price !== null && { lte: body.max_price }),
          },
        }
      : {}),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
    ...((body.updated_from !== undefined && body.updated_from !== null) ||
    (body.updated_to !== undefined && body.updated_to !== null)
      ? {
          updated_at: {
            ...(body.updated_from !== undefined &&
              body.updated_from !== null && { gte: body.updated_from }),
            ...(body.updated_to !== undefined &&
              body.updated_to !== null && { lte: body.updated_to }),
          },
        }
      : {}),
  };
  // Query DB in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        title: true,
        price: true,
        status: true,
        sku: true,
        shopping_mall_ai_product_category_id: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_products.count({ where }),
  ]);
