import { IShoppingMallAiProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductCategory";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieves a paginated list of all top-level and child product categories from
 * the shopping_mall_ai_product_categories table.
 *
 * This endpoint is intended for browsing category structures, populating
 * navigation UIs, and offering admin-level reporting. Category records returned
 * contain unique ID, optional parent_id (for hierarchy), category name, display
 * order, active flag, and audit timestamps. Customers are only able to see
 * categories with active=true. Paging is fixed (page 1, limit 100) as no
 * pagination parameters are provided.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making this request
 *   (mandates that only categories for active customers are shown)
 * @returns Paginated product categories data set for the customer (all
 *   categories with active=true, up to 100 per request)
 * @throws {Error} Throws only for internal database errors
 */
export async function get__shopping_mall_ai_customer_shoppingMallAiProductCategories(props: {
  customer: CustomerPayload;
}): Promise<IPageIShoppingMallAiProductCategory> {
  // Default pagination
  const page = 1;
  const limit = 100;

  // Query active categories
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_product_categories.count({
      where: { active: true },
    }),
    MyGlobal.prisma.shopping_mall_ai_product_categories.findMany({
      where: { active: true },
      orderBy: [{ display_order: "asc" }, { created_at: "asc" }],
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

  // Map results to API DTO (no Date used)
  const data = rows.map((row) => ({
    id: row.id,
    parent_id: row.parent_id ?? null,
    name: row.name,
    display_order: row.display_order,
    active: row.active,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

