 *
 * Creates a new product category row with unique name under the given parent
 * ID, enforcing navigation tree structure.
 *
 * - Only platform admins are authorized to use this endpoint.
 * - Input must match IShoppingMallAiProductCategory.ICreate.
 * - Enforces business uniqueness on (name, parent_id), returning error on
 *   duplicates.
 * - Automatically sets created_at and updated_at timestamps.
 * - Returns the newly created normalized category object with all fields and
 *   brand types.
 *
 * @param props - Request input: admin authentication and category creation body
 * @param props.admin - Authenticated admin payload (must be valid; enforced by
 *   decorator)
 * @param props.body - Category creation data: name (required), optional
 *   parent_id, display_order, active status
 * @returns The complete category object after creation, matching schema
 *   requirements
 * @throws {Error} If a category with the same name and parent already exists,
 *   or if input is invalid
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiProductCategories(props: {
  admin: AdminPayload;
  body: IShoppingMallAiProductCategory.ICreate;
}): Promise<IShoppingMallAiProductCategory> {
  const { body } = props;

  // Enforce (name, parent_id) uniqueness at the application level for clear errors
  const existing =
    await MyGlobal.prisma.shopping_mall_ai_product_categories.findFirst({
      where: {
        name: body.name,
        parent_id: body.parent_id === undefined ? null : body.parent_id,
      },
    });
  if (existing) {
    throw new Error(
      "A category with this name already exists under the specified parent.",
    );
  }

  // Prepare timestamps as ISO8601 strings
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  // Generate a new UUID for the id (required)
  const newId: string & tags.Format<"uuid"> = v4();

  // Insert the new category
  const created =
    await MyGlobal.prisma.shopping_mall_ai_product_categories.create({
      data: {
        id: newId,
        parent_id: body.parent_id === undefined ? null : body.parent_id,
        name: body.name,
        display_order: body.display_order,
        active: body.active,
        created_at: now,
        updated_at: now,
      },
    });

  // Explicitly return a fully typed, branded object per DTO requirements
  return {
    id: created.id,
    parent_id: created.parent_id,
    name: created.name,
    display_order: created.display_order,
    active: created.active,
    created_at: now,
    updated_at: now,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
