import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Update product category details by ID (shopping_mall_ai_product_categories).
 *
 * Updates a product category's atomic fields: name, parent_id, display_order,
 * and active flag. Only an admin may invoke this. Performs referential
 * integrity checks on parent_id; enforces unique (name, parent_id) constraint.
 * Always updates the updated_at to now. Returns full updated category with
 * audit fields (timestamps as string & tags.Format<'date-time'>).
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin context (must be present)
 * @param props.shoppingMallAiProductCategoryId - UUID of the target category
 * @param props.body - Fields to update (IShoppingMallAiProductCategory.IUpdate)
 * @returns The updated product category object
 * @throws {Error} If not found, parent_id invalid, parent_id is self, or
 *   constraint violations
 */
export async function put__shopping_mall_ai_admin_shoppingMallAiProductCategories_$shoppingMallAiProductCategoryId(props: {
  admin: AdminPayload;
  shoppingMallAiProductCategoryId: string & tags.Format<"uuid">;
  body: IShoppingMallAiProductCategory.IUpdate;
}): Promise<IShoppingMallAiProductCategory> {
  const { admin, shoppingMallAiProductCategoryId, body } = props;

  // 1. Ensure the category to update exists
  const category =
    await MyGlobal.prisma.shopping_mall_ai_product_categories.findUnique({
      where: { id: shoppingMallAiProductCategoryId },
    });
  if (!category) {
    throw new Error("Product category not found");
  }

  // 2. If updating parent_id, verify integrity: parent_id must exist (if not null), and must not self-reference
  if (Object.prototype.hasOwnProperty.call(body, "parent_id")) {
    if (body.parent_id !== undefined && body.parent_id !== null) {
      if (body.parent_id === shoppingMallAiProductCategoryId) {
        throw new Error("Cannot set parent_id of a category to itself");
      }
      const parentExists =
        await MyGlobal.prisma.shopping_mall_ai_product_categories.findUnique({
          where: { id: body.parent_id },
        });
      if (!parentExists) {
        throw new Error(
          "Specified parent_id does not refer to an existing category",
        );
      }
    }
  }

  // 3. Try update with allowed fields only, always update updated_at
  try {
    const now = toISOStringSafe(new Date());
    const updated =
      await MyGlobal.prisma.shopping_mall_ai_product_categories.update({
        where: { id: shoppingMallAiProductCategoryId },
        data: {
          name: body.name ?? undefined,
          parent_id:
            "parent_id" in body
              ? body.parent_id === undefined
                ? undefined
                : body.parent_id
              : undefined,
          display_order: body.display_order ?? undefined,
          active: body.active ?? undefined,
          updated_at: now,
        },
      });
    return {
      id: updated.id,
      parent_id: updated.parent_id ?? null,
      name: updated.name,
      display_order: updated.display_order,
      active: updated.active,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
    };
  } catch (err: any) {
    // Uniqueness or FK constraint violations are propagated as generic Error.
    throw err;
  }
}

