/**
 * Permanently deletes a product category by its ID. Only admins may execute.
 *
 * This performs a hard delete on shopping_mall_ai_product_categories with the
 * given ID. Deletion will be blocked if there are any child categories or
 * products referencing this category. Violations trigger a business error,
 * leaving the category and all dependents unchanged.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the operation
 * @param props.shoppingMallAiProductCategoryId - The UUID of the product
 *   category to delete
 * @returns Void
 * @throws {Error} If there are child categories or products referencing this
 *   category
 */
export async function delete__shopping_mall_ai_admin_shoppingMallAiProductCategories_$shoppingMallAiProductCategoryId(props: {
  admin: AdminPayload;
  shoppingMallAiProductCategoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, shoppingMallAiProductCategoryId } = props;
  // Check for child categories
  const childCount =
    await MyGlobal.prisma.shopping_mall_ai_product_categories.count({
      where: { parent_id: shoppingMallAiProductCategoryId },
    });
  if (childCount > 0) {
    throw new Error(
      "Cannot delete: child categories exist for the specified category.",
    );
  }
  // Check for products referencing this category
  const productCount = await MyGlobal.prisma.shopping_mall_ai_products.count({
    where: {
      shopping_mall_ai_product_category_id: shoppingMallAiProductCategoryId,
    },
  });
  if (productCount > 0) {
    throw new Error("Cannot delete: products reference this category.");
  }
  // Proceed with permanent deletion
  await MyGlobal.prisma.shopping_mall_ai_product_categories.delete({
    where: { id: shoppingMallAiProductCategoryId },
  });
}

