 * Only the cart owner can perform this operation. Throws errors for not
 * found/unauthorized cases. Irreversible: the cart item is removed from
 * shopping_mall_ai_cart_items. Success is indicated by absence of content.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (owner) initiating the
 *   delete
 * @param props.cartId - UUID of the cart containing the item to delete
 * @param props.cartItemId - UUID of the cart item being deleted
 * @returns Void (success = no content)
 * @throws {Error} If the cart item is not found
 * @throws {Error} If the cart item doesn't belong to the specified cart
 * @throws {Error} If the cart does not exist
 * @throws {Error} If the authenticated customer does not own the cart
 */
export async function delete__shopping_mall_ai_customer_carts_$cartId_cartItems_$cartItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  cartItemId: string & tags.Format<"uuid">;
}): Promise<void> {
