    cart.shopping_mall_ai_customer_id !== customer.id
  ) {
    throw new Error("Unauthorized: not the cart owner");
  }
  // Step 4: Delete the cart item (hard delete)
  await MyGlobal.prisma.shopping_mall_ai_cart_items.delete({
    where: { id: cartItemId },
  });

  return;
}

