  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: payments.map((p) => ({
      id: p.id,
