import { IShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPayment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create a new payment record for a specific order as a seller
 *
 * This endpoint inserts a new payment event for a specified order. The payload
 * (IShoppingPayment.ICreate) requires atomic payment details: payment method,
 * amount, status, timestamps, and payment channel context. The seller must be
 * authorized for the order. The created record supports audit/compliance
 * workflows.
 *
 * @param props - Request props, including:
 *
 *   - Seller: SellerPayload (authenticated seller making request)
 *   - OrderId: string & tags.Format<'uuid'> (order UUID)
 *   - Body: IShoppingPayment.ICreate (atomic payment details)
 *
 * @returns IShoppingPayment - The full payment object after creation
 * @throws Error when the order does not exist or is not owned by seller
 */
export async function post__shopping_mall_ai_seller_orders_$orderId_payments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingPayment.ICreate;
}): Promise<IShoppingPayment> {
  const { seller, orderId, body } = props;

  // 1. Find order and confirm at least one item is owned by the seller
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findFirst({
    where: { id: orderId },
    select: {
      id: true,
      shopping_mall_ai_order_items: {
        select: {
          shopping_mall_ai_product_id: true,
        },
      },
    },
  });
  if (!order) throw new Error("Order not found");

  // Pull all distinct product IDs in the order
  const productIds = order.shopping_mall_ai_order_items
    ? order.shopping_mall_ai_order_items.map(
        (item) => item.shopping_mall_ai_product_id,
      )
    : [];
  if (productIds.length === 0) throw new Error("Order contains no items");

  // Check if the seller owns at least one of these products
  const sellerProductCount =
    await MyGlobal.prisma.shopping_mall_ai_products.count({
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
    });
  if (sellerProductCount === 0)
    throw new Error("Unauthorized: You do not own any products in this order");

  // 2. Create payment record
  const payment = await MyGlobal.prisma.shopping_mall_ai_payments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_order_id: orderId,
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      method: body.method,
      status: body.status,
      amount: body.amount,
      initiated_at: toISOStringSafe(body.initiated_at),
      resolved_at:
        body.resolved_at !== undefined && body.resolved_at !== null
          ? toISOStringSafe(body.resolved_at)
          : null,
    },
  });

  return {
    id: payment.id,
    shopping_mall_ai_order_id: payment.shopping_mall_ai_order_id,
    shopping_mall_ai_channel_id: payment.shopping_mall_ai_channel_id,
    method: payment.method,
    status: payment.status,
    amount: payment.amount,
    initiated_at: toISOStringSafe(payment.initiated_at),
    resolved_at:
      payment.resolved_at !== undefined && payment.resolved_at !== null
        ? toISOStringSafe(payment.resolved_at)
        : null,
  };
}

