  // Step 1: Fetch payment and ensure it belongs to the specified order
  const payment = await MyGlobal.prisma.shopping_mall_ai_payments.findUnique({
    where: { id: paymentId },
  });

  if (!payment || payment.shopping_mall_ai_order_id !== orderId) {
    throw new Error(
      "Payment record not found or does not belong to the specified order.",
    );
  }

  // Step 2: Allow updates only for permitted fields
  const updated = await MyGlobal.prisma.shopping_mall_ai_payments.update({
    where: { id: paymentId },
    data: {
      method: body.method ?? undefined,
      status: body.status ?? undefined,
      amount: body.amount ?? undefined,
      initiated_at: body.initiated_at ?? undefined,
      // resolved_at: explicit set permitted (can be null to clear)
      resolved_at:
        body.resolved_at === undefined ? undefined : body.resolved_at,
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_order_id: updated.shopping_mall_ai_order_id,
    shopping_mall_ai_channel_id: updated.shopping_mall_ai_channel_id,
    method: updated.method,
    status: updated.status,
    amount: updated.amount,
    initiated_at: toISOStringSafe(updated.initiated_at),
    resolved_at: updated.resolved_at
      ? toISOStringSafe(updated.resolved_at)
      : null,
  };
}

