 * admin.
 *
 * This endpoint removes the payment record from the database using a true
 * delete, as payments do not support soft-delete. Only admins may invoke this
 * operation. The function checks that the payment is associated with the
 * specified order, and records the operation in the audit log for compliance.
 *
 * @param props - Properties for the request:
 * @param props.admin - The authenticated admin user invoking this operation
 * @param props.orderId - The UUID of the order associated with the payment
 * @param props.paymentId - The UUID of the payment to delete
 * @returns Void
 * @throws {Error} When the payment does not exist or does not belong to the
 *   specified order
 * @throws {Error} When referential integrity is violated (e.g., payment in
 *   immutable state)
 */
export async function delete__shopping_mall_ai_admin_orders_$orderId_payments_$paymentId(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  paymentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, orderId, paymentId } = props;

  // Fetch payment record and validate existence and order association
  const payment =
    await MyGlobal.prisma.shopping_mall_ai_payments.findUniqueOrThrow({
      where: { id: paymentId },
    });
  if (payment.shopping_mall_ai_order_id !== orderId) {
