/**
 * Delete a payment record from a specific order by hard delete (no soft-delete
 * field exists in shopping_mall_ai_payments).
 *
 * This endpoint permanently deletes a specified payment record from an order,
 * using a hard delete operation since no soft-delete fields exist in
 * shopping_mall_ai_payments. Only the seller responsible for the order/payment
 * may perform this (authorization is enforced based on seller's association
 * with the order's channel). Successful invocation removes the record and
 * cascades changes to downstream analytics/reporting. All actions are tracked
 * in audit logs for future compliance or financial review.
 *
 * The endpoint will return errors for unauthorized access, attempts to delete
 * immutable payment records, or referential integrity violations. No message is
 * returned on successful erasure; the operation is strictly destructive per
 * compliance design.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request
 * @param props.orderId - Order ID whom the payment is associated with
 * @param props.paymentId - ID of the payment record to be erased
 * @returns Void
 * @throws {Error} When the payment does not exist, does not belong to order,
 *   order is not found, or seller is not authorized
 */
export async function delete__shopping_mall_ai_seller_orders_$orderId_payments_$paymentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  paymentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, paymentId } = props;

  // 1. Find the payment to be deleted
  const payment = await MyGlobal.prisma.shopping_mall_ai_payments.findUnique({
    where: { id: paymentId },
    select: { id: true, shopping_mall_ai_order_id: true },
  });
  if (!payment) throw new Error("Payment record not found.");
  if (payment.shopping_mall_ai_order_id !== orderId)
    throw new Error("Payment does not belong to the specified order.");

  // 2. Fetch the corresponding order
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: {
      id: true,
      channel: { select: { id: true } },
    },
  });
  if (!order) throw new Error("Order not found.");

  // 3. Confirm that the seller is associated with the order's channel
  const channel = await MyGlobal.prisma.shopping_mall_ai_channels.findUnique({
    where: { id: order.channel.id },
    select: { id: true, shopping_mall_ai_sellers: { select: { id: true } } },
  });
  if (!channel) throw new Error("Channel associated with order not found.");

  const sellerOwnsChannel = channel.shopping_mall_ai_sellers.some(
    (s) => s.id === seller.id,
  );
  if (!sellerOwnsChannel)
    throw new Error(
      "Unauthorized: Seller does not have access to this order's payments.",
    );

  // 4. Perform hard delete of the payment record
  await MyGlobal.prisma.shopping_mall_ai_payments.delete({
    where: { id: paymentId },
  });
  // (Assume audit logging is managed externally via triggers or logging middleware)
}

