/**
 * List all shipments for a specific order (shopping_mall_ai_shipments table).
 *
 * This endpoint fetches all shipment records associated with a specified order,
 * but only permits access to sellers who have at least one product included in
 * that order. Authorization is enforced by checking all order items against the
 * requesting seller's ID.
 *
 * RBAC enforcement: Only sellers whose products are part of the order can list
 * shipments for that order. Unauthorized access (seller does not own any items
 * in the order) results in an error.
 *
 * All date/datetime fields are provided as ISO8601 strings (strictly using
 * `string & tags.Format<'date-time'>`).
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller payload (must own at least one
 *   product in the order)
 * @param props.orderId - Unique identifier of the order for which shipments
 *   will be listed
 * @returns An object containing an array of all shipment records
 *   (IShoppingMallAiShipmentList) for the order
 * @throws {Error} If the seller does not own any products in the order
 *   (unauthorized)
 */
export async function get__shopping_mall_ai_seller_orders_$orderId_shipments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiShipmentList> {
  const { seller, orderId } = props;

  // Fetch all order items for the order
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  if (!orderItems.length) return { shipments: [] };

  const productIds = orderItems.map((item) => item.shopping_mall_ai_product_id);
  const products = await MyGlobal.prisma.shopping_mall_ai_products.findMany({
    where: { id: { in: productIds } },
    select: { shopping_mall_ai_seller_id: true },
  });

  // RBAC: Verify seller owns at least one product in the order
  const isSellerForOrder = products.some(
    (product) => product.shopping_mall_ai_seller_id === seller.id,
  );
  if (!isSellerForOrder) {
    throw new Error(
      "Unauthorized: You do not have permission to view shipments for this order",
    );
  }

  // Fetch all shipments for this order
  const shipmentsRaw =
    await MyGlobal.prisma.shopping_mall_ai_shipments.findMany({
      where: { shopping_mall_ai_order_id: orderId },
    });

  const shipments: IShoppingMallAiShipment[] = shipmentsRaw.map((shipment) => ({
    id: shipment.id,
    shopping_mall_ai_order_id: shipment.shopping_mall_ai_order_id,
    status: shipment.status,
    tracking_number: shipment.tracking_number ?? null,
    provider: shipment.provider ?? null,
    created_at: toISOStringSafe(shipment.created_at),
    updated_at: toISOStringSafe(shipment.updated_at),
  }));

  return { shipments };
}

