  const data = rows.map((row) => ({
    id: row.id,
    title: row.title,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    shopping_mall_ai_section_id: row.shopping_mall_ai_section_id,
    shopping_mall_ai_channel_id: row.shopping_mall_ai_channel_id,
    author_nickname: authorMap.get(row.shopping_mall_ai_customer_id) ?? "",
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data,
  };
}

