        ? toISOStringSafe(updated.deleted_at)
        : null,
    };
  }
  // No valid update for seller (nothing to change); return current state
  return {
    id: inquiry.id,
    shopping_mall_ai_product_id: inquiry.shopping_mall_ai_product_id,
