  body: IShoppingMallAiReview.IRequest;
}): Promise<IPageIShoppingMallAiReview> {
  const { admin, body } = props;
  if (!admin || admin.type !== "admin" || !admin.id)
    throw new Error("Unauthorized: admin access only");

  const allowedFields = [
    "id",
    "shopping_mall_ai_product_id",
    "shopping_mall_ai_customer_id",
    "shopping_mall_ai_order_id",
    "rating",
    "body",
    "created_at",
    "updated_at",
    "deleted_at",
  ];

  const filter =
    typeof body.filter === "object" && body.filter !== null ? body.filter : {};
  for (const key of Object.keys(filter)) {
    if (!allowedFields.includes(key))
      throw new Error(`Invalid filter key: ${key}`);
  }
  const where = {
    ...(typeof filter.id === "string" && {
      id: filter.id,
    }),
    ...(typeof filter.shopping_mall_ai_product_id === "string" && {
      shopping_mall_ai_product_id: filter.shopping_mall_ai_product_id,
    }),
    ...(typeof filter.shopping_mall_ai_customer_id === "string" && {
      shopping_mall_ai_customer_id: filter.shopping_mall_ai_customer_id,
    }),
    ...(typeof filter.shopping_mall_ai_order_id === "string" && {
      shopping_mall_ai_order_id: filter.shopping_mall_ai_order_id,
    }),
    ...(typeof filter.rating === "number" && {
      rating: filter.rating,
    }),
    ...(typeof filter.body === "string" && {
      body: {
        contains: filter.body,
        mode: "insensitive" as const,
      },
    }),
    ...["created_at", "updated_at", "deleted_at"].reduce(
      (acc, k) => {
        const v = filter[k as keyof typeof filter];
        if (v && typeof v === "object" && ("gte" in v || "lte" in v)) {
          acc[k] = {
            ...(v.gte && { gte: v.gte }),
            ...(v.lte && { lte: v.lte }),
          };
        } else if (typeof v === "string") {
          acc[k] = v;
        }
        return acc;
      },
      {} as Record<string, unknown>,
    ),
  };

  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 && body.limit <= 100
      ? body.limit
      : 20;
  const skip = (page - 1) * limit;
  const sort: string =
    typeof body.sort === "string" && allowedFields.includes(body.sort)
      ? body.sort
      : "created_at";
  const order: "asc" | "desc" = body.order === "asc" ? "asc" : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_reviews.findMany({
      where,
      orderBy: { [sort]: order },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_reviews.count({ where }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
    rating: row.rating,
    body: row.body,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
    data,
  };
}

