 *
 * - Only the review owner can access their review (and only if not soft-deleted).
 * - Returns 404 if the review is not found or is deleted.
 * - Returns 403 if the requested review does not belong to the authenticated
 *   customer.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload
 * @param props.reviewId - ID of the review to fetch (UUID)
 * @returns The full review object (IShoppingMallAiReview)
 * @throws {Error} 404 if review doesn't exist or is deleted, 403 if not owned
 *   by customer
 */
export async function get__shopping_mall_ai_customer_reviews_$reviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiReview> {
