/**
 * Update a product review by reviewId (rating, body).
 *
 * Allows the original customer to update their own product review's rating
 * and/or body, when the review has not been soft-deleted. All changes are
 * audit-compliant and business-policy compliant. Customers cannot soft-delete
 * their own review; only admins may do so.
 *
 * @param props - The request properties
 * @param props.customer - The authenticated customer payload
 * @param props.reviewId - The target review's ID (UUID)
 * @param props.body - The new review fields (may include rating and/or body);
 *   deleted_at is ignored for customers
 * @returns The updated full review object
 * @throws {Error} When review does not exist (404)
 * @throws {Error} When the review does not belong to the requesting customer
 *   (403)
 * @throws {Error} When the review is soft-deleted and not allowed to be updated
 *   (403)
 * @throws {Error} When no allowed fields (rating or body) are provided in the
 *   update request (400)
 */
export async function put__shopping_mall_ai_customer_reviews_$reviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IShoppingMallAiReview.IUpdate;
}): Promise<IShoppingMallAiReview> {
  const { customer, reviewId, body } = props;

  // Step 1: Retrieve the review and check for existence
  const review = await MyGlobal.prisma.shopping_mall_ai_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) {
    throw new Error("Review not found");
  }

  // Step 2: Verify authorship -- only the original customer can update
  if (review.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Forbidden: You are not the author of this review");
  }

  // Step 3: Prevent update if review is deleted
  if (review.deleted_at !== null) {
    throw new Error(
      "Forbidden: This review has been deleted and cannot be updated",
    );
  }

  // Step 4: Prepare allowed update fields, excluding deleted_at from customer
  const updateFields: {
    rating?: number & tags.Type<"int32">;
    body?: string;
    updated_at: string & tags.Format<"date-time">;
  } = {
    updated_at: toISOStringSafe(new Date()),
  };
  let hasUpdate = false;
  if ("rating" in body && typeof body.rating === "number") {
    updateFields.rating = body.rating;
    hasUpdate = true;
  }
  if ("body" in body && typeof body.body === "string") {
    updateFields.body = body.body;
    hasUpdate = true;
  }
  // Don't allow a request that sends no allowed fields
  if (!hasUpdate) {
    throw new Error(
      "Bad request: At least one of 'rating' or 'body' must be provided",
    );
  }

  // Step 5: Do update
  const updated = await MyGlobal.prisma.shopping_mall_ai_reviews.update({
    where: { id: reviewId },
    data: updateFields,
  });

  // Step 6: Return full review object, mapped to DTO contract
  return {
    id: updated.id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: updated.shopping_mall_ai_order_id,
    rating: updated.rating,
    body: updated.body,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

