import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Soft deletes a product review by marking it as deleted (deleted_at).
 *
 * Only the review author (authenticated customer) can perform this action.
 * Seller or other users are forbidden. Once deleted, the review is hidden from
 * standard queries but remains for audit purposes.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.reviewId - UUID of the review to soft-delete
 * @returns Void (HTTP 204 on success)
 * @throws {Error} When review not found, already deleted, or customer is not
 *   review author
 */
export async function delete__shopping_mall_ai_customer_reviews_$reviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, reviewId } = props;

  // Find the review by ID
  const review = await MyGlobal.prisma.shopping_mall_ai_reviews.findUnique({
    where: { id: reviewId },
    select: {
      id: true,
      shopping_mall_ai_customer_id: true,
      deleted_at: true,
    },
  });
  if (!review) throw new Error("Review not found");

  // Check author (must match authenticated customer)
  if (review.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Forbidden: You may only delete your own review");
  }

  // Check for already deleted (null or undefined is not deleted; any other value is deleted)
  if (review.deleted_at) {
    throw new Error("Review already deleted");
  }

  // Set deleted_at to now (ISO string guaranteed)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_reviews.update({
    where: { id: reviewId },
    data: { deleted_at: now },
  });
}

