    data: {
      id: v4(),
      entity_type: "file",
      entity_id: fileId,
      actor_id: admin.id,
      actor_role: "admin",
      operation: "delete",
      detail: JSON.stringify({
        original_name: file.original_name,
        uri: file.uri,
      }),
      occurred_at: now,
    },
  });
}

